INSERT INTO "FlavourText" ("_row", "Id", "__col1", "Text") VALUES
(0, 'KeybladeText', 28812, 'Forged from thousands of unclaimed Beta keys'),
(1, 'UniqueTwoHandAxe1', 63457, 'One by one, Kaom slaughtered the weakest tribe' || char(13) || '
leaders until the others leapt to join his cause.'),
(2, 'UniqueOneHandSword1', 55516, 'As battle calms, blood turns to rust.'),
(3, 'UniqueAmulet1', 34681, 'You are slow, foolish and ignorant.' || char(13) || '
I am not.'),
(4, 'UniqueRing1', 65486, 'Fear is highly infectious.'),
(5, 'UniqueRing2', 28070, 'A token from the sea' || char(13) || '
A sign for Kaom' || char(13) || '
to lead his Karui to Wraeclast.'),
(6, 'UniqueRing3', 49827, 'Danger is the price of wealth.'),
(7, 'UniqueBow1', 32612, '"See without doubt, slay without hesitation."' || char(13) || '
- Marceus Lioneye of Sarn'),
(8, 'UniqueAmulet2', 55138, 'The maidens of court swoon to see' || char(13) || '
the challengers crushed at your feet.'),
(9, 'UniqueBodyStrInt1', 64924, 'Although a great leader during the war,' || char(13) || '
Voll proved disastrous in times of peace.'),
(10, 'UniqueDagger1', 44922, 'Divine intervention feels better' || char(13) || '
when you do it yourself.'),
(11, 'UniqueBow2', 33951, '"The wild takes care of its own."' || char(13) || '
- Hyrri of the Karui'),
(12, 'UniqueOneHandSword2', 35385, 'In the rift between future and past,' || char(13) || '
life passes quickly.'),
(13, 'UniqueHelmetDexInt1', 37403, 'It was a sliver of Malachai''s soul' || char(13) || '
that animated the first Eternal Guardian.'),
(14, 'UniqueHelmetStr1', 60659, 'Centuries of servitude, a day' || char(13) || '
of glory, an eternity of death.'),
(15, 'UniqueBow3', 47824, 'The mournful music of the strings,' || char(13) || '
The creaking arch, the arrow sings.' || char(13) || '
A choking cry, a rattled breath,' || char(13) || '
The Reaper''s Song, the Harp of Death.'),
(16, 'UniqueStaff1', 33121, 'Burn to cinders, scar and maim,' || char(13) || '
Rule a world, bathed in flame.'),
(17, 'UniqueTwoHandMace1', 1531, '"The crack of bone, the spray of blood.' || char(13) || '
Is there sweeter music?"' || char(13) || '
- Hrimnor of the Ezomytes.'),
(18, 'UniqueTwoHandMace2', 41704, '"One quick tap is all the persuasion you''ll need."' || char(13) || '
- Archbishop Geofri of Phrecia Cathedral'),
(19, 'UniqueTwoHandSword1', 27030, '"Today, clansmen, my sword is my voice!"' || char(13) || '
- Rigwald, at the Battle of Glarryn'),
(20, 'UniqueTwoHandSword2', 35895, 'Stoic visage, icy heart.' || char(13) || '
Life of sorrow, lived apart.'),
(21, 'UniqueRing4', 47327, 'Where her mouth should have been' || char(13) || '
there was only a whirling, black void.'),
(22, 'UniqueRing4x', 30722, '"Prototype #8 makes it difficult to think negatively, but two fatalities' || char(13) || '
resulted when a lead researcher used an epithet in its presence."'),
(23, 'UniqueRing5', 62611, 'Doryani stumbled into a realm of madness' || char(13) || '
And awoke its Master.'),
(24, 'UniqueQuiver1', 60380, 'Molten feathers, veiled spark,' || char(13) || '
Hissing arrows from the dark.'),
(25, 'UniqueQuiver2', 17809, 'Seeing only foot soldiers, the Sarn Knights cast aside' || char(13) || '
their heavy shields... and paid dearly for their mistake.'),
(26, 'UniqueAmulet3', 3906, 'The breath of life is yours to give.'),
(27, 'UniqueAmulet5', 6897, '"Shoot first, ask no questions."' || char(13) || '
- Karui wisdom'),
(28, 'UniqueAmulet5x', 23563, '"In testing, Prototype #9 had no effect on fired arrows. However,' || char(13) || '
an unknown spell did destroy the entire firing chamber."'),
(29, 'UniqueAmulet6', 53094, 'Never blinking, always watching.'),
(30, 'UniqueBodyDex1', 65142, 'Hyrri loosed a barrage of arrows,' || char(13) || '
tipped with a poisoned hatred' || char(13) || '
only oppression can ferment.'),
(31, 'UniqueBodyStr1', 61508, 'The warrior who' || char(13) || '
fears will fall.'),
(32, 'UniqueBodyStr1x', 49278, '"Useless for our purposes, but perhaps we can sell Prototype #5' || char(13) || '
to an archmage to fund other experiments."'),
(33, 'UniqueDexHelmet1', 47690, 'Fairgraves'' trusty tricorne accompanied him far across' || char(13) || '
the seas, deep under the ground, and even beyond death.'),
(34, 'UniqueDexHelmet2', 36784, 'Give of your heated passions.' || char(13) || '
Give of your cold resolve.' || char(13) || '
You will be repaid.'),
(35, 'UniqueIntHelmet1', 5018, 'Lift it lightly, don it slow.' || char(13) || '
The spikes point out and in, you know.'),
(36, 'UniqueIntHelmet2', 56458, 'Asenath''s mind was as quick and nimble' || char(13) || '
as the fingers that drew her bowstring.'),
(37, 'UniqueIntHelmet3', 18994, '"It takes true strength to hold power,' || char(13) || '
and my grip grows tighter by the day."' || char(13) || '
 - Emperor Chitus'),
(38, 'UniqueStrHelmet2', 53874, 'Hrimnor''s presence was as cold as ice,' || char(13) || '
but his heart burned for vengeance.'),
(39, 'UniqueStrDexHelmet1', 41767, 'We wander to pass time.' || char(13) || '
We travel to fulfill.'),
(40, 'UniqueHelmetStrInt1', 34109, '"The craven mind is sharp with self interest.' || char(13) || '
The honourable mind is much easier to manipulate."' || char(13) || '
 - Malachai the Soulless'),
(41, 'UniqueHelmetStrInt2', 23991, 'In the battle for honour, Geofri won.' || char(13) || '
Not so, the battle for survival.'),
(42, 'UniqueAmulet4', 19103, 'It is said to make you invisible when the Great' || char(13) || '
Spirit comes to take you on your final journey.'),
(43, 'UniqueBootsInt1', 21057, 'Wonders abound at death''s door.'),
(44, 'UniqueDagger2', 64498, 'A mighty beast, a lavish feast.'),
(45, 'UniqueBootsStrDex1', 60090, 'Stand and lead the righteous pride,' || char(13) || '
Fight till death, never hide.'),
(46, 'UniqueBootsStrDex1x', 29092, '"Twelve dead, and the seventh lab cannot be entered for several years.' || char(13) || '
Prototype #12 is a ''success,'' if we can ever reach it."'),
(47, 'UniqueBootsStrInt1', 48313, 'Tempest''s power given form,' || char(13) || '
Flee before the walking storm.'),
(48, 'UniqueBootsInt2', 33086, 'All the world is my home.'),
(49, 'UniqueBootsInt3', 35340, 'Shavronne raced to Brutus'' side,' || char(13) || '
her last hope against the Karui tide.'),
(50, 'UniqueBootsDexInt1', 27963, 'Blazing body, shining bold.' || char(13) || '
Dance beneath the orb of gold!'),
(51, 'UniqueBootsStr1', 15639, 'The mocking wind, a shielding spell,' || char(13) || '
The haunting screams, a maddening hell.'),
(52, 'UniqueGlovesDex1', 43965, 'Of ancient giants, none remain,' || char(13) || '
Their only trace is timeless pain.'),
(53, 'UniqueGlovesDex2', 17141, 'Maligaro operated effortlessly,' || char(13) || '
with great speed and terrible consequences.'),
(54, 'UniqueGlovesStrDex1', 22727, 'A soft caress in dead of night,' || char(13) || '
that slips about the neck, so tight.'),
(55, 'UniqueGlovesStrDex2', 64162, 'Wealth is not to be borne lightly.'),
(56, 'UniqueGlovesInt1', 3472, 'Wealth unspent is wealth wasted.'),
(57, 'UniqueGlovesInt2', 45361, 'While Doedre lacked Maligaro''s sense of style,' || char(13) || '
she surpassed her master in pure malevolence.'),
(58, 'UniqueGlovesDexInt1', 38027, 'A single lightning strike fells a man.' || char(13) || '
A single knife stroke fells an empire.'),
(59, 'UniqueGlovesStr1', 1020, 'Why cling to your sanity? It offers you nothing.' || char(13) || '
Surrender to me, and I will grant you everything.'),
(60, 'UniqueAmulet7', 62882, 'The light that reveals is the glare that blinds.'),
(61, 'UniqueAmulet8', 44377, 'Mindless rage will shake the world,' || char(13) || '
Cunning lies will bend it.' || char(13) || '
Reckless haste will break the world,' || char(13) || '
And into darkness send it.'),
(62, 'UniqueBelt1', 54755, 'They say a lifetime of wisdom is carried' || char(13) || '
in every skin the great beasts shed.'),
(63, 'UniqueBelt2', 20027, 'Few men cast a longer shadow' || char(13) || '
 than the Great Meginord of the North.'),
(64, 'UniqueBelt3', 48116, 'A large enough debt turns even a friend' || char(13) || '
into an enemy, and the Perandus family' || char(13) || '
had more debtors than anyone.'),
(65, 'UniqueBelt4', 53105, 'Kaom''s strength was rivaled only by' || char(13) || '
the great Meginord of the north.'),
(66, 'UniqueShieldStrDex1', 64059, 'By tourney''s end, Daresso bled and shivered.' || char(13) || '
Yet even accursed treachery failed to steal the champion''s victory.'),
(67, 'UniqueShieldInt1', 13627, 'The Vaal emptied their slaves of beating hearts,' || char(13) || '
and left a mountain of twitching dead.'),
(68, 'UniqueShieldDex1', 64040, 'Cold, miserable and alone... but alive.'),
(69, 'UniqueShieldDex2', 30765, '"With piety and justice."' || char(13) || '
- Perandus family motto'),
(70, 'UniqueShieldStr1', 56658, 'Marceus'' unblemished shield is a testament' || char(13) || '
to his arrogance... and his fate.'),
(71, 'UniqueTwoHandAce2', 25361, 'Accept your fate, or lie, pretend.' || char(13) || '
Death collects you in the end.'),
(72, 'UniqueTwoHandSword3', 6138, 'His final sensation was of the executioner''s blade.' || char(13) || '
It was not cold, instead warm and reassuring,' || char(13) || '
murmuring a promise of better times ahead.' || char(13) || '
Smiling, he returned death''s embrace.'),
(73, 'UniqueRapier1', 3540, 'She paints her offer in wicked hues' || char(13) || '
An off-white grin, an elegant bruise.' || char(13) || '
To the nascent scourge she sings the ruse:' || char(13) || '
"With me in hand, what else need you use?"'),
(74, 'UniqueBodyStrInt2', 9550, 'Nothing stops the pain like a courageous rush into battle.'),
(75, 'UniqueBodyStrInt2x', 52089, '"Prototype #7 achieved even greater injury responsiveness than expected,' || char(13) || '
though at considerable cost to the long-term survival rate of the user."'),
(76, 'UniqueShieldStrInt1', 46505, 'A swift mind solves problems before they occur.'),
(77, 'UniqueHelmetInt4', 16022, 'The malice in her gaze froze blood and shattered bone.'),
(78, 'UniqueWand1', 40818, 'Cast into darkness' || char(13) || '
And trapped for a thousand years,' || char(13) || '
The lonely moon weeps'),
(79, 'UniqueMap1', 56241, '"Should I depart this mortal coil,' || char(13) || '
so shall all of my treasures."' || char(13) || '
- Atziri, Queen of the Vaal'),
(80, 'UniqueHelmetStrDex2', 13836, 'Swift as thought are the actions of Man ' || char(13) || '
when borne on wings of divine providence.'),
(81, 'UniqueShieldStrInt2', 9503, 'When blood is paid, the weak think twice.'),
(82, 'UniqueShieldStrInt3', 4325, 'From death springs life.'),
(83, 'UniqueTwoHandMace3', 9032, 'Lumbering as a sea lion, clumsy as a berry-drunk pigeon. That was Erqi. ' || char(13) || '
It mattered little. When Erqi''s maul fell true, so did its target.'),
(84, 'UniqueAmulet9', 38807, 'Forged from the blood of countless wars, ' || char(13) || '
its thirst has only begun.'),
(85, 'UniqueGlovesStr2', 20971, 'Ride with pride,' || char(13) || '
strike with vengeance,' || char(13) || '
live with honour.'),
(86, 'UniqueGlovesDexInt2', 25943, 'Fly like a Storm Crow, crush like a Rhoa'),
(87, 'UniqueBootsDex1', 7444, 'Do not let them step on your feet. Keep them at bay.'),
(88, 'UniqueDagger3', 41951, 'Unwieldy and garish became graceful' || char(13) || '
and deadly in Ungil''s nimble hands.'),
(89, 'UniqueDagger3x', 44076, '"Recommend further production of Prototype #122. It makes' || char(13) || '
an ideal weapon for our suppression troops and guards."'),
(90, 'UniqueBootsDex2', 36374, 'The wyrm draws warmth from the fires of desire.'),
(91, 'UniqueBootsInt4', 23221, 'The dead man walks where' || char(13) || '
the living fear to tread.'),
(92, 'UniqueBootsInt4x', 43877, '"Outpost Twelve has been abandoned. On the bright side, I expect the plague of apparitions' || char(13) || '
to serve as ample defence for the relics we left behind." ' || char(13) || '
- Administrator Qotra'),
(93, 'UniqueOneHandMace1', 18427, '"I know how to say ''faster'' and ''attack''' || char(13) || '
in Karui, Marak and Ezo."' || char(13) || '
- Voll of Thebrus'),
(94, 'UniqueBodyInt1', 30680, 'Shavronne''s apparel became ever more extravagant' || char(13) || '
as her body and soul became ever more corrupted.'),
(95, 'UniqueBow4', 29432, '"The rain of a thousand quills that whittle' || char(13) || '
present into past, life into death."' || char(13) || '
- Rigwald of the Ezomytes'),
(96, 'UniqueBow4x', 37153, '"How did you manage to lodge arrows in every single test subject' || char(13) || '
and researcher in Lab Three simultaneously?" ' || char(13) || '
- Doctor Bircus'),
(97, 'UniqueBow5', 45238, '"The Spirit of War knows nothing of good and evil.' || char(13) || '
It knows only destruction."' || char(13) || '
- Sekhema Asenath'),
(98, 'UniqueTwoHandAxe3', 5370, 'Swinging through the air, it sings' || char(13) || '
of sundered, severed, missing things.'),
(99, 'UniqueTwoHandMace4', 21218, 'Cursed is the star whence it came.'),
(100, 'UniqueWand2', 16747, 'A chilling hush, a scraping sound' || char(13) || '
Of things no more entombed in ground.' || char(13) || '
A shambling horde is on its way' || char(13) || '
To crush the very light of day.'),
(101, 'UniqueWand2x', 40312, '"Simply incredible. I caught an escaping test subject myself with' || char(13) || '
swarms of burning skulls. Delightful!" ' || char(13) || '
- Researcher Olesya'),
(102, 'UniqueBow6', 15594, 'As a soldier you want to get close to enemy archers.' || char(13) || '
That is not the case when fighting the Maraketh.'),
(103, 'UniqueBootsDex3', 20512, 'Alive but not unscathed, Victario fled' || char(13) || '
as slaughter blossomed at the gates.'),
(104, 'UniqueBodyStr2', 33894, 'It is safer to be feared than to be loved.'),
(105, 'UniqueBodyDex2', 22735, 'I''m hiding, yet everyone knows where I am.'),
(106, 'UniqueBodyDex3', 38780, 'The blasted oak stands forever.'),
(107, 'UniqueBodyInt2', 30677, 'He who sows an ember shall reap an inferno.'),
(108, 'UniqueBow7', 2659, 'Mark us with mercy, then press on with care,' || char(13) || '
Execute us steadily, notch away at our despair.'),
(109, 'UniqueBow7x', 59440, '"How did you manage to lodge arrows in every single test subject' || char(13) || '
and researcher in Lab Three simultaneously... again?" ' || char(13) || '
- Doctor Bircus'),
(110, 'UniqueClaw1', 40666, 'The darkest clouds clashed and coupled,' || char(13) || '
giving birth to four lightning children of hate.'),
(111, 'UniqueShieldStr2', 25522, 'A mighty bulwark, curved and strong' || char(13) || '
A dauntless wall, against the throng' || char(13) || '
All lance and arrow, knocked aside' || char(13) || '
For rout of foe, for turn of tide.'),
(112, 'QuestGlyph1', 14377, 'Its corrugated surface brings a strange tingle' || char(13) || '
to the fingertips. This is no mere decoration.'),
(113, 'QuestGlyph2', 44832, 'When put to the ear it whispers not of' || char(13) || '
the sea, but long dead incantations.'),
(114, 'QuestGlyph3', 13108, 'Its pleasing sheen remains even in shadow,' || char(13) || '
as if it were somehow lit from within.'),
(115, 'QuestAllflame', 44065, 'Distilled from naked ambition and unfettered obsession,' || char(13) || '
the Allflame emanates a silvern warmth like no other, ' || char(13) || '
and engulfs those moths fool enough to embrace it.'),
(116, 'QuestMedicineChest', 32439, 'Doctor "Shaky Hands" Opden travelled with only the' || char(13) || '
finest medicines and antidotes... and a curiously' || char(13) || '
generous supply of opiates.'),
(117, 'QuestPoisonSpear', 32006, 'Maligaro loved his tools, and took great' || char(13) || '
pains to keep them excruciatingly sharp.'),
(118, 'QuestPoisonGem', 61677, 'The withering glare of corruption, made' || char(13) || '
corporeal and pellucid in crystal.'),
(119, 'QuestRibbonSpool', 28470, 'Machinery makes the minions.' || char(13) || '
Minions make the master.'),
(120, 'QuestThaumeticSulphite', 10436, 'Essence of pure thaumaturgy.' || char(13) || '
Apply with trepidation.'),
(121, 'QuestTolmanBracelet', 51032, 'A craftswoman''s ode to' || char(13) || '
fresh hope, a new love.'),
(122, 'QuestIntAmulet', 38611, 'Segregated by treachery, this artefact' || char(13) || '
longs to be reunited with her sisters.'),
(123, 'QuestDexAmulet', 20017, 'While this artefact resonates with power,' || char(13) || '
it is simply a piece in a larger puzzle.'),
(124, 'QuestStrAmulet', 32537, 'A relic of a sundered relationship,' || char(13) || '
it awaits reconciliation with its kin.'),
(125, 'QuestCombinedAmulet', 51391, 'Though its power has been shared, there' || char(13) || '
is still more the Apex might unlock.'),
(126, 'QuestGoldenHand', 34703, 'An open palm raised in peace,' || char(13) || '
cut down by the slaves of war.'),
(127, 'QuestInfernalTalc', 8381, '"A Virtue Gem is a raging thunderstorm imprisoned within a single raindrop.' || char(13) || '
Infernal Talc simply lets the storm out." - Malachai the Soulless'),
(128, 'QuestSewerKeys', 50984, 'To enter a city''s bowels is to be' || char(13) || '
privy to its best-kept secrets. '),
(129, 'QuestTowerKey', 28720, 'God will only offer the door.' || char(13) || '
Man must choose whether to open it.'),
(130, 'QuestBust1', 18249, 'The Emperor honours Hector Titucius as Supreme Servant.' || char(13) || '
"Strength in purpose is strength in deed."'),
(131, 'QuestBust2', 54906, 'The Emperor honours Gaius Sentari as Supreme Servant.' || char(13) || '
"A man''s thoughts are his shackles. A man''s thoughts are his wings."'),
(132, 'QuestBust3', 44822, 'The Emperor honours Marceus Lioneye as Supreme Servant.' || char(13) || '
"The road to Glory is paved with Sacrifice."'),
(133, 'UniqueBodyDex4', 17632, 'To catch an animal, think like an animal.'),
(134, 'UniqueStaff2', 60488, 'Shed by the winged beast of night,' || char(13) || '
A scaly frost-encrusted thorn.' || char(13) || '
All who feel its wintry light' || char(13) || '
Shiver in pain at the frozen dawn.'),
(135, 'UniqueHelmetDex3', 31810, 'No metal slips as easily through the fingers as gold.'),
(136, 'UniqueShieldStrInt4', 37488, 'Born from the marriage of ice and sky,' || char(13) || '
the aurora evokes both awe and power.'),
(137, 'UniqueSceptre1', 35171, 'Knowledge brings power, and with power you can' || char(13) || '
grab truth by the throat and shape it as you wish.'),
(138, 'UniqueBodyInt3', 42591, 'My Soul is your Strength' || char(13) || '
My Price is your Blood'),
(139, 'UniqueBodyInt4', 27888, 'Despair hums, softly, deadly, in the bones of my enemies. ' || char(13) || '
Eyes will burn, and souls wither, as they bask in my radiance.'),
(140, 'UniqueClaw2', 26157, 'Fear blisters the heart and thins the blood.' || char(13) || '
Fear squeezes lungs and sets the guts to fester.' || char(13) || '
Fear is the wound left untended.'),
(141, 'UniqueTwoHandSword4', 12481, 'The nobles wanted to take her throne.' || char(13) || '
She let the peasants take their wealth.' || char(13) || '
The peasants wanted to take her wealth.' || char(13) || '
She let the soldiers take their heads.' || char(13) || '
The soldiers wanted to take her head.' || char(13) || '
She sat on her throne and wept.'),
(142, 'UniqueShieldDex3', 48621, '"As long as I see death in my mirror, so will Wraeclast."' || char(13) || '
- Atziri, Queen of the Vaal'),
(143, 'UniqueTwoHandAxe4', 40725, 'To cease the flow of blood is to ' || char(13) || '
choke the rain in the very clouds.' || char(13) || '
Both life and land feel the thirst.'),
(144, 'UniqueBow8', 36727, 'Centuries of development in steel armoursmithing' || char(13) || '
turned the armies of the Eternal Empire' || char(13) || '
into very effective lightning rods.'),
(145, 'UniqueHelmetWreath1', 2536, 'To stand triumphant you must serve' || char(13) || '
no master other than your own ambition.'),
(146, 'UniqueShieldInt2', 51102, 'You carried me through life,' || char(13) || '
The least I can do is carry you through death.'),
(147, 'UniqueDagger4', 60245, 'A heart can be stabbed by thoughts, ' || char(13) || '
If your mind is sharp enough.'),
(148, 'UniqueDagger4x', 22617, '"There is something incredibly satisfying about impaling test' || char(13) || '
subjects with Ethereal Knives. Perhaps it is the sound -' || char(13) || '
the spell, the screams, or both."  - Researcher Olesya'),
(149, 'UniqueMap2', 37779, 'Whispers from a world apart' || char(13) || '
Speak my name beyond the tomb;' || char(13) || '
Bound within the Maelström''s heart,' || char(13) || '
Will they grant me strength or doom?'),
(150, 'UniqueBodyDexInt1', 29601, '"...The discomfort shown by the others is amusing, but none' || char(13) || '
can deny that my work has made quite the splash..."' || char(13) || '
- Maligaro''s Journal'),
(151, 'UniqueRing6', 45109, 'Existence is infinite' || char(13) || '
A weave of the living and dead' || char(13) || '
Beyond the understanding' || char(13) || '
Of the many mortal threads'),
(152, 'UniqueShieldStr3', 13842, 'Fire dances with those who doubt' || char(13) || '
Licks the skin and flesh from the fearful' || char(13) || '
Where there is no fear' || char(13) || '
There is no flame'),
(153, 'UniqueMap3', 9859, 'For his sins he was hunted in his sleep,' || char(13) || '
judgement wrought of twisted nightmare.' || char(13) || '
The Coward bound his dreams to stone, awaiting' || char(13) || '
another to walk the path of true atonement.'),
(154, 'UniqueSceptre2', 35432, 'Left in her tomb by the lynch mob, ' || char(13) || '
the flame inside still blazed bright after her death, ' || char(13) || '
and so did hers.'),
(155, 'QuestPage1', 63557, '"The Vaal were even more steeped in gem culture than ' || char(13) || '
our Emperor and his ''Gemlings''. It''s an obsession ' || char(13) || '
as old as civilisation itself."' || char(13) || '
- Icius Perandus'),
(156, 'QuestPage2', 57726, '"A communion... but with what? By all accounts, ' || char(13) || '
it wasn''t God that the Vaal were trying to reach."' || char(13) || '
- Icius Perandus '),
(157, 'QuestPage3', 9341, '"A waking Nightmare. ' || char(13) || '
Madness of the mind? ' || char(13) || '
Or madness of the flesh?"' || char(13) || '
- Icius Perandus '),
(158, 'QuestPage4', 12886, '"Siosa, your Slavery will cause them to overlook you. ' || char(13) || '
Your Karui Way will guide you. ' || char(13) || '
Your Humanity will shame us all."' || char(13) || '
- Icius Perandus '),
(159, 'UniqueMap4', 5194, 'Curious, she shook it then,' || char(13) || '
And tiny screams emerged.' || char(13) || '
Curiouser, she shook again,' || char(13) || '
And an eerie silence purred.'),
(160, 'UniqueHelmetDex4', 18041, 'There was no hero made out of Starkonja''s death,' || char(13) || '
but merely a long sleep made eternal.'),
(161, 'QuestDecanter', 59560, '"Man is blinded by the mud of his corporeal self. Only' || char(13) || '
through the transformation of the material into the' || char(13) || '
spiritual can we hope to taste the full body of life."' || char(13) || '
- Malachai the Soulless'),
(162, 'QuestPlum', 58804, 'As succulent as blood, as sweet as power.'),
(163, 'QuestSpikeKey', 19035, 'A sigil of thaumaturgy graven in granite.'),
(164, 'UniqueClaw3', 44995, '"For the life of the flesh will always be in the blood."' || char(13) || '
- Atalui, Vaal Priestess'),
(165, 'UniqueTwoHandMace5', 57016, 'The faithful may continue to serve, even after death.'),
(166, 'UniqueHelmetDex5', 41988, 'Nature respects the strong' || char(13) || '
And paints the snow red' || char(13) || '
With the blood of the weak'),
(167, 'UniqueHelmetDex5x', 4654, '"Test subject walked right through the poison gas defenses, and attempts to slow her' || char(13) || '
failed. Suppression troop six, the ''Furious Flagellants,'' have been sent to intervene."'),
(168, 'UniqueShieldStrInt5', 25712, 'My bearer shall be guarded by flame,' || char(13) || '
for I am the phoenix, forever radiant in glory.'),
(169, 'UniqueBodyInt5', 55682, 'The night of a thousand ribbons' || char(13) || '
To remember the day of a thousand flames' || char(13) || '
When Sarn burned' || char(13) || '
And was born again'),
(170, 'UniqueBodyDex5', 33816, 'Forget your kite shield. Just put the biggest man' || char(13) || '
 in the field between you and the archers.'),
(171, 'UniqueBootsInt5', 56155, '"They say that you should take life''s troubles in your stride.' || char(13) || '
Some men have a longer stride than others."' || char(13) || '
- Gaius Sentari'),
(172, 'UniqueBootsStrDex2', 12713, '"Sirrius flew on wings of light, faster than wind, faster' || char(13) || '
than thought. But try as he might to outrun the darkness,' || char(13) || '
it was there, at every turn, waiting for him."' || char(13) || '
- Azmerian legend'),
(173, 'UniqueStaff3', 8311, 'Forged to rule the waves and tide' || char(13) || '
Destined to serve the monkey''s paw' || char(13) || '
Strong as a tower of iron' || char(13) || '
Deft as the needle doubt'),
(174, 'UniqueBodyStrInt3', 45873, 'When Solaris closes her burning eye' || char(13) || '
At the end of time,' || char(13) || '
the world will perish in ice.'),
(175, 'UniqueBodyInt7', 27849, 'The greatest mistakes cause suffering ' || char(13) || '
long after they have been made'),
(176, 'UniqueGlovesStrDex3', 15059, 'One warrior, any armour.'),
(177, 'UniqueGlovesInt3', 42063, 'Cool the head and cool the blade.'),
(178, 'UniqueGlovesInt4', 31221, '"You shall hang, in blissful agony, on my every note."' || char(13) || '
- Kalisa, Prima Donna of Sarn'),
(179, 'UniqueGlovesInt4x', 21949, '"Our superiors were getting anxious for results, and lowered security standards.' || char(13) || '
A single attempt of a spell with this unexpected power destroyed an entire floor."'),
(180, 'UniqueGlovesInt5', 50338, 'Death is beautiful. Let not the elements' || char(13) || '
mar it with their clumsy ways.'),
(181, 'UniqueGlovesInt6', 59545, 'Absolute corruption empowers absolutely.'),
(182, 'UniqueGlovesDexInt3', 9258, 'The roar of the heavens' || char(13) || '
Strikes more than fear' || char(13) || '
Into the hearts of Man'),
(183, 'UniqueGlovesDexInt4', 43312, 'The cards don''t choose life and death' || char(13) || '
That''s up to the player.'),
(184, 'UniqueHelmetDex6', 10379, 'A lad with no fear of the pest ' || char(13) || '
Let rats fill his helmet in jest ' || char(13) || '
When they picked his skull clean' || char(13) || '
Where his head should have been' || char(13) || '
Was naught but a vermin-filled nest!'),
(185, 'UniqueHelmetInt5', 7308, 'You are the powerless master of fire.'),
(186, 'UniqueHelmetInt6', 431, 'Many still hold the belief that the fossilised bones' || char(13) || '
of Vaal sacrifices have magical properties.'),
(187, 'UniqueHelmetStr3', 49196, 'When you have slain all of your enemies,' || char(13) || '
what is left to fear?'),
(188, 'UniqueHelmetStr3x', 7970, '"While Prototype #3 does imbue its wearer with strength to match the original,' || char(13) || '
the first researcher to don it burst into flames when he walked into sunlight..."'),
(189, 'UniqueRapier2', 22108, 'Many a collector of rarities discovered to his dismay' || char(13) || '
that the intelligent spirit in this sword' || char(13) || '
does not like to share its master''s attention'),
(190, 'UniqueRing7', 34155, 'The ring I stole,' || char(13) || '
My finger they took,' || char(13) || '
