Cut their curses short,' || char(13) || '
As I drained their spirit' || char(13) || '
And stole their soul.' || char(13) || '
A blessing is often a curse.'),
(191, 'UniqueMap5', 62395, 'Laughs of all the twisted' || char(13) || '
Echo through these halls of gold.' || char(13) || '
