They wander, forever uncontrolled.'),
(192, 'UniqueMap5x', 59068, '"Suppression troop two, the ''Martyrs for Science,'' were able to seal' || char(13) || '
the portals before Outpost Four was overrun. Only three men survived."'),
(193, 'UniqueHelmetWreath1v2', 9035, 'The second trial brought most to their knees.' || char(13) || '
But not you.'),
(194, 'UniqueHelmetStrDex3', 54988, 'May you never hear it toll.'),
(195, 'UniqueClaw4', 27689, 'Desperate times demand desperate measures.'),
(196, 'UniqueClaw4x_', 21322, '"An absurdly vicious weapon in the hands of our test subjects. It seems to' || char(13) || '
channel the desperate will to live. Intriguing." ' || char(13) || '
- Researcher Olesya'),
(197, 'UniqueClaw5', 48344, 'It''s cold and dark where the leviathan sleeps.' || char(13) || '
Colder and darker than death.' || char(13) || '
- Old Sailor''s saying'),
(198, 'UniqueClaw6_', 31538, '"When the hyena howls thrice' || char(13) || '
death is sure to follow."' || char(13) || '
-Maraketh Wisdom'),
(199, 'UniqueRing8', 51191, 'Gentle anger, raging calm.'),
(200, 'UniqueAmulet10', 28295, 'The world is but a piece of parchment, blank and symmetric. ' || char(13) || '
We label each side: one Good, one Evil; one Black, one White. ' || char(13) || '
The divine truth, however, is that both are one and the same. ' || char(13) || '
-Jaetai, Vaal Advisor'),
(201, 'UniqueAmulet10x', 59425, '"A rare unequivocal success, Prototype #11 causes wounds to heal so quickly' || char(13) || '
the type Delta test subject actually survived the entire testing regimen."'),
(202, 'UniqueRing9', 7504, 'By its light, Lori led her young charges to safety ' || char(13) || '
and bound up their wounds. ' || char(13) || '
Her sword arm was iron, yet her heart gentle ' || char(13) || '
and proof against hate.'),
(203, 'UniqueHelmetStrDex4', 11337, '"What lies beneath your feet?!"' || char(13) || '
"Sacred ground, watered with tears of blood!"'),
(204, 'UniqueBodyInt8', 12158, 'When dead men rise and darkness falls' || char(13) || '
Only faith can be your walls' || char(13) || '
Walls of Light, not of brick' || char(13) || '
Twice as strong and twice as thick'),
(205, 'UniqueBodyStrInt4', 62835, '. . . and the Light faded and hope waned' || char(13) || '
Zahndethus cast aside his faith' || char(13) || '
and embraced the darkness.'),
(206, 'UniqueWand3', 24324, '"The trick is to give nothingness,' || char(13) || '
and to receive everything in return."' || char(13) || '
- Inquisitor Maligaro'),
(207, 'UniqueOneHandSword3', 4276, 'Though the Vaal revered peace, it would have ' || char(13) || '
been suicide for any culture to rouse them to war.' || char(13) || '
