(208, 'UniqueMap6', 64514, 'RISE, SISTER!'),
(209, 'UniqueMap7', 39962, 'The Treasures of the Tides wait' || char(13) || '
in agony at the End of the World.'),
(210, 'UniqueAmulet12', 23227, 'Flavour Text goes HERE'),
(211, 'UniqueMap8', 5855, 'Flavourful flavour text is flavourful.'),
(212, 'UniqueRing10', 25360, 'The portrait reflected his pain,' || char(13) || '
a pain that she could never see.'),
(213, 'UniqueMap9', 59174, '"Here the soil is more deadly than any swing of the axe."' || char(13) || '
- Oba of the Karui, Conqueror of Corruption.'),
(214, 'UniqueOneHandAxe1', 19630, 'It is too easy for the soul to escape from an open heart.'),
(215, 'UniqueOneHandAxe1x', 23876, '"Nothing feels so smooth in the hand as Prototype #66.' || char(13) || '
Results like these may justify everything we do here."'),
(216, 'UniqueMap10', 52015, 'They flew, and leapt, and clambered over,' || char(13) || '
They crawled, and swam, and slithered under.' || char(13) || '
Still its ancient secrets await unclaimed' || char(13) || '
And of this hidden temple, only legends remain.'),
(217, 'UniqueMap11', 57810, 'For this beauty,' || char(13) || '
beauty without strength,' || char(13) || '
chokes out life. '),
(218, 'Amulet13', 27850, '"A bit short in the arm, are you? ' || char(13) || '
Then you''ll be short of a head soon enough."' || char(13) || '
- Daresso the Daring'),
(219, 'Amulet14', 52797, '"We are the soldiers of Faith, armoured in devotion.' || char(13) || '
Let the sinners come, for we - the Pure - shall endure!"' || char(13) || '
- Voll of Thebrus, at the Battle of the Bridge'),
(220, 'Amulet15', 57177, '"Grind your words into sharp thoughts.' || char(13) || '
Grind your thoughts into the sharpest of deeds."' || char(13) || '
- Victario, the People''s Poet'),
(221, 'Ring11', 53316, 'God blesses those who bless themselves.'),
(222, 'Ring11x', 51528, '"Our first Prototype. Proof that it can be done.' || char(13) || '
The Templars will give us everything we need,' || char(13) || '
now... but we must keep our true goal secret."'),
(223, 'Ring12', 20220, 'To truly appreciate life you must be there when it ends'),
(224, 'Ring13', 17647, '"Shavronne held Sanity in her right' || char(13) || '
hand and Revelation in her left.' || char(13) || '
Brutus chose the left hand."' || char(13) || '
- Kadavrus, Surgeon to the Umbra'),
(225, 'Belt5', 33117, 'As long as the soul is unfettered, so is the body.'),
(226, 'UniqueMap12', 4732, 'Flavourful flavour text is flavourful.'),
(227, 'UniqueBootsDex4', 10210, '"Sharks thrash and swirl ' || char(13) || '
To the pounding drum of their frenzied hearts' || char(13) || '
As they dance in the waters red."' || char(13) || '
-Lavianga, Guardian of the Karui Way'),
(228, 'UniqueTwoHandMace6', 27038, 'Command like a king and nothing will stand in your way.'),
(229, 'UniqueTwoHandMace6x', 57835, '"Prototype #599 offers an incredible defensive power, but at a cost.' || char(13) || '
What underlying physics are at play here, I wonder?"'),
(230, 'UniqueOneHandSword4', 52233, 'Her purpose seems done; the oath is fulfilled.' || char(13) || '
Rust dulls her smirk with the last demon killed.' || char(13) || '
The embers grow dim and yet hope burns her lips:' || char(13) || '
"An old flame renewed can define our eclipse!"'),
(231, 'UniqueAmulet16', 30695, 'Forge your Perseverance on the Anvil of Faith.'),
(232, 'UniqueSceptre3', 59163, 'With death as my ally, all the world is within my grasp.'),
(233, 'UniqueRing14', 14030, '"Our warehouses are bursting. Our vaults are full.' || char(13) || '
But our minds are still hungry."' || char(13) || '
- Medici Perandus, Prefect to the Treasury'),
(234, 'UniqueRing15', 57629, 'Let winter come. It will only make my fire burn brighter.'),
(235, 'UniqueFlask1', 62906, 'Knowledge is fermented in pain and loss' || char(13) || '
Distilled with reflection' || char(13) || '
To quench the thirst of those' || char(13) || '
who dream of enlightenment'),
(236, 'UniqueHelmetInt7', 53453, 'Turning, gazing, blinking,' || char(13) || '
behold the eyes of void.' || char(13) || '
