your mind is destroyed.'),
(237, 'UniqueBodyDex6', 23916, 'Shedding away her regal past, ' || char(13) || '
she forged a new destiny. ' || char(13) || '
Sacrificing the ephemeral joys of man, ' || char(13) || '
she embraced the eternal grasp of nature. ' || char(13) || '
