she found peace at last.'),
(238, 'UniqueBootsDemigods1', 53489, 'Victory is on the march and nothing can stop it.'),
(239, 'UniqueBootsDemigods2', 32266, 'Those who burn for victory burn for eternity.'),
(240, 'UniqueBow9', 55178, 'It hunts; as silent as falling snow, as deadly as the tempest.'),
(241, 'UniqueBow9x', 11705, '"Beware. Prototype #91 is haunted by a strange miasma,' || char(13) || '
an odour of evil. Nothing can shield the senses." ' || char(13) || '
- Researcher Arn'),
(242, 'UniqueBodyStr3', 47536, 'Tears of blood, aching heart,' || char(13) || '
My dear Isildria must depart.'),
(243, 'UniqueTwoHandAxe6', 36926, 'Fire and Anarchy are the most reliable agents of change.'),
(244, 'UniqueTwoHandAxe6x', 43382, '"The remarkable imbalance of Prototype #848 leads to uncommon' || char(13) || '
power or speed when striking."'),
(245, 'UniqueBodyStrDex1', 20013, 'There is no safer place' || char(13) || '
Than the Belly of the Beast'),
(246, 'UniqueHelmetDexInt2', 55354, 'For none of us are as cruel as all of us.'),
(247, 'UniqueHelmetDexInt2x', 2036, '"Prototype #412 seems to bear much in' || char(13) || '
common with Thought Extractor technology."'),
(248, 'UniqueHelmetStrInt3', 57476, 'Where top is bottom and weak is strong.'),
(249, 'UniqueBootsDex5', 49892, '"Death can be outrun with these, but beware!' || char(13) || '
In running from death, you may forget to live."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 202'),
(250, 'UniqueBootsStrDex3', 22668, '"A lick of shadow may ease ' || char(13) || '
the petty frictions of one''s life."' || char(13) || '
- Inquisitor Maligaro'),
(251, 'UniqueBootsDexInt2', 6172, '"Bored gods won''t give you any favours."' || char(13) || '
- Maraketh proverb'),
(252, 'UniqueTwoHandAxe5', 32010, 'Bargg Wurmkin once severed the heads ' || char(13) || '
of seven men in a single cleave.'),
(253, 'UniqueTwoHandMace7', 58077, '"The finest prosperity grows from the direst' || char(13) || '
carnage. Such is the nature of progress."' || char(13) || '
- Doryani of the Vaal'),
(254, 'UniqueTwoHandSword5', 35418, 'Heavy as guilt.' || char(13) || '
Beautiful as temptation.' || char(13) || '
Painful as betrayal.'),
(255, 'UniqueDagger5', 48634, 'Maligaro considered his work an Art, ' || char(13) || '
and his subjects his canvas.'),
(256, 'UniqueDagger6', 36464, 'A fang of hellfire, chip of frost,' || char(13) || '
Lightning flickers, blade embossed.' || char(13) || '
With dagger clenched, into the fray!' || char(13) || '
Or draw it out, and cast away.'),
(257, 'UniqueRapier3', 12655, 'Galla had an answer to everything.'),
(258, 'UniqueSceptre4', 11609, '"We Ezomytes made promises that this ' || char(13) || '
Eternal God would have us break." ' || char(13) || '
- Thane Rigwald'),
(259, 'UniqueSceptre5', 10556, 'Beneath the blue,' || char(13) || '
The stillness permits' || char(13) || '
The drowned dead' || char(13) || '
To regret their choices.'),
(260, 'UniqueBow10', 55032, 'The eldritch storm descended upon us, and bruised lightning' || char(13) || '
rained down. Metal withered and flesh melted before its' || char(13) || '
arcane power. There was no escape, no shelter. Only despair.'),
(261, 'UniqueFlask2', 31606, 'Doedre Darktongue knew the Way of the Thaumaturge.' || char(13) || '
In order to receive, one must give... without hesitation.'),
(262, 'UniqueAmulet17', 17483, '"Marylene stroked the medallion at her breast ' || char(13) || '
before every duel and every cast of the die." ' || char(13) || '
- Victario, the People''s Poet'),
(263, 'TestUniqueRing1', 31951, '"When one stares into the depth of the flavour text' || char(13) || '
file, one will gain no knowledge, only an addiction' || char(13) || '
to speculation." - Maligaro, Grand Trolllord'),
(264, 'UniqueBodyDex7', 59088, '"I carry neither food nor drink. I rely on the charity' || char(13) || '
of my fellow wayfarers. Dead men are generous men."' || char(13) || '
- Taruk of the Wildmen'),
(265, 'UniqueTwoHandSword6', 17341, 'Give yourself to the flames and your name' || char(13) || '
will burn in the minds of men forever.'),
(266, 'UniqueTwoHandSword6x', 13120, '"Ice and flame antagonized in the essence of a prototype.' || char(13) || '
What once burned now chills the soul." ' || char(13) || '
- Researcher Arn'),
(267, 'UniqueClaw7', 57725, 'Tread lightly, lest their vigil find you.' || char(13) || '
Speak softly, lest their reason fend you.' || char(13) || '
Cut gently, lest their spirit haunt you.'),
(268, 'UniqueOneHandSword5', 45059, '"A raging Solaris seared and contorted the orb''s surface. ' || char(13) || '
A despairing Lunaris filled the scars with her tears. ' || char(13) || '
Yet Viridi remained, trapped within, forever more."' || char(13) || '
 - Azmerian Creation Myth'),
(269, 'UniqueBodyStrDex3', 19310, '"When your back is against the wall,' || char(13) || '
And your opponent is bleeding you dry,' || char(13) || '
There is only one appropriate response:' || char(13) || '
Unbridled, overwhelming violence."' || char(13) || '
- Daresso, the Sword King'),
(270, 'UniqueShieldStrInt6', 45135, '"Let the evil ones deliver their fiery darts.' || char(13) || '
This time I''ve put my faith in steel."' || char(13) || '
 - Commander Santoni of the Damned Brotherhood'),
(271, 'UniqueRing16', 64588, 'Ming slew Tranquillity' || char(13) || '
Took Chaos for his wife' || char(13) || '
And on Her immortal finger' || char(13) || '
He placed his Heart'),
(272, 'UniqueBodyStrDex2', 42605, '"There''s nothing like imminent death' || char(13) || '
to galvanize one''s purpose in life."' || char(13) || '
- Malachai the Soulless.'),
(273, 'UniqueRing17', 11472, 'The Empress gave Romira two sons' || char(13) || '
Born of his brother''s seed' || char(13) || '
Romira threw her a banquet' || char(13) || '
A perfidious meal indeed.'),
(274, 'UniqueOneHandAxe2', 42465, 'Born of love, forged in blood' || char(13) || '
He burned as a torch in the blackest night' || char(13) || '
She shone as ice in the winter sun' || char(13) || '
Proudly, fiercely' || char(13) || '
At their mother''s side, forever.'),
(275, 'UniqueBelt6', 35251, 'The sun''s fury, trapped' || char(13) || '
in pillars of blazing light,' || char(13) || '
Explodes from its cage.'),
(276, 'UniqueBootsDex6', 8799, 'Anticipation, preparation, exhilaration, celebration.'),
(277, 'UniqueRing18', 49628, '"From Frost''s ice-bound pass' || char(13) || '
Berek taunted and jeered' || char(13) || '
Until furious Flame scaled the mountain' || char(13) || '
Berek escaped through the thaw' || char(13) || '
And Frost''s tortured moans."' || char(13) || '
- Berek and the Untamed'),
(278, 'UniqueRing19', 13530, '"Berek hid from Storm''s lightning wrath' || char(13) || '
In the embrace of oblivious Frost' || char(13) || '
Repelled by ice, blinded by blizzards' || char(13) || '
Storm raged in vain' || char(13) || '
While Berek slept."' || char(13) || '
- Berek and the Untamed'),
(279, 'UniqueRing20', 26559, '"With Flame licking at his heels' || char(13) || '
Berek berated the clouds' || char(13) || '
Until vengeful Storm spewed forth his rains' || char(13) || '
And Berek held on tight' || char(13) || '
As Fire screamed and steamed' || char(13) || '
And fled."' || char(13) || '
- Berek and the Untamed'),
(280, 'UniqueRing21', 20937, '"Moon after moon did Berek make fools' || char(13) || '
Of the great and Untamed Three' || char(13) || '
Until malice for a Brother' || char(13) || '
Slew the hatred of the Other' || char(13) || '
And Berek did hunt' || char(13) || '
Alone and free."' || char(13) || '
- Berek and the Untamed'),
(281, 'UniqueFlask3', 51345, '"Kaom fought and killed for his people.' || char(13) || '
Kaom bled for his people.' || char(13) || '
And so the people gave, the people bled,' || char(13) || '
So their King might go on."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(282, 'UniqueFlask4', 2301, '"When the Ancestors fill your cup,' || char(13) || '
It is only good manners to drink your fill."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(283, 'UniqueFlask4x', 59015, '"An intriguing paradox."'),
(284, 'UniqueHelmetDexInt3', 18135, '"It is the Gull that delivers Man unto Ancestor.' || char(13) || '
The consumer of our flesh. The seeder of our' || char(13) || '
souls unto the earth. We give the Gull his life.' || char(13) || '
The Gull gives us our Way."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(285, 'UniqueBelt7', 31790, '"A man''s soul rules from a cavern of bone, learns and' || char(13) || '
judges through flesh-born windows. The heart is meat.' || char(13) || '
The head is where the Man is."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(286, 'UniqueBelt7x', 5438, '"A type Delta test subject escaped with Prototype #18. He was last seen' || char(13) || '
ten times the height of a man and crashing straight through walls."'),
(287, 'UniqueBelt8', 59142, '"She begged the Earth to spare her Son;' || char(13) || '
Out of love the Earth agreed.' || char(13) || '
To the other Elements she did not speak' || char(13) || '
And out of spite They plotted."' || char(13) || '
- Berek and the Untamed'),
(288, 'UniqueBodyDexInt2', 14836, 'When the throat roars,' || char(13) || '
As eyes weep,' || char(13) || '
When the hand grips hard' || char(13) || '
With trembling fingers,' || char(13) || '
When belly twists' || char(13) || '
