That is the work' || char(13) || '
Of the Defiant Heart.'),
(289, 'UniqueDescentDagger1', 35485, 'Into darkness, horror, madness...' || char(13) || '
So goes the descent.'),
(290, 'UniqueDescentWand1', 62812, 'Into darkness, horror, madness...' || char(13) || '
So goes the descent.'),
(291, 'UniqueDescentShield1', 40572, 'Into darkness, horror, madness...' || char(13) || '
