(298, 'UniqueDescentBelt1', 58906, 'Into darkness, horror, madness...' || char(13) || '
So goes the descent.'),
(299, 'UniqueDescentQuiver1', 33648, 'Into darkness, horror, madness...' || char(13) || '
So goes the descent.'),
(300, 'UniqueWand4', 33708, 'From the smallest seeds' || char(13) || '
To the tallest redwoods,' || char(13) || '
Life endures in Wraeclast.'),
(301, 'UniqueSceptre6', 52795, 'My Iron heart will beat when yours is rust. ' || char(13) || '
I take your Strength, your power, your lust. ' || char(13) || '
By Iron Will alone I set my mind in motion.' || char(13) || '
Through endless storms of fervent devotion.'),
(302, 'UniqueGlovesDemigods1', 636, 'Though the battle has been long,' || char(13) || '
Victory is at hand.'),
(303, 'UniqueBootsStrDex4', 57280, 'The cursed ghosts march forever,' || char(13) || '
On their hopeless last endeavour.'),
(304, 'UniqueMap13', 34844, 'So the raiders danced,' || char(13) || '
leading their foe ever west,' || char(13) || '
towards certain death.'),
(305, 'UniqueMap14', 55431, 'A cool map, for a cool guy.'),
(306, 'UniqueBodyStr4', 17931, 'Give me neither havens nor solace;' || char(13) || '
They are for the weak and frightened.' || char(13) || '
Instead, light the path to greatness,' || char(13) || '
So that I may begin my bright pursuit.'),
(307, 'UniqueShieldDex4', 18711, 'An eye for an eye. A curse for a curse.'),
(308, 'UniqueShieldInt3', 44421, 'The last thing Arimagius heard was the' || char(13) || '
jester''s mocking bells in the distance.'),
(309, 'UniqueShieldStrDex2', 61929, 'Doomed to plunder forever.'),
(310, 'UniqueShieldStrInt7', 22560, 'What is below is like what is above,' || char(13) || '
and what is above is like what is below,' || char(13) || '
to accomplish the miracles of one thing.'),
(311, 'UniqueGlovesDex3', 909, 'The fury of the forge determines' || char(13) || '
the ferocity of the metal.'),
(312, 'UniqueDagger7', 7711, 'Unnatural Origins, unnatural benefits, unnatural cost.'),
(313, 'UniqueOneHandAxe3', 11512, 'The eagle knows nothing' || char(13) || '
but the scream and the strike.'),
(314, 'UniqueOneHandAxe4', 5478, 'Kill us with kindness, cut us with care.'),
(315, 'UniqueOneHandMace2', 26841, 'Old Bartek still stands, but is courteously ' || char(13) || '
bowing to the might of time.'),
(316, 'UniqueWand5', 40734, 'And the thunder rumbled on and on.'),
(317, 'UniqueStaff4', 55444, 'You''ve no reason for fear when you''re a root in a fen' || char(13) || '
- Old Ezomyte saying.'),
(318, 'UniqueStaff4x', 1135, '"Attempt #306: The power I can sense in this ancient branch' || char(13) || '
still eludes me. Perhaps if I attach some string and a hook..."'),
(319, 'UniqueDagger8', 44505, 'Calling it poison would imply' || char(13) || '
that it was even edible.'),
(320, 'UniqueHelmetStrInt4', 3016, 'The seeds of greatness are planted in darkness,' || char(13) || '
Watered by suffering,' || char(13) || '
Tended by desperation,' || char(13) || '
And bloom steel flowers of victory.'),
(321, 'UniqueHelmetStrInt4x', 21143, '"Prototype #722 might look like a helmet, but I believe it to be something else' || char(13) || '
entirely. The visions it shows the wearer... are beyond mortal endurance..."'),
(322, 'UniqueFishingRod1', 64656, 'Give a man a fish, and you can feed him for a day.' || char(13) || '
But give a fish a man, and you can feed it for a month.'),
(323, 'UniqueHelmetDexInt4', 52634, '"The ice seared his naked feet' || char(13) || '
As the lightning stilled his heart,' || char(13) || '
But it was the flames upon his lover''s face' || char(13) || '
That roused him to vengeance."' || char(13) || '
- From ''The Three Dragons'' by Victario of Sarn'),
(324, 'UniqueGlovesStrInt1', 1270, 'Captivity breeds creativity.'),
(325, 'UniqueOneHandMace3', 28166, 'Look the storm in the eye and you will have its respect.'),
(326, 'UniqueStaff5', 48856, 'The whispers of the dead' || char(13) || '
Carry wisdom for the living,' || char(13) || '
If you are willing to give your life' || char(13) || '
To listen.'),
(327, 'UniqueGlovesDexInt5', 29890, '"As the serpent shuns thought,' || char(13) || '
It shuns fear.' || char(13) || '
It strikes with the speed of wrath' || char(13) || '
And the skill of compulsion."' || char(13) || '
- Deshret, The Red Sekhema'),
(328, 'UniqueBootsStrInt2', 28029, 'Alberon walked among the accursed,' || char(13) || '
and they welcomed him.'),
(329, 'UniqueBootsStrInt2x', 33290, '"Starving test subject became completely incapable of exerting force.' || char(13) || '
However, after being fed, he began to poison everything he touched..."'),
(330, 'UniqueHelmetStrDex5', 62681, 'All that was left of the Iron King was his bleached skull.' || char(13) || '
Yet it was all the Iron King needed.'),
(331, 'UniqueRing23', 18264, 'The darker the eye, the more diligent the watched.'),
(332, 'UniqueRing23x', 55099, '"So close, yet frustratingly distinct. Something more is going on here..."'),
(333, 'UniqueGlovesStrDex4', 40577, '"The gems are strangely human at times.' || char(13) || '
They simply love to be held."' || char(13) || '
- Doryani, First Seer to the Queen'),
(334, 'UniqueQuiver3', 37992, '"Why waste such a fine arrow on just one man?" ' || char(13) || '
- Kiravi, Vaal Archer'),
(335, 'UniqueQuiver4', 53605, '"It''s a rare man that has eyes in the back of his head."' || char(13) || '
- Kiravi, Vaal Archer'),
(336, 'UniqueStaff6_', 38697, '"To shake a hand is to double your power."' || char(13) || '
- Jaetai, Queen''s Advisor'),
(337, 'UniqueBootsDex7', 23147, '"Those who dance are considered insane ' || char(13) || '
by those who cannot hear the music."' || char(13) || '
- Atziri, Queen of the Vaal'),
(338, 'UniqueBelt9', 51185, '"You can invite them but you can never be ' || char(13) || '
sure who will come knocking."' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(339, 'UniqueFlask5', 53881, '"Death needs not your understanding. It needs only your loyalty." ' || char(13) || '
- Atziri, Queen of the Vaal'),
(340, 'UniqueGlovesStr3', 22077, '"The heart is the herald. ' || char(13) || '
It will tell me when it is best to strike."' || char(13) || '
- Atziri, Queen of the Vaal'),
(341, 'UniqueGlovesStr3x', 32190, '"One of our researchers cut himself on Prototype #2,' || char(13) || '
and he has not stopped screaming for months..."'),
(342, 'UniqueBodyStrDexInt1', 26874, '"When you have nothing to hide,' || char(13) || '
you have nothing to fear."' || char(13) || '
- Atziri, Queen of the Vaal'),
(343, 'UniqueHelmetDexInt5', 41964, '"A queen should be seen, admired, but never touched."' || char(13) || '
- Atziri, Queen of the Vaal'),
(344, 'UniqueTwoHandAxe7', 61579, '"I do not believe in disguising my disappointment."' || char(13) || '
- Atziri, Queen of the Vaal'),
(345, 'UniqueBodyInt9', 45692, 'Reap what others have sown' || char(13) || '
Muster them from their graves' || char(13) || '
Parade them for your pleasure' || char(13) || '
Zealots in mortis enslaved'),
(346, 'AtziriFragment1_1', 63270, 'Look to our Queen, for she will lead us into the light.'),
(347, 'AtziriFragment1_2', 57651, 'Only those who aspire can dare to hope.'),
(348, 'AtziriFragment1_3', 48209, 'The light without pales in comparison to the light within.'),
(349, 'AtziriFragment1_4', 58228, 'The Vaal shall never fear the setting of our sun.'),
(350, 'AtziriFragment2_1', 28743, 'We are but dogs, howling at an uncaring moon.'),
(351, 'AtziriFragment2_2', 21645, 'Look to our Queen, for she will lead us from the darkness.'),
(352, 'AtziriFragment2_3', 51223, 'It is only the blind who can live in darkness.'),
(353, 'AtziriFragment2_4', 27240, 'When we prostrate ourselves to the night, we worship mortality.'),
(354, 'ProphecyFragment1', 40247, 'Mouth of the Masses, whose greatness spreads by our breath and touch,' || char(13) || '
who feeds the starving with the starved, the strong with the weak.'),
(355, 'ProphecyFragment2', 43496, 'Lord of the Wild, of the feral and frenzied,' || char(13) || '
of the uncivilized, the untamed, the untouched.'),
(356, 'ProphecyFragment3', 3721, 'The Infinite Mind, unbound by the tethers of sanity,' || char(13) || '
whose thirst for knowledge is all-consuming,' || char(13) || '
whose every word stands our hair on end.'),
(357, 'ProphecyFragment4_', 25859, 'She of Many Bodies, whose very flesh unites all,' || char(13) || '
whose dark whispers draw forth our souls, unfettered.'),
(358, 'ShaperFragment1', 56546, 'Enter the crucible. The nexus of' || char(13) || '
nothingness and equilibrium of eternity.'),
(359, 'ShaperFragment2', 25999, 'Enter the crucible. The nexus of' || char(13) || '
nothingness and equilibrium of eternity.'),
(360, 'ShaperFragment3', 52766, 'Enter the crucible. The nexus of' || char(13) || '
nothingness and equilibrium of eternity.'),
(361, 'ShaperFragment4', 11561, 'Enter the crucible. The nexus of' || char(13) || '
nothingness and equilibrium of eternity.'),
(362, 'ElderFragment1', 31828, 'Freedom is won, not given.'),
(363, 'ElderFragment2', 17780, 'Plagues are exhausted, not cured.'),
(364, 'ElderFragment3', 50359, 'Webs are torn, not untangled.'),
(365, 'ElderFragment4', 45905, 'Corruption is purged, not cleansed.'),
(366, 'UberElderFragment1', 36378, 'Beauty is in the eye of the creator.'),
(367, 'UberElderFragment2', 25595, 'Understanding leads to mastery.'),
(368, 'UberElderFragment3', 22646, 'Fear drives survival.'),
(369, 'UberElderFragment4', 12776, 'What is not cannot cause harm.'),
(370, 'SirusFragment1', 54897, 'He sought to be the best,' || char(13) || '
but lost his family.'),
(371, 'SirusFragment2', 39840, 'He sought God,' || char(13) || '
but lost himself.'),
(372, 'SirusFragment3', 22381, 'He sought a kingdom,' || char(13) || '
but lost his people.'),
(373, 'SirusFragment4', 62116, 'She sought to bring salvation,' || char(13) || '
but lost her compassion.'),
(374, 'UniqueSceptre7', 17488, 'The result of the catalytic reaction would be either immortality for all,' || char(13) || '
or death for all. It was a risk Doryani was willing to take.'),
(375, 'UniqueWand6', 13643, '"Stone still, amidst the reeds,' || char(13) || '
breath fogging in the iron cold air. ' || char(13) || '
he sits, he waits, he watches. ' || char(13) || '
A piscatorial vigil, sat by the river, ' || char(13) || '
his cathedral, his patience his unanswered prayer."' || char(13) || '
- Jojoba Mansell, bard, angler, adventurer'),
(376, 'UniqueBeltDemigods1', 64476, 'The bindings of the victorious' || char(13) || '
wrap around the throats of the defeated.'),
(377, 'UniqueQuiver5', 22910, 'Mist of breath' || char(13) || '
Icing to lips and throat' || char(13) || '
As the warm ones choke and fall' || char(13) || '
Upon the frozen wasteland.'),
(378, 'UniqueBodyStrInt5', 42415, 'Only light may banish the shadows from this land' || char(13) || '
And the black lies wrapped around your heart'),
(379, 'UniqueQuiver6', 48869, 'A Karui woman''s place was not the ' || char(13) || '
battlefield, but the hearth.' || char(13) || '
Hyrri changed all of that.'),
(380, 'UniqueBow11', 37891, '"Toasted or frozen' || char(13) || '
Or twitching in the light' || char(13) || '
I''m not fussy' || char(13) || '
And neither is Death."' || char(13) || '
- Koralus Doomfletch'),
(381, 'UniqueOneHandSword6', 58973, '"Hyaon the ''Red Wolf''' || char(13) || '
Howling mad' || char(13) || '
Cloaked in blood' || char(13) || '
A banner to his legion' || char(13) || '
A terror to his foes."' || char(13) || '
- Garivaldi, Chronicler to the Empire'),
(382, 'UniqueBootsStr2', 60701, 'Don''t flinch. It''s a waste of good hitting time.'),
(383, 'UniqueChest1', 53331, '"Political power is an illusion.' || char(13) || '
Popular power is fickle.' || char(13) || '
Financial power is real and loyal."' || char(13) || '
- Cadiro Perandus, Lord of the Coin'),
(384, 'UniqueChest2', 53248, '"Treasure that which the Ancestors have gifted you.' || char(13) || '
For it can be gone between one breath and the next."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(385, 'UniqueChest3', 32376, '"A fool steps into the unknown.' || char(13) || '
An explorer finds his way back again."' || char(13) || '
- Malachai, Thaumaturge Laureate'),
(386, 'UniqueOneHandSword7', 36199, 'Maligaro was transformed by Raulo''s love.' || char(13) || '
Thaumaturgy allowed Maligaro to return the favour.'),
(387, 'UniqueQuiver7', 12732, 'In this chaotic world' || char(13) || '
The rewards of the Soul' || char(13) || '
Outlast the rewards of the Flesh.'),
(388, 'UniqueQuiver7x', 17823, '"The theft of another''s vitality is short-lived, but sweet.' || char(13) || '
It calls to me, bidding me abandon all other pursuits."' || char(13) || '
- Researcher Arn'),
(389, 'UniqueFlask6', 50487, 'Your reach exceeds your grasp.'),
(390, 'UniqueDescentOneHandSword1', 41640, 'Into darkness, horror, madness...' || char(13) || '
So goes the descent.'),
(391, 'UniqueDescentClaw1', 34672, 'Into darkness, horror, madness...' || char(13) || '
So goes the descent.'),
(392, 'UniqueStaff7', 54810, 'The right to rule demands mental acuity,' || char(13) || '
a strong arm,' || char(13) || '
And a tenacious sense of justice.'),
(393, 'QuestKaomGem', 31436, '"Fear becomes Hatred. ' || char(13) || '
Hatred becomes Fury. ' || char(13) || '
Thus is Man transformed ' || char(13) || '
from Martyr to Maker." ' || char(13) || '
- Malachai'),
(394, 'QuestDaressoGem', 21088, '"It is a cruel joke that ' || char(13) || '
Man was born with more ' || char(13) || '
Intent than Life."' || char(13) || '
- Malachai'),
(395, 'UniqueMap15', 19262, 'We all began life in darkness, we shall all end it there.'),
(396, 'UniqueShieldDexInt1', 25850, 'One wrong step triggers destruction. ' || char(13) || '
Agony slowly dominates the will to live.'),
(397, 'UniqueShieldDex5', 47149, 'Crimson burn''d the star of sadness,' || char(13) || '
All was woe that seem''d but gladness.'),
(398, 'UniqueOneHandSword8', 7421, 'Being lost is a trick of the mind.' || char(13) || '
A man always has two directions available to him.' || char(13) || '
Forward and through.'),
(399, 'UniqueRing24', 43866, 'Fire makes the perfect blossom in the endless night.'),
(400, 'UniqueDagger9', 57935, 'Nothing is pure.' || char(13) || '
Slice open the Innocent' || char(13) || '
And spill a thousand Sins.'),
(401, 'UniqueFlask7', 57604, '"Yesterday I was clever, so I wanted to change the world.' || char(13) || '
Today I am wise, so I am changing myself."' || char(13) || '
-Rumi of the Vaal'),
(402, 'UniqueFlask7x', 58015, '"The most terrifying split second of my life." ' || char(13) || '
- Researcher Graven'),
(403, 'UniqueOneHandSword9', 20628, 'She dances a dance beneath the shade,' || char(13) || '
The twilight shroud her only blade,' || char(13) || '
Who now hears her feathersteps flowing?' || char(13) || '
Beneath the stars, the moondrops glowing.'),
(404, 'UniqueOneHandSword9x', 49070, '"Once we armoured the test subject heavily enough to test Prototype #502, he proceeded' || char(13) || '
to fight his way out. I don''t know what we expected." ' || char(13) || '
- Researcher Graven'),
(405, 'UniqueBootsStrInt3', 32231, 'Become one with the unstoppable flame. '),
(406, 'UniqueBootsDex8', 42078, 'It takes a clear mind to outrun a storm. '),
(407, 'UniqueBodyStrDex4', 4768, '"The Consort of Chaos descended,' || char(13) || '
swiftly, brutally, artfully, she consumed the living,' || char(13) || '
leaving naught behind but a Rosemarie bloom,' || char(13) || '
to celebrate the massacre."' || char(13) || '
- Blass, explorer, hunter, adventurer'),
(408, 'UniqueWand7', 16046, 'Apep''s poison entraps, encircles,' || char(13) || '
and engulfs the leaking mind of Man.'),
(409, 'UniqueOneHandAxe5', 35728, '"More blood... hack open flesh... must drink..."'),
(410, 'UniqueGlovesStrInt2', 43042, 'What is freedom but a clean slate' || char(13) || '
in an unclean world?'),
(411, 'UniqueGlovesStrDex5', 42666, 'What is greed but trading a mountain of death' || char(13) || '
for a sliver of life?'),
(412, 'UniqueGlovesDexInt6', 37241, 'What is fear but a snuffed torch' || char(13) || '
and death in the wind?'),
(413, 'UniqueTwoHandAxe8', 11746, 'Let it grow and gather inside them,' || char(13) || '
Let it flow through their veins.' || char(13) || '
Don''t waste a drop.'),
(414, 'UniqueTwoHandAxe8x', 49025, '"Why is Prototype #67 never in the vault it should be?' || char(13) || '
Either we''re keeping faulty logs, or..." ' || char(13) || '
- Researcher Graven'),
(415, 'UniqueTwoHandSword7', 29806, 'Soon, the pleas for mercy were muted.' || char(13) || '
Only one voice remained.' || char(13) || '
Laughing.'),
(416, 'UniqueSceptre8', 33097, 'Feed on the light of the living,' || char(13) || '
Bring darkness to all I see,' || char(13) || '
Until we are one in shadow.'),
(417, 'UniqueQuiver8', 17523, 'Hit them hard. Hit them once.'),
(418, 'UniqueMap16', 58616, 'The grandest and greatest ever to fight,' || char(13) || '
Divine the champions stand tall.' || char(13) || '
But match their power, best their might,' || char(13) || '
And even the immortal may fall.'),
(419, 'UniqueRing25', 1955, 'When the wind blows, ' || char(13) || '
Know which way to bend' || char(13) || '
and watch the others break.'),
(420, 'UniqueRing25x', 16766, '"As much as Prototype #20 hints at some deep alternate physics, we cannot afford' || char(13) || '
to expend any more test subjects. Experiments halted."' || char(13) || '
- Administrator Qotra'),
(421, 'UniqueShieldInt4', 2174, 'Open your eyes and you will see the cracks in your enemy''s walls.' || char(13) || '
Open your mind and you will see the cracks in your enemy''s plans.'),
(422, 'UniqueTwoHandSword8', 53673, 'So the seed of hate was born,' || char(13) || '
Evil forged and Hope forsworn.'),
(423, 'UniqueShieldDex6', 59383, 'The horrors we''ve encountered are nothing' || char(13) || '
compared to the horrors we haven''t.'),
(424, 'UniqueChestMap9', 39362, 'The objects Oba valued more than his life,' || char(13) || '
sealed from the corruption that ultimately took it.'),
(425, 'UniqueRingDemigods1', 43260, 'The victor stands tall with hand held high,' || char(13) || '
unwavering, unblinking, unstoppable.'),
(426, 'UniqueStaff8', 13764, 'One for each corner of the great Vinktar Square.'),
(427, 'UniqueAmuletVictor1', 26980, 'A glimpse of victory' || char(13) || '
is all you need to win.'),
(428, 'UniqueStaff9', 22051, 'Touch not the thorn, for only blood and pain await.'),
(429, 'UniqueStaff9x', 61741, '"Physical forces and flames seem to share some innate bond.' || char(13) || '
What logic lies beneath the veil of reality?"'),
(430, 'UniqueBelt10', 33753, 'Nothing is as vivid as the rage of battle'),
(431, 'UniqueBelt10x', 32264, '"A legion of forty soldiers attempted to break into Outpost Five and' || char(13) || '
steal Prototype #659. What do they know that we do not?"'),
(432, 'UniqueBelt11', 27075, 'At knifepoint, a moment''s hesitation means death.'),
(433, 'UniqueBelt11x', 51660, '"I cannot fathom the mysteries of Prototype #16. It did nearly nothing until I' || char(13) || '
brought it to [RESTRICTED]. It makes no sense!"' || char(13) || '
- Researcher Graven'),
(434, 'UniqueRing26', 50884, 'Hear no evil.'),
(435, 'UniqueWand8', 24977, 'If it''s worth doing once, it''s worth doing twice.'),
(436, 'UniqueAmulet18', 58527, 'Gentle anger, raging calm.'),
(437, 'UniqueShieldDexInt2', 25938, '"Look around you. What do you see? ' || char(13) || '
Corruption, perversion, sin?' || char(13) || '
No. It is progress. ' || char(13) || '
You simply lack the means to see it." ' || char(13) || '
- Inquisitor Maligaro'),
(438, 'UniqueBelt12', 26900, '"Our genius will pave the way forward.' || char(13) || '
May all who are worthy be improved!"' || char(13) || '
- Inquisitor Maligaro'),
(439, 'UniqueHelmetStrInt5', 53264, 'Every rule has an exception.'),
(440, 'UniqueQuiver9', 63896, 'Fear not the dark, the song of night,' || char(13) || '
Hear not the arch, the falling cry.' || char(13) || '
My giving sun, fight no more,' || char(13) || '
Rest alone, my grand nightfall.'),
(441, 'UniqueGlovesStrDex6', 63826, 'Your lies are our strength.' || char(13) || '
Your threats are our laughter.' || char(13) || '
Your hate is our infinity' || char(13) || '
The fire rises!'),
(442, 'UniqueBelt13', 38600, 'In battle, virtue matters not. ' || char(13) || '
Only victory.'),
(443, 'UniqueRing27', 56289, '"To us mere mortals, time is slippery. ' || char(13) || '
I''m just evening things out." ' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(444, 'UniqueRing28', 17684, 'Rage is a big part of courage.'),
(445, 'UniqueBow12', 53994, 'The hunt continues when the prey falls.'),
(446, 'UniqueAmulet19', 52666, 'Fate''s smile, man''s ruin.'),
(447, 'UniqueRing29', 31569, 'A gift from Valako,' || char(13) || '
appointing Kiloava as the Herald of War.' || char(13) || '
A title Kaom claimed when he ended Kiloava''s bloodline.'),
(448, 'UniqueRing30', 52458, 'A gift from Tasalio, God of Water,' || char(13) || '
to the chieftain Rakiata.' || char(13) || '
Kaom took Rakiata''s head and hand' || char(13) || '
so that his warriors'' axes might rise and fall like the waves.'),
(449, 'UniqueRing30x', 21955, '"Likely our closest to the original, yet Prototype #22 still falls short.' || char(13) || '
Are these objects actually somehow resisting our efforts?"'),
(450, 'UniqueRing31', 13936, 'A gift from Ngamahu,' || char(13) || '
a sign to the Karui to spread like fire.' || char(13) || '
Given to Akoya, but inherited by Kaom with the swing of his axe.'),
(451, 'UniqueBodyStrDex5', 51379, 'The truth lies inside every man, if you dig around. ' || char(13) || '
Many a confession was found in the bowels of Axiom.'),
(452, 'UniqueHelmetInt8', 14970, '"The sharper the pain, the sharper the mind. ' || char(13) || '
A curious paradox."	' || char(13) || '
- Shavronne of Umbra'),
(453, 'UniqueSceptre9', 42679, '"A sprinkle of liquid encouragement is often required ' || char(13) || '
to garnish the perfect confession." ' || char(13) || '
- Brutus, Warden of Axiom'),
(454, 'UniqueFlask8', 15836, 'A sip will freeze your lips,' || char(13) || '
A swig will chill your heart,' || char(13) || '
A glass will still your soul.'),
(455, 'UniqueBodyStr5', 18391, 'Some would question if the risk was worth it.' || char(13) || '
The rest were already dead.'),
(456, 'UniqueAmulet20', 60685, 'As you have lived, so you shall die ' || char(13) || '
forever trying to keep up with me. ' || char(13) || '
Your blood on these hands of mine' || char(13) || '
forever makes me the public enemy.'),
(457, 'UniqueHelmetInt9', 8222, 'A scar of the flesh you''ll never forget,' || char(13) || '
A scar of the mind you''ll never remember.'),
(458, 'UniqueHelmetStrDex6', 40672, 'The beasts we fear the most' || char(13) || '
are the ones who dwell in total darkness.'),
(459, 'UniqueGlovesStrInt3', 11880, 'Far south, the winter crawls under the skin.' || char(13) || '
Below the snow, adrift wanderers sleep.'),
(460, 'UniqueChestGrandmaster1', 5126, 'The champions rest now, free from pain,' || char(13) || '
Their souls ascend to the sun.' || char(13) || '
Some parting gifts are all that remain,' || char(13) || '
Their eternal vigil is done.'),
(461, 'UniqueRing32', 20641, 'In a blaze of glory,' || char(13) || '
An anomaly defying all odds' || char(13) || '
The "unkillable" beast met the divine' || char(13) || '
And Ventor met his latest trophy.'),
(462, 'UniqueRing33', 17068, 'When the axe finally fell, Seryl shared his pain,' || char(13) || '
and the last thought that flickered through his' || char(13) || '
fading mind was her broken, shattered scream.'),
(463, 'UniqueBelt14', 17979, 'With her cold resolve' || char(13) || '
And burning sacrifice' || char(13) || '
The Eternal twins arose.'),
(464, 'UniqueStaff10', 45493, 'That which was broken may yet break.'),
(465, 'UniqueChestBarrel1', 43194, 'Just an ordinary barrel, used to store sensible objects. ' || char(13) || '
Not swarms of things.'),
(466, 'UniqueBodyDexInt4', 1345, '"Every life is a story.' || char(13) || '
If you''re not writing your own,' || char(13) || '
you''d better know who''s writing it for you!"' || char(13) || '
- Victario, the People''s Poet'),
(467, 'UniqueDagger10', 54473, 'The brightest flames cast the darkest shadows.'),
(468, 'UniqueAmulet21', 10517, 'The first light to grow in the primordial darkness.'),
(469, 'UniqueStaff11', 25696, 'The best way to gain the element of surprise,' || char(13) || '
is to let your enemy learn your plans,' || char(13) || '
and execute them - twice.'),
(470, 'UniqueOneHandAxe6', 60814, 'Relentless fury' || char(13) || '
Sunder my every foe' || char(13) || '
Fuel my boiling blood'),
(471, 'UniqueOneHandMace4', 64581, '"You''ll have my riches when you pry them' || char(13) || '
from my cold, dead hands!"' || char(13) || '
"That''s how I prefer it."'),
(472, 'UniqueGlovesStr4', 53368, 'Doryani''s ingenuity raised the Vaal Empire' || char(13) || '
to unprecedented heights. His curiosity' || char(13) || '
reduced it to ruins and bones.'),
(473, 'UniqueOneHandMace5', 21856, 'To neither ebb nor flow,' || char(13) || '
but weather the rising tide,' || char(13) || '
outlast, unshifting and unshifted,' || char(13) || '
until the waters recede and we stand together.'),
(474, 'UniqueSceptre10', 18448, '"All are welcome in Hinekora''s eternal home." ' || char(13) || '
- Karui Proverb'),
(475, 'UniqueOneHandSword10', 57678, 'As a maiden I was bound; as a crone was I scorned' || char(13) || '
Promised power rarely found, delivered fury fairly thorned.' || char(13) || '
Not enough?...Fine. Now I am become both and another' || char(13) || '
To take your hand and cradle your talents, not smother' || char(13) || '
The consummate flames. So hush, dear, say not a word. ' || char(13) || '
Bequeathed, betrayed...beloved. At last, I am the third.'),
(476, 'UniqueOneHandSword11', 39381, 'Master yourself before you seek to master others.'),
(477, 'UniqueGlovesStr5', 34071, '"I like my vassals at sword point,' || char(13) || '
but my enemies as close as the hilt."' || char(13) || '
- Emperor Chitus'),
(478, 'UniqueBodyDexInt3', 21115, 'Use the dead to stave off death,' || char(13) || '
An armour of bones and rot.' || char(13) || '
Hanging on with bated breath,' || char(13) || '
One lapse and all for naught.'),
(479, 'UniqueBodyDexInt3x', 33567, '"Further research must be done on Prototype #282.' || char(13) || '
There is power here, if it can be tapped."'),
(480, 'UniqueFlask9', 20018, 'A sprinkle of hunger, a spoonful of menace' || char(13) || '
and three generous cups of Might.'),
(481, 'UniqueClaw8', 4705, 'To the Maraketh, death is as intimate as love.'),
(482, 'UniqueStaff12', 52665, 'Guard your darkest thoughts well, for they are' || char(13) || '
the cracks through which the Nightmare crawls.'),
(483, 'UniqueAmulet22', 27973, 'A shimmering symbol of Purity, clear as water,' || char(13) || '
but I know better than most how quickly' || char(13) || '
Purity can succumb to Corruption.' || char(13) || '
How quickly water turns to blood.' || char(13) || '
- Victario, the People''s Poet'),
(484, 'UniqueAmulet23', 30413, 'In my dream, a voice spoke to me. It said:' || char(13) || '
''My reach knows no bounds.' || char(13) || '
All that is pure is destined to rot.' || char(13) || '
All that lives is destined to serve.''' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(485, 'UniqueBodyStr6', 10501, '"The Virtue Gems are a gift from the land, ' || char(13) || '
our land, and we will not let our gifts' || char(13) || '
be destroyed by savages."' || char(13) || '
- Marceus Lioneye'),
(486, 'UniqueGlovesStrInt4', 58115, '"I ask not for understanding,' || char(13) || '
only for forgiveness' || char(13) || '
for what I am about to do.' || char(13) || '
There will be blood on these shackles yet."' || char(13) || '
- Anonymous carving, Axiom Prison.'),
(487, 'UniqueWand9', 40353, 'Life persisted,' || char(13) || '
hardened, twisted.'),
(488, 'UniqueWand9x', 6527, '"Energy redirected is energy imbalanced.' || char(13) || '
Prototype #78 serves as a prime example."'),
(489, 'UniqueTwoHandAxe9', 5940, 'A King and his people are linked together' || char(13) || '
like a soul and a beating heart.' || char(13) || '
Both can be severed by a same edge, ' || char(13) || '
then forged anew.'),
(490, 'UniqueJewel1', 64389, 'In the end, time comes for all of us.' || char(13) || '
It just comes for some much sooner.'),
(491, 'UniqueRingVictors', 38185, 'The road to victory is paved' || char(13) || '
with the bones of the defeated.'),
(492, 'UniqueJewel2', 47871, '"True Thaumaturgy can only be learned ' || char(13) || '
by the brilliant or the mad."' || char(13) || '
- Shavronne of Umbra'),
(493, 'UniqueJewel3', 53666, 'If you do not learn from a won battle' || char(13) || '
then you have already lost the war.'),
(494, 'UniqueJewel4', 58377, 'A gentle hand rarely leaves a mark on the world.'),
(495, 'UniqueJewel5', 29038, 'The shield crab does not leave his shell unless it is forced to, ' || char(13) || '
and even then, it knows to keep its distance.'),
(496, 'UniqueJewel6', 54266, 'The carpenter who picks up a blade is not mad.' || char(13) || '
He''s ambitious.'),
(497, 'UniqueJewel7', 46406, 'The Darktongue clan has long let their undead feed at the table' || char(13) || '
with their slaves, and occasionally on them.'),
(498, 'UniqueJewel8', 32804, 'Observe and master your surroundings.'),
(499, 'UniqueJewel9', 33006, 'A helping hand has long reach.');
INSERT INTO "FlavourText" ("_row", "Id", "__col1", "Text") VALUES
(500, 'UniqueJewel10', 61954, 'Nature provides its own solutions.'),
(501, 'UniqueJewel11', 54728, '"The swallow flew fast and took many turns,' || char(13) || '
spilling a seed where no plant had grown before. ' || char(13) || '
This seed grew and grew until the desert became fertile and abundant. ' || char(13) || '
Your mind is like this seed." ' || char(13) || '
- Maraketh Proverb'),
(502, 'UniqueJewel13_', 56115, 'Even the strongest of steel can be made to bend.'),
(503, 'QuestRedBanner', 17724, 'When the sun sets, the plains should be red.'),
(504, 'UniqueJewel14', 4080, 'When you get down to it, we''re all really just' || char(13) || '
an unprepared meal for something or someone.'),
(505, 'UniqueJewel15', 4726, 'The strongest Karui tribes left the longest impressions on the land.' || char(13) || '
Their symbols served as guidance many generations' || char(13) || '
after their creators had been buried deep beneath the earth.'),
(506, 'UniqueJewel16', 27275, 'When you create life from nothing, ' || char(13) || '
sometimes things get a little stuck in between.'),
(507, 'UniqueJewel17', 46024, 'The strong grow stronger still.'),
(508, 'UniqueJewel18', 26681, 'When you throw iron weapons against an iron wall' || char(13) || '
you only make the wall grow thicker.'),
(509, 'UniqueJewel19', 62345, 'Never pet a feeding Hellion.'),
(510, 'UniqueJewel20', 4044, 'It''s hard to stay still when you''re engulfed in flames.'),
(511, 'UniqueJewel20x', 60785, '"Does this jewel accomplish nothing? If only we could somehow' || char(13) || '
master cold and turn it to our own ends..." ' || char(13) || '
- Lead Researcher Ksaret'),
(512, 'UniqueCorruptedJewel1', 20281, 'The hotter something burns, the less is left at the end.'),
(513, 'UniqueCorruptedJewel2', 38372, 'Ill will is the greatest of burdens.'),
(514, 'UniqueCorruptedJewel3', 58386, 'In sickness, the insane becomes sane.'),
(515, 'UniqueJewel22', 10365, 'And lo, Nick said unto his disciples:' || char(13) || '
"It May Be Crazy Broken"' || char(13) || '
And his disciples replied' || char(13) || '
"Meh"' || char(13) || '
And made it anyway.'),
(516, 'UniqueJewel24', 41510, 'The first green shoots of Spring are the most resilient,' || char(13) || '
and the most vulnerable.'),
(517, 'UniqueJewel24x', 60830, '"Distribute Prototype #723 to the guards. Perhaps their survival rate will increase."'),
(518, 'UniqueJewel25', 11188, 'The difference between the master and his apprentice' || char(13) || '
is what they see when they look at the same block of wood.'),
(519, 'UniqueJewel26', 25845, '"If one is an annoyance' || char(13) || '
then a hundred is a threat."' || char(13) || '
- Ancient Karui Proverb'),
(520, 'UniqueJewel28', 8645, 'Each life taken makes the next a little easier.'),
(521, 'UniqueJewel29', 36666, '"Take your time, make all your plans. ' || char(13) || '
Then tell me which plan' || char(13) || '
pulls my axe from your ribs."' || char(13) || '
- Barkhul, the Butcher'),
(522, 'UniqueJewel30', 12114, 'When your thoughts flow like a river, why build a dam?'),
(523, 'UniqueJewel32_', 54462, '"Curiously, as I deepen my understanding of Thaumaturgy,' || char(13) || '
I find I better understand the land we inhabit' || char(13) || '
and everything in it."' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(524, 'UniqueJewel33', 38429, 'Some people live on the suffering of others.'),
(525, 'UniqueJewel34', 62186, 'Working smart and working hard aren''t mutually exclusive.'),
(526, 'UniqueJewel35', 58879, 'Picking a lock takes an immense amount of skill and practice.' || char(13) || '
Breaking it with a hammer takes about three seconds.'),
(527, 'UniqueJewel36', 63945, '"Greatly outnumbered, Deshret dressed her personal guard ' || char(13) || '
in identical garb. When the Empire rode north, Deshret and ' || char(13) || '
her guard took turns revealing themselves, creating the illusion ' || char(13) || '
of speed beyond the capabilities of even the Virtue Gems."' || char(13) || '
- History of the Maraketh'),
(528, 'UniqueJewel37', 45929, 'There is no force without movement.'),
(529, 'UniqueCorruptedJewel4', 27858, 'The Vaal used human sacrifice to power their empire.' || char(13) || '
They, too, eventually sought means to ' || char(13) || '
make their machines run more efficiently.'),
(530, 'UniqueCorruptedJewel5', 53236, 'Atziri went to great lengths to ensure her immortality,' || char(13) || '
but nothing is eternal.' || char(13) || '
'),
(531, 'UniqueCorruptedJewel6', 34993, 'In their final days, every crime was punishable by death.' || char(13) || '
Atziri''s empire ran on blood, but the blood was running dry.'),
(532, 'UniqueJewel41', 31183, 'A sharp eye can be more deadly than a sharp blade.'),
(533, 'UniqueJewel42', 19087, 'A steady hand can hold back an army.'),
(534, 'UniqueJewel43', 10933, 'A quick step can advance great plans.'),
(535, 'UniqueJewel44', 38985, 'The stone may yet bleed.'),
(536, 'UniqueJewel44x', 21314, '"The effect is subtle, but potentially lethal..."'),
(537, 'UniqueJewel45', 41041, 'What you earn is almost as important as what you take.'),
(538, 'UniqueJewel46_', 49704, 'Victory is as simple as being the last one standing.'),
(539, 'UniqueCorruptedJewel7', 52397, 'Even a millennium later, Atziri''s presence' || char(13) || '
casts a shroud over Wraeclast.'),
(540, 'UniqueCorruptedJewel8', 4495, '"The Vaal left a thousand warnings behind.' || char(13) || '
We ignored every single one."' || char(13) || '
- Siosa, the Last Scholar'),
(541, 'UniqueCorruptedJewel9', 40608, 'Few living things survived the cleansing flames.' || char(13) || '
Those that did thrived... ' || char(13) || '
And changed...'),
(542, 'UniqueCorruptedJewel10', 65499, 'Darkness can never be sated.'),
(543, 'UniqueCorruptedJewel11', 35637, 'There is no price you can give eternal life' || char(13) || '
that some would not pay.'),
(544, 'UniqueCorruptedJewel12', 58042, 'Nothing is immune to the Nightmare''s twisted influence.'),
(545, 'UniqueCorruptedJewel13', 23015, 'Beg for forgiveness.'),
(546, 'UniqueCorruptedJewel14', 59420, 'Power always comes with a price.'),
(547, 'UniqueCorruptedJewel14x', 38870, '"You know what to do with this, don''t you?" - Researcher Graven' || char(13) || '
"Kill test subjects for their vitality?" - Researcher Olesya' || char(13) || '
"That is not what he meant." - Researcher Arn'),
(548, 'UniqueCorruptedJewel15', 25594, 'Walls built in a hurry fall in a hurry.'),
(549, 'UniqueCorruptedJewel16', 56481, '"Your fear will overcome you."'),
(550, 'UniqueCorruptedJewel17', 11088, '"Your flesh will fail you."'),
(551, 'UniqueCorruptedJewel18', 54234, '"Your desires will mislead you."'),
(552, 'UniqueRing34', 12352, 'Forged by three brothers' || char(13) || '
so that they may recognize each other' || char(13) || '
across any distance of time or travel.'),
(553, 'UniqueJewel47', 53806, 'The best dancers often make the best fighters.'),
(554, 'UniqueJewel48', 52287, 'Winter provides us with her own weapons,' || char(13) || '
hanging from the eaves of our homes.'),
(555, 'UniqueJewel49', 14360, 'Leaders are not born in times of peace.' || char(13) || '
Leaders are born in ruins and flames.'),
(556, 'UniqueJewel50', 39043, '"I''ve yet to see prayer stop an arrow."'),
(557, 'UniqueJewel51', 8008, 'The Azmeri ascetics learnt the power' || char(13) || '
of going without the body''s ordinary cravings.'),
(558, 'UniqueJewel52', 20403, 'Once you understand how your body truly works' || char(13) || '
you can''t help but treat it better.'),
(559, 'UniqueJewel53', 47980, '"Movement expends energy, but perhaps a little of that energy' || char(13) || '
can be recaptured and... reappropriated."' || char(13) || '
- Inquisitor Maligaro'),
(560, 'UniqueJewel54', 60855, 'For the ambitious, flesh is a limitation.'),
(561, 'UniqueJewel55', 41136, 'True strength can be found anywhere, and in anything.'),
(562, 'UniqueBodyStrInt6', 47366, 'The toughest armour is the trust of your people.'),
(563, 'UniqueDagger11', 63067, 'A tap on the shoulder' || char(13) || '
A peck on the cheek' || char(13) || '
A sip of your wine' || char(13) || '
So red and so sleek'),
(564, 'UniqueDagger12', 51750, '"I''m a painter, and crimson is my chosen hue."' || char(13) || '
- Coralito, Brotherhood of Silence'),
(565, 'UniqueDagger12x', 63203, '"Prototype #131 must never be allowed near anyone who bears a wound, no' || char(13) || '
matter how slight. Even a tiny cut makes it exponentially more dangerous."'),
(566, 'UniqueWand10', 61755, 'The Goat King drank the smoke and ate the flames' || char(13) || '
as his ruin spread across the land.'),
(567, 'UniqueStaff13', 697, '"God''s creations always begin and end' || char(13) || '
with flames and ice.' || char(13) || '
We should count ourselves lucky when we see neither."' || char(13) || '
- Archbishop Geofri'),
(568, 'UniqueClaw9', 38569, 'There are two things to know about fighting:' || char(13) || '
When to swing like crazy, and when to run.'),
(569, 'UniqueShieldStrDex3', 11893, 'The thicker the shell,' || char(13) || '
the greater the beast that hunts it.'),
(570, 'UniqueOneHandAxe7', 5101, 'The fastest way to a man''s heart' || char(13) || '
is through his sternum.'),
(571, 'UniqueOneHandAxe8', 38676, 'Beneath the cold light of the moon,' || char(13) || '
the wing moves faster than the eye.'),
(572, 'UniqueOneHandSword12', 47222, '"She''s pretty, aye. So pretty you''ll' || char(13) || '
want to be with her long after you''re dead."'),
(573, 'UniqueOneHandSword13', 54825, '"May the Blessed Lakishu watch our backs and our wives."' || char(13) || '
- Legionnaire Battle Blessing'),
(574, 'UniqueOneHandMace6', 12721, 'Sure, there''s many a hard man out there.' || char(13) || '
But this''ll soften them up.'),
(575, 'UniqueOneHandMace7', 36211, '"The painful memories are the easiest to recall."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(576, 'UniqueOneHandMace8', 34496, 'I suffer, I long, with thirst to slake.' || char(13) || '
Though countless corpses lie in wake.'),
(577, 'UniqueStaff14', 22941, 'When the storm comes,' || char(13) || '
the safest place to be is the centre.'),
(578, 'UniqueMap2_13', 32377, 'To the east, ' || char(13) || '
it cannot be seen.' || char(13) || '
To the west, ' || char(13) || '
it cannot be touched.' || char(13) || '
To the south, ' || char(13) || '
it cannot be remembered.' || char(13) || '
And to the north, ' || char(13) || '
it cannot be contained.'),
(579, 'ThreeFacesInTheDark', 25667, 'For every threat you spy in the shadows, there are two others you don''t.'),
(580, 'LantadorsLostLove', 11890, '<smaller>{They fought the storm together as one, ' || char(13) || '
Until the longest of days was done. ' || char(13) || '
Their love grew stronger' || char(13) || '
with every breath, ' || char(13) || '
Until it was broken apart in death.}'),
(581, 'TheHermit', 25293, 'The hermit''s only friend is the greenery he can find.'),
(582, 'TheDoctor', 41163, '"They said I needed my head examined, but I''d rather just take yours." - Klopek the Cannibal'),
(583, 'TheMetalsmithsGift_', 6010, '<size:31>{A month''s work, a year''s wages, a foolish shortcut through a Rhoa''s nest, and a grieving bride-to-be, who never received her betrothed''s great gift.}'),
(584, 'TheBattleBorn', 36527, '"No man can best me, no demon can fell me. For I vanquish all with my axe!"'),
(585, 'TheGladiator', 38459, 'The thumb turns down' || char(13) || '
and the crowd roars, ' || char(13) || '
they want death ' || char(13) || '
and the blood is yours.'),
(586, 'TheScholar', 37478, 'It is with the smallest of words that we find the largest of truths.'),
(587, 'TheBrittleEmperor', 33655, '<size:31>{"When Voll spared Malachai, accepting his aid in pursuit of Purity, the strongest faith was infected by Corruption and made brittle as glass."' || char(13) || '
- Victario, the People''s Poet}'),
(588, 'ThePoet', 13049, '<size:27>{God had forsaken the land ' || char(13) || '
And Victario wept.' || char(13) || '
Corruption consumed the land ' || char(13) || '
And Victario''s tears turned to blood.}'),
(589, 'TheCarrionCrow', 38303, 'From death, life. ' || char(13) || '
From life, death. ' || char(13) || '
The wheel turns, ' || char(13) || '
and the corbies wheel overhead.'),
(590, 'Hope', 1378, '<size:31>{The others succumbed to madness and depravity, but Lori fought on. Alone in the darkness, she could still see the dull light of hope''s distant dawn.}'),
(591, 'TheFiend', 49371, '<size:31>{Your era is now,' || char(13) || '
your power unwavered, ' || char(13) || '
soon we will see' || char(13) || '
who the gods truly favoured.}'),
(592, 'BirthOfTheThree', 46909, 'A small token of Her affliction.'),
(593, 'ViniasToken', 48147, 'You can change your name, but you cannot change your history.'),
(594, 'TheSummoner', 46299, 'To own a piece of the Nightmare, you must first belong to the Nightmare.'),
(595, 'TheCataclysm', 47777, '<size:27>{The mighty warriors traded in blows, the nimble archers in arrows, yet it was the brazen thaumaturgists who would bring catastrophe to all.}'),
(596, 'TheHunger', 15797, '"How many lives have you consumed?" ' || char(13) || '
"How many times have you blinked?"'),
(597, 'TheHoarder', 61811, '"More! I want more!" - Faendris, the Insatiable'),
(598, 'TheDrunkenAristocrat', 13271, 'The finer the brew, the harder it is to remember drinking it.'),
(599, 'TheSun', 13590, '<size:31>{Each night, the light dies, and each morning she is born anew, embracing the land in her golden wings.}'),
(600, 'TheWarden', 749, '<size:31>{Brutus'' first innovation as Lord Incarcerator was a weighted chain around every neck so that his prisoners would forever bow to him.}'),
(601, 'TheScarredMeadow', 26851, 'The earth offers nourishment, growth and healing. Unless, of course, the sky has other plans.'),
(602, 'TheDarkMage', 45410, 'With staff in hand' || char(13) || '
and wrath in heart,' || char(13) || '
your soul and corpse' || char(13) || '
shall surely part.'),
(603, 'TheGemcutter', 65145, 'In the hands of a master craftsman, a worthless pebble can adorn the crown of a king.'),
(604, 'TheGambler', 61492, '"I don''t believe in karma. If it were real, I would never win."'),
(605, 'TheLover', 3493, '<size:26>{"I wanted to give you three things. I''ve given you my eternal love. I''ve sung to you my most beautiful song. I''d have given you the moon last, but it couldn''t be found. I hope you''ll accept this instead."}'),
(606, 'ChaoticDisposition', 48160, 'Life isn''t what you make of it, it''s already been made for you.'),
(607, 'TheRoadToPower', 55618, 'A beacon on the horizon; a guiding light, a call for help, or a warning to turn back.'),
(608, 'TheAvenger', 55392, 'Justice comes swift ' || char(13) || '
Equal to the crime ' || char(13) || '
Revenge is a gift ' || char(13) || '
Life for a life ' || char(13) || '
Eye for an eye'),
(609, 'EmperorsLuck', 57480, 'The house always wins.'),
(610, 'UniqueRing35', 33759, 'Each time, it is granted to the most senior captain of the fleet,' || char(13) || '
and each time, the ring soon washes ashore once more, ' || char(13) || '
still wrapped around a severed finger.'),
(611, 'UniqueRing36', 59691, 'To ascend to leadership, the child of a Redblade warlord' || char(13) || '
must pull the band from the still-hot' || char(13) || '
ashes of their father.'),
(612, 'UniqueRing37', 38239, 'When a fallen leader''s body is taken to the funeral peak,' || char(13) || '
those who seek power must ascend together.' || char(13) || '
One returns with the seal. ' || char(13) || '
The rest do not return at all.'),
(613, 'UniqueShieldInt5', 51918, 'The lords of the sea bow to no one.'),
(614, 'UniqueShieldStr4', 37727, 'Blood shed is blood shared.'),
(615, 'UniqueShieldDex7', 50382, 'Embrace the snow or be buried.'),
(616, 'UniqueShieldDemigods', 48769, 'The light of victory burns eternally.'),
(617, 'TimeLostRelic', 17240, 'Time cannot wash away that which cannot be forgotten.'),
(618, 'LuckyConnections', 15336, 'Luck is a fool''s game, and I know plenty of rich fools.'),
(619, 'TheFeast', 42342, 'Shame what happened to my husband. He had such good taste.'),
(620, 'RainOfChaos', 4915, '<size:27>{Fire filled the sky that night ' || char(13) || '
Chaos reigned ' || char(13) || '
Where the shards fell ' || char(13) || '
All was destroyed ' || char(13) || '
-Jozen Kasigi, retelling an urban legend of the Cataclysm}'),
(621, 'TheWatcher', 20716, '<size:31>{Strange eyes on top of spines ' || char(13) || '
Gaze beyond the veil of time ' || char(13) || '
Deep down below the mines ' || char(13) || '
A dream of crimson and of grime}'),
(622, 'TheIncantation', 59357, 'When there is no other choice, even the meekest whisper can bring about the greatest storm.'),
(623, 'CovetedPossession', 24732, 'A taste of power brings a hunger for more.'),
(624, 'TheKingsHeart', 24415, '<size:31>{500 times Kaom''s axe fell, 500 times Kaom''s Heart splintered. Finally, all that remained was a terrible, heartless Fury.}'),
(625, 'AbandonedWealth', 44122, 'When the world burned, the greedy burned with it, while the clever left as paupers.'),
(626, 'TheWind', 57461, '<size:33>{Weaving through the cracks, searching for weaknesses, silent, indiscriminate, leaving sorrow in its wake.}'),
(627, 'ThePact', 60272, '"On this day I mark the first of many agreements that I will have with this land and its people."'),
(628, 'GemcuttersPromise', 42337, '<size:29>{"I swore to use my position to help the people. What good is power when it just accumulates on the already-powerful?" - Erasmus, Imperial Gemcutter}'),
(629, 'TheCelestialJusticar', 21101, 'Wrapped in the glory of the heavens, she comes to mete out justice for the fallen.'),
(630, 'TheChainsThatBind', 41087, 'Scarier than any criminal is an innocent man in chains, for when he breaks free, his revenge will be justified.'),
(631, 'TheArtist', 64384, '"Paint, metal, flesh... A true artist does not limit himself." - Malachai the Soulless'),
(632, 'TheInventor', 27325, 'Jump right in, ' || char(13) || '
But beware ' || char(13) || '
Of things broken ' || char(13) || '
Or beyond compare.'),
(633, 'ThePackLeader', 65235, 'Become the leader you were born to be.'),
(634, 'JackInTheBox', 52905, 'Turn the crank, ' || char(13) || '
close your eyes, ' || char(13) || '
and pray to the gods ' || char(13) || '
for a pleasant surprise.'),
(635, 'TheUnion', 39393, 'On the 21st of Eterni, ' || char(13) || '
two become one, ' || char(13) || '
their light outshines ' || char(13) || '
the setting sun.'),
(636, 'TheQueen', 56268, 'The power of the world, ' || char(13) || '
lies upon your hands.'),
(637, 'Humility', 22285, ' '),
(638, 'TheExplorer', 59391, 'A map is only useful if you know where you stand.'),
(639, 'TheSpoiledPrince', 4868, 'A boy who grows up with everything learns to appreciate nothing.'),
(640, 'TheBetrayal', 18747, 'It''s sad times we live in when a friendship has a price people are willing to pay.'),
(641, 'TheFlorasGift', 21441, 'Sturdy and strong,' || char(13) || '
grown from the stream.' || char(13) || '
The Flora that live here,' || char(13) || '
A combatant''s dream.'),
(642, 'TheSiren', 36834, '<size:26>{At the beck and call' || char(13) || '
of The Siren''s hand,' || char(13) || '
winter ravages' || char(13) || '
the trembling land,' || char(13) || '
and the weight of ice that binds' || char(13) || '
will break the strongest of minds.}'),
(643, 'TheOneWithAll', 42512, '<size:26>{Embrace death to honour the lost,' || char(13) || '
no fear in life no matter the cost. ' || char(13) || '
With one of all we are, ' || char(13) || '
and all of one we trust, ' || char(13) || '
throughout past, present and future... be just.}'),
(644, 'TheLastOneStanding', 6807, 'The strongest emerge from suffering. The toughest bear the most scars. The sole survivor claims the greatest of rewards.'),
(645, 'DoedresMadness', 30607, '"Hold your tongue before I claim it." - Doedre Darktongue'),
(646, 'TheEncroachingDarkness', 48121, 'No matter where your dreams take you, Nightmare follows close behind.'),
(647, 'TheWrath', 15975, '<size:31>{"Daughter of catastrophe, mother of pain. Amongst the filth of Wraeclast, she wanders, and her wrath follows." - Quintoon the Returned}'),
(648, 'TheKingsBlade', 12685, '<size:25>{"To know for what you fight. To get up again when you''ve been struck down. To outmanoeuvre someone faster, trick someone smarter, crush someone stronger. That''s what it takes to claim the crown."' || char(13) || '
- Daresso, the King of Swords}'),
(649, 'UniqueBootsDexInt4', 19162, 'Those Theopolis fatcats put a price on our heads.' || char(13) || '
Let''s see what they''ll pay for their own. '),
(650, 'UniqueBootsStrDex5', 5748, 'Corruption sweeps across this land,' || char(13) || '
but our bloodline is clear.' || char(13) || '
It is our duty to keep it so.'),
(651, 'UniqueBootsStr3', 46250, 'Our home was swallowed beneath ' || char(13) || '
the great mountain for our complacency. ' || char(13) || '
Now we must prove our value to the Molten One ' || char(13) || '
by sating his hunger for life.'),
(652, 'UniqueShieldStr5', 19816, 'The problem with working fresh trolltimber:' || char(13) || '
by the time you''ve carved out one end, ' || char(13) || '
the other has sprouted fresh roots!'),
(653, 'UniqueTwoHandMace8', 4447, 'His flesh had long turned to dust,' || char(13) || '
but his vengeance lived on' || char(13) || '
in every scrap of iron he touched.'),
(654, 'UniqueHelmetDexInt6', 40502, 'A lightless world' || char(13) || '
a silent reign' || char(13) || '
two sightless eyes' || char(13) || '
feed on your pain.'),
(655, 'QuestMalachaisHeart', 65464, 'My heart forces blood through my veins.' || char(13) || '
But one who may bleed may die, and' || char(13) || '
death is no fitting end to genius.'),
(656, 'QuestMalachaisLungs', 62638, 'My lungs breathe the same air as' || char(13) || '
the foolish and the weak. May I be' || char(13) || '
yet another step removed from them.'),
(657, 'QuestMalachaisEntrails', 57768, 'My organs tether me to mortality' || char(13) || '
like a chain. This chain holds me' || char(13) || '
from my true potential.'),
(658, 'QuestTukohamasTooth', 56797, '"The belly cannot hunger for what the eyes cannot see."' || char(13) || '
 - Karui Proverb'),
(659, 'QuestValakosJaw', 26856, '"One day you eat the fish. One day you feed the fish."' || char(13) || '
 - Karui Proverb'),
(660, 'QuestHinekorasHair', 12870, '"What we steal in life we repay in death."' || char(13) || '
 - Karui Proverb'),
(661, 'UniqueHelmetInt10', 40909, 'An angry god is one thing, ' || char(13) || '
but you should really fear a god ' || char(13) || '
with an unpredictable sense of humour.'),
(662, 'UniqueRing38', 24634, 'Leave the world in flames behind you.'),
(663, 'UniqueRing38x_', 56303, '"The flames raced through Lab Five with incredible speed, but were extinguished' || char(13) || '
just as quickly. This could have been much worse." ' || char(13) || '
- Lead Researcher Ksaret'),
(664, 'UniqueClaw10', 27463, 'What drives us to kill, to carve and to shred?' || char(13) || '
What drives us to drink the seething souls of the dead?' || char(13) || '
What drives us to love and to hold, but still go amiss?' || char(13) || '
What drives us to leave this world for the Abyss?'),
(665, 'UniqueClaw10x', 39755, '"Test subject was able to survive the entire process simply by shouting epithets at' || char(13) || '
the researcher. Researcher''s feelings were slightly injured." ' || char(13) || '
- Researcher Graven'),
(666, 'WIP', 23785, 'Work in progress'),
(667, 'UniqueBootsInt6', 56911, 'To fight an enemy on their lands is a tactical mistake. ' || char(13) || '
Make those lands your own, and the mistake becomes theirs.'),
(668, 'UniqueShieldStrInt8', 15190, 'Be not blinded by the light.'),
(669, 'UniqueRing39', 36302, 'A man who changes his loyalties often,' || char(13) || '
soon finds he has none.'),
(670, 'UniqueFlask10', 16205, 'Let blood sear in your veins, ' || char(13) || '
Let the pain push outwards and turn away your enemy''s blows.'),
(671, 'Talisman1_1', 56498, '"I know where we found our belief in' || char(13) || '
the First Ones. I see it every time I walk' || char(13) || '
the untouched forests and hills. The' || char(13) || '
primordial world is still here. With us."'),
(672, 'Talisman1_2', 18372, '"We held our trust in the First Ones long' || char(13) || '
before we learned runes. Long before we' || char(13) || '
were shown the ways of cities and roads."'),
(673, 'Talisman1_3', 47069, '"This land was always harsh and brutal,' || char(13) || '
ever seeking ways to kill and maim us.' || char(13) || '
We had to grow and change to survive,' || char(13) || '
but each clan had its own ideas how..."'),
(674, 'Talisman1_4', 29877, '"A great rift formed, between clans,' || char(13) || '
between families. Those that remained' || char(13) || '
resolved to endure times of struggle,' || char(13) || '
if it meant we could keep our ways."'),
(675, 'Talisman1_5', 12744, '"Those that departed sought the way of' || char(13) || '
cities and roads. Theirs would be a path' || char(13) || '
fraught with danger and hardship, as they' || char(13) || '
set out to find and build a new home."'),
(676, 'Talisman1_6', 12113, '"When they set out to find and build' || char(13) || '
Ezomyr, they encountered creatures of' || char(13) || '
deadly variety and intent. Many died,' || char(13) || '
for none yet knew how to fight back."'),
(677, 'Talisman1_7', 19909, '"Lysanda of Myr was but a girl on that exodus.' || char(13) || '
Ezomyr almost met its end before it began...' || char(13) || '
but she could not hear that deadly lure. She' || char(13) || '
took the Siren''s head with her bare hands."'),
(678, 'Talisman1_8', 49474, '"It turned out, Lysanda made for an excellent' || char(13) || '
vanguard - a light, evasive girl who could scout' || char(13) || '
and lead the way. The people came to see her' || char(13) || '
as their guide, their hope, and then... their leader."'),
(679, 'Talisman1_9', 26690, '"Those that swore loyalty to Lysanda, that' || char(13) || '
forged ahead with her to clear the way.' || char(13) || '
became known as the first Knights...' || char(13) || '
armoured, battered, and courageous."'),
(680, 'UniqueAmulet24', 34418, 'Shackled fires dance about;' || char(13) || '
Might within from force without.'),
(681, 'UniqueJewel56', 11697, 'The prisoners of the empire raised their shackled hands.' || char(13) || '
Begging to be delivered from Corruption.' || char(13) || '
The rebellion smote their chains,' || char(13) || '
And gave them the freedom to choose corruption for themselves.'),
(682, 'UniqueJewel57', 36238, 'Ondar not only betrayed his emperor,' || char(13) || '
He betrayed his friend.' || char(13) || '
And in his dying moments, Chitus ensured,' || char(13) || '
That Ondar felt the full weight of his guilt.'),
(683, 'UniqueJewel58', 16337, 'With a fire burning brash in his golden eye,' || char(13) || '
Marceus fired his arrow into the pitch-dark sky,' || char(13) || '
And seared the hope of surprise,' || char(13) || '
From Kaom''s skulking horde.'),
(684, 'UniqueJewel59', 18770, 'The Sekhema rode to the mountain,' || char(13) || '
With her tribe, devoted and strong.' || char(13) || '
And sewed shut the mouth of nightmare,' || char(13) || '
So that it would not consume her world.'),
(685, 'UniqueJewel60', 48661, 'Maligaro understood that devotion to science,' || char(13) || '
Means devotion to trial and error.' || char(13) || '
For Maligaro''s errors, death was slow,' || char(13) || '
And very painful.'),
(686, 'UniqueBelt15', 61538, 'Our forefathers danced and drank and ate their fill' || char(13) || '
and did not honour the First Ones for their gifts.' || char(13) || '
So the First Ones filled the sky with fire.'),
(687, 'UniqueBelt16', 26702, 'After the Great Fire, the land lay barren' || char(13) || '
and our forefathers grew weak.' || char(13) || '
Mother Gull took pity on them' || char(13) || '
and gave them grain and water.'),
(688, 'UniqueBelt17', 27090, 'But the grain grew twisted and the water turned dark' || char(13) || '
and those who partook of Mother Gull''s gift' || char(13) || '
birthed monsters that fed ' || char(13) || '
on the flesh of one another.'),
(689, 'TheTrial', 64281, 'You cannot journey to new lands until you have the courage to leave the safety of home.'),
(690, 'TheGentleman', 62224, '"Axes and mauls are so uncivilised. A good clean cut to the neck with a sharp blade, that''s the Sarn way!"'),
(691, 'HouseOfMirrors', 27434, 'What do you see in the mirror?'),
(692, 'WealthAndPower', 53256, '<size:31>{The greatness of a man is not in how much wealth or power he acquires, but in his integrity and his ability to positively affect those around him.}'),
(693, 'TheCatalyst', 30262, 'Simple actions can lead the world to an early grave.'),
(694, 'TheVast', 5216, '<size:30>{Can you hear the siren''s calls,' || char(13) || '
Just beyond the sea?' || char(13) || '
A voice which hearts' || char(13) || '
of men enthralls,' || char(13) || '
I too am hooked to thee.}'),
(695, 'GiftOfTheGemlingQueen', 10986, 'Our Lady Dialla,' || char(13) || '
as a symbol of our progress,' || char(13) || '
shines greater than all the gems.'),
(696, 'TheDragonsHeart', 6232, 'They say when a dragon dies, the flesh smoulders and burns until all that remains is the still, white-hot, heart.'),
(697, 'TheFox', 55576, '"Masters of wit, strength and cunning. To survive the harsh winters, you must be like the fox."' || char(13) || '
- Ezomyte Proverb'),
(698, 'TheDoppelganger', 11827, 'Upon seeing her face, I am terrified—the moon shows me my own form!'),
(699, 'TheSurvivalist', 11157, 'A lucky number ' || char(13) || '
For us all ' || char(13) || '
To help us through ' || char(13) || '
The perils told.'),
(700, 'Death', 26309, '<size:31>{The end of the old,' || char(13) || '
the beginning of the new.' || char(13) || '
A unique opportunity for transformation,' || char(13) || '
for those with the power' || char(13) || '
to grasp it.}'),
(701, 'GraveKnowledge', 14463, 'The dead tell me great insights. They''ve had nothing but time to sit and think.'),
(702, 'TheJester', 53978, '<size:25>{Summoned for the King''s desire,' || char(13) || '
soon applause came from the court.' || char(13) || '
However insanity was his only sire,' || char(13) || '
so the King''s reign was cut short.}'),
(703, 'TheMercenary', 37053, 'Loyalty can be bought. Just make sure you know who the buyer is.'),
(704, 'TheInoculated', 42531, 'Chaos spread, wreaking havoc and death. They said none would be spared, and yet here I stand.'),
(705, 'Loyalty', 37046, 'Bound by fate,' || char(13) || '
inseparable by choice.'),
(706, 'PrideBeforeTheFall', 18997, '<size:27>{As Kaom slew the last of his kin,' || char(13) || '
something deep inside him broke.' || char(13) || '
And through the cracks, corruption,' || char(13) || '
pure and black, spread forth.}'),
(707, 'Audacity', 14610, '<size:27>{A jolt, and it moves. Or smolders.' || char(13) || '
A current, and it lives. Or dies.' || char(13) || '
A surge, and it transcends.' || char(13) || '
Or... not.' || char(13) || '
Only one way to find out.}'),
(708, 'AssassinsFavor', 27808, 'By the time their eyes meet, ' || char(13) || '
the dark deal has long since been made, ' || char(13) || '
and his fate long since sealed.'),
(709, 'HuntersResolve', 778, 'Primed, curved and sleek.' || char(13) || '
Decisive and final.' || char(13) || '
For malice and righteousness.' || char(13) || '
There''s but one solution.'),
(710, 'ScholarOfTheSeas', 30924, 'I''ve never come upon a ship I could not command. I have however met sailors that were not willing to be led.'),
(711, 'TheConduit', 37833, 'The path to godhood is guided by the hand of sacrifice.'),
(712, 'TheTower', 34707, 'A tower built of the strongest stone is not eternal; a towering intellect is not enlightened.'),
(713, 'UniqueAmulet25', 8917, 'Combat is simple.' || char(13) || '
Keep your blood in.' || char(13) || '
Take theirs out.'),
(714, 'UniqueTwoHandAxe10', 40973, 'When a craving cannot be sated, any source will do.'),
(715, 'UniqueFlask11', 38589, 'The great city of storms, washed away by Vinktar''s thirst for power.'),
(716, 'UniqueShieldInt6', 23580, 'Those who are skilled in combat do not become angered.' || char(13) || '
Those who are skilled at winning do not become afraid. ' || char(13) || '
Thus the wise win before they fight, ' || char(13) || '
while the ignorant fight to win.'),
(717, 'UniqueBootsInt7', 41366, 'The quick die young, the brilliant go mad,' || char(13) || '
and the powerful stand alone in a wasteland of their own creation.'),
(718, 'UniqueJewel61', 61141, 'There''s no motivation for genius' || char(13) || '
quite like desperation.'),
(719, 'UniqueJewel61x', 9590, '"Prototype #298 must be contained in a non-conductive glass box at all times."'),
(720, 'UniqueBow13', 60509, '"Exiled to the sea; what a joke. ' || char(13) || '
I''m more free than I''ve ever been."' || char(13) || '
- Captain Weylam "Rot-tooth" Roth of the Black Crest'),
(721, 'UniqueGlovesStr6', 21665, 'Izaro was slow to see the treachery growing in his own court' || char(13) || '
and powerless to stop it once he had;' || char(13) || '
a captain sailing his own ship into rocks.'),
(722, 'UniqueFlask12', 15718, 'Rancid, rotten, and wicked are those that dare to taste my serum.'),
(723, 'UniqueJewel62', 39723, 'When Voll took the throne,' || char(13) || '
He swore to care for the empire with eyes open.' || char(13) || '
And so he looked to the salvation of his people,' || char(13) || '
Blind to the damnation in his hands.'),
(724, 'UniqueJewel63', 18689, 'From north to south the sea of fire swept,' || char(13) || '
Rolling waves of gorging flame,' || char(13) || '
Growing taller and hungrier,' || char(13) || '
With every land they consumed.'),
(725, 'UniqueJewel64', 57661, 'As a boy, Rigwald was taught to hunt,' || char(13) || '
Through the first snows of winter,' || char(13) || '
When beasts have gorged their fill,' || char(13) || '
And see nothing but the long slumber ahead.'),
(726, 'UniqueJewel65', 59481, 'The Purity Rebels fought with heart and soul,' || char(13) || '
To free their empire from corruption.' || char(13) || '
And the fires of war did merely serve,' || char(13) || '
To temper the steel of their spirits.'),
(727, 'UniqueStaff15', 39746, '"They spent a lifetime in the service of God, ' || char(13) || '
only to spend eternity in the service of me." ' || char(13) || '
- Kadavrus, Surgeon to the Umbra'),
(728, 'TestingRing1_', 48367, '546'),
(729, 'TestingAxe1', 12841, '547'),
(730, 'TestingRing2', 36914, '548'),
(731, 'TestingRing3', 24216, '549'),
(732, 'TestingRing4', 8441, '550'),
(733, 'UniqueWand11', 27340, 'We forge order from the world around us' || char(13) || '
Wielding anarchy and destruction as our tools of genesis.'),
(734, 'UniqueGlovesStrDex7', 50193, 'Those who witness the shimmering scales of the wyrm' || char(13) || '
know only fear for the rest of their lives.' || char(13) || '
Fortunately, the rest of their lives' || char(13) || '
can be measured in seconds.'),
(735, 'UniqueSceptre11', 45482, 'Thousands gazed upon the doors of the great labyrinth,' || char(13) || '
at an Eternal Champion in steel and gold, ' || char(13) || '
The first to challenge its treacherous traps. ' || char(13) || '
To mark the occasion, Izaro had the Champion''s remains gilded.'),
(736, 'UniqueJewel66', 40594, 'The once-glorious emperor spent his final days' || char(13) || '
imprisoned in his greatest creation;' || char(13) || '
a tool to filter out the unworthy' || char(13) || '
that pushed a monster to power.'),
(737, 'TheTwins', 19020, 'Two sides of a coin;' || char(13) || '
Heads for a friend,' || char(13) || '
tails a foe;' || char(13) || '
Gemini toss up'),
(738, 'AnarchysPrice', 6666, '<size:31>{Born of relentless fury and abhorrence, warped by turmoil and anguish, tainted through desire and carnality, I thirst for bloodshed once more.}'),
(739, 'TheLich', 59306, 'When the dead raise and master their own, the land is truly lost.'),
(740, 'TheThaumaturgist', 47884, '<size:31>{"Mastery of thaumaturgy is like any other pursuit; it requires dedication and sacrifice. Sometimes several sacrifices."' || char(13) || '
- Shavronne of Umbra}'),
(741, 'TheAesthete', 7200, '"Some see our mortal flesh as a limitation. I see it as an opportunity for vast, miraculous improvements."' || char(13) || '
- Shavronne of Umbra'),
(742, 'TheEnlightended', 2367, 'Weaving the six,' || char(13) || '
a serpent stands tall.' || char(13) || '
Wearing a crown,' || char(13) || '
the thousand petals call.'),
(743, 'HuntersReward', 7735, 'To tame a beast, you first must subdue its heart.'),
(744, 'TheFletcher', 18779, 'Let these fine arrows pack a punch.'),
(745, 'TheSurveyor', 56405, 'Exploring lands made of flesh and sorrow, we''ll reap and plunder like there''s no tomorrow.'),
(746, 'BowyersDream', 60536, 'If this is my dream, I don''t wish to wake.'),
(747, 'TheSurgeon', 33308, '"He might be lacking in vision, but his virtuosity is undeniable."' || char(13) || '
- Malachai, on Maligaro'),
(748, 'VolatilePower', 62918, 'Unlimited power is apt to corrupt the minds of those who possess it.'),
(749, 'LastHope', 5956, '<size:31>{As their civilisation crumbled, the Vaal looked to their queen. In her, they saw a way out. In them, she saw a burden she was happy to free herself from.}'),
(750, 'Hubris', 22241, '"This one? It is NOT for sale. You would sooner pry it from my lifeless hand."' || char(13) || '
- Jonfé Darontos, Ringmaker'),
(751, 'BlindVenture', 47037, '"It''s risky not knowing where your wares come from. That''s why I source my own."' || char(13) || '
- Klayver, the Antiquarian'),
(752, 'MercilessArmament', 57599, '"Through thick and thin,' || char(13) || '
blood and bone,' || char(13) || '
a peaceful life' || char(13) || '
is one I can''t condone."' || char(13) || '
- Tukohama, Father Of War'),
(753, 'TheCartographer', 56198, '<size:31>{My son, you lost your way before you arrived.' || char(13) || '
To never lose you again,' || char(13) || '
I make a path in my heart.}'),
(754, 'UniqueOneHandSword14', 33378, '"With this, I will weave the threads of fate ' || char(13) || '
into a noose for our ''glorious'' emperor."' || char(13) || '
- Chitus Perandus'),
(755, 'UniqueOneHandClaw11', 57696, 'Izaro saw himself not as a man,' || char(13) || '
but as a divine saviour trapped in a man''s body.'),
(756, 'UniqueAmulet26', 33621, 'When slaughtered flesh falls silent,' || char(13) || '
the soul may yet scream on.'),
(757, 'UniqueTwoHandSword9', 52778, 'Take your partners by the hand,' || char(13) || '
Keep your steps in time.' || char(13) || '
Swing together, spin apart,' || char(13) || '
And dance with death sublime.'),
(758, 'UniqueJewel67', 27439, 'A mage from the coast rode up on a broken nag, legs burnt to his bones.' || char(13) || '
Before he collapsed, he uttered:' || char(13) || '
"I watched the world we know end yesterday."'),
(759, 'UniqueJewel68', 406, 'Chitus began to aggressively expand his empire' || char(13) || '
into neighbouring nations at great human cost. ' || char(13) || '
But for absolute power, there is no price ' || char(13) || '
that a Perandus won''t pay.'),
(760, 'UniqueJewel69', 37106, 'Lioneye''s men stood at the walls,' || char(13) || '
eyeing the savages that walked the beach below.' || char(13) || '
With a single word,' || char(13) || '
a thousand bodies, and ten thousand arrows,' || char(13) || '
would litter the sands.'),
(761, 'UniqueJewel70', 19327, 'Long after the Karui passed through,' || char(13) || '
the whispers of those who stood their ground' || char(13) || '
at Lioneye''s Watch could be heard amongst the rubble.'),
(762, 'UniqueBow14', 25139, 'The Eternals commanded an army that need not eat, sleep, or breathe' || char(13) || '
without the usual depravities of necromancy.'),
(763, 'UniqueBow14x', 39936, '"Admittedly lacking the finesse of the fabled original,' || char(13) || '
Prototype #4 achieved identical results through brute force alone."'),
(764, 'UniqueWand12', 286, 'You can never truly tame the tempest.' || char(13) || '
You can barely even leash it.'),
(765, 'UniqueWand13', 56478, 'Every decade, Lunaris devours Solaris' || char(13) || '
Each time, Solaris emerges from Lunaris, born anew.'),
(766, 'UniqueSceptre12', 44453, 'When God forged the rules of reality,' || char(13) || '
he stated that some forces cannot co-exist.' || char(13) || '
He then made man with an unequivocal' || char(13) || '
desire to disobey.'),
(767, 'UniqueSceptre13', 63114, 'In time, all becomes nothing.' || char(13) || '
We just expedite the process.'),
(768, 'UniqueSceptre14', 28706, 'Fight not the cold' || char(13) || '
Forsake hope' || char(13) || '
Be still.'),
(769, 'UniqueSceptre14x', 22695, '"Attempt #2520: Been slaving away at this one for longer than I can remember.' || char(13) || '
Convinced this assignment is retribution from my superior..."'),
(770, 'UniqueBelt18', 47219, '"They say a draught of fine spirits will ward off' || char(13) || '
the elements and promote a longer, merrier life.' || char(13) || '
I have found this to be true on all counts." ' || char(13) || '
- Zerphi of the Vaal'),
(771, 'TheWarlord', 25037, 'To cure the Goddess,' || char(13) || '
and break the chains of corruption,' || char(13) || '
you must shatter the world.'),
(772, 'TheDemoness', 36516, 'Wherever she went, death was sure to follow.'),
(773, 'TheTraitor', 29749, '<size:31>{Sometimes an apprentice becomes a master through countless hours of hard work and practice.' || char(13) || '
Sometimes it happens by force.}'),
(774, 'TheOffering', 42933, 'Eternal beauty has a cost, one which Shavronne was happy to pay with the lives of others.'),
(775, 'LostWorlds', 11139, '<size:27>{"There are worlds that lie beyond the edge of my page, the edge of my understanding. Worlds of wonder. Worlds of terror."' || char(13) || '
Aramil - Cartographer to Emperor Chitus}'),
(776, 'TheLordInBlack', 14911, '<size:27>{Thy knee shall bend' || char(13) || '
in shifting dark,' || char(13) || '
thy blade shall serve his vigil.' || char(13) || '
Thy oath shall bind thee' || char(13) || '
to his mark,' || char(13) || '
thy flesh shall bear his sigil.}'),
(777, 'AMothersPartingGift', 63306, 'Nature was her domain,' || char(13) || '
Love was her song,' || char(13) || '
Family was her devotion,' || char(13) || '
Knowledge was her gift.'),
(778, 'TheBody', 11616, 'They say it is the head that leads, but all must flow through the body at some point.'),
(779, 'TurnTheOtherCheek', 40804, '"Only after one forsakes rage, can true power be found."' || char(13) || '
- Sekhema Asenath'),
(780, 'GlimmerOfHope', 29192, 'When you dwell in total darkness, even the faintest light may guide you out.'),
(781, 'TheEthereal', 54359, '<size:30>{"Long ago, people looked to the stars, believing they influenced us. Soon, it will be us who influence the stars."' || char(13) || '
- Doryani, Queen''s Thaumaturge}'),
(782, 'UniqueTalisman1', 40944, 'In the light of Solaris, the shadows cower and hide.' || char(13) || '
But every night they gather and grow,' || char(13) || '
and all but the strong and the stupid' || char(13) || '
seek shelter from their grasp until daybreak.'),
(783, 'Talisman2_3', 11269, '"Against the Winter Curse, only the forges of' || char(13) || '
runesmiths could stand. The people huddled,' || char(13) || '
shoulder to shoulder, while those within were' || char(13) || '
pressed against the fires, screaming in agony."'),
(784, 'Talisman3_1', 59950, '"Romance never interested Queen Lysanda,' || char(13) || '
but her advisors insisted heirs were needed.' || char(13) || '
To spite them, she took the Hag''s only son as' || char(13) || '
her Consort - a quiet, pale, and strange man."'),
(785, 'Talisman2_5', 8087, '"The night refused to end, and the Winter Curse' || char(13) || '
howled. The people wailed, and Lysanda raged.' || char(13) || '
It was then that the sky tore open, unleashing' || char(13) || '
a saviour fury... at the behest of the Druids."'),
(786, 'Talisman2_6', 57425, '"The Druids emerged from the forests to greet' || char(13) || '
and warn the new settlers. This was an ancient' || char(13) || '
land full of mysteries and dangers. Lysanda sent' || char(13) || '
her best men to study and learn with them."'),
(787, 'UniqueRing40', 61582, '"This thing is not a pet. It is a parasite that feeds on the very will of its host.' || char(13) || '
Like any part of nightmare, it has found a way to make its price... acceptable."' || char(13) || '
- Malachai the Soulless'),
(788, 'UniqueAmulet27', 32492, '"I offer to you an eternal oath ' || char(13) || '
that binds your heart to mine;' || char(13) || '
a bond that not even death will break.' || char(13) || '
Will you accept?"' || char(13) || '
- Daresso, to his beloved'),
(789, 'UniqueTalisman2', 15609, 'Long ago, the ocean was a puddle where a golden fish dwelt,' || char(13) || '
who lit the ocean from within and kept the water fresh.' || char(13) || '
When the sky burned, the fish dived deep,' || char(13) || '
never to return, and the waters turned sour.'),
(790, 'UniqueTalisman3', 58965, 'Just as the rat cowers before the dog' || char(13) || '
and the dog cowers before Man,' || char(13) || '
so too should we cower before the First Ones' || char(13) || '
and pray we never learn of what comes next.'),
(791, 'UniqueTalisman4', 58644, 'I once thought the First Ones were just' || char(13) || '
stories made to scare children.' || char(13) || '
But I''ve seen what they can do. I''ve felt it.' || char(13) || '
And now I must live with that terrible knowledge.'),
(792, 'UniqueTalisman5', 58282, 'I am but a vessel for a greater force.' || char(13) || '
It acts through me. Speaks through me.' || char(13) || '
Decides what lives and dies through me.' || char(13) || '
And will change the world through me.'),
(793, 'Talisman2_1', 58165, '"The clans had travelled to their new home' || char(13) || '
united, and they did love Lysanda, but some' || char(13) || '
men must go their own way. Those that braved' || char(13) || '
the inland sea settled the Isles of Skothe."'),
(794, 'Talisman2_2', 59885, '"The journey was over, the land was being' || char(13) || '
secured, and the foundations for the first city' || char(13) || '
had been laid. Winter hit them with horrible' || char(13) || '
fury, sent not by nature, but by a curse."'),
(795, 'Talisman2_4', 11655, '"And still the Winter Curse raged in through' || char(13) || '
every window and every door. The fathers' || char(13) || '
and mothers of those within let themselves' || char(13) || '
freeze solid, sealing the gaps with their lives."'),
(796, 'Talisman2_7', 4545, '"As the Ezomytes of Myr prospered, they' || char(13) || '
needed more and spreading lands. Queen' || char(13) || '
Lysanda led the ongoing campaign to' || char(13) || '
slaughter every last creature of darkness."'),
(797, 'Talisman3_2', 40294, '"Queen Lysanda''s spiteful choice of Consort' || char(13) || '
spited only herself. Alasdair was unlike any' || char(13) || '
man she had ever met. It was not long before' || char(13) || '
the trumpets sounded for the Royal Wedding."'),
(798, 'Talisman3_3', 17221, '"The Royal Wedding of Lysanda of Myr' || char(13) || '
lasted for a full month. The hunts were' || char(13) || '
vigorous, and the meat and drink flowed' || char(13) || '
freely for all. There was much rejoicing."'),
(799, 'Talisman3_4', 30220, '"But there were some who could not forget' || char(13) || '
the horrors of the Winter Curse, and of the' || char(13) || '
Hag that had sent it. Alasdair dropped his' || char(13) || '
wine goblet, and fell to the ground, choking."'),
(800, 'Talisman3_5', 64197, '"There followed a time of fear and fire.' || char(13) || '
None would speak against their fellows.' || char(13) || '
None would say who had poisoned him.' || char(13) || '
Lysanda''s justice was swift and brutal."'),
(801, 'Talisman3_6', 33992, '"In the years that followed, Queen Lysanda' || char(13) || '
poured herself into the long and brutal task' || char(13) || '
of securing the lands of the Ezomytes of Myr.' || char(13) || '
Every fell beast, every creature, had to die."'),
(802, 'Talisman3_7', 33500, '"The Blue Knight stood against the swarm,' || char(13) || '
icy and unassailable. His identity was not' || char(13) || '
known, and he never removed his helmet.' || char(13) || '
Glimpses were caught of piercing blue eyes."'),
(803, 'UniqueRing41', 7466, 'Within the heart of every man and woman' || char(13) || '
lies the soul of a ferocious beast.' || char(13) || '
If you cannot tame it, embrace it.'),
(804, 'UniqueOneHandAxe9', 30034, 'Tear the flesh from the bone. ' || char(13) || '
Turn the bone to dust.' || char(13) || '
Scatter the dust to the wind.'),
(805, 'UniqueOneHandSword15', 5314, 'Fear not death. Turn to him, face him.' || char(13) || '
And smile as he sinks his teeth' || char(13) || '
into the throats of our oppressors.'),
(806, 'UniqueQuiver10', 19860, 'The fortunate inscribe their legacy' || char(13) || '
in the pages of history books.' || char(13) || '
The rest of us must leave our mark with our blood' || char(13) || '
or the blood of others.'),
(807, 'UniqueMap2_14', 30356, 'Howls and laughter' || char(13) || '
They hide in the day' || char(13) || '
They smell you, they watch you' || char(13) || '
They track their new prey'),
(808, 'Talisman4', 33337, 'The wolf greeted the king,' || char(13) || '
In the light of the harvest moon.' || char(13) || '
The wolf offered the strength of the wild,' || char(13) || '
And the king paid for it in blood.'),
(809, 'UniqueAmulet28', 29952, 'Those who dwell in the deep freeze' || char(13) || '
enjoy a special kind of madness.'),
(810, 'Talisman1_10', 3462, '"Lysanda and her Knights brought the' || char(13) || '
settling clans to what would become' || char(13) || '
Ezomyr... but there was one beast against' || char(13) || '
which even they could not stand."'),
(811, 'UniqueBodyDemigods', 33592, 'The victorious know only leadership,' || char(13) || '
the rest only servitude.'),
(812, 'Prosperity', 64807, 'Accumulating wealth has its own costs.'),
(813, 'TheSigil', 10271, '<size:29>{Three men travel' || char(13) || '
through the gate;' || char(13) || '
they carry a protective ward.' || char(13) || '
A faction conspires' || char(13) || '
against their fate,' || char(13) || '
but magic unravels the sword.}'),
(814, 'TheDapperProdigy', 35255, '"Many believe murder is a grisly, grim, and grotesque crime. Then there are those who simply make art of it."'),
(815, 'TheRabidRhoa', 19732, '"Experiment 22A: Rhoas, when deprived of water, secrete a most delightfully potent toxin."' || char(13) || '
- Maligaro'),
(816, 'TheSoul', 19217, '"Most people only have one. I''m a bit of a hoarder."'),
(817, 'TheLion', 43225, '<size:31>{The Eternals lauded his valour. The Karui relished his defeat. Yet the final thoughts of Marceus Lioneye were naught but lament for his pride.}'),
(818, 'TheDragon', 12573, '<size:28>{Scaly beast of the skies,' || char(13) || '
watching with his golden eyes.' || char(13) || '
Shadow that blocks out the sun,' || char(13) || '
it''s too late for you to run.}'),
(819, 'Rats', 7516, 'Whoever said ''more is always better'' has obviously never met a rat.'),
(820, 'TheRisk', 63167, '"There is no right or wrong choice, no best or worst. There are only choices and their consequences."'),
(821, 'Tranquillity', 53194, 'Beware the sudden calm, for it is a sure sign of a storm on the horizon.'),
(822, 'UniqueFlask13', 48471, 'To achieve godhood, they would cast off all that god has gifted us.' || char(13) || '
Mortality, compassion, even the sanctity of flesh.' || char(13) || '
 - High Templar Voll'),
(823, 'UniqueTwoHandAxe14', 28856, '"The Karui savages claim the weapon was forged by their fire god.' || char(13) || '
I''m rather inclined to believe them."' || char(13) || '
- Fairgraves, Renowned Explorer'),
(824, 'UniqueShieldInt7', 32113, 'Thaumaturgy has no limit.' || char(13) || '
It is our fragile reality that imposes boundaries.'),
(825, 'Talisman1_12', 15849, '"With the headless beast incinerated, the' || char(13) || '
settlers rejoiced, and began building homes.' || char(13) || '
They would soon find that this hostile land' || char(13) || '
had more insidious ways of rejecting them."'),
(826, 'UniqueFlask14', 53586, 'Between a rock and a rock.'),
(827, 'Talisman2_8', 47784, '"Each new valley, each new grove, held new' || char(13) || '
dangers. Many Knights paid the price. Lysanda' || char(13) || '
had never been known for her beauty, but she' || char(13) || '
bore a new scar each season, earned gladly."'),
(828, 'Talisman1_11', 47033, '"A great headless monstrosity with arms like' || char(13) || '
teeth stalked the lands they hoped to settle.' || char(13) || '
No other weapon would find purchase. They' || char(13) || '
surrounded it with fire, burning it for days."'),
(829, 'UniqueSceptre15', 19050, ''),
(830, 'UniqueBelt19', 18955, '"The power of rebirth rivals that of immortality."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 3'),
(831, 'UniqueAmulet29', 46281, 'Those who dwell in the deep freeze' || char(13) || '
enjoy a special kind of madness.'),
(832, 'UniqueAmulet29x', 16834, '"Researcher Graven spent eleven hours suffering electrocution in the lab' || char(13) || '
before he was found. Prototype #14 somehow kept him from dying."'),
(833, 'UniqueOneHandClaw12', 31350, '"A man cowers behind his walls.' || char(13) || '
A woman carries her fortress with her.' || char(13) || '
In heart, in mind, in hand."' || char(13) || '
- Sekhema Deshret'),
(834, 'UniqueOneHandClaw12x', 11390, '"Additional test subjects approved. Determine exactly how many wounds' || char(13) || '
need to be endured to activate Prototype #612''s energies."'),
(835, 'HerMask', 3182, 'To her beauty you submit,' || char(13) || '
lest your neck the great Queen slit.'),
(836, 'TreasureHunter', 45533, '"Don''t worry, I know what I''m doing."' || char(13) || '
- Toggo''s Last Words'),
(837, 'EarthDrinker', 27082, 'Taste and grow strong. Drink too much and be buried.'),
(838, 'TheWolfsShadow', 1723, '"If I fall, we will fall together with my fangs in your throat."'),
(839, 'TheArenaChampion', 21815, 'The fight is the easy part. It''s the years of training that''ll kill you.'),
(840, 'UniqueStaff16', 18982, '"Since one with knowledge of machines' || char(13) || '
might be able to bring the labyrinth to a standstill, ' || char(13) || '
Izaro had us place many boobytrapped decoys.' || char(13) || '
But I know which switch brings the monster down."' || char(13) || '
- Xirgil, Trapbuilder''s final words.'),
(841, 'UniqueChest4', 28444, 'What is stronger, the stone or the wind?' || char(13) || '
Look to the east. Do you see a single stone still standing amongst the dunes?' || char(13) || '
- Sekhema Deshret'),
(842, 'UniqueChest5', 51979, 'An era so ingrained with decadence, greed and cruelty' || char(13) || '
that even the graves of murderers were gilded.'),
(843, 'UniqueChest6', 33491, 'Little makes it across the dry plains ' || char(13) || '
to the foot of the mountain alive.' || char(13) || '
The mountain dwellers ensure nothing reaches the top.'),
(844, 'UniqueChest7', 1617, 'The caustic fumes that rise from the caldera' || char(13) || '
kill nearly everything downwind eventually.' || char(13) || '
The Redblade, however, just go mad.'),
(845, 'UniqueChest8', 64474, 'For generations, the gentle Pondium tides' || char(13) || '
sheltered the smugglers, murderers and thieves,' || char(13) || '
and let their resentment and population flourish.'),
(846, 'UniqueChest9', 61660, 'As if pulled by divine strings,' || char(13) || '
the powerful are drawn to the powerful,' || char(13) || '
breaking any morals and laws that might stand in the way.'),
(847, 'UniqueChest10', 129, 'A captain''s first love is his ship. ' || char(13) || '
They either die together,' || char(13) || '
or forever linger apart.'),
(848, 'UniqueChest12', 60148, 'Unconventional criminals require unconventional prisons.'),
(849, 'UniqueTwoHandMace10', 5960, '"Though ingenious instruments have been found,' || char(13) || '
it seems surgery before thaumaturgy' || char(13) || '
was not so delicate."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 3546'),
(850, 'UniqueTwoHandMace10x', 13306, '"The best place for this prototype would be in the hands of our enemies."'),
(851, 'UniqueDagger13', 42197, 'Love only death' || char(13) || '
For she shall never let you go.'),
(852, 'UniqueOneHandMace9', 48540, 'There is nothing, flesh, spirit, or stone' || char(13) || '
Free from our hunger for dominion.'),
(853, 'UniqueOneHandMace10', 50334, 'A merciful murderer swept through the streets of Sarn' || char(13) || '
Robbing breath from the weak and worthless.'),
(854, 'UniqueOneHandMace10x', 24036, '"Three test subjects confirmed Prototype #495 creates an additional' || char(13) || '
debilitating effect from poisons. This could be very useful."'),
(855, 'UniqueOneHandSword16', 22841, 'The blade thrums with wild energy' || char(13) || '
Eager for vengeance against all who walk free.'),
(856, 'UniqueOneHandSword16x', 57374, '"Test subjects were unable to strike even a motionless target.' || char(13) || '
However, when a trained guard tried it..."'),
(857, 'UniqueRapier4', 10485, 'It doesn''t matter how well the young swordsman trains.' || char(13) || '
All form and finesse are forgotten when blood first hits the ground.'),
(858, 'UniqueWand14', 64341, '"We do not command fire.' || char(13) || '
Ngamahu lends it, and Hinekora returns it."' || char(13) || '
- Lavianga, Advisor to Kaom'),
(859, 'UniqueFishingRod2', 42938, 'He cast far into the ocean' || char(13) || '
And tore out her heart.'),
(860, 'UniqueFlask15', 7021, 'As man sins,' || char(13) || '
God weeps.'),
(861, 'UniqueFlask15x', 42714, '"Success! Prototype #54 has tapped into that sliver of divinity that exists within.' || char(13) || '
Faith fuels the flesh, and the flesh fuels the fire..."'),
(862, 'UniqueBodyStrInt7', 29786, 'Faith does not make us invulnerable.' || char(13) || '
It makes us immortal.'),
(863, 'UniqueSceptre16_', 32050, 'The worst of Axiom were imprisoned by more than iron.'),
(864, 'UniqueOneHandSword17', 63643, '"Painful suicide in the hands of a fool, ' || char(13) || '
Creative death in the hands of a master."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 2992'),
(865, 'UniqueBodyStrDex6', 17936, 'Swift and silent.' || char(13) || '
One strike, one corpse.'),
(866, 'UniqueBootsDex10', 60443, 'The Goat King knew not of war,' || char(13) || '
of the lands and laws he trampled.' || char(13) || '
The Goat King knew only joy' || char(13) || '
at turning life to ash.'),
(867, 'UniqueBodyInt10', 19738, 'The quickest way to understand' || char(13) || '
your own strengths and weaknesses' || char(13) || '
is to walk in the skin of another.'),
(868, 'UniqueFlask16', 13264, '"Proof that if you devote yourself to a god of death,' || char(13) || '
you may be spared from its wrath."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 408'),
(869, 'UniqueClaw13', 15897, 'Terror doesn''t make you jump.' || char(13) || '
Terror makes you run.'),
(870, 'UniqueJewel71', 24021, 'Why waste the good stuff on something that''s going to blow up?'),
(871, 'UniqueJewel71x', 34658, '"A curious jewel. Like so many others, a shining little paradox."'),
(872, 'UniqueShieldDexInt3', 33307, 'Izaro''s insistence on using lava' || char(13) || '
resulted in some surprising material discoveries.'),
(873, 'UniqueJewel72', 27300, 'Anyone can catch a lumbering beast.' || char(13) || '
Try catching a bird before it has even landed.'),
(874, 'UniqueBow15', 40678, 'Night''s frost becomes morning''s dew' || char(13) || '
Darkness cleansed, pure and new.'),
(875, 'UniqueJewel73', 60929, 'The Ezomytes have a saying:' || char(13) || '
Take everything and waste nothing.'),
(876, 'UniqueJewel74', 22874, 'Saboteurs, like chefs, have their own secret recipes.'),
(877, 'UniqueJewel74x', 16068, '"Researchers will refrain from giving test subjects virtue gems which produce traps.' || char(13) || '
We are still finding explosives in the vents months later." ' || char(13) || '
- Administrator Qotra'),
(878, 'UniqueHelmetDexInt7', 36145, 'Branded a heretic for your beliefs,' || char(13) || '
You stand alone against many.' || char(13) || '
May the truth that fuels their anger,' || char(13) || '
Carry your blade into their hearts.'),
(879, 'UniqueJewelLabyrinth1', 21658, 'The greatest victories happen' || char(13) || '
before the battle has begun.'),
(880, 'UniqueJewelLabyrinth2', 5580, 'Language is a tool that can be used to build walls ' || char(13) || '
or tear them down.'),
(881, 'UniqueJewelLabyrinth3', 3762, 'Even an iron fist can be handled with grace.'),
(882, 'UniqueJewelLabyrinth4', 71, 'Learn as much as you can, ' || char(13) || '
and surround yourself with people who know the rest.'),
(883, 'UniqueBelt20', 53168, 'A single step forward' || char(13) || '
Snap free from the prison' || char(13) || '
Reborn into freedom eternal'),
(884, 'LabyrinthBaneOfTheLoyal', 25457, 'A snake cannot survive without its head.' || char(13) || '
But neither can the head survive without the body.'),
(885, 'LabyrinthHeartOfTheGargoyle', 62039, 'All living things need a heart,' || char(13) || '
even those made of stone.' || char(13) || '
No heart, no life.'),
(886, 'LabyrinthCubeOfAbsorption', 64196, 'Beware the one who seeks to contain a storm.'),
(887, 'LabyrinthOrbOfElementalEssence', 15167, 'Return Nature''s gift to the source.'),
(888, 'LabyrinthRodOfDetonation', 48197, 'What can be built, can be destroyed.'),
(889, 'LabyrinthSandOfEternity', 59756, 'That which takes an eternity does not happen.'),
(890, 'LabyrinthCogsOfDisruption', 18517, 'Take a cog here, place a cog there,' || char(13) || '
and the great machine grinds to a halt.'),
(891, 'LabyrinthPortalShredder', 48012, 'The best way to keep out an unwanted guest' || char(13) || '
Is to simply close the door.'),
(892, 'UniqueShieldStrInt9', 20170, 'A man''s life is the greatest gift he can give.'),
(893, 'UniqueShieldStrInt9x', 35683, '"Close to the original, and perhaps even more useful. However,' || char(13) || '
close is not what we are looking for. Keep trying." ' || char(13) || '
- Administrator Qotra'),
(894, 'UniqueMap2_15', 2753, 'Forget kings and emperors;' || char(13) || '
He who holds the coin holds all the power.'),
(895, 'UniqueOneHandSword18', 26252, 'A sword he brought, his foes to maim and rend,' || char(13) || '
from places dark behind forbidden doors,' || char(13) || '
but night by night he woke with frighten''d roars' || char(13) || '
from ghoulish dreams, too strange to comprehend.'),
(896, 'UniqueOneHandSword18x', 64682, '"The night-gaunts, they fly, soaring about in darkness beyond the ken of mankind.' || char(13) || '
I hear the silent whispers of their wings as they descend, for me, for me..." ' || char(13) || '
- Researcher Arn'),
(897, 'TheSephirot', 55367, 'If the path to divinity were simple, we''d all be gods.'),
(898, 'TheVisionary', 10807, 'Lioneye looked to the heights of glorious victory. And thus he missed the defeat right under his nose.'),
(899, 'ThunderousSkies', 22074, '<size:30>{Many that have wielded the power of lightning have said that death by electrocution looks like the victim is more alive than ever before.}'),
(900, 'DyingAnguish', 38326, '<size:29>{Moribund, he gazed upon the journey taken as blood trickled down his chin. His eye closed on the city ahead that he would never call home.}'),
(901, 'TheImmortal', 28373, '<size:30>{"Greetings! Just because you think I''m greedy doesn''t mean I''m not willing to share. You''ll just have to kill me first."' || char(13) || '
-Grandmaster Dy''Ness}'),
(902, 'BoundlessRealms', 55405, 'Boundless is the distance between where we start and where we start again.'),
(903, 'TheThrone', 25629, 'A king''s movement is unwavering.'),
(904, 'TheDevastator', 8367, 'Only a fool tries to contain unlimited power.'),
(905, 'DestinedToCrumble', 2035, '<size:30>{"Let us not forget the most important lesson the Vaal taught us:' || char(13) || '
Nothing is eternal."' || char(13) || '
- Siosa Foaga, Imperial Scholar}'),
(906, 'ShardOfFate', 64201, 'Their whims left unknown,' || char(13) || '
Their life left for others.'),
(907, 'Heterochromia', 58798, '<size:26>{Black and White, Silver and Gold' || char(13) || '
Let us see the world Unfold' || char(13) || '
Red and Blue, Yellow and Green' || char(13) || '
Let us remake it in colours Unseen}'),
(908, 'RainTempter', 55867, 'Be like water, friend.'),
(909, 'TheVoid', 14772, 'Reach into the Void and claim your prize.'),
(910, 'TheTyrant', 42934, '"Fear controls the masses."' || char(13) || '
- Laszlo, the Scourge'),
(911, 'TheWeb', 32203, '<size:30>{A weapon, a shelter, a prison.' || char(13) || '
The web''s purpose changes' || char(13) || '
with the spider''s needs.' || char(13) || '
A lesson we should' || char(13) || '
take to heart.}'),
(912, 'TheHarvester', 43110, '<size:30>{Taste not of their' || char(13) || '
forbidden fruit.' || char(13) || '
Theirs is a harvest of' || char(13) || '
the darkest kind,' || char(13) || '
twisted, rotten and' || char(13) || '
damned for eternity.}'),
(913, 'TheLunarisPriestess', 24131, 'Embrace the Light,' || char(13) || '
Await the Morrow,' || char(13) || '
No more Spite,' || char(13) || '
And no more Sorrow.'),
(914, 'EmperorOfPurity', 62721, 'True to his title,' || char(13) || '
Voll, newly crowned,' || char(13) || '
had many of the' || char(13) || '
Eternal Empire''s signature' || char(13) || '
extravagances destroyed.'),
(915, 'TheCursedKing', 27419, 'The First Ones' || char(13) || '
may be blasphemy,' || char(13) || '
but they are' || char(13) || '
powerful blasphemy.'),
(916, 'TheStormcaller', 24315, 'If you beckon the' || char(13) || '
Lord of Lightning,' || char(13) || '
do not be surprised' || char(13) || '
when you are struck.'),
(917, 'LysahsRespite', 43123, 'So many memories,' || char(13) || '
so much pain in' || char(13) || '
such a small token.' || char(13) || '
Drown it in blood' || char(13) || '
so you can forget.'),
(918, 'CartographersDelight', 30874, '<size:28>{A map is similar' || char(13) || '
to a pair of eyes,' || char(13) || '
without one you stumble' || char(13) || '
around, unable to find your way.}'),
(919, 'LuckyDeck', 24872, 'When the outcome is the same, does it matter if it is fortune or trickery?'),
(920, 'LightAndTruth', 15604, 'Time and change' || char(13) || '
shall naught avail,' || char(13) || '
To dim the Light' || char(13) || '
of Truth''s fair grail.'),
(921, 'LuckOfTheVaal', 33356, 'They can''t be THAT lucky,' || char(13) || '
or they''d still be here!'),
(922, 'TheEndurance', 8923, '<size:28>{Crimson rubies, drops of vigour,' || char(13) || '
flowing through my veins,' || char(13) || '
flesh like coal, try to crush me,' || char(13) || '
diamond is what remains.}'),
(923, 'ThePenitent', 5866, '<size:28>{First, I gave my wealth, and we went hungry. Next, I gave my land, and we were homeless. Then, I gave my family, and I was alone. Last, I gave my eyes, and all I could dream was mine.}'),
(924, 'TheWolf', 36523, '<size:29>{The largest beasts cannot be overpowered. The Greatwolf teaches us to use guile, not strength, to probe for the soft flesh and strike deep.}'),
(925, 'DiallasSubjugation', 28330, '<size:28>{A symbol of beauty and innocence' || char(13) || '
The gems corrupted her mind' || char(13) || '
Malachai corrupted her gems' || char(13) || '
All but a glimmer of' || char(13) || '
greatness lost in madness}'),
(926, 'TheCalling', 7169, '<size:32>{Blood flows not just through veins, but through worlds.}'),
(927, 'TheValkyrie', 5764, '<size:26>{The villain strikes,' || char(13) || '
the world is torn.' || char(13) || '
A war begins, a hero is born,' || char(13) || '
The nemesis sets the sky alight.' || char(13) || '
A hero''s sacrifice' || char(13) || '
sets everything right.' || char(13) || '
- Drake''s Epitaph}'),
(928, 'TheFormlessSea', 54540, 'Formless might,' || char(13) || '
Wild beauty tamed,' || char(13) || '
The brine of gods,' || char(13) || '
The seas restrained.'),
(929, 'UniqueAmulet30', 31977, 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod'),
(930, 'UniqueDagger14', 50658, 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod'),
(931, 'UniqueBootsDex9', 33401, 'Move in with haste.' || char(13) || '
Strike quick, strike hard.' || char(13) || '
Vanish like smoke in the wind.'),
(932, 'UniqueBootsDex9x', 43241, '"The test subject nearly escaped, but the poison gas' || char(13) || '
system in the hallway functioned as expected."'),
(933, 'UniqueShieldStr6', 25718, 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod'),
(934, 'UniqueBodyInt11', 7863, 'Renowned by those distinguished,' || char(13) || '
Exalted by the few.' || char(13) || '
He skulks in darkness, ' || char(13) || '
and watches from beneath the city.'),
(935, 'UniqueJewel75', 44012, 'Thoughts that shimmer like light across the rain.'),
(936, 'UniqueJewel76', 22145, 'Skin like steel tempered by bright flames.'),
(937, 'UniqueJewel77', 33074, 'Fists that strike like a falling tree.'),
(938, 'UniqueHelmetInt11', 22933, 'You think we do not know.' || char(13) || '
We know all that you think.'),
(939, 'UniqueAmulet31', 31512, 'Remember the past, anticipate the future.'),
(940, 'UniqueHelmetStrInt6', 7780, 'Tukohama, Tawhoa and Kitava went to the lake to fish.' || char(13) || '
Tawhoa weaved a net to catch the fish,' || char(13) || '
Tukohama built a fire to cook the fish,' || char(13) || '
and Kitava swallowed the entire lake, fish and all, with a single gulp.'),
(941, 'UniqueOneHandSword19', 17745, 'Even from the back rows,' || char(13) || '
the whistling steel was mesmerising.' || char(13) || '
They watched the dance in the arena dust, silent as the dead.' || char(13) || '
A spell only broken by the spilling of blood.'),
(942, 'UniqueFlask17', 19040, 'Empty cup, full of promise.'),
(943, 'UniqueQuiver11', 29754, 'Beaten in contest, he would try once more' || char(13) || '
Guided by magic, Magjar took aim at a dove' || char(13) || '
Saemus'' gift would influence the score' || char(13) || '
Guided by darkness, Magjar spilled the blood of his love'),
(944, 'UniqueGlovesStr7', 18240, 'With unending determination and resolve he destroyed first the gates, ' || char(13) || '
then the constructs guarding the tomb on the other side.'),
(945, 'UniqueBodyDex8', 43119, 'Do not hide your flaws, your cracks,' || char(13) || '
mend them, and display them proudly.' || char(13) || '
For it is these that set us apart.'),
(946, 'UniqueBootsStr5', 663, 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod'),
(947, 'UniqueJewel78', 33673, 'The smaller the teeth, the sharper the bite.'),
(948, 'UniqueClaw14', 50100, 'Grip the frozen steel, feel it numb you.' || char(13) || '
Wield the cold touch of death like ' || char(13) || '
a splinter of your own shattered heart.'),
(949, 'UniqueBodyStrInt8', 2838, 'Fragile is the vessel that holds the soul.' || char(13) || '
Wrap it in cloth, seal it tight.' || char(13) || '
For once the seal is broken, the contents are lost forever.'),
(950, 'UniqueTwoHandSword10', 37760, 'The cuts on my hands are a small price to pay' || char(13) || '
for the opportunity to drive my steel' || char(13) || '
beyond the flesh and into the demon''s soul.'),
(951, 'UniqueRapier5', 19898, 'A single breeze blows' || char(13) || '
A hundred blades dance'),
(952, 'UniqueShieldStr7', 28999, 'A true predator does not chase; It waits.'),
(953, 'UniqueJewel79', 61751, 'All revere the earth they walk,' || char(13) || '
For it wields strength beyond compare,' || char(13) || '
Holds knowledge more than thought,' || char(13) || '
Stands long after all else falls.'),
(954, 'UniqueHelmStrInt7', 15963, 'Righteous men seek virtue like tame pups seek praise.'),
(955, 'UniqueHelmStrInt8', 21970, 'Wicked men chase power like stray dogs chase a rat.'),
(956, 'UniqueBodyDex9', 32576, 'Curse their vile Council,' || char(13) || '
They cast me aside as if I am some bastard child.' || char(13) || '
If they only knew the power I possess.'),
(957, 'OfferingToTheGoddess', 17695, 'It is time for the Goddess to give her final verdict.' || char(13) || '
Your fate rests in her even hands.'),
(958, 'UniqueAmulet32', 64327, 'Many things come to one who has nothing.'),
(959, 'UniqueQuiver12', 61434, 'If two great leaders like Lioneye and Kaom' || char(13) || '
had been on the same side of the battle,' || char(13) || '
nothing would remain unconquered.'),
(960, 'UniqueAmulet33', 48249, 'Each death witnessed is a valuable lesson, ' || char(13) || '
and what use is knowledge if it is not put into practice?'),
(961, 'UniqueGlovesInt7', 47089, 'Death does not remove you from our grasp.' || char(13) || '
Death only brings you closer.'),
(962, 'UniqueGlovesInt7x', 16702, '"I feel altered when Administrator Qotra wears these gloves.' || char(13) || '
Somehow, I find that disturbing." ' || char(13) || '
- Researcher Arn'),
(963, 'UniqueFlask18', 2028, 'Travelers of the deep wood speak of a witch' || char(13) || '
whose ale provides a different kind' || char(13) || '
of liquid courage.'),
(964, 'UniqueBodyDexInt5', 29178, 'Thin is the line between mechanical genius and magic.'),
(965, 'UniqueBootsStrInt4', 54712, 'To extend your life as long as possible' || char(13) || '
is to extend all the maladies that come with it.'),
(966, 'UniqueBow16', 64681, 'We stand together. We strike together.'),
(967, 'UniqueScepter17', 24807, 'Breathe deep, and give yourself over to eternity.'),
(968, 'FatedUnique1', 25365, 'Kaom guided his Karui across the sea' || char(13) || '
and spilled their blood on foreign soil.'),
(969, 'FatedUnique2', 40193, 'For dead men require no answer.'),
(970, 'FatedUnique3', 50592, 'There is no wall thicker or stronger than fear.'),
(971, 'FatedUnique4', 40085, 'The Karui boats were closing the gap,' || char(13) || '
but Shavronne had laid for them one final trap.'),
(972, 'FatedUnique5', 22420, 'The overture stretches thin,' || char(13) || '
The chorus gathers to begin.' || char(13) || '
Stacatto, drone, a rest drawn long,' || char(13) || '
Another hears Death''s final song.'),
(973, 'FatedUnique6', 53171, 'Nothing spreads fear faster than the unknown.'),
(974, 'FatedUnique7', 20507, 'The largest rock leaves the deepest mark.'),
(975, 'FatedUnique8', 22897, 'Fire spreads thick and fast.' || char(13) || '
The first spark is never the last.'),
(976, 'FatedUnique9', 27358, 'Flames to guide the Great Spirit to the site of the dead,' || char(13) || '
and smoke to carry them into the sky.'),
(977, 'FatedUnique10', 26394, 'Giant''s blood you cannot tame,' || char(13) || '
as wild as an unwatched flame.'),
(978, 'FatedUnique11', 59390, 'Let it pierce you, let blood flow.' || char(13) || '
Make more room for the soul to grow.'),
(979, 'FatedUnique12', 57019, 'A moment of victory may last an eternity in memory.'),
(980, 'FatedUnique13', 56343, 'May it echo through the halls.'),
(981, 'FatedUnique14', 6611, 'What goes out must come in.'),
(982, 'FatedUnique15', 37230, 'Even the mightiest tree was once just a sapling.'),
(983, 'FatedUnique16', 51326, 'Flesh may freeze and rot,' || char(13) || '
but the soul remains unbroken.'),
(984, 'FatedUnique17', 10636, 'The gryphon knows only the hunt and the flight.'),
(985, 'FatedUnique18', 3334, 'A burned branch leaks sap no more.'),
(986, 'FatedUnique19_', 42619, '"The Vaal, a thousand years ago, ' || char(13) || '
came up with more delightful methods of murder' || char(13) || '
than I could ever wish for." ' || char(13) || '
- Koralus Doomfletch'),
(987, 'FatedUnique20', 3978, 'The lone tree grows thickest.'),
(988, 'FatedUnique21', 27354, 'Where steel-grey clouds gather and crash together,' || char(13) || '
a storm is sure to follow.'),
(989, 'FatedUnique22', 33129, 'The last sweet music to touch Hrimnor''s ears' || char(13) || '
passed right beneath his chin.'),
(990, 'FatedUnique23', 61638, 'No one likes a quiet encore.'),
(991, 'FatedUnique24', 65535, '"The flames are surely coming.' || char(13) || '
I just pray I am long dead before they arrive."' || char(13) || '
- Archbishop Geofri'),
(992, 'FatedUnique25', 30737, 'The soldiers stormed her throne room.' || char(13) || '
The guards held them at bay.' || char(13) || '
The peasants overwhelmed the guards.' || char(13) || '
The nobles paid for their lives.' || char(13) || '
The nobles took her throne,' || char(13) || '
and so she fled to the woods.'),
(993, 'FatedUnique26', 36113, '"A taste of Midnight, and you may never see the dawn."' || char(13) || '
- Inquisitor Maligaro'),
(994, 'FatedUnique27', 24583, '"At last, my beauty is beyond reproach."' || char(13) || '
- Atziri, Queen of the Vaal'),
(995, 'FatedUnique28', 57419, 'It was Doedre who learned that pain is just' || char(13) || '
as much about fear as it is about injury.'),
(996, 'FatedUnique29_', 27889, 'You cannot control the storm,' || char(13) || '
but you can utilise it.'),
(997, 'FatedUnique30', 9476, 'Die for no one.'),
(998, 'FatedUnique31', 14896, '"Laws are for city folk.' || char(13) || '
Can''t try a man for murder if you can''t find him."' || char(13) || '
- Taruk, Last of the Wildmen'),
(999, 'FatedUnique32', 48896, 'Beneath the frozen eye of Lunaris' || char(13) || '
a new world will be born.' || char(13) || '
A crystalline, perfectly still utopia.');
INSERT INTO "FlavourText" ("_row", "Id", "__col1", "Text") VALUES
(1000, 'FatedUnique33', 22234, 'A single taste leaves you wanting more.'),
(1001, 'FatedUnique34', 31411, 'Burning goddess, shine so bright.' || char(13) || '
Set the world ''fore you alight.'),
(1002, 'FatedUnique35', 36499, 'An open mouth, a blinding shriek,' || char(13) || '
Your mind goes dark, your body weak.'),
(1003, 'FatedUnique36', 5864, 'Embrace your burning ambition.' || char(13) || '
Embrace your frozen heart.' || char(13) || '
You will be transformed.'),
(1004, 'FatedUnique37', 20932, '"Even for the great Magi,' || char(13) || '
time passes without relent."' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(1005, 'FatedUnique38', 7646, '"The most dizzying heights are surrounded by precipitous falls.' || char(13) || '
Progress cannot be eternal."' || char(13) || '
- Doryani of the Vaal'),
(1006, 'FatedUnique39', 5269, '"Cut down the tallest tree,' || char(13) || '
and another becomes the tallest."' || char(13) || '
- Old Ezomyte saying'),
(1007, 'FatedUnique40', 27019, 'Follow your most basic instincts.' || char(13) || '
The rest will come naturally.'),
(1008, 'FatedUnique41', 17468, 'Asenath loosed arrows with almost musical rhythm,' || char(13) || '
a rhythm matched by her nearly inaudible whispers,' || char(13) || '
and the crunch of the dead hitting the dust.'),
(1009, 'FatedUnique42', 57035, '"Make a man believe he is doing the world a good deed,' || char(13) || '
and there is nothing you can''t make him do."' || char(13) || '
- Malachai, the Soulless'),
(1010, 'FatedUnique43', 8838, 'There is no cost too great to pay for power.' || char(13) || '
Merely men who lack the conviction to pay it.'),
(1011, 'FatedUnique44', 4583, 'The breath of life is theirs to take.'),
(1012, 'FatedUnique45', 38714, 'By light we are shadowed,' || char(13) || '
in darkness we are bound.'),
(1013, 'FatedUnique46', 23487, 'Few men command an army better' || char(13) || '
than the Great Meginord of the North'),
(1014, 'FatedUnique47', 14323, 'Few men can guide their people' || char(13) || '
like the Great Meginord of the North'),
(1015, 'FatedUnique48', 13945, 'Fury fuels defiance.'),
(1016, 'FatedUnique49', 13358, 'Hyrri''s quick thinking led to victory,' || char(13) || '
but it came at the cost of respect.'),
(1017, 'FatedUnique50', 1487, 'Make a man hot, and his heart will skip a beat.' || char(13) || '
Set a man on fire, and his heart will skip all beats.'),
(1018, 'FatedUnique51', 53638, 'The night dances on' || char(13) || '
Wine continues to flow' || char(13) || '
Your skin looking pale' || char(13) || '
Your soul letting go'),
(1019, 'FatedUnique52', 15964, '"Confess your sins to me. My god will not be nearly so forgiving."' || char(13) || '
- Archbishop Geofri of Phrecia Cathedral'),
(1020, 'FatedUnique53', 65403, '"Please, take whatever you want. Just don''t kill me"' || char(13) || '
"But then I wouldn''t have everything I want, would I?"'),
(1021, 'FatedUnique54', 12939, 'As death arrives, so too does instinct.'),
(1022, 'FatedUnique55', 14178, 'Legend tells of a time when Solaris will' || char(13) || '
burst forth from Lunaris,' || char(13) || '
and night will be eternally banished.'),
(1023, 'FatedUnique56', 55536, 'One more partner by the hand,' || char(13) || '
Let your steps entwine.' || char(13) || '
Spin together, swing as one,' || char(13) || '
And dance with death in trine.'),
(1024, 'FatedUnique57', 57634, '"Stand steadfast in the face of destruction.' || char(13) || '
The Council cannot afford to falter."' || char(13) || '
- Mauritius, the Iron Heart'),
(1025, 'FatedUnique58', 37037, 'The weight of faith is great' || char(13) || '
Yet it is never borne alone.'),
(1026, 'FatedUnique59_', 19437, 'Even the dead dare not' || char(13) || '
trespass into Ullr''s dominion.'),
(1027, 'FatedUnique60', 33179, '"Though Geofri''s beacon was extinguished,' || char(13) || '
his embers may yet light our way."' || char(13) || '
- Victario, The People''s Poet'),
(1028, 'FatedUnique61', 46655, 'As you guided me, now I guide others.'),
(1029, 'ProphecyWickedKingChest', 6973, 'Temptation is man''s greatest folly.'),
(1030, 'UniqueRing42', 5704, 'The Thaumaturgical masters of the Eternal Empire,' || char(13) || '
as unpredictable and varied as they were,' || char(13) || '
all understood one thing:' || char(13) || '
Free thinking leads to free action.'),
(1031, 'UniqueTwoHandSword11', 44837, 'Faintly gleaming in the moonlit night,' || char(13) || '
Kondo''s Pride was primed to fight.' || char(13) || '
Driven by an inner fire,' || char(13) || '
bloodlust, spite and ill desire.' || char(13) || '
He swiftly moved to strike them all,' || char(13) || '
wreaking havoc like a steel squall.'),
(1032, 'UniqueRing43', 57375, 'They will rise and fall in fire and blood.'),
(1033, 'UniqueBodyStr7', 61889, 'The turtle''s shell one day becomes its tomb.'),
(1034, 'UniqueTwoHandMace11', 12288, 'The mind may have no limits, but the skull sure does.'),
(1035, 'UniqueOneHandSword20', 16941, 'Quickly cooled the steel,' || char(13) || '
but never could it forget' || char(13) || '
the heat of the forge.'),
(1036, 'UniqueAmulet35', 42690, '"...and so He said: ''Let only the good meet my gaze''' || char(13) || '
and no eye met His. So He called down the cleansing flames' || char(13) || '
and let black smoke sweep the Sinners away."' || char(13) || '
- Book of Innocence'),
(1037, 'UniqueBow17', 64840, 'A hundred blind heads, each seeking the taste of prey on the air.'),
(1038, 'UniqueHelmetDex7', 46317, 'If you know where to strike, you need only strike once.'),
(1039, 'UniqueRing44', 46955, 'They wrap around you' || char(13) || '
until your blood turns as cold as theirs.'),
(1040, 'UniqueClaw15', 31428, 'With increasing mastery over death' || char(13) || '
comes an increasing desire for it.'),
(1041, 'UniqueOneHandSword21', 38976, 'Breathe deep, my child.' || char(13) || '
Let the frigid air engulf your soul.' || char(13) || '
Embrace the eternal cold, ' || char(13) || '
And it will embrace you back.'),
(1042, 'UniqueTwoHandSword12', 21408, 'The end is written into the beginning.'),
(1043, 'UniqueJewel80', 8526, 'They roamed, they fed, they grew,' || char(13) || '
Killing as they went,' || char(13) || '
Conquer though they may,' || char(13) || '
Their hearts will never be content.'),
(1044, 'UniqueBootsDexInt5', 56617, 'Step into the void' || char(13) || '
and experience true freedom.'),
(1045, 'UniqueBootsDexInt5x', 51605, '"Test subject was able to walk into the walls of his chamber after breaking a rabbit''s neck.' || char(13) || '
He was not fast enough, however. Suggest we begin excavation to retrieve prototype."'),
(1046, 'UniqueGlovesStrInt5', 12564, 'By my hand, the inert is given life.' || char(13) || '
By my hand, that which rots is reborn.' || char(13) || '
There is nothing that cannot be changed.' || char(13) || '
Nothing.'),
(1047, 'UniqueRing45', 33653, '"I don''t always have a flame handy' || char(13) || '
when a fresh delinquent walks through our gates."' || char(13) || '
- Brutus, Warden of Axiom'),
(1048, 'UniqueFlask19', 30127, '"Think of those that cursed us, judged us, ' || char(13) || '
and burned our sisters upon the pyre. ' || char(13) || '
Think of their names as you drink, ' || char(13) || '
and even their children will feel what we do to them today." ' || char(13) || '
-Vadinya, to her coven'),
(1049, 'UniqueFlask20', 10623, 'All things must die.' || char(13) || '
Whether you burn out or explode is up to you.'),
(1050, 'UniqueMap3_16', 17198, 'Please take out your blades,' || char(13) || '
your whips, and your spikes.' || char(13) || '
Class is now in session.'),
(1051, 'AtzirisVessel', 30272, 'Eternal life is within our grasp. Do not let it go.'),
(1052, 'UniqueMap3_17', 31367, 'Some dead have long envied the living.' || char(13) || '
When given the chance, they take from us what they can.' || char(13) || '
So we offer our suffrage.' || char(13) || '
In return, they give only suffering.'),
(1053, 'UniqueJewel81', 44920, '"A stone is not a stone.' || char(13) || '
It is but one part of a fortress."' || char(13) || '
- Ezomyte proverb'),
(1054, 'UniqueJewel82', 58454, '"Do not cause the land to stir,' || char(13) || '
It holds secrets better unknown."' || char(13) || '
- Azmerian proverb'),
(1055, 'UniqueJewel82x', 33446, '"The summoned golems immediately battered through the chamber wall' || char(13) || '
and killed several guards, but their fury only lasted a short time."'),
(1056, 'UniqueJewel83', 8396, '"Kings fall, empires crumble, mortals perish.' || char(13) || '
All turn to earth and sand."' || char(13) || '
- Maraketh proverb'),
(1057, 'TheOath', 9298, 'An oath once made is an oath never broken. Do not delay in keeping it, for I take no pleasure in fools.'),
(1058, 'TheScavenger', 60647, 'Take small pieces of things and then assemble them together'),
(1059, 'MawrBlaidd', 42066, 'Rigwald believed he''d seized great power, but it was the great power that had seized Rigwald'),
(1060, 'BeachBox', 6783, 'BeachBox Placeholder'),
(1061, 'UniqueBow18', 62808, 'Upon the red pyre we are born.'),
(1062, 'UniqueBow19', 6373, 'Upon the grey winds his love spreads.'),
(1063, 'UniqueHelmetStr4', 44293, 'Our skin turns to ash' || char(13) || '
and we are swallowed by his brilliant red light.'),
(1064, 'UniqueHelmetStr5', 29125, 'He burns us to keep us from harm.'),
(1065, 'UniqueAmulet37', 36548, 'His is our heart.' || char(13) || '
To its beat we all are driven.'),
(1066, 'UniqueAmulet38', 10056, 'We are his blood.' || char(13) || '
Through us he carries his burning message.'),
(1067, 'UniqueWand15', 39827, 'We remember the stillness.' || char(13) || '
Then the great fall.' || char(13) || '
The pain of separation.' || char(13) || '
We return once more.'),
(1068, 'UniqueWand16', 21914, 'We fracture and splinter.' || char(13) || '
We pierce our sides.' || char(13) || '
But in the great freeze we are forged anew.'),
(1069, 'UniqueWand16x', 47691, '"Are we mad for attempting to build an engine out of this?' || char(13) || '
Looping cycles, power and pain..." ' || char(13) || '
- Researcher Arn'),
(1070, 'UniqueBodyDex10', 2517, 'We dance in the white, like water,' || char(13) || '
colliding as many and emerging as one.'),
(1071, 'UniqueBodyDex11', 6477, 'We share one space,' || char(13) || '
speak one voice,' || char(13) || '
act through one body.' || char(13) || '
A flawless crystal.' || char(13) || '
Brittle.'),
(1072, 'UniqueBodyDex11x', 61307, '"This is what I''ve been trying to tell you. This prototype' || char(13) || '
was different before. Now, it''s always been this way!"' || char(13) || '
- Researcher Graven'),
(1073, 'UniqueAmulet39', 5860, 'We wait, still as the dead,' || char(13) || '
to join the great avalanche.'),
(1074, 'UniqueAmulet40', 58673, 'A single moment sets in motion an eternal fall,' || char(13) || '
beneath which all are buried.'),
(1075, 'UniqueClaw16', 58533, 'She carries us and nurtures us' || char(13) || '
until we must feed upon each other.'),
(1076, 'UniqueClaw16Royale', 30071, 'She carries us and nurtures us' || char(13) || '
until we must feed upon each other.'),
(1077, 'UniqueClaw17', 62429, 'She thinks and we act.' || char(13) || '
She acts and we think.' || char(13) || '
Fragments of the whole that washes clean the skies.'),
(1078, 'UniqueShieldInt8', 3305, 'She looked upon her reflection' || char(13) || '
and trembled, and shook,' || char(13) || '
until she was not what she saw.'),
(1079, 'UniqueShieldInt9', 63094, 'She could see what she was not;' || char(13) || '
a silhouette wreathed in light.' || char(13) || '
And she was still.'),
(1080, 'UniqueAmulet41', 48271, 'When she of many mouths spoke,' || char(13) || '
we bowed in awe and were crushed.'),
(1081, 'UniqueAmulet42', 29950, 'But the fool did not bow.' || char(13) || '
The fool stood and questioned.' || char(13) || '
And the fool was unwritten.'),
(1082, 'UniqueBootsStr6', 35428, 'We move to be closer to her, but the distance yet grows.'),
(1083, 'UniqueBootsStr7', 12349, 'We leave a trail, that we may know' || char(13) || '
where never we will return.'),
(1084, 'UniqueBootsStr7x', 12002, '"Researchers will please refrain from combining our prototypes with existing relics' || char(13) || '
of power. The temptation is obvious, but the results can be... unpredictable." ' || char(13) || '
- Administrator Qotra'),
(1085, 'UniqueTwoHandAxe11', 64090, 'We feel the Mother''s love' || char(13) || '
and beg to return to her womb.'),
(1086, 'UniqueTwoHandAxe12', 47822, 'At last she holds us,' || char(13) || '
and so we turn to dust.'),
(1087, 'UniqueShieldStr8', 17691, 'We are within her reach,' || char(13) || '
and when the time is right,' || char(13) || '
she will reach into us.'),
(1088, 'UniqueShieldStr9', 18297, 'Our hearts cry out' || char(13) || '
but are silenced by our flesh' || char(13) || '
and so we give up our flesh.'),
(1089, 'UniqueOneHandSword22', 63056, 'His lucky thralls dream eternal,' || char(13) || '
but we must crawl on our own.'),
(1090, 'UniqueOneHandSword23', 35725, 'They grow fat and ripe in slumber.' || char(13) || '
To be fed upon when he wakes.'),
(1091, 'UniqueBodyInt13', 18220, 'We happily give our limbs.' || char(13) || '
A net woven to keep safe the bones of the Lords.'),
(1092, 'UniqueBodyInt14', 64561, 'The Lords are chosen so carefully.' || char(13) || '
Only they may grace His flesh.'),
(1093, 'UniqueJewel85', 8973, 'We flow like blood into Chayula''s open mouth,' || char(13) || '
and spill into the land we have watched forever.'),
(1094, 'UniqueJewel86', 58519, 'We coagulate; a crimson shell' || char(13) || '
that suffocates the unworthy.'),
(1095, 'UniqueJewel87', 12294, 'We climb like vines up Chayula''s arms,' || char(13) || '
reaching into the world that should be ours.'),
(1096, 'UniqueJewel88_', 61028, 'We take root in the dirt' || char(13) || '
and strangle those who tread upon it.'),
(1097, 'UniqueJewel89', 32616, 'We crash against Chayula''s body,' || char(13) || '
and fall like rain into the place we cannot go.'),
(1098, 'UniqueJewel90', 5782, 'We swell and flood' || char(13) || '
and drown the undeserving beneath our might.'),
(1099, 'UniqueShieldStr10', 24179, 'Tukohama couldn''t lose a fight in his fortress,' || char(13) || '
So he carried his fortress to the fight.'),
(1100, 'UniqueShieldStr10x', 16342, '"As one of our few creations that did not cost any fatalities,' || char(13) || '
Prototype #10 bore unexpectedly positive results."'),
(1101, 'UniqueRing46', 12741, 'A man can spend his whole life fishing' || char(13) || '
before he learns it is not fish that he seeks.'),
(1102, 'UniqueWand17', 20475, 'Without light, there can be no shadow.'),
(1103, 'UniqueHelmetStrInt8', 11979, 'Greatest is the Brine King''s domain,' || char(13) || '
and every day it grows a little greater,' || char(13) || '
not through force, but patience.'),
(1104, 'UniqueFlask21', 37379, 'And from the ashes he rose, like a black cloud.' || char(13) || '
The Sin of one became the Sin of many.'),
(1105, 'UniqueShieldInt10', 16799, 'Without night, there can be no day.'),
(1106, 'UniqueTwoHandAxe13', 31258, 'Hinekora bound Kitava to a rock ' || char(13) || '
that Kitava could not lift with all his might.' || char(13) || '
Kitava vowed that when he broke free, ' || char(13) || '
he would devour every soul in Hinekora''s domain.'),
(1107, 'UniqueStaff17', 8421, '"The world is not simply black and white,' || char(13) || '
it is not divided into good and evil.' || char(13) || '
But black and white, good and evil, do exist,' || char(13) || '
and we must know how to recognize them."' || char(13) || '
- Archbishop Geofri'),
(1108, 'UniqueStaff17x', 5745, '"Lab Two suffered significant structural damage in the process of creating' || char(13) || '
Prototype #77. It is, however, the closest we''ve come to perfection."'),
(1109, 'UniqueBelt22', 58320, '"Some blows must be evaded. Some blows must be endured.' || char(13) || '
The trick is to tell them apart."' || char(13) || '
- Daresso, the Sword King'),
(1110, 'UniqueDagger15', 7617, 'All children must eat.'),
(1111, 'UniqueBodyStrDex7', 54075, 'Simple is the life of the bear.'),
(1112, 'UniqueAmulet43', 42952, 'The dreamer stirs, the world trembles. '),
(1113, 'ThePorcupine', 60337, 'The first quill separates the quick learners from the dead.'),
(1114, 'TheComingStorm', 33152, 'No man may hope to turn back the storm. You can only hope you do not attract its ire.'),
(1115, 'ThePolymath', 45926, 'Genius knows no limits.'),
(1116, 'TheWolverine', 42354, 'Claw them from the bottom, you''ll be glad that you have got ''em, claw them from the top, you''ll never want to stop.'),
(1117, 'Mitts', 39846, 'Those whose hands are their livelihood know the importance of keeping them safe and warm.'),
(1118, 'TheWretched', 5207, 'Necromancers, believe me, are more terrifying than their thralls.'),
(1119, 'TheWolvenKingsBite', 7991, '<size:31>{A wolf does not bite his mate as he does his prey, yet both begin with bared teeth. Know who you are, and you will know the meaning of the bite.}'),
(1120, 'TheStandoff', 6115, 'Sometimes your greatest enemy is the only one keeping you breathing.'),
(1121, 'TheForsaken', 52069, 'You gave us life and love, more than you could spare. Now you''re gone, and we are stranded, alone, cold and without purpose.'),
(1122, 'TheGarishPower', 44328, 'Maligaro may have valued function over form, but that did not mute his flair for the dramatic.'),
(1123, 'LingeringRemnants', 40650, 'Never dying, yet not living,' || char(13) || '
Endlessly they wander' || char(13) || '
beneath the harvest moon.'),
(1124, 'TheSparkAndTheFlame', 48384, 'When sky meets ground the flames can be found, but who has the will to tame them.'),
(1125, 'TheSaintsTreasure', 10160, '<size:31>{Publicly, he lived a pious and chaste life of poverty. Privately, tithes and tributes made him and his lascivious company very comfortable indeed.}'),
(1126, 'CallToTheFirstOnes', 4150, 'The Ezomyte, desperate for aid, cried out to the gods.'),
(1127, 'TheValleyOfSteelBoxes', 46817, '"The most valuable treasures should be hidden in plain sight." ' || char(13) || '
- Ina, Keeper of Goods'),
(1128, 'UniqueChest11', 4270, 'TBC'),
(1129, 'UniqueBootsDex11', 29123, 'The higher you soar, the further you must fall. '),
(1130, 'UniqueBodyStr8', 5538, 'The pirates of Pondium know that full pockets have a tendency to sink.'),
(1131, 'UniqueAmulet36', 40851, 'Friendship worth its weight in gold,' || char(13) || '
a treasure every day.' || char(13) || '
I thought together we''d grow old,' || char(13) || '
until fate pulled you away.'),
(1132, 'UniqueBelt23', 17754, 'You were always there, by my side,' || char(13) || '
whether we sat or played.' || char(13) || '
Our friendship was a joyful ride,' || char(13) || '
I wish you could have stayed.'),
(1133, 'UniqueTwoHandMace12', 7275, 'The sea strikes the rock relentlessly.' || char(13) || '
Whether in one day or in ten thousand years,' || char(13) || '
eventually the rock will crumble,' || char(13) || '
and the Brine King''s domain will grow.'),
(1134, 'UniqueJewel91', 4810, 'Malachai ran roughshod over every ethical boundary in pursuit of creating the ideal gemling.' || char(13) || '
For him, there was no doubt that the end would justify the means.'),
(1135, 'UniqueJewel92', 29832, 'After years of subterfuge, sabotage, and sacrifice,' || char(13) || '
Sarn had become a powder keg just waiting to explode.' || char(13) || '
Finally, Victario lit the match.'),
(1136, 'UniqueJewel93', 62609, 'Even as the tide turned, and victory swiftly became impossible,' || char(13) || '
the legionnaires of Lioneye''s Watch stood their ground and fought on,' || char(13) || '
every last man dying a brutal, but honourable death.'),
(1137, 'UniqueJewel94', 27502, 'Cadiro watched young Chitus play in the frostbitten grass, care-free, happy,' || char(13) || '
and unburdened by the responsibility the Perandus scion would soon endure.'),
(1138, 'UniqueJewel95', 36859, 'As Malachai stepped into the Highgate mines,' || char(13) || '
cold winds billowed from the mountain above.' || char(13) || '
One final, feeble attempt to save what was meant to be eternal.'),
(1139, 'UniqueJewel96', 63841, 'News of Kaom''s victory in the south spread quickly.' || char(13) || '
Those in support of the coming rebellion bided their time.' || char(13) || '
The rest fled like rats from a fire.'),
(1140, 'UniqueJewel97', 55748, 'The winter that followed the Cataclysm was especially harsh.' || char(13) || '
Wraeclast''s few survivors fought to the death for the last scraps of bread.'),
(1141, 'UniqueJewel98', 21351, 'Emperor Chitus could offer you a gift with one hand,' || char(13) || '
and drive a blade into your back with the other.' || char(13) || '
His blend of brutality and charisma cultured a potent ' || char(13) || '
mixture of fear and admiration among the masses.'),
(1142, 'UniqueJewel99', 55638, 'The Maraketh knew that a mountain path' || char(13) || '
free of vegetation was cut by regular avalanches,' || char(13) || '
and so the advancing Eternals were unwittingly drawn into a deathtrap.'),
(1143, 'UniqueJewel100', 35106, 'At night, as a young Daresso shared his bed with a woman whose name he could not recall,' || char(13) || '
his thoughts remained in the one place he called his own: The Grand Arena.'),
(1144, 'UniqueJewel101', 51352, 'The infamous Weylam Roth was never afraid' || char(13) || '
to push the boundaries of Templar authority,' || char(13) || '
and was never deterred when the Templar pushed back.'),
(1145, 'UniqueJewel102', 13115, 'Izaro gave rise to Chitus.' || char(13) || '
Chitus gave rise to Voll.' || char(13) || '
None could know how it would end.' || char(13) || '
None could stop it.'),
(1146, 'UniqueJewel103', 59877, 'Exposure led to the deaths of many slaves.' || char(13) || '
And it was the duty of slaves to bury the dead in the frozen ground.' || char(13) || '
A growing circle of misery and death ' || char(13) || '
that the elite were all too happy to sustain.'),
(1147, 'UniqueJewel104', 42964, 'The Cataclysm was but the first act in a play of horrors.' || char(13) || '
The dead lingered, and the living began to rot.'),
(1148, 'UniqueJewel105', 20155, '"Rage, malice, hunger - some traits are more easily carried across the barrier of death."' || char(13) || '
- Kadavrus, Surgeon to the Umbra'),
(1149, 'UniqueJewel106', 34065, 'Of the elements at the thaumaturgist''s disposal, lightning remained the least understood.' || char(13) || '
The simple passage of energy from one to another could result in profound power, or rapid death.'),
(1150, 'UniqueJewel107', 32454, 'Sarn''s crematorium, built amidst the city''s slums, ' || char(13) || '
coated the nearby shanties in a film of ash.' || char(13) || '
The dwellers grew ill, sputtering and coughing,' || char(13) || '
and in this way the crematorium guaranteed it would have many customers.'),
(1151, 'UniqueJewel108', 8806, 'The Eternal Empire gave few freedoms to the Ezomytes, but fostered their talents as archers. ' || char(13) || '
At auction, an Ezomyte slave''s value was only as good as their aim.'),
(1152, 'UniqueStaff18', 51106, 'You have been found guilty.' || char(13) || '
Let the fires cleanse you of your sins.'),
(1153, 'UniqueGlovesStrDex8', 54667, '"A master artist takes his time when he''s painting.' || char(13) || '
Unfortunately, my kind doesn''t often have that luxury."' || char(13) || '
- Coralito, Brotherhood of Silence'),
(1154, 'UniqueHelmetStr6', 58756, '"The Emperor''s trusted surgeons are not the only ones who ' || char(13) || '
practice the dark arts. Some of us are just more discreet."'),
(1155, 'UniqueBodyDexInt7', 56139, 'What mother wouldn''t give her life for that of her children?'),
(1156, 'UniqueOneHandSword24', 16813, '"Impossibly heavy, yet the ancient edge is as keen as any modern blade''s.' || char(13) || '
A reminder that, in the end, when we lie in the bellies of worms,' || char(13) || '
it is what we make that makes us."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 47'),
(1157, 'UniqueHelmetStrInt9', 53475, '"To touch it is to be overwhelmed with the need to carve your name into history.' || char(13) || '
A face no one remembers, yet once you have seen it, you will never forget."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 48'),
(1158, 'UniqueHelmetStrInt7', 61181, 'A strong pair of legs may carry you far,' || char(13) || '
but a silver tongue and a few brutes' || char(13) || '
can take you to the edge of the world.'),
(1159, 'UniqueBodyDexInt6', 17758, 'Don''t hesitate; bring death to all, conclusively and swiftly,' || char(13) || '
or they will give you the same treatment.'),
(1160, 'UniqueSceptre17', 50599, 'After the fires swept down from the sky and swallowed the city,' || char(13) || '
all that lingered, as if locked in time,' || char(13) || '
was a memory of that which was gone, a whisper of deeds undone.'),
(1161, 'UniqueTwoHandAxe15', 16110, 'A sharp and heavy beat,' || char(13) || '
discorded, out of tune,' || char(13) || '
when you hear it on the wind,' || char(13) || '
you know death will follow soon.'),
(1162, 'UniqueBodyInt12', 1443, 'Whiff of cold, tiny spark, faintest flicker in the dark.' || char(13) || '
Embers swirl, ice takes form, sky exposed - Death''s perfect storm.' || char(13) || '
Frost and thunder, flames shine bright, ruin walks the land tonight.' || char(13) || '
By your hand they dance and bend, wield them and brook no end.'),
(1163, 'UniqueClaw18', 5428, 'To discover how cruel nature can be,' || char(13) || '
you need only shake the wrong branch.'),
(1164, 'UniqueDagger16', 22344, 'Some things must die so that others can live.'),
(1165, 'UniqueAmulet44', 47687, '"He does not love. He does not feel regret or remorse.' || char(13) || '
He does not think about consequences, only possibilities.' || char(13) || '
If that does not describe a monster, tell me: what does?"' || char(13) || '
- Archbishop Geofri'),
(1166, 'UniqueBodyDexInt8', 32282, 'Ask any tracker and they''ll tell you:' || char(13) || '
the most dangerous animals' || char(13) || '
are the ones who don''t bother to hide.'),
(1167, 'UniqueGlovesDexInt7', 32389, '"Decomposition takes hold too quickly!' || char(13) || '
No, if we are to keep the specimen in perfect shape,' || char(13) || '
we must begin the process before expiry."'),
(1168, 'UniqueGlovesInt8', 46373, '"Nothing is more natural than competition.' || char(13) || '
One feasts, another starves.' || char(13) || '
One blossoms, another withers.' || char(13) || '
And one cannot catch the golden sunlight' || char(13) || '
without casting a bitter shadow."' || char(13) || '
- Cadiro Perandus'),
(1169, 'UniqueGlovesInt8x', 39203, '"There seems to be some innate relationship between the forces of' || char(13) || '
chaos and cold. Perhaps we should consult an occultist."'),
(1170, 'UniqueBootsInt8', 64252, 'Though the path we walk is the same,' || char(13) || '
each journey is different.'),
(1171, 'UniqueBootsInt8x', 5359, '"Prototype #56 was deemed safe, but judging by Administrator Qotra''s new hustle' || char(13) || '
and improved ability to micromanage us, I''m not so sure." ' || char(13) || '
- Researcher Graven'),
(1172, 'UniqueGlovesStrInt6', 42793, 'You do not cease to be when you die' || char(13) || '
any more than the caterpillar ceases to be when it cocoons.' || char(13) || '
Come, let me show you.'),
(1173, 'UniqueGlovesStrInt6x', 7713, '"Prototype #73 is a near perfect opposite of the original. Perhaps our failures' || char(13) || '
are due to some unknown polarity we have yet to discover."'),
(1174, 'UniqueHelmetInt12', 58778, 'The impediments of flesh are weak.' || char(13) || '
The air we breathe knows no such boundaries.' || char(13) || '
I exhale, and you inhale,' || char(13) || '
and inexorably we inch towards oneness.'),
(1175, 'UniqueBodyDex12', 19515, 'Feed a beast and it will not hunt.' || char(13) || '
Protect it and it will not fight.' || char(13) || '
Ferocity must be learned, not taught.' || char(13) || '
It is suffering that forges the greatest warriors.'),
(1176, 'UniqueBodyInt16', 13624, 'He took me by my hand, promised me power beyond compare.' || char(13) || '
But I did not do it for power.' || char(13) || '
I did it for love.' || char(13) || '
And I''d do it again in an instant.'),
(1177, 'UniqueGlovesDexInt8', 64958, 'What man does not wish for immortality?'),
(1178, 'UniqueClassicMap1', 49750, 'Whispered memory,' || char(13) || '
A shimmer in the darkness.' || char(13) || '
Forgotten no more.'),
(1179, 'Unique340Reliquary', 12287, 'Though flesh may decay, and bones turn to dust, the spirit fades not.' || char(13) || '
Floundering eternal in pools of tranquil dark.'),
(1180, 'UniqueVaalReliquary', 53992, 'Ambition followed progress,' || char(13) || '
Vanity followed passion,' || char(13) || '
Hubris followed intellect...' || char(13) || '
And silence followed all.'),
(1181, 'UberVenariusKey', 18244, 'I have already lost more' || char(13) || '
than you shall ever possess.'),
(1182, 'UberEaterOfWorldsKey', 7882, 'That which could not be digested' || char(13) || '
remains lost within, the buried remnants' || char(13) || '
of whole cultures, of entire worlds.'),
(1183, 'UberMavenKey', 34137, 'Champions of her collection may take what' || char(13) || '
they wish, so long as they use it to entertain her...'),
(1184, 'UberSearingExarchKey', 55624, 'Minds are not the only thing' || char(13) || '
the Cleansing Fire keeps eternal...'),
(1185, 'UberSirusKey', 41890, 'There is a place, a state of being,' || char(13) || '
where all that you love forgets you.'),
(1186, 'UberShaperKey', 57996, 'Step into the inner sanctum of the minds of old' || char(13) || '
Enter a realm untouched even by starlight' || char(13) || '
Through transcendence, bend reality to your will.'),
(1187, 'UberUberElderKey', 57106, 'A great Silence falls...'),
(1188, 'UberNeglectVaultKey', 3743, 'Time sweeps us further and further away' || char(13) || '
from the moments in which they lived.'),
(1189, 'UberBenevolenceVaultKey', 54436, 'The cold light of today can never compete' || char(13) || '
with the shining golden aura of yesteryear.'),
(1190, 'UberIgnoranceVaultKey', 34043, 'Surrounded by comfort and kindness' || char(13) || '
all we see are the enemies of the past.'),
(1191, 'CelestialVaultKey', 63463, 'An heirloom of the champions of Wraeclast' || char(13) || '
Lies forgotten in an abandoned reliquary' || char(13) || '
Born of a starry void from which time cannot escape'),
(1192, 'ChestForgottenReliquary', 54383, 'The craftsman rots.' || char(13) || '
His tools rust.' || char(13) || '
But his legacy cuts through the ages.'),
(1193, 'ChestForgottenReliquary2', 22275, 'The words of a man, delicate like life, pass on feebly into forgotten verse,' || char(13) || '
but his creations... his craft shall be championed agelessly.'),
(1194, 'ChestForgottenReliquaryVaal', 29059, 'Time is a river, forking forever into infinite unknowns.' || char(13) || '
Nothing is ever truly gone.' || char(13) || '
It is merely taking a different route to the sea.'),
(1195, 'ChestForgottenReliquaryVenarius', 27809, 'It is not regret that stalks me now...' || char(13) || '
merely the child of my sins.'),
(1196, 'ChestForgottenReliquaryEaterOfWorlds', 25110, 'Remember us.'),
(1197, 'ChestForgottenReliquaryMaven', 64913, 'You are not the first champion to receive this gift,' || char(13) || '
and you will likely not be the last.'),
(1198, 'ChestForgottenReliquarySearingExarch', 52298, 'To a being of the stars, Time is irrelevant,' || char(13) || '
and memories are but a collection of present moments.'),
(1199, 'ChestForgottenReliquarySirus', 63918, 'Though you might not see it, a sliver of my soul remains,' || char(13) || '
and I am trying with all my strength to get back to you.'),
(1200, 'ChestForgottenReliquaryUberShaper', 61683, 'You did not slay me.' || char(13) || '
You saved me.' || char(13) || '
I forgive you.'),
(1201, 'ChestForgottenReliquaryUberUberElder', 20819, 'There are holes in the sky...'),
(1202, 'ChestForgottenReliquaryNeglect', 31922, 'A touch on the shoulder.' || char(13) || '
A smile on a sunny day.' || char(13) || '
An idle conversation...'),
(1203, 'ChestForgottenReliquaryBenevolence', 4194, 'Those we idolise are not gods.' || char(13) || '
They were men, with flaws.' || char(13) || '
They made... mistakes.'),
(1204, 'ChestForgottenReliquaryIgnorance', 42409, 'Some wounds, we do not let heal.' || char(13) || '
Some wounds, we poke and prod,' || char(13) || '
simply to keep the feeling alive.'),
(1205, 'ChestForgottenReliquaryCosmic', 48554, 'Time stands still, and a new champion ascends.'),
(1206, 'UniqueBelt24', 53913, 'All creatures have the potential for greatness' || char(13) || '
or unequivocal failure.'),
(1207, 'UniqueBelt21', 45476, 'Vaal bloodpriests were among the earliest intellectuals on record. ' || char(13) || '
It was they who found that a newly freed soul would ' || char(13) || '
desperately cling to any other source of life.'),
(1208, 'UniqueBelt21x', 63836, '"Curious. The test spike penetrated the subject''s flesh, but the chest wound' || char(13) || '
was not as deep as expected. There is something here..."'),
(1209, 'UniqueShieldStrDex4', 12679, 'Silent, silent night,' || char(13) || '
Quench the holy light.'),
(1210, 'UniqueShieldStrInt11', 60219, 'Eternal soldiers fight for glory or death.' || char(13) || '
The Solaris Vanguard know only glory.'),
(1211, 'MightIsRight', 18418, 'The mind had much to endure before the advent of thaumaturgy.'),
(1212, 'TheOpulecent', 1543, 'Wealth can, in fact, buy happiness.'),
(1213, 'StruckByLightning', 65471, '''Lightning never strikes the same place twice''' || char(13) || '
is really just wishful thinking.'),
(1214, 'AtzirisArsenal', 58345, 'In the prison of all sins, will you grasp godhood or sorrow? Only hope lies under the shadows.'),
(1215, 'TheRuthlessCeinture', 54253, 'In combat, a warrior must first be resourceful,' || char(13) || '
and second, decisive.'),
(1216, 'NoTraces', 4367, '<size:31>{There is no mistake so great that it cannot be undone.}'),
(1217, 'TheRealm', 52446, 'If you wish to rush into strange places, be prepared to face strange things.'),
(1218, 'TheEyeOfTheDragon', 17710, 'Some powers are far too great even for the' || char(13) || '
gods of old.'),
(1219, 'TheBlazingFire', 54883, 'Lethal, untouchable, keen, aflame. Just what I was looking for.'),
(1220, 'LeftToFate', 21757, '<size:30>{Many strive for greatness,' || char(13) || '
but it is challenge, unforeseen,' || char(13) || '
that forges heroes.}'),
(1221, 'Rebirth', 45858, 'He shattered Her smile' || char(13) || '
Scattered the fragments like ash' || char(13) || '
All she did was laugh'),
(1222, 'TheInsatiable', 50167, 'A lust for souls. The urge to kill just to satisfy its thirst. An unbearable burden that would make even the purest heart blacken over time.'),
(1223, 'TheObscured', 27914, 'Our world, dangerous as it is, is far safer than what lies just beyond our sight.'),
(1224, 'TheIronBard', 40998, '<size:19>{Fourfold the refrain, fortissimo cheer.' || char(13) || '
One hundred rent twain, naught left for a bier.' || char(13) || '
The song rattles on, though hollow a bit.' || char(13) || '
See the hope is gone, no prize shall ye get.}'),
(1225, 'ForbiddenPower', 40834, 'Some things should not be used. Some power is too great a risk.'),
(1226, 'TheBreach', 45282, 'Ever get the feeling you''re being watched...?'),
(1227, 'TheDreamer', 9974, '<size:29>{A dark note drips ' || char(13) || '
from the dreamer''s lips, ' || char(13) || '
A honeyed melody. ' || char(13) || '
We stand, we fall ' || char(13) || '
on his beck and call, ' || char(13) || '
for in his dream we''re free.}'),
(1228, 'TheWorldEater', 17667, 'Its body knows no limits. Its appetite knows no bounds.'),
(1229, 'TheDeceiver', 41757, 'Beware the combatant who shows no confidence, yet still enters the ring, for they are surely hiding something.'),
(1230, 'BlessingofGod', 27854, 'When the darkness weighs upon you, grow light from within.'),
(1231, 'ThePuzzle', 41708, 'As countless fractures weaken the divide, nightmares seep through from the other side.'),
(1232, 'TheWitch', 52535, '<size:27>{A wanderer in the wild strives ' || char(13) || '
Against countless foes he survives ' || char(13) || '
A fool pursues a quest contrived ' || char(13) || '
By the gift of the witch, alive.}'),
(1233, 'ImmortalResolve', 47150, 'The threads of fate are the strongest ties.'),
(1234, 'TheJewellersBoon', 60045, 'The jeweller''s true talent is the capacity to see a jewel''s beauty before they draw it out.'),
(1235, 'TheDarkestDream', 15102, 'A dream from which you cannot awake is nothing other than a nightmare.'),
(1236, 'TheMaster', 56082, 'In a world filled with chaos, he could always seek comfort in the hands of his master.'),
(1237, 'TheFathomlessDepths', 12425, 'Fall into endless night; a voyage into an ocean of oblivion.'),
(1238, 'TheUndaunted', 62861, '<size:29>{"Fate was always my nemesis... ' || char(13) || '
But it didn''t stop me then, and it won''t stop me now."' || char(13) || '
- Kjetilbrann, The Undaunted}'),
(1239, 'TheAdmirer', 12444, 'Lucian lost himself in ancient scrolls and found in those scrolls a love whose power bridged a millennium.'),
(1240, 'TheSwordKingsSalute', 25659, '<size:26>{Many were slain by the sword king ' || char(13) || '
Their blood decorating his ring ' || char(13) || '
Those who retreated were slaughtered ' || char(13) || '
Those who fought bravely were honoured}'),
(1241, 'TheArmyOfBlood', 35900, '<size:28>{I gave my mind without a fight, ' || char(13) || '
The twelfth hour I lost control. ' || char(13) || '
The day is gone but there is light, ' || char(13) || '
eyes that glow like red-hot coal.}'),
(1242, 'TheCelestialStone', 58806, 'Stare into its depths too long, and you may lose yourself entirely.'),
(1243, 'Perfection', 34973, 'There are countless worlds, but only those with limitless potential will be able to achieve perfection.'),
(1244, 'TheDreamland', 55908, 'All dreams vanish when the dreamers wake.'),
(1245, 'HarmonyOfSouls', 20051, '<size:29>{Shrieking souls locked away ' || char(13) || '
Hate splits frozen cells asunder ' || char(13) || '
The knot of corruption' || char(13) || '
undone at last}'),
(1246, 'TheSamuraisEye', 41630, 'At night, when the seas are calm, and the skies dark, he can see it. The formless fiend that took his eye, and fractured his mind.'),
(1247, 'TheHaleHeart', 60691, 'Though the years weakened his mind, his body remained deadly as ever.'),
(1248, 'TheMayor', 34066, 'A ruler is only as powerful as he is wealthy. ' || char(13) || '
Control the coin, control the empire.'),
(1249, 'TheUndisputed', 18621, 'To create something truly spectacular, you must risk total failure.'),
(1250, 'TheRiteOfElements', 58814, '<size:29>{A mind as quick as lightning, ' || char(13) || '
fists as hard as stone, ' || char(13) || '
a heart that burns with fury, ' || char(13) || '
and eyes that chill to the bone.}'),
(1251, 'ThreeVoices', 5334, 'The village elders had a curious rule: If you hear three voices scream for aid, flee as fast as you can.'),
(1252, 'TheProfessor', 47463, 'The academic route to knowledge is wide and well-trodden; but it is the untaught one who scales the mountain.'),
(1253, 'TheBeast', 44706, 'To know the monster, you must become the monster.'),
(1254, 'TheInnocent', 20889, 'His brother would not atone, so he took his brother''s life, and with it, his sins.'),
(1255, 'TheWiltedRose', 29429, 'Though the path to divinity is fraught with peril, hope may bloom from within.'),
(1256, 'TheEndlessDarkness', 23376, 'Gaze towards the stars, but beware what gazes back.'),
(1257, 'BeautyThroughDeath', 35556, 'Her beauty did not fade ' || char(13) || '
her humanity did not survive.'),
(1258, 'ThePriceOfProtection', 40681, 'To protect her mansion, she would cut a deal with anyone. Anything. ' || char(13) || '
' || char(13) || '
Something answered.'),
(1259, 'BoonOfTheFirstOnes', 56452, '<size:28>{Wreathed in the skin and bones' || char(13) || '
of the beasts she slew, ' || char(13) || '
her gift came from what she lost: ' || char(13) || '
her humanity.}'),
(1260, 'TheTwilightMoon', 53386, 'The day is dying, the night is born, the air grows cool, the sky is torn.'),
(1261, 'TheCacophony', 30730, 'Nothing can be heard above the din or seen amongst the turmoil. The senses are shattered. All is left to fate.'),
(1262, 'DivinationCardTheSacrifice', 2930, 'For some, the price of power is never too great.'),
(1263, 'DivinationCardADabOfInk', 40418, 'The Poet''s blood is the Empire''s ink.'),
(1264, 'DivinationCardTheNurse', 56145, 'We tried to tell him to get his head checked.'),
(1265, 'DivinationCardTheMasterArtisan', 34989, 'Perfection is the standard, excellence will be handled on a case by case basis.'),
(1266, 'DivinationCardTheLifeThief', 65171, '"The process of eternal youth is a give and take. You give them death and take their youth."' || char(13) || '
- Zerphi of the Vaal'),
(1267, 'DivinationCardTheSeeker', 57952, 'All that is flawed is worthless. The slightest error, and this might as well be trash.'),
(1268, 'DivinationCardTheMessenger', 13354, '<<hbgi04>><<HBG04>><<HBGAt>><<HBG03>><<HBGAs>><<HBG01>><<HBGAy>><<HBG01>><<HBGBa>>' || char(13) || '
<<hbgi04>><<HBG02>><<HBGAk>><<HBG03>><<HBGBd>>' || char(13) || '
<<hbgi04>><<HBG02>><<HBGAm>><<HBG01>><<HBGAa>>' || char(13) || '
<<HBGBc>><<HBG03>><<HBGAy>><<hbgi00>><<HBGBe>><<HBG03>><<HBGAd>>'),
(1269, 'DivinationCardTheMadKing', 56462, 'Fear the man who lusts for power, for he will do anything to get it.'),
(1270, 'DivinationCardBoonOfJustice', 47320, 'Some gifts are obligations while others are simply opportunities.'),
(1271, 'DivinationCardTheJourney', 32348, 'Oh the places you will go, the sights you will see, the things you will meet.'),
(1272, 'DivinationCardArroganceOfTheVaal', 18361, 'Discovery can lead to beauty, or it can lead to ruin.'),
(1273, 'DivinationCardTheLanding', 20264, 'Warriors of a distant land, you embark on a journey from which you may not return, but which we will be all the better for.'),
(1274, 'DivinationCardTheMountain', 15369, '<size:28>{Charmed by beautiful stones ' || char(13) || '
Consumed with the ' || char(13) || '
pursuit of perfection ' || char(13) || '
Ever deeper into the waiting dark}'),
(1275, 'DivinationCardSevenYearsBadLuck', 18308, 'If enough people believe something to be true, whether or not it is becomes irrelevant.'),
(1276, 'DivinationCardTheGoldenEra', 21112, 'Before gemlings, before thaumaturgy, a simple court magician could enthrall the masses.'),
(1277, 'DivinationCardMonochrome', 55689, '<size:28>{"You cannot portray the world using just one colour. Together, you and I, we will paint our world into perfection." ' || char(13) || '
- Kyra, renegade thaumaturgist}'),
(1278, 'DivinationCardDarkTemptation', 37353, '"Only a fool looks to the occult for power and expects to be spared from its wrath." ' || char(13) || '
- Voll, Emperor of Purity'),
(1279, 'DivinationCardAloneInTheDarkness', 58827, '"Sometimes, the most beautiful treasures...are the ones you cannot have." ' || char(13) || '
- Beryl, Survivor from the Azurite Mines'),
(1280, 'DivinationCardSambodhisVow', 22028, '<size:34>{He dispels dark realms' || char(13) || '
until mortal sufferings' || char(13) || '
yield to hopeful light.}'),
(1281, 'DivinationCardTheLordOfCelebration', 45915, 'Though they were a pack of elite combatants, the Emperor''s royal guards were not ready to face one of his notorious parties.'),
(1282, 'DivinationCardVanity', 59825, ' '),
(1283, 'DivinationCardImperialLegacy', 53822, 'A life lost, A legacy born.'),
(1284, 'DivinationCardBurningBlood', 55580, '<size:28>{There''s a place where up is down, ' || char(13) || '
where right is wrong, ' || char(13) || '
where pleasure is agony, ' || char(13) || '
and where the living wish only for death.}'),
(1285, 'DivinationCardThePrimordial', 34735, 'We play at God with our necromancy, ' || char(13) || '
but forces far more potent ' || char(13) || '
sleep within these stones.'),
(1286, 'DivinationCardEchoesOfLove', 22314, '"I gave up my body for you. I gave up my name for you. And one day I shall give up my life for you."'),
(1287, 'DivinationCardThirstForKnowledge', 19743, '<size:28>{A ravenous mind can readily take in ideas from any source. ' || char(13) || '
Fortunately for the scholars, he has already learned about sustainability.}'),
(1288, 'DivinationCardAlluringBounty', 60808, '<size:28>{A treasure worth killing for ' || char(13) || '
is a treasure worth dying for.}'),
(1289, 'DivinationCardTheFool', 56231, 'Even the most learned man is a fool to his own fate.'),
(1290, 'DivinationCardPrideOfTheFirstOnes', 48542, 'Upon silent paws and masked by the reeds, ' || char(13) || '
Farrul''s hunt begins as the light recedes.'),
(1291, 'DivinationCardTheDeepOnes', 58517, '<size:28>{"The Seas Call, the Mad Answer"}'),
(1292, 'DivinationCardTheArchMagesRightHand', 45865, '"When grasped in his hand, even an ordinary piece of wood can make the heavens tremble with fear."'),
(1293, 'DivinationCardDarkDreams_', 37713, 'No one ever truly understood what she meant when she said she wanted to raise a family.'),
(1294, 'DivinationCardBuriedTreasure', 56041, '<size:28>{You can''t seek riches without getting your hands dirty.}'),
(1295, 'DivinationCardDemigodsWager', 1474, 'Sometimes you need to make your own luck.'),
(1296, 'DivinationCardTheOldMan', 43935, 'Hear me, fish! I love and respect you, but before this day ends I will kill you dead.'),
(1297, 'DivinationCardNooksCrown', 21708, '<size:28>{Every skull was once a person. ' || char(13) || '
Though ''Who?'' is rarely asked. ' || char(13) || '
Friends, who wear ' || char(13) || '
the crown of Nook, ' || char(13) || '
Never need to ask. ' || char(13) || '
They remember.}'),
(1298, 'DivinationCardTheSideQuest', 38358, 'You''ll never know the things you miss if you keep your eyes closed'),
(1299, 'DivinationCardThePriceOfLoyalty', 47044, '"Forge me a carapace from their skin, imbued with their soul. Then feed their flesh to the hounds."'),
(1300, 'DivinationCardTheHeroicShot', 17480, 'Try a thousand times, and eventually you''ll have to give up.'),
(1301, 'DivinationCardRemembrance', 32257, '<size:28>{"For all your struggles, all your achievements, even for the greatest of us, a story is all that remains. Write it well." ' || char(13) || '
' || char(13) || '
-Julius Perandus, Father of Chitus}'),
(1302, 'DivinationCardMoreIsNeverEnough', 13539, 'Greed is a hunger that only grows as you feed it'),
(1303, 'DivinationCardVilePower', 25585, '<size:24>{Dread and danger ' || char(13) || '
makes the air feel thin. ' || char(13) || '
Above, power slumbers, tempting fate. ' || char(13) || '
Greed and ambition ' || char(13) || '
draws countless in, ' || char(13) || '
For those who seek power ' || char(13) || '
can never wait.}'),
(1304, 'DivinationCardTheBargain', 45356, 'In the pursuit of power, as in that of wealth, anything goes.'),
(1305, 'DivinationCardAzyransReward', 48098, 'Method transcends shape and size. Do something in parallel long enough, and you will always find ' || char(13) || '
another way.'),
(1306, 'DivinationCardTheSkeleton', 41039, 'They stand among us, and within us.'),
(1307, 'DivinationCardTheEyeOfTerror', 37922, 'The Lord of Chaos dreams as his Eye gazes, unblinking, at his prize. And soon, all shall tremble before his waking form.'),
(1308, 'DivinationCardTheDemon', 27643, 'A man who hears voices may not necessarily be crazy.'),
(1309, 'DivinationCardAkilsProphecy', 28663, '<size:28>{The hatungo know many answers to the same question, ' || char(13) || '
for time itself is a tangled web.}'),
(1310, 'DivinationCardTheDamned', 57336, '<size:28>{Souls along a conduit of blood, ' || char(13) || '
from one vessel to the next.}'),
(1311, 'DivinationCardVoidOfTheElements', 49467, 'Though the forces of nature are mighty and intimidating, it is their absence which should be feared.'),
(1312, 'DivinationCardTheDeal', 23723, 'In the pursuit of wealth, as in that of power, anything goes.'),
(1313, 'DivinationCardTheWolfsLegacy', 37369, 'The howls and cackling could not mask the sadness.'),
(1314, 'DivinationCardBaitedExpectations', 11982, 'The line between having not enough to do and too much to do is unusually fine.'),
(1315, 'DivinationCardSuccorOfTheSinless', 38858, 'Blessed is the blood of the beholden disciple. The earth is anointed by his step. The damnable are sanctified by his strike.'),
(1316, 'DivinationCardUndergroundForest', 41758, '"In the forest again... But at least I have these."'),
(1317, 'DivinationCardTheEscape', 30973, 'In fleeing reality, you step into the realm of madness.'),
(1318, 'DivinationCardDeathlyDesigns', 47205, '"The Karui was correct; there is virtue in honouring my ancestors."'),
(1319, 'DivinationCardTheChosen', 2163, 'They whose lives were given to clothe the Dark Dreamer... They were the lucky ones.'),
(1320, 'DivinationCardCameriasCut', 44872, '"There are two ways to pay, Gold and Blood. I''ll take my share in both."' || char(13) || '
' || char(13) || '
-Cameria the Coldblooded'),
(1321, 'DivinationCardDivineJustice', 37729, 'Many sought the Goddess'' blessing. Few survived the Labyrinth to receive it.'),
(1322, 'DivinationCardTheFishmonger', 935, 'However vicious Rhoas might be, a dedicated angler may in time tame them.'),
(1323, 'DivinationCardTheBones', 8117, 'The flesh is a prison, and we are finally free.'),
(1324, 'DivinationCardFriendship', 44001, '<size:30>{"Set your life on fire. ' || char(13) || '
Seek those who' || char(13) || '
fan your flames"' || char(13) || '
' || char(13) || '
-Rumi of the Vaal}'),
(1325, 'DivinationCardTheCraving', 26199, 'What was once a passing thought tickling the back of the mind is now a desperate, driving desire.'),
(1326, 'DivinationCardEtchedInBlood', 6759, 'When you strive to write your name on the dense pages of History, someone else, inevitably, must be crossed out.'),
(1327, 'DivinationCardSquanderedProsperity', 58700, '"Our rulers are being ridiculous, and we are suffering."'),
(1328, 'DivinationCardTheStrategist', 7501, 'Know thine enemy better than you know thyself.'),
(1329, 'DivinationCardTheCheater', 63601, 'Sometimes the best way to achieve greatness is to use a shortcut.'),
(1330, 'DivinationCardTheTinkerersTable', 16328, 'Trying to bring your vision to life is enough to drive you mad.'),
(1331, 'DivinationCardTheEasyStroll', 34863, '"I''m going for a walk. I''ll be back soon."' || char(13) || '
' || char(13) || '
 - Blonca''s last words'),
(1332, 'DivinationCardTheProgenyOfLunaris', 44364, 'Born beneath silver light, bearing Lunaris'' mark.' || char(13) || '
Conjuring all his might, the Prodigy turned light to dark.'),
(1333, 'DivinationCardTheEldritchDecay', 11333, 'Time dismantles all things eventually, but some wish to accelerate the process.'),
(1334, 'DivinationCardCouncilOfCats_', 16926, '<size:30>{A King Loved By All,' || char(13) || '
A Shadow Awaiting Nightfall,' || char(13) || '
A Speaker Howling Away,' || char(13) || '
A Hunter Seeking Prey}'),
(1335, 'DivinationCardTheTumbleweed', 6014, 'Love is the only redemption after succumbing to the grasps of the Wasteland.'),
(1336, 'DivinationCardTheHiveOfKnowledge', 48428, 'Within years of knowledge, distilled by careful craftsmanship, lies great power.'),
(1337, 'DivinationCardGiftOfAsenath', 54448, 'The Golden Sekhema''s words could solve many a feud. Just what form that solution took was another matter.'),
(1338, 'DivinationCardANoteInTheWind', 15710, '<size:30>{The artist is long dead,' || char(13) || '
the lyrics are long forgotten,' || char(13) || '
yet the Song of War longs to be sung again}'),
(1339, 'DivinationCardTheGreatestIntentions', 63689, 'Chasing purity in the rising light means facing the darkening edges of the spirit.'),
(1340, 'DivinationCardTheWhiteKnight', 18499, 'Where Decay festers, I shall expunge it, and leave in its place a shining monument.'),
(1341, 'DivinationCardPrometheusArmoury', 50054, 'It is a mortal man''s folly to seek power beyond his comprehension.'),
(1342, 'DivinationCardTheSustenance', 39478, 'She took all she had and turned it into something she was craving.'),
(1343, 'DivinationCardPeacefulMoments', 56502, 'Savour these moments, for they may never return.'),
(1344, 'DivinationCardTheAwakened', 33878, 'Some seek to change the world. Others change the world as a consequence of what they seek.'),
(1345, 'DivinationCardAFamiliarCall_', 62629, 'The mighty huntress always called for her share,' || char(13) || '
But what we shared was a lifelong bond.'),
(1346, 'DivinationCardTheLongCon', 44921, '"This was the proudest moment of my life."' || char(13) || '
' || char(13) || '
"... so far"'),
(1347, 'DivinationCardTheGulf', 7859, '<size:28>{I thought love stronger than all,' || char(13) || '
but time and isolation broke' || char(13) || '
that which madness could not.}'),
(1348, 'DivinationCardTheBitterBlossom', 15673, 'The pain you feel is of no consequence, it is evolution, to be made whole within something greater.'),
(1349, 'DivinationCardTriskaidekaphobia', 43807, 'The Mists of Madness prey on those who harbour the deepest of fears.'),
(1350, 'DivinationCardUnrequitedLove', 38899, '<size:26>{The pale flame of his heart disappeared in his azure reflection.' || char(13) || '
The work of a life.' || char(13) || '
Ambitious, and unfinished.}'),
(1351, 'DivinationCardTheCache', 3405, '<size:23>{Vintage or crafted, Glittering and shiny' || char(13) || '
Dusty or glittering, huge or tiny' || char(13) || '
Secured within a chest ' || char(13) || '
or unearthed from your mining' || char(13) || '
Find jewellery everywhere, ' || char(13) || '
no need for divining!' || char(13) || '
So why is it so hard ' || char(13) || '
to figure out which one to wear?' || char(13) || '
This one makes me stronger, ' || char(13) || '
but does it match my hair?}'),
(1352, 'DivinationCardTheAcademic', 58358, '<size:26>{"Such dedication for so many years,' || char(13) || '
all for a couple extra letters at the front of your name..."}'),
(1353, 'DivinationCardDesecratedVirtue', 48591, '<size:25>{Awoken virtuous slivers of the void,' || char(13) || '
defiled by the avaricious, ' || char(13) || '
seized by the tyrannical.}'),
(1354, 'DivinationCardBrothersStash', 42603, 'Even though he found the stash just in time,' || char(13) || '
He would trade it all away and then some to have him back.'),
(1355, 'DivinationCardUnchained', 20754, 'Mold the world with your bare hands. Be careful, for what is your doing might become your undoing.'),
(1356, 'DivinationCardTheUnexpectedPrize', 39485, '<size:26>{They came from far and wide under a common banner.' || char(13) || '
They sought companionship and competition,' || char(13) || '
but found a treasure none had foreseen.}'),
(1357, 'DivinationCardCursedWords', 5822, 'If you look hard enough for hidden meaning, you will find it.'),
(1358, 'DivinationCardTheJournalist', 21958, 'A good spy doesn''t forget she''s gone undercover.'),
(1359, 'DivinationCardHauntingShadows', 31356, 'In the dead of night you may elude your shadows,' || char(13) || '
but they will always find you by dawn.'),
(1360, 'DivinationCardAcclimatisation', 6686, 'The world is ever-changing.' || char(13) || '
Once-lush woods now lost beneath shifting sands,' || char(13) || '
Great cities now drown beneath turbulent waters.' || char(13) || '
Adapt or perish.'),
(1361, 'DivinationCardTheWhiteout', 65530, '<size:25>{They thought winter had come early,' || char(13) || '
that snow blanketed the land,' || char(13) || '
but in truth, all their chickens' || char(13) || '
had come home to roost.}'),
(1362, 'DivinationCardSocietysRemorse', 23082, '<size:28>{We live to dream of worlds we aren''t in,' || char(13) || '
a false narrative that we use to fill our souls' || char(13) || '
with doubt;' || char(13) || '
The world is already beautiful,' || char(13) || '
there''s no need to dream.}'),
(1363, 'DivinationCardDyingLight', 61967, 'Even the brightest eventually fade to darkness.'),
(1364, 'DivinationCardFatefulMeeting', 48206, '<size:26>{Some people act as beacons, illuminating the path for others. I was lucky to meet one such person.' || char(13) || '
' || char(13) || '
- Anton to Zhenya}'),
(1365, 'DivinationCardTheAstromancer_', 50690, '<size:24>{They would say that he was a dangerous man,' || char(13) || '
unbound by the sense of morality,' || char(13) || '
but what does this matter,' || char(13) || '
when his love for humanity is undeniable' || char(13) || '
and completion of his work would benefit everyone?}'),
(1366, 'DivinationCardKeepersCorruption', 62509, 'With great power comes...' || char(13) || '
' || char(13) || '
...Even greater power.'),
(1367, 'DivinationCardRecklessAmbition', 60655, 'Why settle when more is never enough.'),
(1368, 'DivinationCardLoveThroughIce', 49986, '"I know one lady for whose sake I will rip out my heart"' || char(13) || '
' || char(13) || '
- Derrok, the Dreamer'),
(1369, 'DivinationCardDrapedInDreams', 28016, 'The suit I wear,' || char(13) || '
Is heavy and bare.' || char(13) || '
A canvas, it seems, breathing life into dreams.'),
(1370, 'DivinationCardThePatient', 35413, 'I have a headache, can anyone find me a nurse?'),
(1371, 'DivinationCardTheLongWatch', 10729, '<size:26>{The rain pelts down, Mud grasping at his feet, as thoughts of those in his care bolster his resolve.}'),
(1372, 'DivinationCardTheBearWoman', 50113, '<size:24>{For the blessed bear in the cave,' || char(13) || '
A hundred days pass in silence and darkness,' || char(13) || '
until moon begins its fourth passage,' || char(13) || '
the bear sheds her beastly fur,' || char(13) || '
and is reborn, human and whole.}'),
(1373, 'DivinationCardBrotherhoodInExile', 57908, '<size:25>{Seeking shelter from the night,' || char(13) || '
in the warmth of the run-down inn,' || char(13) || '
erstwhile foes put aside the fight,' || char(13) || '
to bond over whiskey and gin.}'),
(1374, 'DivinationCardWintersEmbrace', 52347, '<size:29>{Come home to me, my sweet.' || char(13) || '
Oh, how long you''ve been!' || char(13) || '
Lie with me in the frozen dark.' || char(13) || '
I may yet find forgiveness' || char(13) || '
Now that fear has left you.}'),
(1375, 'DivinationCardSambodhisWisdom', 4793, '<size:28>{No blade conquers sin;' || char(13) || '
guide a sinner to virtue,' || char(13) || '
unveil their lost sight—' || char(13) || '
your eyes, too, see in' || char(13) || '
everyone the inner child,' || char(13) || '
no matter their might.}'),
(1376, 'DivinationCardTheEnthusiasts', 3620, '<size:25>{"Glimmers of benevolence,' || char(13) || '
Shrouded a lacquered lust for power,' || char(13) || '
Yet still they followed his influence."}'),
(1377, 'DivinationCardBrokenPromises', 16605, 'Experience teaches us that the cold is not the same as the absence of warmth.'),
(1378, 'DivinationCardBrushPaintAndPalette', 32053, '"Man may shape the world, but these? These shape the man." -Inquisitor Maligaro'),
(1379, 'DivinationCardDeadlyJoy', 26236, '<size:27>{"Be fast. That is all that matters."' || char(13) || '
- Rita of the Asylum}'),
(1380, 'DivinationCardTheAdventuringSpirit', 58065, 'Dost thou lead my men to victory, my child?'),
(1381, 'DivinationCardTheEternalWar', 9414, 'They believed, falsely, that the strongest of generals could outlast eons of corruption.'),
(1382, 'DivinationCardPrejudice', 53734, 'One who is blinded by their past may only see a sliver of the present.'),
(1383, 'DivinationCardTheShortcut', 41511, 'If time is the most valuable currency, how do you make more of it?'),
(1384, 'DivinationCardTheCardSharp', 9240, '"The house always wins... except when I do."'),
(1385, 'DivinationCardAModestRequest', 32357, '<size:25>{Cede all power and wealth to me and serve me in perpetuity.' || char(13) || '
A minor inconvenience I assure you.}'),
(1386, 'DivinationCardLuminousTrove', 53859, '<size:24>{Plenty enter, dreaming of treasure' || char(13) || '
Twenty bled, slain as they fled' || char(13) || '
Shadows loom, half left doomed' || char(13) || '
The blind cries, five lost eyes' || char(13) || '
Careless twins, a lich''s new prize' || char(13) || '
One as a decoy, none pass the king' || char(13) || '
Gehennix feeds only on whispers}'),
(1387, 'DivinationCardTheHook', 54432, 'Every obsession began with a single, innocent taste.'),
(1388, 'DivinationCardTheLastSupper', 45633, '"Bino''s brief career as a chef at Axiom saved the executioner a lot of work."'),
(1389, 'DivinationCardTheEmptiness_', 29672, 'He appeared before the Light Eater, and at once knew his soul was damned.'),
(1390, 'DivinationCardASeaOfBlue', 30606, 'The harvest ended, the floods began.'),
(1391, 'DivinationCardTheOffspring', 62708, 'The swarm began with just a couple of children. Now, it is her entire existence.'),
(1392, 'DivinationCardThePriceOfPrescience', 9521, '<size:26>{The strange voice showed Aul a future where his legacy was forgotten, where new cultures broke themselves upon Aul''s ruined world.}'),
(1393, 'DivinationCardTheMindsEyes', 26285, '<size:28>{Through the eyes of a person, ' || char(13) || '
you can see their soul' || char(13) || '
Through the eyes of a jewel, ' || char(13) || '
you can see the universe}'),
(1394, 'DivinationCardTerribleSecretOfSpace', 43600, 'They said they were here to protect us.'),
(1395, 'DivinationCardTheBlessingOfMoosh', 27503, 'While the Labyrinth traps have claimed countless adventurers, they were not designed with felines in mind.'),
(1396, 'DivinationCardCostlyCurio', 39210, '"Oh no, I couldn''t possibly afford this fine artefact. I''m... just looking."'),
(1397, 'DivinationCardLachrymalNecrosis', 48067, 'Without the ability to weep, the heart hardens against both the pure and the corrupt.'),
(1398, 'DivinationCardDementophobia', 33003, '<size:28>{I never truly understood the depths of my insanity,' || char(13) || '
until I realized the voices beckoning me towards the abyss,' || char(13) || '
were none other than my own.}'),
(1399, 'DivinationCardAmbitiousObsession', 30513, 'The most pathetic person in the world is someone who has sight, but no vision.'),
(1400, 'DivinationCardDesperateCrusade', 11453, 'Through despondent hardships, those strong of spirit shall claim the prize.'),
(1401, 'DivinationCardAStonePerfected', 12750, '<size:28>{They gave the stone life. Over eons spent bathed in Corruption, that life evolved.}'),
(1402, 'DivinationCardTreasuresOfTheVaal', 24215, '<size:23>{The cities of the Empire were plundered' || char(13) || '
by those who came after... all but one.}'),
(1403, 'DivinationCardTheRabbitsFoot', 19987, 'It is said anyone who bears this trinket is the luckiest exile in all of Wraeclast. The gods would disagree, and forever curse any whom give it away.'),
(1404, 'DivinationCardChasingRisk', 3985, 'A fond memory fills me with nostalgia; some men would have felt guilt, but I felt no regret over the anguish and fear my ambitions caused.'),
(1405, 'DivinationCardThePrinceOfDarkness', 6940, '<size:30>{Fear a man who is willing to sacrifice anything for power.}'),
(1406, 'DivinationCardTheCatch', 52567, 'The largest hooks offer the greatest catch, but often the catch is the hook.'),
(1407, 'DivinationCardEternalBonds', 39717, 'Separate, stories untold.' || char(13) || '
Together, memories unfold.'),
(1408, 'DivinationCardDisdain', 37696, '<size:28>{No man sees all, but you''ll see more than some see in a lifetime.}'),
(1409, 'DivinationCardTheScout', 28183, 'The first to travel are often rewarded for their journey, but all the treasure in the world cannot bring back those that are lost.'),
(1410, 'DivinationCardGuardiansChallenge_', 61852, 'To accept a challenge from the void is merely suicide for the unprepared.'),
(1411, 'DivinationCardTheForgottenTreasure', 65064, '<size:28>{Don''t let fool''s gold deceive you.}'),
(1412, 'DivinationCardTheFoxInTheBrambles', 17033, '<size:26>{Hemmingsworth 6:10 - "And the fox gazed out from the brambles, unreachable and smirking."}'),
(1413, 'DivinationCardTheAspirant', 36561, '<size:26>{Those Exiles that survive Wraeclast' || char(13) || '
dream not of home, but of power.}'),
(1414, 'DivinationCardJudgingVoices', 31122, 'He was seeking sanity, but the demons were inside his head.'),
(1415, 'DivinationCardDazzlingDisplay', 46143, 'The last thing they saw was the blue light of death.'),
(1416, 'DivinationCardBijoux', 33203, '"Such fine trinkets show their true value in times of crisis." - Tangmazu'),
(1417, 'DivinationCardSilenceAndFrost', 45687, 'Cry havoc!' || char(13) || '
Unleash pandemonium!'),
(1418, 'DivinationCardMiseryInDarkness', 60065, '<size:30>{He wandered the bone-filled depths hoping each corner would be his last.' || char(13) || '
Eventually, he found Light.}'),
(1419, 'DivinationCardTheTirelessExtractor', 31098, '<size:30>{"I am not alone in this. I have God by my side! And... you help sometimes, I suppose."' || char(13) || '
- Sister Cassia}'),
(1420, 'DivinationCardJustifiedAmbition', 58382, '"Everything I have done has been for Wraeclast. You would pledge your life to me if you saw things my way... and soon, you will."' || char(13) || '
- High Templar Venarius'),
(1421, 'DivinationCardParasiticPassengers', 62519, 'Feeding on death, they grew stronger and stronger, until they were ready to hatch...'),
(1422, 'DivinationCardDuality', 18416, 'Good and Evil can be woven together to become something greater than either.'),
(1423, 'DivinationCardTheOneThatGotAway', 19192, '<size:30>{Savor life''s missing pieces.' || char(13) || '
To complete one''s final goal' || char(13) || '
is to take one''s last breath.}'),
(1424, 'DivinationCardTheTransformation', 13865, 'Even the most beautiful of transformations can still have a dark side.'),
(1425, 'DivinationCardMagnumOpus', 35296, 'Wraeclast will unite. This shall be my great work - the minds of the people made one.'),
(1426, 'DivinationCardImperfectMemories', 33940, 'Everything is eroded by time, but sometimes the edges that fade can make a wonderful memory even more beautiful.'),
(1427, 'DivinationCardTheMagmaCrab', 24156, 'Drink deeply of living rock and be as stone, with blood afire.'),
(1428, 'DivinationCardAlteredPerception', 19784, 'You mustn''t forget: you won''t be leaving this place.'),
(1429, 'DivinationCardFurtherInvention', 40009, 'Why not both?'),
(1430, 'DivinationCardTheBrawnyBattleMage', 30338, 'A humble piece of wood offers the simplest solution to life''s problems: just hit them really, really hard.'),
(1431, 'DivinationCardAFateWorseThanDeath', 10777, '"It was as though my very thoughts were breaking... fracturing into tiny motes to be lost on the wind."'),
(1432, 'DivinationCardTheDestination', 39183, 'You may be nothing to everybody, but you are everything to somebody.'),
(1433, 'DivinationCardRebirthAndRenewal', 33478, 'Life has an end, then life begins again.'),
(1434, 'DivinationCardTheForwardGaze', 26945, '"When they realize our true intent, they will decry us, assault us, and try to crush what we have built. We must stand tall, Qotra, and make the future our own."'),
(1435, 'DivinationCardTheApothecary', 43184, '"You seek the power of my strongest potions, but the price will be far higher than you can imagine."'),
(1436, 'DivinationCardHome', 25194, '<size:28>{There are countless people,' || char(13) || '
countless stories,' || char(13) || '
and countless eras,' || char(13) || '
but there is one place that,' || char(13) || '
for a time, each of us loved' || char(13) || '
and was loved. It matters.' || char(13) || '
We matter.}'),
(1437, 'DivinationCardTheDungeonMaster__', 11560, '"So desperate was I for control, I turned my entire world into a prison. Now you will share in my agony."'),
(1438, 'DivinationCardFromBoneToAshes', 25274, 'For centuries, they stood vigil in secret over their sleeping goddess, even as contamination oozed out of the decadent Vaal empire.'),
(1439, 'DivinationCardDarkerHalf', 55005, 'When you find what you''re looking for, it''s never quite right. When you have what you desire, yet you still want more.'),
(1440, 'DivinationCardBrokenTruce', 38224, 'With a single act, years of peace have been shattered. An unknown assassin brings war upon us all.'),
(1441, 'DivinationCardDoryanisEpiphany', 50314, '"Virtue gems have facets beyond those that can be seen by the mortal eye. Let us look deeper..."'),
(1442, 'DivinationCardEndlessNight', 53458, 'The sun shines not for me. I walk in darkness, never free. Time stopped when you both died in my arms.'),
(1443, 'DivinationCardTheShieldbearer', 44153, 'While you grow, I shall be your knight, and you my squire. One day, you shall be the one who stands and defends our home.'),
(1444, 'DivinationCardChokingGuilt', 33497, 'As death approached, clarity eluded him. The pain he had wrought surrounded him, dragging him into darkness.'),
(1445, 'DivinationCardTheEnforcer', 30901, '<size:28>{"Boss said to get rid of him, didn''t say not to make a mess."' || char(13) || '
- Rune The Goon}'),
(1446, 'DivinationCardTheShepherdsSandals', 63961, '<size:30>{He who watches the flock is himself watched by those with loyalty beyond measure.}'),
(1447, 'DivinationCardAzureRage', 53726, '<size:28>{The mask hides his identity' || char(13) || '
but also makes it hard to read...}'),
(1448, 'DivinationCardTheLeviathan', 34692, '<size:28>{Ancient behemoths swam the' || char(13) || '
depths of the oceans long' || char(13) || '
before Man walked these lands.}'),
(1449, 'DivinationCardThePriceOfDevotion', 33393, '<size:30>{Unbeknown to Atziri''s finest thaumaturgists, their loyalty would require far greater devotion than mere research.}'),
(1450, 'DivinationCardAstralProtection', 58299, 'For a time, we had something stronger than eldritch evil.' || char(13) || '
We had each other.'),
(1451, 'DivinationCardGemcuttersMercy', 56407, 'When you can only have one, which shall it be?' || char(13) || '
Red?' || char(13) || '
Blue?' || char(13) || '
Probably Green.'),
(1452, 'DivinationCardCheckmate', 32146, 'When victory is impossible, each of us plays only to delay the end.'),
(1453, 'DivinationCardLetheanTemptation', 10064, 'My memories tortured me without end. To escape them, I embraced nothingness, but oblivion simply brought a different kind of pain...'),
(1454, 'DivinationCardSomethingDark', 47858, 'Even in darkness you may find a friend.'),
(1455, 'DivinationCardManWithBear', 47710, 'A stereotypical joke may lead to an unexpected bond.'),
(1456, 'DivinationCardAliviasGrace', 39311, 'Her innocence and grace were enough to tame even the wildest of beasts.'),
(1457, 'DivinationCardAuspiciousAmbitions_____', 64507, '<size:30>{"Gaze upon the mirrors of what may come and step backward into infinity." ' || char(13) || '
- Dexion, Thaumetic Aspirant}'),
(1458, 'DivinationCardDivineBeauty_', 42327, '<size:30>{In a land far away lived ' || char(13) || '
a maiden most fair.' || char(13) || '
Her smile melted the coldest' || char(13) || '
of hearts, her song made' || char(13) || '
men and beast cry, ' || char(13) || '
her beauty unparalleled;' || char(13) || '
Divine.}'),
(1459, 'DivinationCardTheWeddingGift', 63141, 'The acolytes congratulated the lucky groom for becoming one with the goddess.'),
(1460, 'DivinationCardTheInsaneCat__', 61560, 'One person''s madness is another person''s reality.'),
(1461, 'DivinationCardEverChanging', 19867, 'The Atlas is our prison, and our only defence. She is our only hope, and our certain doom.'),
(1462, 'DivinationCardADustyMemory', 5803, '<size:29>{In the oldest halls of my mind, at the end of a rarely used passage, lies my greatest treasure: one moment of happiness and innocence, pure and untouchable.}'),
(1463, 'DivinationCardTheReturnOfTheRat', 31925, 'And he shall be heralded by the screams of the damned.'),
(1464, 'DivinationCardTheFinishingTouch', 31589, '<size:29>{A little extra flair never hurts.}'),
(1465, 'UniqueShieldStr11', 32047, '"It''s not Karui, Azmeri or even Vaal in origin,' || char(13) || '
but one thing is certain. It is very, very old."' || char(13) || '
- Icius Perandus, Antiquities Collection, Item 46'),
(1466, 'UniqueFlask22', 47309, 'The summer sun dries the soil and burns the leaves.' || char(13) || '
The autumn rain extinguishes the flames.' || char(13) || '
The spring bloom shades the wet earth.' || char(13) || '
Nature is an eternal tug of war.'),
(1467, 'UniqueOneHandSword25', 18970, '<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAc>><<HBG03>><<HBGAo>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAb>><<HBG03>><<HBGAv>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAw>><<HBG03>><<HBGAx>>' || char(13) || '
<<HBGAf>><<HBG02>><<HBGAw>><<HBG03>><<HBGAy>>'),
(1468, 'QuestSilverLocket', 149, 'From Weylam to Meredith:' || char(13) || '
I shall love thee as I love the sea.'),
(1469, 'QuestKisharaStar', 45362, 'To the wily Kishara''s eye, a star brighter than the sun.'),
(1470, 'QuestObsidianKey', 11945, '"The cool blanket of shadows preserves our treasures."' || char(13) || '
 - Inquisitor Maligaro'),
(1471, 'QuestMaligaroMap', 55389, '"Certain maps can only be rendered in the most vivid of viscera."' || char(13) || '
 - Inquisitor Maligaro'),
(1472, 'QuestGreustNecklace', 853, '"A boy becomes a man when he has faced the animal' || char(13) || '
in his heart and wet the forest floor with its blood."' || char(13) || '
 - Azmeri Proverb'),
(1473, 'QuestBlackVenom', 41901, '"The spider is not defined by how' || char(13) || '
it lives, but by how it kills."' || char(13) || '
 - Inquisitor Maligaro'),
(1474, 'QuestFirefly1', 59805, 'In all things living, the light burns bright.'),
(1475, 'QuestFirefly2', 24789, 'A passionate fire that consumes the heart.'),
(1476, 'QuestFirefly3', 5185, 'The Spirit, it radiates not from above.'),
(1477, 'QuestFirefly4', 51306, 'It is the warmth that draws you ever inward.'),
(1478, 'QuestFirefly5', 3570, 'Where rest the truest colours of life.'),
(1479, 'QuestFirefly6', 18023, 'Gold of the organ. Green of the throat. Red of the vein.'),
(1480, 'QuestFirefly7', 52277, 'The myriad wet rainbow of the Spirit''s domain.'),
(1481, 'QuestKaruiEye', 1802, '"Weakness must be purged lest it' || char(13) || '
poison the blood of all Karui."' || char(13) || '
 - Prayer to Tukohama'),
(1482, 'QuestBestelManuscript', 50699, '"A stranger''s kiss on a moonlit night.' || char(13) || '
Dost thou believe in love at first sight?"'),
(1483, 'QuestBlackFlag', 34233, '"May the lubbers feel fear in their' || char(13) || '
nethers, and may our blades follow."' || char(13) || '
 - Rot-tooth''s Rallying Cry'),
(1484, 'QuestMiasmeter', 37741, '"We shall peer at these cosmic wonderments as they' || char(13) || '
wake and writhe within that deep and nameless dark."' || char(13) || '
 - Vilenta, ''Miasmeter: A Thesis'''),
(1485, 'QuestTemplarCourtKey', 11507, 'Eyes blazing with holy flame, the Pilgrim saw' || char(13) || '
a great palace descend from the burgeoning sky,' || char(13) || '
its gates barred against the unfaithful.'),
(1486, 'QuestKitavaKey', 52811, 'Wrought from blood and gold, Innocence fashioned a weapon of tempered purity,' || char(13) || '
capable of banishing darkness, and bringing order to the chaos in men''s hearts.'),
(1487, 'QuestSunOrb', 28949, '"The sun is a devoted mother. She casts her golden blessings on' || char(13) || '
the crops of the pious and makes barren the fields of heresy.' || char(13) || '
Sunlight is belief. Sunlight is life."' || char(13) || '
 - The Solar Verses'),
(1488, 'QuestMoonOrb', 41090, '"Moonlight is a wise mother. The moon which bathes us in soft,' || char(13) || '
cooling light, does so with the intent of illuminating our paths.' || char(13) || '
Moonlight is wisdom. Moonlight is life."' || char(13) || '
 - The Lunar Verses'),
(1489, 'QuestAnkhOfEternity', 58114, '"The amulet, it... whispers to me. Horrible things..."'),
(1490, 'QuestWingsOfVastiri', 40164, 'And mounting her mighty Roc, Garukhan, holy queen of the sky,' || char(13) || '
descended upon her enemies and their armies of darkness.'),
(1491, 'TemporaryTutorialSupport', 33904, 'This gem is only temporary, and only for the tutorial.'),
(1492, 'DivineVessel', 30121, 'Power is a curious thing. ' || char(13) || '
It can be contained, hidden, locked away, ' || char(13) || '
and yet it always breaks free.'),
(1493, 'QuestSekhemaFeather', 45753, '"And how shall we know a sekhema worthy of rule? ' || char(13) || '
By the anointing of the Great Roc, under whose wings we grow and soar."' || char(13) || '
 - Maraketh Coronation Ritual'),
(1494, 'QuestStormSword', 21896, 'Garukhan sought madness and knowledge amongst the billowing clouds of a ' || char(13) || '
blackened sky. A vulture of pride, she would not be refused, and so the' || char(13) || '
stratosphere divulged unto her eldritch secrets of its tumultuous past.'),
(1495, 'QuestA9Ingredient1', 18386, '"Blow it all down! The emperor must have his gems, no matter the cost!"'),
(1496, 'QuestA9Ingredient2', 42448, 'Nobility once thought to capture the Basilisks and keep them as exotic pets.' || char(13) || '
This only served to fatten the vileness of their hearts, and with a hateful' || char(13) || '
acid that festered inside, the creatures became soured to their very bones.'),
(1497, 'QuestCalendar', 40752, 'The King looked upon images swirling atop the ancient stone dial.' || char(13) || '
"You look peaceful" he told his bride-to-be, "So peaceful, asleep in our wedding bed."' || char(13) || '
But in phantasm, she did not slumber, and what he saw was not a place for dreams,' || char(13) || '
rather, a wooden box... about to be closed and lowered into earthy depths.' || char(13) || '
 - Maraketh Legend'),
(1498, 'QuestBottledStorm', 39882, '"One should not entice the storm; one cannot invite the storm, or give warrant' || char(13) || '
to its tyrant-soul. We survive only by appeasing the storm, with gifts and' || char(13) || '
offerings of adoration. We hope that, in its mercy, it shall pass us by."' || char(13) || '
- Tempestology of the Maraketh, Repudion IV '),
(1499, 'QuestPotion', 55326, 'Famous for her many lovers, those that did not' || char(13) || '
come willing to Atziri, came by liquid persuasion.');
INSERT INTO "FlavourText" ("_row", "Id", "__col1", "Text") VALUES
(1500, 'QuestTeardrop', 30104, '"T''gnagn iia y r''ngusla ph''tu Tsoatha nga mekghul''an."' || char(13) || '
 - Indecipherable verse'),
(1501, 'QuestAvariusStaff_', 9875, '"Worry not for the heathens. They are devoid of soul.' || char(13) || '
Made vessels of wrath, they are damned by holy design."' || char(13) || '
- High Templar Avarius'),
(1502, 'UniqueJewel1b', 18846, 'In the end, time comes for all of us.' || char(13) || '
For some, it comes much sooner.'),
(1503, 'UniqueJewel107b', 13170, '"Would you leave an orchard of apples to rot unharvested?' || char(13) || '
A cemetery is no different." ' || char(13) || '
-Kadavrus, Surgeon to the Umbra'),
(1504, 'UniqueBootsStr9', 57078, 'Like lightning, the Ezomyte cavalry need never strike twice.'),
(1505, 'UniqueGlovesStr8', 5653, 'The monstrous men of yore used bows too,' || char(13) || '
theirs were just bigger.'),
(1506, 'UniqueHelmetInt13', 43554, 'Countless men proclaimed themselves the masters of death,' || char(13) || '
and each one succumbed to it.'),
(1507, 'UniqueStaff21', 41737, '"Creation is the act of making the intangible tangible.' || char(13) || '
To work backwards, to make the tangible intangible,' || char(13) || '
is to step into the mind of a god."' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(1508, 'UniqueBelt25', 22325, '<<HBGAa>><<HBG02>><<HBGAb>><<HBG03>><<HBG02>><<HBGAc>><<HBG03>><<HBGAd>>' || char(13) || '
<<HBGAa>><<HBG02>><<HBGAb>><<HBG03>><<HBG02>><<HBGAc>><<HBG03>><<HBGAe>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAg>><<HBG03>><<HBGAa>><<HBG01>><<HBGAb>>'),
(1509, 'UniqueShieldStrInt10', 11781, '<<HBGAh>><<HBG01>><<HBGAe>><<HBG00>><<HBGAp>>' || char(13) || '
<<HBGAa>><<HBG02>><<HBGAq>><<HBGAr>><<HBG03>><<HBGAl>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAs>><<HBG00>><<HBG04>><<HBGAt>>'),
(1510, 'UniqueQuiver13', 3084, '<<HBGAa>><<HBG01>><<HBGAc>><<HBG01>><<HBGAo>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAe>><<HBG00>><<HBGAl>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAm>><<HBG03>><<HBGAc>><<HBG01>><<HBGAo>>'),
(1511, 'UniqueHelmetDexInt8', 15316, '<<HBGAh>><<HBG01>><<HBGAe>><<HBG00>><<HBGAi>>' || char(13) || '
<<HBGAa>><<HBG02>><<HBGAj>><<HBGAk>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAl>><<HBG03>><<HBGAa>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAm>><<HBG03>><<HBGAa>><<HBG01>><<HBGAn>>'),
(1512, 'UniqueStaff20', 49425, '<<HBGAa>><<HBG02>><<HBGAq>><<HBG03>><<HBGAl>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAn>><<HBG02>><<HBGAu>><<HBG00>><<HBGAv>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAl>><<HBG02>><<HBG04>><<HBGAt>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAn>><<HBG00>><<HBGAv>><<HBG02>><<HBGAu>><<HBG03>><<HBGAa>><<HBG01>><<HBGAf>><<HBG01>><<HBGAn>>'),
(1513, 'UniqueMapHarbinger', 32175, '<<HBGAa>><<HBG01>><<HBGAf>><<HBG02>><<HBGAm>><<HBG03>><<HBGAo>>' || char(13) || '
<<HBG02>><<HBGAt>><<HBG03>><<HBGAy>>'),
(1514, 'DivineVesselBrineKing1', 10354, 'Though his mind decayed with each passing wave,' || char(13) || '
the Brine King stood steadfast in his hatred,' || char(13) || '
and wore it like a shell, protecting himself ' || char(13) || '
from his failure to sire a worthy heir.'),
(1515, 'DivineVesselBrineKing2', 65155, 'The fish-wives of Tsoatha rejoiced loudly as' || char(13) || '
the Brine King descended into the great abyss,' || char(13) || '
making merry while his blasphemous offspring' || char(13) || '
slithered ''neath the icy waters...'),
(1516, 'DivineVesselBrineKing3', 12967, 'Slumbering in the breach between worlds,' || char(13) || '
the Brine King dreamt of a day he would rise,' || char(13) || '
in triumph from the shivering depths and take' || char(13) || '
back the Kingdom he once so ruthlessly culled.'),
(1517, 'DivineVesselArakaali1', 26418, 'There is a story held by the ancient Vaal, in which the' || char(13) || '
beautiful seductress Arakaali strode through towns, stealing' || char(13) || '
the hearts of men, and turning to ash their lovers'' desires.' || char(13) || '
- "Legends of the Vaal" by Eramir, Scholar at Theopolis'),
(1518, 'DivineVesselArakaali2', 61338, 'When the cold was at its strongest, Arakaali came,' || char(13) || '
and like a farmer leading cattle to the slaughter,' || char(13) || '
she drove her victims into the outer darkness.' || char(13) || '
- "Legends of the Vaal" by Eramir, Scholar at Theopolis'),
(1519, 'DivineVesselArakaali3', 12988, 'Records of Arakaali''s violent reign suggest she kept her citizens' || char(13) || '
sedated with ''juices of lust'' and venoms of the spider. Perhaps her' || char(13) || '
guise of seductress was in fact her way of farming those ''juices''.' || char(13) || '
- "Legends of the Vaal" by Eramir, Scholar at Theopolis'),
(1520, 'DivineVesselSolaris1', 47323, 'The mud is cracked and dry. The fields now burn beneath the blistering sun.' || char(13) || '
Even our children are dying in the streets! We''ve angered Solaris and so' || char(13) || '
we pay tribute to appease her fiery heart...'),
(1521, 'DivineVesselSolaris2', 32929, 'When Solaris is angered, there must always be sacrifice. Our women' || char(13) || '
have taken to mourning, they drag themselves through ash and glass,' || char(13) || '
not wanting to give up our youth to the all-consuming flame.'),
(1522, 'DivineVesselSolaris3', 24000, 'To take from the sun is to invite her wrath, and we''ve more than warranted her curse.' || char(13) || '
The granaries were vacant, so we lessened our tribute to the sun thinking it would' || char(13) || '
save our children, but they will die now regardless.'),
(1523, 'DivineVesselLunaris1', 29200, 'Once beneath a moonlit sky, Lunaris bathed her child in the ocean''s tide.' || char(13) || '
Though the waters were frigid with icy death, the boy was sick and' || char(13) || '
couldn''t be healthy until he was silent, clean and still...'),
(1524, 'DivineVesselLunaris2', 47998, 'And so it was, that Lunaris, in her compulsion to nurture and protect,' || char(13) || '
killed her son beneath the light of a waning moon. She stood silent, in' || char(13) || '
trial before her tribe, as her fiery sister fought in vain to defend her...'),
(1525, 'DivineVesselLunaris3', 3990, 'But Lunaris refused to admit any wrongdoing. She''d saved her child, had she not?' || char(13) || '
He was safe now, buried beneath the dirt. Conviction gnarled around her fragile mind,' || char(13) || '
and in her pride she rose to seat a deathless throne.'),
(1526, 'DivineVesselAbberath', 35987, 'When the demon Goat plays his flute,' || char(13) || '
And cloven hooves clip-clop your path,' || char(13) || '
Pray the gods will hold you mute,' || char(13) || '
And bless the fire on your hearth.'),
(1527, 'DivineVesselGruthkul', 24963, 'The earth shakes, moon eclipses black.' || char(13) || '
Graveyards quake, crops turn to ash,' || char(13) || '
as the grieving mother weeps.' || char(13) || '
Oceans boil and wind ravages home. ' || char(13) || '
We feel famine inside our bones,' || char(13) || '
as the grieving mother, Gruthkul weeps.'),
(1528, 'DivineVesselYugul', 14967, 'In nature, there are many feelings exclusive only to man. But terror is not one.' || char(13) || '
Terror flourishes in our world, transcending all things. It is the bedrock on' || char(13) || '
which our great cosmos is formed. I am Yugul and I deign to understand this' || char(13) || '
mystery, to explore its depths and unlock its secrets...'),
(1529, 'DivineVesselShakari', 19653, '"So it''s true." Shakari thought, as she took her final breath.' || char(13) || '
"My father, Sin, wishes me dead. And he has sent his rabid dog to do it..."'),
(1530, 'DivineVesselTukohama', 15923, 'Tukohama stood in the door, blocking the sunlight' || char(13) || '
from Hikatomanga and his family. The Father of War''s' || char(13) || '
retribution was inevitable, for it is known - man' || char(13) || '
cannot cheat the gods without consequence...'),
(1531, 'DivineVesselRalakesh', 10723, '"Lock the gates and build the walls!" came the rallying cry,' || char(13) || '
"Let those of Ralakesh take care of those of Ralakesh!"' || char(13) || '
- The God Behind The Wall'),
(1532, 'DivineVesselGarukhan', 13021, 'Garukhan wished once more for the skies. If she were to die,' || char(13) || '
she wanted it to be up there in the clouds. This world had never' || char(13) || '
been her home. She required greater things. She required adventure.' || char(13) || '
But die she would, here in the dirt...'),
(1533, 'DivineVesselRyslatha', 41784, 'Ryslatha was flushed with pride as she watched her mindless spawn' || char(13) || '
mature. Sharpening their mandibles, her children slithered from the hive,' || char(13) || '
eager to devour all the creatures that frequented the ancient woods.'),
(1534, 'UniqueMap3_21', 56333, 'In the shadow of war,' || char(13) || '
all are eclipsed.'),
(1535, 'UniqueMap3_22', 63879, 'We are ever the makers of our own undoing.'),
(1536, 'UniqueMap3_23', 43487, 'Man creates where nature cannot.'),
(1537, 'UniqueMap3_23x', 63803, '"Whatever these maps are, it is clear they are dangerous. Send in only' || char(13) || '
test subjects, no guards or researchers." ' || char(13) || '
- Administrator Qotra'),
(1538, 'UniqueBootsStrInt5', 40612, 'The Master of a Million Faces lived by one' || char(13) || '
simple ethos: why make the effort, when' || char(13) || '
you can simply mimic what others have?'),
(1539, 'UniqueRing48', 5235, 'Be careful where you put your finger.'),
(1540, 'UniqueWand18', 17060, 'In every piece of prose, lies a tiny spark of magic.'),
(1541, 'UniqueJewel110', 9930, 'In the years that followed the twisted sky,' || char(13) || '
cold winds cloaked Wraeclast in snow.' || char(13) || '
The pure-white blanket masked a black heart' || char(13) || '
that lay dormant deep beneath the earth.'),
(1542, 'UniqueJewel111', 2410, 'The skilled know how to learn.' || char(13) || '
The talented know who to learn from.'),
(1543, 'UniqueJewel111x', 1068, '"Twelve test subjects were expended in the production of Prototype #800.' || char(13) || '
Was it worth the expense? Only time will tell."'),
(1544, 'UniqueBootsDIY', 44905, '"Every day we choose safety or knowledge. ' || char(13) || '
Live and stagnate, or risk death for truth.' || char(13) || '
I would rather see the end of the Vaal' || char(13) || '
than help it tread water." ' || char(13) || '
- Doryani, Queen''s Thaumaturgist'),
(1545, 'UniqueFlask23', 31545, '"What cruelty it is, that to be judged a success,' || char(13) || '
such great work must go uncredited." ' || char(13) || '
- Coralito, Brotherhood of Silence'),
(1546, 'UniqueHelmetStrInt10', 1665, 'Your memories are a bridge to the past.' || char(13) || '
Let no one cross.'),
(1547, 'UniqueShieldDexInt4', 30158, 'One''s burden is another''s gift.'),
(1548, 'UniqueFlask24', 34185, 'Dance like dust on the desert wind.'),
(1549, 'UniqueDagger17', 26482, 'The Maraketh fear very little, ' || char(13) || '
but they dare not whisper the name' || char(13) || '
of the demon that flies on Winter''s gales.'),
(1550, 'UniqueBow20', 64866, 'Through droughts, fires, floods and frost,' || char(13) || '
the ancient giants stand resolute,' || char(13) || '
while deep in the rich, dark earth,' || char(13) || '
their grasp stretches ever farther.'),
(1551, 'UniqueAmulet46', 49350, 'Let the unrepentant be dragged ever downwards by the weight of their sins.'),
(1552, 'UniqueJewel112', 37434, 'Enough mice can kill a wolf.'),
(1553, 'UniqueJewel113', 49325, 'Hurt as you would be hurt.'),
(1554, 'UniqueBootsDexInt6', 31034, 'Even the dead serve the Lightless.'),
(1555, 'UniqueGlovesStrDex9', 60313, '"Ever watched a man crush another man''s skull?' || char(13) || '
Hard to feel hope after that."'),
(1556, 'UniqueBelt27', 24667, 'Hold in your hand the darkness' || char(13) || '
and never will the light blind you.'),
(1557, 'UniqueHelmetStrInt11', 20714, 'The eyes of the living hold a glimmer of hope.' || char(13) || '
Don''t waste it.'),
(1558, 'UniqueBodyDexInt9', 52353, 'Look to the darkness for nourishment and you will never go hungry.'),
(1559, 'UniqueBodyDexInt9x', 4646, '"Eyes of black, three by three, staring ever darker into me..."' || char(13) || '
- Researcher Arn'),
(1560, 'UniqueGlovesDex4', 673, 'Land and sea did not dissuade,' || char(13) || '
nor did the Kelpie''s maw;' || char(13) || '
the wild beast crossed half the world' || char(13) || '
to sate his hungry claw.'),
(1561, 'UniqueJewel114', 59354, 'Candles with the brightest light' || char(13) || '
Bring life to death and day to night.' || char(13) || '
But lovely as the glow may seem,' || char(13) || '
Their light is fleeting, as a dream...'),
(1562, 'UniqueBodyInt15', 33332, 'As she was sentenced to death, Doedre was silent.' || char(13) || '
As she was tied to the stake, Doedre was silent.' || char(13) || '
As the flames licked away her life, Doedre was silent.' || char(13) || '
But Wraeclast had not heard the last of her.'),
(1563, 'UniqueBodyStr9', 38328, '"The Council have a great many secrets.' || char(13) || '
Some are better kept that way, Cospri."' || char(13) || '
- Mauritius, the Iron Heart'),
(1564, 'UniqueAmulet45', 53762, 'Though its body was locked in stone,' || char(13) || '
its essence wandered the infinite,' || char(13) || '
learning, and preparing.'),
(1565, 'UniqueAmulet45Uber', 56087, 'There is no darker void than the hollow' || char(13) || '
ache of love disremembered...'),
(1566, 'UniqueBelt26', 50413, 'With the patience of a prowling lion,' || char(13) || '
the Shade watched the Scholar.'),
(1567, 'UniqueJewel115', 16213, 'One by one, they stood their ground against a creature ' || char(13) || '
they had no hope of understanding, let alone defeating,' || char(13) || '
and one by one, they became a part of it.'),
(1568, 'UniqueGlovesDexInt9', 14679, 'Reaching nature''s limits, ' || char(13) || '
many sought power in the unnatural.'),
(1569, 'UniqueOneHandMace11', 61094, 'They hoped that, trapped in its prison,' || char(13) || '
the creature would age and perish.' || char(13) || '
But time would not touch the fiend.'),
(1570, 'UniqueBow21', 12055, 'Their last thoughts were not of their friends,' || char(13) || '
or their families, or their homes.' || char(13) || '
Their last thoughts were untethered from reality,' || char(13) || '
and bathed in fear and ferocity.'),
(1571, 'UniqueWand19', 56700, 'All at once, a calmness would encompass them,' || char(13) || '
and all at once, it would be torn away,' || char(13) || '
unveiling forms no sound mind could grasp.'),
(1572, 'UniqueHelmetDexInt9', 8015, 'Men always fell for her honeyed eyes,' || char(13) || '
and broke when they hit the ground.'),
(1573, 'UniqueShieldStr12', 30967, 'Lunaris crossed silently, shining and full, ' || char(13) || '
Softly night left her, alone and forlorn.' || char(13) || '
Solaris rose to meet her, feeling her pull.' || char(13) || '
''Neath the midday sun, the night was reborn.'),
(1574, 'UniqueSceptre18', 62375, 'When the world spins out of control,' || char(13) || '
the safest place to be is in the centre.'),
(1575, 'UniqueOneHandSword27', 38773, 'Through countless seasons they stand, stoic,' || char(13) || '
Each season leaving its mark; ' || char(13) || '
a memory written in fibrous flesh.'),
(1576, 'UniqueOneHandSword28', 8229, 'By wind and wing they are carried,' || char(13) || '
Their fates not theirs to control,' || char(13) || '
Yet the fates of others dragged in their wake.'),
(1577, 'UniqueDagger18', 47231, 'Lava bled from the earth and,' || char(13) || '
after a time, cooled and hardened.' || char(13) || '
The world protecting its beating heart ' || char(13) || '
with a thick, black scab.'),
(1578, 'UniqueAmulet47', 28886, 'Darkness never stops feeding.'),
(1579, 'UniqueOneHandSword26', 41081, '"Your name is Demon Slayer? Really? Good name for rotgut, that."' || char(13) || '
She said: I prefer "The Goddess Of Swords". Much more dignified. And accurate.' || char(13) || '
"Demon Slayer The Cheap And Nasty it is then. Burns going down, burns coming up?"' || char(13) || '
She said: Every single time, Charan. And still...you''ll bathe me, and you''ll drink my love. Until you can''t.'),
(1580, 'ShaperMemoryFragment1_1', 33581, '"...A golden machine was found broken in the ruins of Wraeclast. ' || char(13) || '
Believing it to contain some dark infernal secret, ' || char(13) || '
High Templar Venarius asked that I restore it ' || char(13) || '
and weaponize whatever powers it might contain..."'),
(1581, 'ShaperMemoryFragment2_1', 64947, '"...Though the device seemed to be mostly functioning, ' || char(13) || '
something important appeared to be missing...' || char(13) || '
...I worked tirelessly in search of answers, until finally, ' || char(13) || '
at the base of that cruel device, I fell into a deep, deep sleep..."'),
(1582, 'ShaperMemoryFragment3_1', 11546, '"...I awoke in the most beautiful of places, and as I wandered this strange new land, ' || char(13) || '
I felt a growing sense of realization that I was not alone. ' || char(13) || '
A Shade, a whisper of embodied smoke, spoke to me through thoughts and pictures.' || char(13) || '
I found myself enthusiastically volunteering information in detail of Oriath..."'),
(1583, 'ShaperMemoryFragment4_1', 63604, '"...The Shade knew of the device - a doorway between my world' || char(13) || '
and the dreamlands. It offered to help me rebuild the missing part, ' || char(13) || '
to create a conduit between this beautiful land and Oriath. ' || char(13) || '
All that the Shade asked of me was to return the favour..."'),
(1584, 'ShaperMemoryFragment5_1', 30474, '"...Every night, I found myself asleep at the foot of the strange device, ' || char(13) || '
awoken to the reality of another world within my own.' || char(13) || '
The Shade taught me how to shape and build things from my imagination,' || char(13) || '
how to transport such phantasmagorical treasures back into the world of man..."'),
(1585, 'ShaperMemoryFragment6_1', 47408, '"...The missing part of the great device had finally been formed.' || char(13) || '
The Shade requested its one favour. I was shown images of the past,' || char(13) || '
the Shade as King of the dreamlands, the hateful Watchers of Decay...' || char(13) || '
It led me deep into a cave, to a statue pierced by a sword..."'),
(1586, 'ShaperMemoryFragment7_1', 45537, '"Pull the blade from my chest. Free me!" the Shade imposed.' || char(13) || '
But doubt entered my mind, and the Shade flew into a fury!' || char(13) || '
I felt my mind torn asunder as images of murder and mutilation were forced upon me. ' || char(13) || '
I fled in a panic, cursing myself for ever trusting such a strange creature so blindly..."'),
(1587, 'ShaperMemoryFragment8_1', 11227, '"...Months have now passed since the Shade revealed its true nature.' || char(13) || '
Each morning, I lock myself inside my study, searching for some knowledge ' || char(13) || '
that might save us. I have found at last, some information on the Watchers of Decay. ' || char(13) || '
The truth is so unutterable that I hesitate, even now, to write it down..."'),
(1588, 'ShaperMemoryFragment8_2', 38605, '"...They called it the Elder. A creature of malignant madness... it cannot be killed.' || char(13) || '
The Watchers built the device to lock tight its kingdom, bringing with them the' || char(13) || '
blade - ''Starforge''. A weapon to give the Elder eternal rest. But the Shade...' || char(13) || '
I must find a way to put a stop to it before it finds a path to freedom..."'),
(1589, 'ShaperMemoryFragment9_1', 9869, '"...I''ve spent every waking hour since, trying to find a way to end this unholy Elder.' || char(13) || '
Within my secret study, I''ve begun work on a device of my own, tinkering and shaping.' || char(13) || '
When I''m finished, this Elder will never bother our world again.' || char(13) || '
The creature cannot be killed, but maybe... it can be exiled..."'),
(1590, 'ShaperMemoryFragment9_2', 41317, '"...Lack of progress on the device has given the High Templar cause for suspicion.' || char(13) || '
Clapped in irons, I was lead off to the Theopolis prisons for my insubordination.' || char(13) || '
I must find my way from these chains at all costs. The Elder is coming for us.' || char(13) || '
Only I can save us from this blasphemy that will soon befall Oriath..."'),
(1591, 'ShaperMemoryFragment9_3', 19538, '"...Venarius, that bastard... he marched me through the streets.' || char(13) || '
His men beat me within an inch of death... I... I told him everything. ' || char(13) || '
He demanded that I take all of us into the dreamlands, to meet with the Elder.' || char(13) || '
Using the device, we stepped through, setting foot in the Atlas of Worlds..."'),
(1592, 'ShaperMemoryFragment10_1', 31335, '"...It wasn''t long before we were met by the Shade itself.' || char(13) || '
The very essence of the Elder, demanding of me in visions to' || char(13) || '
tell it why I had returned. But before I could answer,' || char(13) || '
Venarius stepped forward and greeted the phantom..."'),
(1593, 'ShaperMemoryFragment10_2', 21833, '"...Before we knew it, we stood at the base of that blasphemous effigy.' || char(13) || '
"Pull the sword from my chest." The Elder imposed, and Venarius didn''t hesitate.' || char(13) || '
The earth shook in the face of the Elder''s reunion with its body. The true scope of the' || char(13) || '
Elder befell the High Templar and his men, and as it began to feed, I began to run..."'),
(1594, 'ShaperMemoryFragment10_3', 15985, '"...I fear this to be the end. Not just the end for me, but the end of all things. ' || char(13) || '
The Elder has been freed. Soon it will feast on me... on the rest of the world.' || char(13) || '
It was too late for me. The Elder had to be stopped. I knew of the shaping powers.' || char(13) || '
Only I could have a hope at defeating the Elder..."'),
(1595, 'ShaperKey', 44713, 'I spent my life shining a light on truth...' || char(13) || '
but some things should remain in darkness,' || char(13) || '
locked away for all eternity.'),
(1596, 'UniqueRing49', 31721, 'Be not stirred by the Void.'),
(1597, 'UniqueRing50', 25130, 'Let madness take control.'),
(1598, 'UniqueHelmetInt14', 39910, 'Where the body''s limits begin,' || char(13) || '
the mind''s limits end.'),
(1599, 'UniqueStaff22', 21132, 'Blurred is the boundary' || char(13) || '
between creator and destroyer.'),
(1600, 'UniqueTwoHandSword13', 15815, 'A weapon born of nothingness,' || char(13) || '
can only create more nothingness.'),
(1601, 'UniqueQuiver14', 47423, 'Even emptiness may be harnessed.'),
(1602, 'UniqueBodyStr10', 18353, 'The First of the Deep was the First of All.' || char(13) || '
It was He who conquered the waves,' || char(13) || '
who stood guard as land rose from sea.'),
(1603, 'UniqueHelmetStrInt12', 30869, 'When the rains come, we cower beneath shelter.' || char(13) || '
The First of the Deep teaches us' || char(13) || '
that we should seek no shelter but ourselves.'),
(1604, 'UniqueGlovesStr9', 22392, 'The stone that stays in the waves soon crumbles to sand.' || char(13) || '
The First of the Deep teaches us to watch the tides' || char(13) || '
and choose our moments to move wisely.'),
(1605, 'UniqueBootsStr10', 50110, 'When the land rose above the sea, The First of the Deep did not move.' || char(13) || '
When the sky turned to fire, The First of the Deep did not perish.' || char(13) || '
We must remember our place, and play to our strengths.'),
(1606, 'UniqueBodyStrInt10', 19311, 'A general may carry his men to greatness, ' || char(13) || '
or be dragged beneath the mire by their burden.'),
(1607, 'UniqueBodyStrDex8', 13470, 'The First of the Plains was the First of the Hunt' || char(13) || '
It was she who showed us that there is honour' || char(13) || '
in waiting in the shadows and picking your moment.'),
(1608, 'UniqueBodyStrDex8x', 4408, '"Attempt #120: the prototype has finally achieved power similar to the original' || char(13) || '
without breaking all the bones of the test subject. A rousing success."'),
(1609, 'UniqueHelmetDexInt10', 47630, 'It is a fool who strikes the turtle''s shell.' || char(13) || '
The First of the Plains teaches us to exploit weaknesses,' || char(13) || '
and where no weakness can be found, to create one.'),
(1610, 'UniqueGlovesStrDex10', 13324, 'A hungry beast wastes no energy. ' || char(13) || '
Every strike, no matter how small, must work towards victory.' || char(13) || '
The First of the Plains teaches us ' || char(13) || '
that the largest prey can still be whittled away.'),
(1611, 'UniqueBootsDex13', 41279, 'A secret is a weapon your enemies do not have.' || char(13) || '
When the First of the Plains hunted, she moved in silence and acted quickly.' || char(13) || '
To do otherwise is to arm your foes.'),
(1612, 'UniqueGlovesStrInt7', 45176, 'When the inferno spread across the land,' || char(13) || '
it was the First of the Sky who singed his feathers' || char(13) || '
as he brought the flames to a standstill.'),
(1613, 'UniqueBodyDexInt10', 3832, 'The First of the Sky was the Last of the First.' || char(13) || '
It was he who showed us that our limits are self-imposed,' || char(13) || '
that what we take for law may just be an illusion.'),
(1614, 'UniqueBootsStrDex6', 25639, 'A bird, too heavily laden, cannot take flight.' || char(13) || '
The First of the Sky teaches us to put aside our possessions' || char(13) || '
so that we may live more freely.'),
(1615, 'UniqueHelmetDex8', 26335, 'Though we are individual, we share the same plight.' || char(13) || '
The First of the Sky teaches us that unity and selflessness,' || char(13) || '
not division and greed, is what will carry us upwards.'),
(1616, 'UniqueBodyInt17', 44373, 'The First of the Night was the first explorer' || char(13) || '
It was she who first braved night''s terrors' || char(13) || '
and found comfort in silence and solace.'),
(1617, 'UniqueHelmetInt16', 60444, 'A hunter uses everything at their disposal.' || char(13) || '
The First of the Night did not hold back her venom. ' || char(13) || '
She used it to weaken her enemies, ' || char(13) || '
and used her enemies to strengthen her many children.'),
(1618, 'UniqueGlovesDexInt10', 61795, 'A burden shared is a burden made lighter.' || char(13) || '
The First of the Night teaches us that our burdens ' || char(13) || '
are not just ours to bear, but ours to use against oppressors.'),
(1619, 'UniqueBootsDexInt7', 20531, 'When the fires spilled out of the mountain, The First of the Night wove a net' || char(13) || '
and was carried into the night on its hot winds.' || char(13) || '
Though we cannot live without danger, we can learn to live with it.'),
(1620, 'UniqueHelmetInt15', 45441, 'Gleeful are the few' || char(13) || '
who bask in the blood of the many.'),
(1621, 'UniqueBodyStrInt9', 57031, 'When it comes to finding a use for surplus,' || char(13) || '
a rich man has within himself' || char(13) || '
boundless creativity.'),
(1622, 'UniqueBodyStrInt9x', 46280, '"Better... stronger... more vital... and then... failure. Always, failure.' || char(13) || '
What key fundamental secret are we missing?"'),
(1623, 'UniqueRing51', 42980, 'When your skin sloughs, and your blood cooks,' || char(13) || '
you''ll wish the lightning strike had killed you.'),
(1624, 'UniqueBelt28', 39875, 'What started as a desire to feed' || char(13) || '
became a desire to learn...'),
(1625, 'UniqueGlovesDexInt11', 44696, 'Great works take time.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Dominance}'),
(1626, 'UniqueGlovesDexInt12', 7192, 'A plan without a deadline stays a plan.'),
(1627, 'UniqueHelmetStrInt13', 58898, 'Our flesh is our most sacred gift.' || char(13) || '
Taint it not with the occult.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Summoning}'),
(1628, 'UniqueHelmetStrInt14', 46063, 'From the flesh of the gods, Xibaqua was born.' || char(13) || '
From the carnage of Xibaqua, we were born.' || char(13) || '
It is our duty to return to the gods what was once theirs.'),
(1629, 'UniqueShieldInt11', 11334, 'The heart grows slow,' || char(13) || '
the spirit grows strong.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Awakening}'),
(1630, 'UniqueShieldInt12', 50102, 'Give him your body, and your burdens will follow.'),
(1631, 'UniqueBodyStrDexInt2', 59258, 'Destined for sacrifice,' || char(13) || '
they were dressed in garments' || char(13) || '
that blurred the lines between this world' || char(13) || '
and the next.'),
(1632, 'UniqueAmulet48', 29677, 'The seed of life, saved and savoured.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Sacrifice}'),
(1633, 'UniqueAmulet49', 1820, 'We are incapable of change without sacrifice, for we are both the iron and the forge.'),
(1634, 'UniqueJewel116', 17827, 'We are born raw and untested, and we are shaped by life.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Transcendence}'),
(1635, 'UniqueJewel117', 41442, 'Though the body rots, the spirit lives on.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Transcendence}'),
(1636, 'UniqueJewel118', 43025, 'Any thought, no matter how fleeting, changes the thinker.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Transcendence}'),
(1637, 'UniqueJewel119', 44881, 'We are as much shaped by what we do' || char(13) || '
as what is done to us.'),
(1638, 'UniqueJewel120', 40122, 'Take comfort knowing that, even in death,' || char(13) || '
we may serve our Queen and fuel her empire.'),
(1639, 'UniqueJewel121', 34510, 'A keen mind sees what others do not,' || char(13) || '
makes connections where others do not, ' || char(13) || '
and is dangerous in a way that others are not.'),
(1640, 'UniqueFlask25', 13973, 'Freedom is for the privileged, even in death.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of the Ghost}'),
(1641, 'UniqueFlask26', 19137, '"What care have I for their pain? They''re already dead."' || char(13) || '
- Atalui, Vaal Priestess'),
(1642, 'UniqueBelt29', 48246, 'For the Vaal, the relationship between slave and master' || char(13) || '
was as intimate and volatile as that of lovers.'),
(1643, 'UniqueBootsDexInt8', 61993, 'Facing their death,' || char(13) || '
the mind of a sacrifice' || char(13) || '
retreats into instinct and madness.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of the Ritual}'),
(1644, 'UniqueBootsDexInt8Royale', 15055, 'Facing their death,' || char(13) || '
the mind of a sacrifice' || char(13) || '
retreats into instinct and madness.'),
(1645, 'UniqueBootsDexInt9', 13009, 'Only a fool seeks meaning' || char(13) || '
in a life so fleeting.'),
(1646, 'UniqueBelt30', 41212, 'As a gift or as punishment,' || char(13) || '
the Empire will have your blood.' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Consequence}'),
(1647, 'UniqueBelt31', 57846, 'Death is your most important duty.' || char(13) || '
Face it, or curse your bloodline for all eternity.'),
(1648, 'UniqueOneHandSword29', 6173, 'Through war we found peace. Through death we found advancement.' || char(13) || '
Our ancestors did not know where their actions would take them.' || char(13) || '
Are we any better?' || char(13) || '
' || char(13) || '
<default>{This item can be transformed on the Altar of Sacrifice along with Vial of Fate}'),
(1649, 'UniqueOneHandSword30', 22135, 'Doryani promises immortality, yet we build great structures, ' || char(13) || '
carve magnificent works into stone, so a part of us lives onward.' || char(13) || '
A sign of faithlessness through action.'),
(1650, 'UniqueTwoHandAxe16', 6493, 'War is a thriving infection.' || char(13) || '
It numbs the heart and eats away at the soul' || char(13) || '
until only emptiness remains.'),
(1651, 'UniqueSceptre19', 17891, 'There the weary multitude of man-kind ' || char(13) || '
shall turn in their masses into the wide fire, ' || char(13) || '
where the destroying flame embraces the living, ' || char(13) || '
some will go up, some down, filled with misery.'),
(1652, 'UniqueSceptre19x', 52539, '"Lord of Bone, Lord of Flesh, yet all that we can' || char(13) || '
master turns to ash." ' || char(13) || '
- Researcher Arn'),
(1653, 'UniqueShieldDexInt5', 10292, '"Great minds wish to reveal all the secrets of time and space.' || char(13) || '
But it does not matter. Creation, the act of Matter Metamorphosis, ' || char(13) || '
is the only secret worth discovering." ' || char(13) || '
- Zeel, Vaal Tinkerer'),
(1654, 'UniqueShieldStrInt12', 5887, 'An Emperor must conquer his own darkness' || char(13) || '
before he can act as a beacon of light.'),
(1655, 'UniqueJewel122', 64258, 'Kaom watched the torches patrol the top of the Watch. ' || char(13) || '
He observed the lay of the beach, its barricades and rocks, ' || char(13) || '
and his men in their canoes, ready to lay their lives down for him.' || char(13) || '
But when his foot hit the sand, he thought only of the fight.'),
(1656, 'UniqueJewel123', 20616, 'Standing behind iron bars,' || char(13) || '
Daresso thought of his adoring fans cheering his name, ' || char(13) || '
his wife''s warm embrace waiting for him, ' || char(13) || '
and of the celebrations that would soon be thrown in his name.' || char(13) || '
But when the arena gate lifted, he thought only of the fight.'),
(1657, 'UniqueJewel124', 50099, 'Voll stood at the gates of Sarn, and a nation stood behind him. ' || char(13) || '
He thought of the righteousness of his cause, ' || char(13) || '
and of the glory he would bring to the empire he would soon lead. ' || char(13) || '
But as Chitus and his gemlings advanced, he thought only of the fight.'),
(1658, 'UniqueAmulet50', 29713, '"Did we make this? Why do we have no record of it?' || char(13) || '
We were warned that there would be consequences..."' || char(13) || '
- Administrator Qotra'),
(1659, 'UniqueJewel125', 24192, '"I don''t know how I know, ' || char(13) || '
I just know that I know."'),
(1660, 'UniqueHelmetStrDex7', 23407, 'When you''re on the run,' || char(13) || '
look only to yourself for survival.'),
(1661, 'UniqueGlovesInt10', 60476, 'Xibaqua''s treachery was met with divine fury.' || char(13) || '
One by one, the gods reclaimed their flesh,' || char(13) || '
until all that remained was a droplet of pure light:' || char(13) || '
The first Vaal.'),
(1662, 'UniqueRing52', 16960, 'So great was the thaumaturgy of a bloodpriest''s mark,' || char(13) || '
that sacrifices soon welcomed their death.'),
(1663, 'UniqueStaff23', 21783, 'Death is but the start of your servitude.'),
(1664, 'UniqueGlovesStrInt8', 16523, 'We serve only the Night.'),
(1665, 'UniqueStaff24', 27789, 'There was never a simpler time.' || char(13) || '
Just simpler motivations.'),
(1666, 'UniqueAmulet51', 57776, 'The leash of the lifegiver' || char(13) || '
binds in both directions.'),
(1667, 'UniqueGlovesInt9', 57915, '"One coy look. One blown kiss. One word spoken.' || char(13) || '
One night I wish I''d forget."'),
(1668, 'UniqueAmulet52', 16870, 'He was a lot luckier before he lost this.'),
(1669, 'UniqueShieldInt13', 21022, 'The empire is both the tree and the fruit.' || char(13) || '
It provides safe harbour as ideas grow within,' || char(13) || '
and when the time is right, the apple is picked. ' || char(13) || '
The idea, and our ideals, take root.'),
(1670, 'UniqueHelmetDexInt11', 34003, 'Sing with me one last duet,' || char(13) || '
the curtain closes nigh.' || char(13) || '
Join me in a quiet song,' || char(13) || '
Before we all must die.'),
(1671, 'UniqueSceptre20', 49019, 'The greatest of guardians make the greatest of sacrifices.'),
(1672, 'UniqueHelmetInt17', 21203, '"Feel the pain of ancient wounds.' || char(13) || '
Feel the doom of dying souls."'),
(1673, 'UniqueHelmetStrInt15', 54899, 'You will know if your subjects follow you from fear' || char(13) || '
or respect when you have your first moment of weakness.' || char(13) || '
If it''s the former, they will tear you into pieces like rabid dogs.'),
(1674, 'UniqueAmulet53', 26944, 'It was not his fearlessness or ferocity, nor his tactical genius,' || char(13) || '
it was his leadership that earned Aul, the Last King, his crown.'),
(1675, 'UniqueRing53a', 35629, 'Fleeing the destruction set upon her home,' || char(13) || '
the Clayshaper sought safety in the clouds of ash above.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Meadow and Valley ring at a Vendor.}'),
(1676, 'UniqueRing53b', 20905, 'Where once had stood a village, lay naught but splinters.' || char(13) || '
Some had once been her home. ' || char(13) || '
Some had once been her creations.' || char(13) || '
Some had once been her family.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Mountain and Valley ring at a Vendor.}'),
(1677, 'UniqueRing53c', 11038, 'The river, once fertile and fresh, ' || char(13) || '
and flowing briskly to the sea,' || char(13) || '
now stood, stained, at a standstill.' || char(13) || '
Dammed by the coagulating dead.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Meadow and Mountain ring at a Vendor.}'),
(1678, 'UniqueRing53d', 17593, 'The narrow path turned to rough rocks that led towards the sky.' || char(13) || '
One last obstacle in a life-long journey' || char(13) || '
to find a land they could call home.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Meadow and Valley ring at a Vendor.}'),
(1679, 'UniqueRing53e', 59387, 'Cold winds blasted what little grew on the icy surface.' || char(13) || '
The gifts of the land lay hidden deeper,' || char(13) || '
and only patience and persistence would free them.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Mountain and Valley ring at a Vendor.}'),
(1680, 'UniqueRing53f', 22647, 'Sheltered beneath thick ice,' || char(13) || '
the river ferried fat fish towards the sea.' || char(13) || '
But the First King knew the river''s secret,' || char(13) || '
and the fish were not the only ones who grew fat.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Meadow and Mountain ring at a Vendor.}'),
(1681, 'UniqueRing53g', 50873, 'He surveyed his lands, green and vital,' || char(13) || '
watched with pride as his slaves quarried fine stone for his fortress,' || char(13) || '
and thanked the heavens for his many blessings.' || char(13) || '
But this pilgrimage to the peak was to be his last.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Meadow and Valley ring at a Vendor.}'),
(1682, 'UniqueRing53h', 59684, 'The fields were silent but for the plucking of fruits,' || char(13) || '
the rustling of leaves, and the breaking of stone.' || char(13) || '
No slave dared to speak or look the passing king in the eye.' || char(13) || '
No one... except Aul.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Mountain and Valley ring at a Vendor.}'),
(1683, 'UniqueRing53i', 23496, 'With no stone for rebuilding, each storm took its toll on the village.' || char(13) || '
Huts eventually collapsed, their occupants injured or dead.' || char(13) || '
Bodies were left by the river, to appease the gods.' || char(13) || '
But the dead would not remain there.' || char(13) || '
' || char(13) || '
<default>{This item can be combined with a Meadow and Mountain ring at a Vendor.}'),
(1684, 'UniqueRing54', 23274, 'History teaches humility.'),
(1685, 'UniqueJewel127', 48015, 'In the weeks that followed the Cataclysm,' || char(13) || '
the dead began to rot and fester.' || char(13) || '
The air fouled with such concentration,' || char(13) || '
that passing birds drowned in flight.'),
(1686, 'UniqueShieldInt14', 54539, 'Though we live and act as individuals,' || char(13) || '
in truth, we are tethered together. ' || char(13) || '
The barriers that divide us need not be broken ' || char(13) || '
for our spirits to become entangled.'),
(1687, 'UniqueAmulet54', 36162, 'Time, like light, can be refracted into all its myriad colours.' || char(13) || '
The first shade is beautiful, but the last will drive the unwary insane.'),
(1688, 'UniqueBow22', 26776, '"There were no survivors. It had only been fired twice."' || char(13) || '
- Order of the Djinn inscription'),
(1689, 'UniqueRing55', 60892, '"Fusing the parasite with another ring has manifested unpredictable effects.' || char(13) || '
I theorise the sacrificial vessel''s level of anguish is a key variable."' || char(13) || '
- Arzaak, Syndicate Researcher'),
(1690, 'UniqueFlask27', 61418, 'A controlled burn is sometimes necessary for new life.'),
(1691, 'UniqueGlovesStrDex11', 42128, 'Open the way to new and dangerous lands.'),
(1692, 'UniqueGlovesStrDex12_', 53658, 'Is it better to find new lands - or to create them?'),
(1693, 'UniqueHelmetInt18', 47027, 'See the land as it is.'),
(1694, 'UniqueHelmetInt19a', 23145, 'See creation as it was, aflame and frantic.'),
(1695, 'UniqueHelmetInt19b', 7942, 'See creation as it will be, frozen and silent.'),
(1696, 'UniqueHelmetInt19c', 31681, 'See creation as it is, energetic and storming.'),
(1697, 'UniqueBodyDexInt11', 1854, 'There can be no defence against the celestial siblings entropy and time.'),
(1698, 'UniqueBodyDexInt11x', 24536, '"The form of this replica came to me in a troubled dream.' || char(13) || '
I do not believe we should ever allow it to be used."' || char(13) || '
- Researcher Arn'),
(1699, 'UniqueRapier6', 59126, 'What has no siblings but is always a twin?'),
(1700, 'UniqueRapier6x', 64037, '"This is one riddle I can''t solve." ' || char(13) || '
- Researcher Graven'),
(1701, 'UniqueBelt32', 23436, 'Cold winds whirl at the crown of the world.'),
(1702, 'UniqueBodyInt18', 37280, 'In their crimson nightmare, the Vaal are still sacrificing themselves to her glory and beauty. ' || char(13) || '
They stab their own hearts and cry out in ecstasy, only to rise again.'),
(1703, 'UniqueHelmetInt20', 27479, 'The spirit hungers for the flesh.'),
(1704, 'UniqueSceptre21', 30866, 'The vastness of the cosmos holds energies beyond comprehension,' || char(13) || '
should one have the fortitude to grasp them.'),
(1705, 'UniqueSceptre21x', 6561, '"We could rival the gods with this power, if only we had the mitigating mechanisms' || char(13) || '
to make it work. A jewel, a talisman, an armour... or the Font..."'),
(1706, 'UniqueFlask28', 27869, 'A tourniquet for the soul, squeezing ethereal into physical.'),
(1707, 'UniqueGlovesStrInt9', 37253, '"You covet the strength of your peers, mortal?' || char(13) || '
Perhaps it can be yours, if you are willing to make an offering of their blood..."' || char(13) || '
- Vaal Myth of the Third Snake'),
(1708, 'UniqueBodyInt19', 53537, 'Exceptional men and women of strong will can flicker a spark, ' || char(13) || '
but something much greater is needed to unleash the wildfire of true divine flames.'),
(1709, 'UniqueGlovesDexInt13', 45725, 'The power of lightning is a power best shared.'),
(1710, 'UniqueHelmetStrInt16', 41792, 'The judge determines worthiness by comparison to the paragon: himself.'),
(1711, 'UniqueRing56', 3981, 'I condemned an innocent man to the pyres, but to admit this mistake is to condemn myself.' || char(13) || '
My only choice is to strive harder.'),
(1712, 'UniqueRing57', 60519, 'My subordinates circled me eternally, attuned to the slightest weakness,' || char(13) || '
ready to tear me apart for their own gains.'),
(1713, 'UniqueRing58', 40556, 'I sacrificed a life of love for one of responsibility, so that she,' || char(13) || '
and others like her, might be kept safe.'),
(1714, 'UniqueRing59', 19904, 'I was a happy child, before the cruel truth was revealed to me.' || char(13) || '
I fight so that the children may remain ignorant.'),
(1715, 'UniqueRing60', 3550, 'I feel the moral weight of what I must do to protect Wraeclast.' || char(13) || '
I accept my guilt without shame. It is my gift to humanity.'),
(1716, 'UniqueAmulet55', 48217, 'Strike true, strike hard, and leave no survivors to retaliate.'),
(1717, 'UniqueAmulet55x', 4967, '"The type Delta test subjects could have escaped with the power offered by' || char(13) || '
Prototype #15, but they suddenly chose to murder each other instead..."'),
(1718, 'UniqueShieldDexInt6', 58840, 'Something within the machine never stops moving,' || char(13) || '
but Oriathan scholars dare not open it to find out why.'),
(1719, 'UniqueBootsStrInt6', 23347, 'When the time comes to face evil, the faithful are never alone.'),
(1720, 'UniqueQuiver15', 33510, 'Midnight tinkering begets midday murdering;' || char(13) || '
a sinister shaft surreptitiously shot slays a scoundrel.' || char(13) || '
I will see them again, but not until my work is done.'),
(1721, 'UniqueQuiver15x', 27341, '"The Midnight Tinkerer''s aid was invaluable during our brief alliance,' || char(13) || '
but when we failed to make any progress on resurrection, he continued his search elsewhere..."'),
(1722, 'UniqueGlovesDexInt14', 35962, 'The Black Sekhema''s trial had only just begun.'),
(1723, 'UniqueHelmetDemigods1', 44728, 'The champion''s name echoes through time, ' || char(13) || '
drowning out the whispers of the defeated.'),
(1724, 'UniqueHelmetInt21', 26086, 'Young Napuatzi was thrown into the pits, an unwilling sacrifice, ' || char(13) || '
but the offer of her blood was refused. ' || char(13) || '
She rose from the pit alive and anew.  ' || char(13) || '
A Leader. A Conquerer. A Viper.'),
(1725, 'UniqueAmulet56', 1382, '"Hyrri and her arrows broke the sacred code, damning herself. ' || char(13) || '
Kaom seized her sacrifice, and in doing so, seized victory." ' || char(13) || '
- Lavianga, Advisor to Kaom'),
(1726, 'UniqueHelmetDexInt12', 2398, '"The more the warrior understood Tangmazu''s gift, the less the mask aided him.' || char(13) || '
His dreams were filled with divine laughter."' || char(13) || '
- Tenth Song of the Islands'),
(1727, 'UniqueHelmetInt22', 18130, 'The Light drove the darkness from our lands and from our hearts.'),
(1728, 'UniqueSceptre22', 16857, 'A secret few among the Templars grant absolution by bearing the guilt of others.'),
(1729, 'UniqueJewel128', 39075, 'They believed themselves the pinnacle of civilisation, but that height toppled their empire.'),
(1730, 'UniqueJewel129', 46561, 'They believed themselves the greatest warriors, but that savagery turned upon their own.'),
(1731, 'UniqueJewel130', 45402, 'They believed themselves the most ordered, but that tradition turned their forests to salt.'),
(1732, 'UniqueJewel131', 36763, 'They believed themselves the utmost faithful, but that conviction became oppression.'),
(1733, 'UniqueJewel132', 29374, 'They believed themselves better than the past, but that confidence brought about nightmare.'),
(1734, 'UniqueJewel133', 56675, 'The enslaved Ezomyte clans were not permitted to own weapons.' || char(13) || '
For years, they trained in secret, watching and waiting for the' || char(13) || '
perfect moment to reveal the true depth of the Empire''s folly.'),
(1735, 'UniqueGlovesExpedition1', 40480, 'Those heroes that set foot on Wraeclast found' || char(13) || '
themselves changing, only subtly at first...'),
(1736, 'UniqueGlovesExpedition2', 48556, 'For forty-two nights, the Feller of Heroes challenged' || char(13) || '
the next greatest warrior to a one-on-one duel.' || char(13) || '
None could match his might.'),
(1737, 'UniqueBootsExpedition1', 59394, 'In their hour of desperate need, the Knights of the Sun' || char(13) || '
called out for aid... and the Black Scythe answered.'),
(1738, 'UniqueBootsExpedition2', 14209, 'Where others would retreat when vulnerable,' || char(13) || '
Olroth the Gallant fought deeper into battle.'),
(1739, 'UniqueHelmetExpedition1', 23668, 'The priests of the Kalguur worshipped knowledge, not gods.'),
(1740, 'UniqueHelmetExpedition2', 63979, 'Cadigan the Third ruled dispassionately' || char(13) || '
through the iron might of artifice.'),
(1741, 'UniqueFlask29', 5984, 'Olroth the Gallant,' || char(13) || '
tireless and true,' || char(13) || '
he fights for me,' || char(13) || '
he fights for you!'),
(1742, 'UniqueFlask30', 49801, 'Uhtred and his priests drank of the skies' || char(13) || '
to empower runes... and themselves.' || char(13) || '
'),
(1743, 'UniqueFlask31_', 31646, 'Nothing endures. All things end.' || char(13) || '
Then, they begin again.'),
(1744, 'UniqueFlask32', 43152, 'Vorana trained her mercenaries' || char(13) || '
thus: strike true and survive.'),
(1745, 'UniqueGlovesStrDex14', 57582, 'Try as you like to hide the' || char(13) || '
blood on your hands.' || char(13) || '
You''ll still know the truth.'),
(1746, 'UniqueAmulet66', 26497, 'Death''s approach brings clarity.'),
(1747, 'UniqueBelt43_', 31709, 'Rivers of power course through your veins.'),
(1748, 'UniqueBodyDexInt15', 39770, 'Those that can never die have but one wish.'),
(1749, 'UniqueAmulet67', 58450, 'The time is nigh.' || char(13) || '
War has come.' || char(13) || '
We dream as one.'),
(1750, 'UniqueShieldStrDex7', 45665, 'Judge not the weak, for' || char(13) || '
they empower the strong.'),
(1751, 'UniqueShieldStrDex8', 40919, 'Every clash leaves one more scar.'),
(1752, 'UniqueJewel158', 32408, '"We awoke to a sudden jungle rupturing the valleys of our home.' || char(13) || '
Grasping limbs coiled around us, into us. We sank into each other,' || char(13) || '
then rose into the living sky. My family screams alongside me still."'),
(1753, 'UniqueJewel159', 23854, '"We awoke to a sudden dawn cresting through the mountains.' || char(13) || '
Each peak rose into searing fire, a massive roiling tide.' || char(13) || '
A great eye gazed upon us, and we became known—utterly."'),
(1754, 'UniqueAmulet68', 51050, 'That winter, scorched refugees emerged from the shrine,' || char(13) || '
speaking only in strange tongues. They prayed to a new' || char(13) || '
symbol of power, not out of love, but out of fear.'),
(1755, 'UniqueAmulet69', 2948, 'A single facet contains the wisdom' || char(13) || '
of countless disintegrated worlds.'),
(1756, 'UniqueStaff30', 47146, 'There is no force more destructive in the heavens' || char(13) || '
than the scintillating light of utter clarity.'),
(1757, 'UniqueBow23', 8205, 'To eat, to feast, to forget the horror of endless agonising existence' || char(13) || '
if but for a moment... only to disgorge and do it all again...'),
(1758, 'UniqueGlovesInt11', 23381, 'He reached for his home one last time, a shining jewel among the stars...' || char(13) || '
only to watch in horror as it ruptured and shattered under a tide of limbs.'),
(1759, 'UniqueHelmetInt25', 57522, 'Where that searing dawn fell, silence reigned.' || char(13) || '
We sought the shadows, but none remained.'),
(1760, 'UniqueRing72', 7484, 'Those that escaped the annihilating light' || char(13) || '
sank eternally into crushing darkness. '),
(1761, 'UniqueGlovesStr11', 5584, 'Lost in a sea of limbs and screaming faces, they claw' || char(13) || '
for any fleeting pleasure which might dull the pain.'),
(1762, 'UniqueBootsDexInt12', 35597, 'A multitude of beings share a wretched existence' || char(13) || '
irrevocably bound together in perpetual torture.'),
(1763, 'UniqueShieldStr13', 21873, '"The newcomers warn of doom and death beyond mortal ken.' || char(13) || '
I ask, why should we fear the fire when we serve the Lord of Light?"' || char(13) || '
- Maxarius, the first High Templar'),
(1764, 'UniqueJewel160', 29943, 'The minds of those studied utterly by the Cleansing Fire' || char(13) || '
continue to think and dream and beg for silence...'),
(1765, 'UniqueJewel161_', 25814, 'The bodies of those wholly subsumed by the Tangle' || char(13) || '
continue to merge and mutate and cry out for release...'),
(1766, 'UniqueJewel162', 57569, 'Gripping the stolen Spear of Solerai in hand,' || char(13) || '
the bandit king of Stridevolf watched his enclave burn.' || char(13) || '
As foretold, the weapon was powerful beyond compare,' || char(13) || '
but using it had cost him absolutely everything.'),
(1767, 'UniqueBelt44', 52971, 'Mortal pleasures can hold back the memories,' || char(13) || '
but a hollow soul can never be healed.'),
(1768, 'UniqueHelmetStr9', 18067, 'A cacophony of battle cries' || char(13) || '
Reverberate through time and space' || char(13) || '
Inflicting pain beyond measure'),
(1769, 'UniqueAmulet70', 6965, 'Simply the way it must be, so that existence may be.'),
(1770, 'UniqueRing73', 42503, 'Only when the mind is empty of ambition' || char(13) || '
can the cold truth of existence take hold.'),
(1771, 'UniqueJewel163_', 15969, 'She was the last of countless progeny bred to test the limits of limitless power.' || char(13) || '
In the cosmic prison of her birth, her siblings fought each other to the death' || char(13) || '
for supremacy. She alone reached her limit... and broke through.'),
(1772, 'UniqueJewel164', 244, 'This world is not good enough for her,' || char(13) || '
so I will make a better one. Nothing' || char(13) || '
matters but the pursuit of perfection.'),
(1773, 'UniqueSentinel1', 59952, 'Destruction incarnate leaves a bitter aftertaste' || char(13) || '
as one soul is imbued with remnants of another,' || char(13) || '
and the earth is salted by rivers of blood.' || char(13) || '
'),
(1774, 'UniqueSentinel2', 58955, 'Alone among the powers of artifice, there is one against' || char(13) || '
which the horrors of Wraeclast have never adapted.' || char(13) || '
'),
(1775, 'UniqueSentinel3_', 21438, 'She stands grim, wreathed in flame, awaiting the crusader''s call.'),
(1776, 'UniqueSentinel3b', 18250, 'Knowing the human body to harbour infinite potential,' || char(13) || '
she endowed her subjects with the most potent forces at her disposal,' || char(13) || '
striving invariably for improvement.'),
(1777, 'UniqueSentinel3c', 45303, 'Some artists wait a lifetime for inspiration. He waited for five.'),
(1778, 'UniqueSentinel3d', 35, 'Even after she harvested their tongues, they were still able to scream.'),
(1779, 'UniqueSentinel3e', 23466, 'This grotesque conglomerate is truly an abomination to behold.' || char(13) || '
You feel a strange sense of déjà vu when you gaze upon its hideous visage...'),
(1780, 'UniqueSentinel3f', 38388, 'A fiery horror from a distant plane of existence,' || char(13) || '
it feasts upon the charred corpses subsumed by lava pits.' || char(13) || '
Don''t fall in...'),
(1781, 'UniqueSentinel3g', 18595, 'Lightning always strikes twice.'),
(1782, 'UniqueSentinel3h', 41793, 'He feeds on the nightmares of the Atlas'' denizens.' || char(13) || '
If you fall asleep in the Atlas, he''ll be waiting...'),
(1783, 'UniqueSentinel4', 41206, 'In the wake of tyranny,' || char(13) || '
The battlefields have been left barren.'),
(1784, 'UniqueSentinel6', 24596, 'Under clouds of black beset by crimson lightning, we sailed stormy seas of poison and disease. Only one light shone in that darkness; only one Flame to keep hope alive.'),
(1785, 'UniqueSentinel7', 18339, 'A life without risk is no life at all.'),
(1786, 'UniqueSentinel8', 40498, 'On judgement day, only those who are worthy will survive.'),
(1787, 'UniqueSentinel9', 30398, 'Otherworldly incantations echo across the battlefield,' || char(13) || '
And the warrior readies his blade.'),
(1788, 'UniqueSentinel11', 9893, 'Mechanisms gone awry, circuitry in flux.' || char(13) || '
This experiment became something truly perverse.'),
(1789, 'UniqueSentinel12', 5437, 'Torture something enough, and you just might force a reaction.'),
(1790, 'UniqueGlovesStr12', 50208, 'Who can tell when whispers are truly from a god?'),
(1791, 'UniqueMap26', 32901, 'On the outskirts of Utzaal, at the Temple of Chaos,' || char(13) || '
the Trialmaster awaits your challenge.'),
(1792, 'UniqueGlovesDexInt18', 53069, 'Fear can be instilled by the smallest entity.'),
(1793, 'UniqueBootsStr12', 15086, 'In a void strewn with incandescent stardust,' || char(13) || '
the emissary of flame traverses interplanetary space' || char(13) || '
consuming the knowledge of fallen civilisations.'),
(1794, 'UniqueBodyInt21', 63842, 'Faith springs abundant at the edge of death.'),
(1795, 'UniqueHelmetStr10', 42990, 'We may fight, and we may die, but in these' || char(13) || '
moments of blood and battle, we truly live.'),
(1796, 'UniqueHelmetDex11', 55194, 'Ancient worshippers of the Greatwolf were overtaken' || char(13) || '
by a ravenous hunger for all things mystical.'),
(1797, 'UniqueBootsStrDex8', 39523, 'Pray that the flames find fascination,' || char(13) || '
for the true end follows when the great eye closes.'),
(1798, 'UniqueQuiver19', 10753, 'What do you see when you look inward?'),
(1799, 'UniqueRing22', 6013, 'On one hand, you have a choice.' || char(13) || '
On the other, you have its twin.'),
(1800, 'UniqueFlask33', 3733, 'They were bred in a cosmic ocean of raw creation.' || char(13) || '
Feasting and drinking of the milk of the mother,' || char(13) || '
they fought to the death for every last drop.'),
(1801, 'UniqueJewel165', 46873, 'A wellspring of vitality bubbling from within.'),
(1802, 'UniqueJewel166', 26508, 'A mountain fortress safe from the storm.'),
(1803, 'UniqueJewel167', 3229, 'A mass of flesh writhing with savage fury.'),
(1804, 'UniqueJewel168', 35084, 'A body that never falters.'),
(1805, 'UniqueJewel169', 1936, 'A spirit that never rests.'),
(1806, 'UniqueJewel170', 46815, 'A mind that never quiets.'),
(1807, 'UniqueJewel171', 47483, 'Logic wanes in shining faith, and in rationalism, ardour dims' || char(13) || '
Thus, the cynic and the zealot are divided' || char(13) || '
But can they not be one and the same?'),
(1808, 'UniqueRing74', 19270, 'Too much of something is bad enough;' || char(13) || '
too much of nothing is just as tough.'),
(1809, 'UniqueGlovesDexInt19', 32780, 'A legion of lives claimed' || char(13) || '
by the shards of obliterated worlds.'),
(1810, 'UniqueFlask34', 11716, 'Ennui prevailed, until inspiration sparked' || char(13) || '
a mote of flame, kindled by fury' || char(13) || '
and all in his path were obliterated.'),
(1811, 'UniqueFlask35', 17908, '"To proclaim a vision of the future is to make it so,' || char(13) || '
for those that have the will, and the way!"' || char(13) || '
- High Templar Andronicus'),
(1812, 'UniqueAmulet71', 37136, 'The price of immortality is isolation.'),
(1813, 'UniqueHelmetInt26', 27165, 'Bold and beautiful, a castaway' || char(13) || '
Hemmed and hawed, for her to stay' || char(13) || '
Oh, what I''d give for one more day' || char(13) || '
For she''s the one that got away' || char(13) || '
-Franklin'),
(1814, 'UniqueJewel172', 28542, 'How simple a power, on which empires turn,' || char(13) || '
when one man stands firm and says, "I refuse."'),
(1815, 'UniqueJewel173', 3929, 'The true secret of the elements' || char(13) || '
is that all are one and the same.'),
(1816, 'UniqueJewel174', 290, 'Within a firestorm, the Thane commands the flames' || char(13) || '
Emblazoned by glory and the song of the First Ones' || char(13) || '
For the master of fire fears nothing.'),
(1817, 'UniqueStaff31', 58416, 'Life... Death...' || char(13) || '
The whim of the cosmos.'),
(1818, 'UniqueJewel175', 44534, 'In darkest night, ''neath waxen moon' || char(13) || '
A witch snatches a boy from his room.' || char(13) || '
He wards off her hexes' || char(13) || '
The witch he perplexes' || char(13) || '
And so becomes part of her stew.'),
(1819, 'UniqueRing75', 15582, 'Enraged by the incompetence of mortals' || char(13) || '
The demon-lord opens a gateway' || char(13) || '
Unleashing a litany of pain upon the world.'),
(1820, 'UniqueAmulet72', 14132, 'Maligaro did the cutting... at her request.' || char(13) || '
In the new void, a malevolent power emerged.'),
(1821, 'UniqueTwoHandSword14', 52695, 'Witness the emergence of a new cosmic power.'),
(1822, 'UniqueJewel176', 47098, 'Fellshrine stood as a holy bastion opposite the' || char(13) || '
Chamber of Sins, and all that it represented.' || char(13) || '
For one to rise, the other must fall.'),
(1823, 'UniqueHelmetInt27', 17402, 'A fell wind brings death.'),
(1824, 'UniqueRelic1', 61089, '"They ascended together, one unwillingly. The vilified became black as coal, and the lauded, golden. After a lifetime of ambition, he finally had his heart''s desire. It only cost him his brother." - Lycia, the Heretic'),
(1825, 'UniqueRelic2', 9382, '"He took the newcomers'' symbol and made it his own. Finally, they flocked to him. Finally, he had the power and wealth he so desired." - Lycia, the Heretic'),
(1826, 'UniqueRelic3', 48611, '"He took many of his people''s traditions and gilded them, hollowed them. They rejected his new religion, and he and his followers were forced to depart the mountains for lands unknown." - Lycia, the Heretic'),
(1827, 'UniqueRelic4', 30835, '"The newcomers were terrified of fire. He used their fear to control them, to lay the seeds of unquestioning faith. He claimed only his god could protect them." - Lycia, the Heretic'),
(1828, 'UniqueRelic5', 26202, '"In pursuit of divinity, he tried many times to found a religion. Few followed his initial symbols and proverbs. He needed something greater. A symbol none could deny." - Lycia, the Heretic'),
(1829, 'UniqueRelic6', 45300, '"His followers were too small in number to spark divinity, so he turned to a greater power: hatred. He vilified his brother, sparking zealotry, and the change finally began." - Lycia, the Heretic'),
(1830, 'UniqueRelic7', 8860, '"It''s all here. The lie at the core of my faith. Maxarius was not the first chosen of Innocence. Maxarius was Innocence himself. A charlatan, a liar, and a power-seeker." - Lycia, the Heretic'),
(1831, 'UniqueRelic8', 37652, '"After weeks of being pursued, the veiled traveller made her stand in a sandstorm. Somehow, she wounded a god. Innocence relented; his brother and the traveller made good their escape." - Lycia, the Heretic'),
(1832, 'UniqueRelic9', 64687, '"The mysterious traveller saw the vilified brother chained to a cliff, where all could point and shout and deride him. In one fell swing, she cracked the mountainside, freeing him." - Lycia, the Heretic'),
(1833, 'UniqueRelic10', 46159, '"Building on the fear and hatred that deified him, Innocence threatened an eternity of flames for nonbelievers. The newcomers wailed and threw themselves at his feet in the thousands." - Lycia, the Heretic'),
(1834, 'UniqueRing76', 54171, 'Innocence rose to godhood not on inspired faith,' || char(13) || '
but on the vilification and hatred of another.'),
(1835, 'UniqueHelmetStr11', 54003, 'An eye for an eye makes the whole world dead.'),
(1836, 'UniqueAmulet73', 35517, 'Beidat made false promises to many denizens,' || char(13) || '
converting only one into a conduit through' || char(13) || '
which Wraeclast might be consumed.'),
(1837, 'UniqueJewel177', 43941, 'The spirits of our ancestors guided us from the Archipelago to the continent.' || char(13) || '
Inextricably, the purity of our souls is linked to the ones who came before us.'),
(1838, 'UniqueGlovesDexInt20', 37884, 'The fundamental forces of our world are secrets' || char(13) || '
to be uncovered by the intelligent and the capable.' || char(13) || '
Like all secrets, they, too, can be stolen.'),
(1839, 'UniqueBow24', 11731, '"I loosed a volley of arrows into the heart of the man' || char(13) || '
who slew my beloved. There was no satisfaction, no' || char(13) || '
healing, no revenge. There was only... emptiness."' || char(13) || '
- Chieftainess Ahuana of the Ramako Tribe'),
(1840, 'UniqueBow25', 12610, 'Fear flies by night,' || char(13) || '
a bone, cold as death,' || char(13) || '
all that remains' || char(13) || '
of hope''s whisper.'),
(1841, 'UniqueBow26', 50377, '"So long as a single flame flickers, our akhara lives.' || char(13) || '
And when there is nothing left to give to the fire,' || char(13) || '
we shall burn the enemy for warmth!"' || char(13) || '
- Varashta, the Winter Sekhema'),
(1842, 'UniqueBow27', 55166, '"Hope? There is no such thing! We are all rotting flesh,' || char(13) || '
stuck here on this world to torture each other. Hope' || char(13) || '
is a mistake, and we will show you its folly."' || char(13) || '
- Batoor, of the Afarud'),
(1843, 'UniqueBelt45', 5026, '"A man confronted with sufficient adversity' || char(13) || '
may ascend to unprecedented heights' || char(13) || '
and triumph over his coddled rivals."' || char(13) || '
- Weylan the Ezomyte'),
(1844, 'UniqueGlovesStrDex15', 60112, 'There is no greater thrill than leaping into combat,' || char(13) || '
slashing and hewing with utmost abandon.'),
(1845, 'UniqueBootsDex15', 62814, 'The inferno surged past, devastating Stridevolf, but the Maraketh' || char(13) || '
warrior somehow remained. Soot-blackened and resolute, she' || char(13) || '
grinned. In that moment, the bandit king knew true despair.'),
(1846, 'UniqueJewel178', 12387, 'At the core of the warrior''s spirit,' || char(13) || '
a fierce determination burns,' || char(13) || '
igniting their capacity to endure.'),
(1847, 'UniqueBodyStrInt15', 33555, 'Seek not to avoid the mortal pains of this world.' || char(13) || '
In flagellation, there lies freedom from temptation.'),
(1848, 'UniqueRing77_', 15007, '"Slay my twin and I will inherit her wisdom.' || char(13) || '
Slay me and her life will be prolonged by my demise.' || char(13) || '
Our souls are eternally bound by the sacrifices we have made."' || char(13) || '
- High Priest Atazek'),
(1849, 'UniqueAmulet74', 7699, '"Atziri ordained that we exploit the weaknesses inherent in our slaves.' || char(13) || '
With relish, we did exactly as she instructed."' || char(13) || '
- Guatelitzi, Architect of Flesh'),
(1850, 'UniqueBelt46', 63819, '"Put your faith in me.' || char(13) || '
Our god demands it."' || char(13) || '
- High Templar Maxarius'),
(1851, 'UniqueHelmetStrDex10', 33931, 'As the fiery remnants of our outpost were subsumed into the caldera,' || char(13) || '
a thunderous voice echoed across the barren landscape,' || char(13) || '
"Your fragility is your folly. May others rise where you have fallen."' || char(13) || '
- El''Abin, Bloodeater'),
(1852, 'UniqueStaff32', 33710, 'For their mortal allies, the last Titans forged a mighty staff,' || char(13) || '
one that could safely hold the first unearthed virtue gem.'),
(1853, 'UniqueOneHandSword34', 38712, 'Its forging marked the melding of man' || char(13) || '
and Titan against the rising darkness.'),
(1854, 'UniqueBootsStr13', 50294, 'Confidence is calm and measured.'),
(1855, 'UniqueBelt47', 57819, 'For centuries, he burned in an unending' || char(13) || '
nightmare of lava and flame... but he endured.'),
(1856, 'UniqueHelmetDexInt17', 31225, 'Fight in the traditional Way, or not at all!'),
(1857, 'UniqueTwoHandSword15', 35320, 'In the shifting reflections of the sea, the truth of the soul can be seen.'),
(1858, 'UniqueQuiver20', 45111, 'The last Queen of the Karui gave up power willingly.'),
(1859, 'UniqueShieldDex9', 53019, 'Not even the storm knows when lightning will strike.'),
(1860, 'UniqueRing78', 7037, 'The soul still beats, even when the heart never did.'),
(1861, 'UniqueAmulet75', 36011, 'Even the loneliest of souls can aid a friend in times of darkness.'),
(1862, 'UniqueSceptre25', 58134, 'What we give to others, we also give to ourselves.'),
(1863, 'UniqueSceptre25x', 59855, '"And so it begins. Someone,' || char(13) || '
somewhere, is trying again...' || char(13) || '
seems mankind never learns."'),
(1864, 'UniqueBodyStr13', 35780, 'The world will end in a divine stomach once Kitava has eaten all that lives.'),
(1865, 'UniqueBelt48', 47752, 'Knowing what will happen' || char(13) || '
and knowing when it will happen' || char(13) || '
are two very different things.'),
(1866, 'UniqueAmulet76', 7462, 'The farmer was struck again and again, but he refused to stay down.' || char(13) || '
Astonished, the raiding warlord ordered the man''s family spared.'),
(1867, 'UniqueRing79', 26363, 'The respect of Karui warriors is hard to earn,' || char(13) || '
but lasts a lifetime... and beyond.'),
(1868, 'UniqueJewel179', 11200, 'The story of a life, written in blood and ink.'),
(1869, 'UniqueJewel180_', 32130, 'At their height, the Vaal glittered under the sun.' || char(13) || '
A decade, a century, an aeon of prosperity...' || char(13) || '
now nothing more than a passing wonder.'),
(1870, 'UniqueAmulet77', 14977, 'Geomancy offered a safer way to use the Tears...' || char(13) || '
but most Maji rejected that temptation as well.'),
(1871, 'UniqueBodyStr14', 1079, 'The Maji were forbidden from touching virtue gems...' || char(13) || '
so their practical warriors employed geomancy instead.'),
(1872, 'UniqueStaff33', 46529, 'Nothingness is loathe to relinquish its grip.' || char(13) || '
Every moment is a struggle to exist.'),
(1873, 'UniqueJewel181', 50004, 'Faith given under false pretenses still carries the same power.'),
(1874, 'UniqueHelmetStrDex11', 36605, 'The Raven Trickster made no move to defend himself.' || char(13) || '
He merely grinned... and the foolish warrior charged.'),
(1875, 'UniqueOneHandSword35', 38299, 'It need not know your True Name. Our most' || char(13) || '
dearly held secrets spill forth in our blood.'),
(1876, 'UniqueShieldStrDex9', 36875, 'The Wildwood was a gift, meant as a haven' || char(13) || '
against the Winter of the World.'),
(1877, 'UniqueRing80', 53012, 'Chaos offers possibility, not outcome.' || char(13) || '
Our own imaginations ensnare us.'),
(1878, 'UniqueBootsStrDex9', 59009, 'All your tomorrows lie ahead of you,' || char(13) || '
unknown and snarled to the very last.'),
(1879, 'UniqueBodyInt3x', 37809, '"Researcher Graven''s request to wear Prototype #2998 in' || char(13) || '
place of his standard lab attire is... granted."' || char(13) || '
- Lead Researcher Ksaret'),
(1880, 'UniqueAmulet57x', 63662, '"I stood upon the tower''s edge, and saw that we had cracked the sky.' || char(13) || '
There is nowhere we can run that our sins will not find us now."' || char(13) || '
- Researcher Arn, last recorded words'),
(1881, 'UniqueFlask19x', 43943, '"Nobody will listen to me, because I''m the only one that sees it.' || char(13) || '
Nothing left to do now but drink until this world makes sense."' || char(13) || '
- Researcher Graven'),
(1882, 'UniqueBodyDex1x', 41472, '"Yes, a catastrophic storm erupted, and yes, they screamed for me' || char(13) || '
to stop the experiment... but you know how I am with screams."' || char(13) || '
- Researcher Olesya, on #2999 and the loss of Outpost Eight'),
(1883, 'UniqueCorruptedJewel16x', 5825, '"Release the type Delta test subjects. Unseal all prototype lockers.' || char(13) || '
Arm yourself! I know that, as researchers, you''ve never had to fight' || char(13) || '
before, but they''re coming to kill us all. It''s resist or die!"' || char(13) || '
- Lead Researcher Ksaret, two hours post-Incident'),
(1884, 'UniqueCorruptedJewel17x', 12223, '"Our defenses are failing at Outpost One. We can''t hold out much' || char(13) || '
longer. All outposts, abandon your stations! Escape while you can!"' || char(13) || '
- Lead Researcher Ksaret, three hours post-Incident'),
(1885, 'UniqueCorruptedJewel18x', 65272, '"The suppression troops have stopped responding to my orders.' || char(13) || '
I''m no longer in charge, and I likely never truly was... I suspect' || char(13) || '
they''re already coming for us."' || char(13) || '
- Lead Researcher Ksaret, one hour post-Incident'),
(1886, 'UniqueHelmetDex2x', 32288, '"The storm... that lightning... I''d be dead if I hadn''t...' || char(13) || '
but it was cold. Ice cold! It''s not what we think, and' || char(13) || '
the plan won''t work! Where''s Arn?! I have to tell him!"' || char(13) || '
- Researcher Graven, infirmary report'),
(1887, 'UniqueAmulet31x', 35247, '"I touched #2993, and I saw... how blind we''ve been. The visions' || char(13) || '
weren''t the future. They were the past! Our ''unforeseen' || char(13) || '
consequences'' have already been happening!"' || char(13) || '
- Researcher Graven'),
(1888, 'UniqueBodyInt22', 14721, 'When I finally rejected my faith entirely, my stagnant belief' || char(13) || '
became thick white blood, as choking as it was nourishing.'),
(1889, 'UniqueHelmetStrDex12', 18274, 'The Decay infects thought itself, leaving nothing' || char(13) || '
but hollow husks filled with virulent void...'),
(1890, 'UniqueBootsStr14', 12699, 'Where he tread, disintegrating storms of lightning' || char(13) || '
and death laid waste to all around him.'),
(1891, 'UniqueWand21', 44448, 'In a time of darkness, know that the Draíocht will bring you light.'),
(1892, 'UniqueHelmetStrInt22', 39031, 'There is power in hunger, though it will' || char(13) || '
consume all that you have... and more.'),
(1893, 'UniqueBelt49', 43696, 'There is an ebb and flow to all things,' || char(13) || '
tangible to those who watch and wait.'),
(1894, 'UniqueGlovesStr13', 9411, 'Forged from the heart of the densest star,' || char(13) || '
your courage will fail long before it does.'),
(1895, 'UniqueAmulet78', 40654, 'He who stands on the loftiest peak is bound to be seen...'),
(1896, 'UniqueBelt50', 3475, '"I come from a long line of scholars, poets, and artists.' || char(13) || '
You can imagine how little we leave our children...' || char(13) || '
My father only gifted me one thing: for good or ill,' || char(13) || '
I don''t know when to quit."' || char(13) || '
- Victario Nevalius, the People''s Poet'),
(1897, 'UniqueGlovesStrInt13', 4777, 'To drive back the darkness, to bring peace,' || char(13) || '
we must fight side by side as brothers.'),
(1898, 'UniqueBootsDexInt13', 29243, '"Follow me if you desire better for yourself, and for your' || char(13) || '
families. Follow me if you hunger for more than this!"'),
(1899, 'UniqueRing81', 10267, 'The first Grattus patriarch had only one tell. When he' || char(13) || '
slowly turned his ring, all cowered before him.'),
(1900, 'UniqueJewel182', 33938, 'It was more than luck that allowed the Perandus line' || char(13) || '
to turn even great misfortunes into golden opportunities.'),
(1901, 'UniqueJewel183_', 36810, 'To name a thing is to give it power.'),
(1902, 'UniqueShieldStr14', 27277, 'The priests found the Great Shield the night it fell to Middengard,' || char(13) || '
but it was the smiths who delved into the secrets it held.'),
(1903, 'UniqueTwoHandSword16', 36314, 'Green-cloaked travelers emerged from the mists, planted a tree,' || char(13) || '
and named it Lorrata. Its strongest root became a weapon...'),
(1904, 'UniqueTwoHandSword17_', 40604, '"He speaks, he leads, he stands tall...' || char(13) || '
yet, what has he truly done, save' || char(13) || '
spill our blood in pursuit of power?"'),
(1905, 'UniqueTwoHandSword18', 36711, '"This blade, which once tasted the green ichor of Kulemak himself, is now' || char(13) || '
anathema to all life. Piece by piece, we shall steal back what we are owed..."' || char(13) || '
- Sak, of the Afarud'),
(1906, 'UniqueTwoHandSword19', 46434, '"To the Children of Winter, the Sun was but a myth. While Lundara held Kulemak' || char(13) || '
impaled, Solerai struck - not at him, but upwards. Her blade pierced the heavens,' || char(13) || '
and searing light embraced her golden armour. The Sun was real, and it was her."'),
(1907, 'UniqueGlovesStr14', 33007, '"The long and venerable lineages of the Oriathan nobility tended' || char(13) || '
to produce Admirals with, shall we say... quick tempers."'),
(1908, 'UniqueGlovesStr15', 29478, 'The Cyclops of Trarthus became the star' || char(13) || '
of the Oriath Arena, but he was merely' || char(13) || '
biding his time, waiting for his chance...'),
(1909, 'UniqueTwoHandMace13', 20362, 'Strike with the might of a falling oak,' || char(13) || '
and know that you never stand alone.'),
(1910, 'UniqueHelmetStr12', 56250, 'Kaom ordered the desecration of the Empire''s dead.' || char(13) || '
There would be no rest or honours for the wicked.'),
(1911, 'UniqueHelmetStrInt25', 47429, '"I don''t judge who you are, Saresh. I judge what you do. True leadership' || char(13) || '
comes from fighting alongside those you command, from elevating them,' || char(13) || '
and sharing the glory of victory. This, you will never understand."' || char(13) || '
- Sekhema Orbala, to be crowned Garukhan'),
(1912, 'UniqueBelt51', 27838, 'When all else was burning and overrun,' || char(13) || '
she held the bridge to the very end.'),
(1913, 'UniqueOneHandMace12', 58944, 'Truly great Artificers push the boundaries of the possible.'),
(1914, 'UniqueStaff34', 64386, 'WIP'),
(1915, 'UniqueTincture1', 29067, 'Life and death dance ever closer,' || char(13) || '
waiting only for the right moment.'),
(1916, 'UniqueTincture2_', 14516, 'The liquid within boils and fumes,' || char(13) || '
ready to erupt at any provocation.'),
(1917, 'UniqueTincture3', 60287, 'New life will follow, but first come the flames.'),
(1918, 'UniqueTincture4_', 15543, 'The struggle for balance never ends.'),
(1919, 'UniqueTincture5', 15772, 'A virulent brew of death and decay.'),
(1920, 'UniqueAtlasRelic1', 47819, '[DNT]'),
(1921, 'UniqueAtlasRelic2', 32459, '[DNT]'),
(1922, 'UniqueAtlasRelic3', 12209, '[DNT]'),
(1923, 'FragmentUniqueAmulet1_1', 61034, 'Perfect knowledge is only possible in an empty universe.'),
(1924, 'FragmentUniqueAmulet1_2', 10085, 'When hunger can never be satiated, the' || char(13) || '
act of eating becomes the only solace.'),
(1925, 'FragmentUniqueAmulet1_3', 27115, 'The future holds infinite promise... as does she.'),
(1926, 'FragmentUniqueAmulet1_4', 9926, 'All that is will one day come to naught.'),
(1927, 'UniqueRing82', 53970, 'I will build the wall that stands against the tide.' || char(13) || '
The day is coming... I have seen it.'),
(1928, 'UniqueRing83', 36067, 'In truth, they point the finger at themselves.'),
(1929, 'UniqueRing84', 18459, 'And when you are no longer useful, you will' || char(13) || '
discover how much you truly mean.'),
(1930, 'UniqueRing85', 18186, 'Quiet thy troubled soul. Think not. Just pray... to me.'),
(1931, 'UniqueMapRelicEyeoftheDjinn', 25676, 'The Order never lost sight of their mission, no matter the cost.'),
(1932, 'UniqueMapRelicLoneAdventurer', 18839, 'Travelling alone makes one an easier target?' || char(13) || '
I believe not.' || char(13) || '
Travelling alone keeps one free of distraction.'),
(1933, 'UniqueMapRelicTwistofFate', 39579, 'The landscape twists before your eyes, morphing into realms of unspeakable horror.'),
(1934, 'UniqueMapRelicWellspringofCreation', 946, 'The waters of life roil and flow,' || char(13) || '
birthing horrors of flesh and marrow.'),
(1935, 'UniqueMapRelicDanceofDestruction', 64231, 'Atlassian aberrations engage in a deadly dance.' || char(13) || '
Will you be joining them in the fray?'),
(1936, 'UniqueMapRelicSingularFocus', 35947, 'You fancy yourself a god. You see only what you want to see.'),
(1937, 'UniqueMapRelicEldritchGaze', 23344, 'You were drunk on the power of the cosmos,' || char(13) || '
until a hideous gaze settled upon you,' || char(13) || '
and tendrils began to unfurl...'),
(1938, 'UniqueMapRelicWrathoftheCosmos', 54083, 'A fiery dawn illumines the horizon, and it becomes apparent that all that glitters is not gold...'),
(1939, 'UniqueMapRelicShadowShaping', 906, 'In lieu of happiness, sometimes the absence of pain is good enough.'),
(1940, 'UniqueMapRelicExtremeArchaeology', 56254, 'Verisium is often found in a recent crater. Properly refined, it can easily make another.'),
(1941, 'UniqueMapRelicCropRotation', 57828, 'A good sword is worthless without a hundred plowshares behind it.'),
(1942, 'UniqueMapRelicTimelessConflict', 7672, 'Haste is irrelevant in the face of eternity.'),
(1943, 'UniqueMapRelicUnendingNightmare', 26384, 'What if it''s all just in your head?'),
(1944, 'UniqueMapRelicImmutableDogma', 33445, 'Do not doubt. Do not question.' || char(13) || '
This is the way it has always been.' || char(13) || '
This is the way it shall always be.'),
(1945, 'UniqueMapRelicArbitraryTenets', 55696, 'They are unforgivable sinners and fools...' || char(13) || '
We pray each Sacrato. They pray each Kaso.' || char(13) || '
They are absolutely mad!'),
(1946, 'UniqueMapRelicEndlessTide', 19803, 'You fight on, muscles burning, limbs leaden,' || char(13) || '
hoping for that singular moment of victory that' || char(13) || '
might finally bring relief... but it never comes.'),
(1947, 'UniqueMapRelicSpeakeroftheDead', 32751, 'For nine hundred years, they have had no voice, no hope.' || char(13) || '
Finally, they have found a kindred soul... in you.'),
(1948, 'UniqueMapRelicCassia''sPride', 17509, 'She''ll certainly never give you credit now.'),
(1949, 'UniqueMapRelicMeticulousAppraiser', 22620, 'Within every treasure can be found shades of gold, should one have the patience to look.'),
(1950, 'UniqueMapRelicLucidDreams', 47054, 'Shattered fragments of reality float through the void,' || char(13) || '
waiting to be shaped by your mind''s desire.'),
(1951, 'UniqueMapRelicDestructivePlay', 33225, 'She makes the rules up as she goes.' || char(13) || '
It was never going to be fair.'),
(1952, 'UniqueMapRelicBoldUndertakings__', 53490, 'Fortune will rain upon those who bring humour to Chaos.'),
(1953, 'UniqueMapRelicGruellingGauntlet', 51604, 'Chaos smiles upon those who leave their Fate to chance.'),
(1954, 'UniqueMapRelicRuinousWager', 25620, 'There are many ways to win... and many ways to lose.'),
(1955, 'UniqueMapRelicRefinersBargain', 28340, 'No form is forged without forfeit.'),
(1956, 'UniqueMapRelicThoroughExploration_', 47514, 'The mists of the Atlas offer up that which you' || char(13) || '
most desire... so long as you never leave.'),
(1957, 'UniqueMapRelicSmashAndGrab', 63857, 'An army won''t notice their supplies have been raided until after the battle.'),
(1958, 'UniqueMapRelicEssenceBoss', 59797, 'Fracturing crystals here seems to make them stronger elsewhere.'),
(1959, 'UniqueRelicWellSupplied', 35474, 'When the armory is full there is more to go around.'),
(1960, 'UniqueRelicPerceivedGreatness', 10312, 'A treasure is only as valuable as you think it to be.'),
(1961, 'UniqueRelicTwistedWish', 17057, 'Control comes at a price.'),
(1962, 'IncursionVialTrap', 38560, 'Blood, slaves and stone.' || char(13) || '
The timeless edifice of Dominance.'),
(1963, 'IncursionVialHealing', 39047, 'Call to place the demon gods of the past.'),
(1964, 'IncursionVialPoison', 8264, 'The eyes of Apep flicker open and the Poisoned One stirs.'),
(1965, 'IncursionVialLightning', 42231, 'The ritual creates order. ' || char(13) || '
Both in the minds of men and gods. ' || char(13) || '
The ritual creates order.'),
(1966, 'IncursionVialFire', 62449, 'Ancient myths of flame, frost and thunder.' || char(13) || '
Will we ever know the way forward?'),
(1967, 'IncursionVialMinion', 2241, 'Your actions live but a moment;' || char(13) || '
their repercussions never die.'),
(1968, 'IncursionVialBossFlask', 35194, 'With great tragedy and power,' || char(13) || '
the dead are netted in anguish.'),
(1969, 'IncursionVialBossJewel', 26291, 'It is not our flesh, our thoughts, or our soul that limits us;' || char(13) || '
it is the distinction between them.'),
(1970, 'IncursionVialBossAmulet', 43908, 'Festivities of blood. Bleeding hearts and screaming lungs.'),
(1971, 'TrialMasterFragment1', 39989, 'They took pride in all that they built, considering each new' || char(13) || '
temple a testament to the gods... and then, to themselves.'),
(1972, 'TrialMasterFragment2', 56244, 'Delving into the mysteries of existence, they deciphered' || char(13) || '
the secret laws of nature... and then, harnessed them.'),
(1973, 'TrialMasterFragment3', 48275, 'Not content to live in harmony with the world, they strove' || char(13) || '
to understand it, to improve it... and then, to master it.'),
(1974, 'TrialMasterFragment4', 62176, 'They collaborated with each other and with nearby peoples,' || char(13) || '
at first sharing, teaching... and then, dominating.'),
(1975, 'ScarabBreach1', 13223, 'The Ember-dwellers sought to throw you to their volcanic god, young Omid,' || char(13) || '
but we caught you instead. The Order of the Djinn is your tribe now.'),
(1976, 'ScarabBreach2', 13085, 'We task you, honoured Omid, with the investigation of this mysterious' || char(13) || '
''Xoph'' and artefacts related to rifts in the boundaries of our world.'),
(1977, 'ScarabBreach3', 19684, 'Omid, Master Researcher, has left a final commandment upon his death:' || char(13) || '
the world must never know.'),
(1978, 'ScarabBreach4', 6654, 'The Master Researcher''s final commandment has failed.' || char(13) || '
The High Templar has seen the truth of our situation,' || char(13) || '
and the world will be undone by his fear.'),
(1979, 'ScarabMaps1', 47293, 'Consider yourself an orphaned Eternal no longer, young Betucia.' || char(13) || '
The Order of the Djinn is your family now.'),
(1980, 'ScarabMaps2', 61491, 'For your loyalty and valour, honoured Betucia, we are proud to put' || char(13) || '
the requisition of dream-artefacts in your capable hands.'),
(1981, 'ScarabMaps3', 22104, 'Betucia, Bearer of the Sealing Blade, the Order of the Djinn survives' || char(13) || '
because of your sacrifice, but will be forever wounded by your loss.'),
(1982, 'ScarabMaps4', 15237, 'The Sealing Blade has been removed, and the agent of Decay' || char(13) || '
shall feed upon this world until nothing remains but dust.'),
(1983, 'ScarabUniques1', 21386, 'The Maraketh left you to die alone in the desert, young Sumei, but we' || char(13) || '
saw the potential in you. The Order of the Djinn is your akhara now.'),
(1984, 'ScarabUniques2', 6365, 'As the best of our lorekeepers, honoured Sumei, it is now your task' || char(13) || '
to investigate the mysterious duplication of artefacts of power.'),
(1985, 'ScarabUniques3', 7891, 'Go to your rest now, Sumei, Master Lorekeeper. The Order shall keep' || char(13) || '
contained the terrible secret that burdened your final years.'),
(1986, 'ScarabUniques4', 25240, 'The books were burned, and the scribes set themselves aflame.' || char(13) || '
What secret so terrible could they have discovered?' || char(13) || '
Though centuries have passed, we must investigate this for ourselves.'),
(1987, 'ScarabBeasts1', 61327, 'Feuding Ezomytes slaughtered your kin, young Agnar, but we pulled you' || char(13) || '
from the flames. The Order of the Djinn is your clan now.'),
(1988, 'ScarabBeasts2', 2729, 'None among us understand the beasts of this world better than you,' || char(13) || '
honoured Agnar. You will root out the mysteries of wild-artefacts.'),
(1989, 'ScarabBeasts3', 34038, 'The Order was your clan in life, Agnar, Beastmaster, but the First Ones call' || char(13) || '
back their favoured son. The gift of their Visions will pass to another.'),
(1990, 'ScarabBeasts4', 10963, 'Without an experienced Beastmaster to find them new realms,' || char(13) || '
the First Ones'' ravaging hunt brings them ever closer to Wraeclast.'),
(1991, 'ScarabBeasts4a', 46550, 'Without an experienced Beastmaster to find them new realms,' || char(13) || '
the First Ones'' ravaging hunt brings them ever closer to Wraeclast.'),
(1992, 'ScarabBeasts4b', 345, 'Without an experienced Beastmaster to find them new realms,' || char(13) || '
the First Ones'' ravaging hunt brings them ever closer to Wraeclast.'),
(1993, 'ScarabBeasts4c', 16020, 'Without an experienced Beastmaster to find them new realms,' || char(13) || '
the First Ones'' ravaging hunt brings them ever closer to Wraeclast.'),
(1994, 'ScarabBeasts4d', 40223, 'Without an experienced Beastmaster to find them new realms,' || char(13) || '
the First Ones'' ravaging hunt brings them ever closer to Wraeclast.'),
(1995, 'ScarabShaperRares1', 50731, 'The Peak-dwellers saw you as impure, young Qianga, but the Order of' || char(13) || '
the Djinn sees you as all the stronger for your uniqueness.'),
(1996, 'ScarabShaperRares2', 16721, 'Bold dreamer, Qianga of the Stars, she of the Celestial Cold! These titles' || char(13) || '
we bestow upon the one among us whose soul speaks to the ineffable.'),
(1997, 'ScarabShaperRares3', 2825, 'Qianga of the Stars, Deliverer of the Sealing Blade to the Watchers, go now, and' || char(13) || '
let your half-dreamt life be troubled by nightmares of achromic hunger no more.'),
(1998, 'ScarabShaperRares4', 55217, 'The Watchers have gone silent, yet they scream still.' || char(13) || '
Something lurks among the stars of our dreams, knocking at the door,' || char(13) || '
whispering with the voices of long lost friends...'),
(1999, 'ScarabElderRares1_', 41471, 'Your visions led the Azmeri down into a world left abandoned by the Vaal.' || char(13) || '
They cast you out, young Egrin, but the Order of the Djinn accepts you.');
INSERT INTO "FlavourText" ("_row", "Id", "__col1", "Text") VALUES
(2000, 'ScarabElderRares2_', 8701, 'Speaker of unclean truths, Egrin of the Dark Between Stars.' || char(13) || '
We curse you whose soul echoes the madness of the void!'),
(2001, 'ScarabElderRares3', 15411, 'Egrin of the Dark Between Stars, Forger of the Sealing Blade,' || char(13) || '
let your name be redeemed by your unexpected sacrifice.'),
(2002, 'ScarabElderRares4', 55023, 'We are all equally fools for our childish notions.' || char(13) || '
That dread force Decay cannot be defeated by self-sacrifice.'),
(2003, 'ScarabSulphite1', 45622, 'As the first Brinerot to join the Order, you have much to prove,' || char(13) || '
young Raethan. We are confident you will succeed.'),
(2004, 'ScarabSulphite2', 47441, 'For harnessing and controlling the power of lightning, you, Raethan,' || char(13) || '
are now charged with researching this new energy.'),
(2005, 'ScarabSulphite3', 41731, 'Let him not be called Raethan the Betrayer. His discovery was too important' || char(13) || '
to keep locked away. Now, for good or ill, it is in civilisation''s hands.'),
(2006, 'ScarabSulphite4', 34574, 'Madness marches in machine form.' || char(13) || '
Harnessed lightning, grim faces, and cold ambition abounds.' || char(13) || '
Civilisation will be its own undoing.'),
(2007, 'ScarabDivinationCards1', 44847, 'You were a casualty of callous Karui warfare, ageless Narumoa, but the Order' || char(13) || '
mended your wounds. You are bound to us now by your own code.'),
(2008, 'ScarabDivinationCards2', 49602, 'Though your peers fear you, Narumoa, the elders have decided that your' || char(13) || '
second sight is ideal for handling all artefacts that seek to subvert Fate.'),
(2009, 'ScarabDivinationCards3', 48581, 'Your centuries of service have been invaluable to us, Narumoa. Go now,' || char(13) || '
return to Hinekora, and join your ancient kin in the halls of the dead.'),
(2010, 'ScarabDivinationCards4', 55612, 'Hinekora has sent the world another herald, but this hatungo walks another path.' || char(13) || '
We are left blinded, and subject to the vagaries of Fate.'),
(2011, 'ScarabTorment1', 31371, 'Young Tsarsk, you were a broken and forgotten child lying glassy-eyed' || char(13) || '
in a flesh-pit in Trarthus, but the Order found and cleansed you.'),
(2012, 'ScarabTorment2', 8521, 'Your tortured soul long kept you isolated from your peers, Tsarsk, but has attracted' || char(13) || '
new kindred in kind. You are tasked with appeasing these anguished spirits.'),
(2013, 'ScarabTorment3', 6143, 'Though you were swallowed by your own darkness, you saved countless others' || char(13) || '
from eternal misery, young Tsarsk. You were not nothing, as you feared.'),
(2014, 'ScarabTorment4', 36283, 'Without a speaker of the dead, the countless anguished spirits only grow in number.' || char(13) || '
They have no voice, and no hope. The sun darkens with each passing year.'),
(2015, 'ScarabStrongbox1', 9346, 'Your outlaw camp abandoned you when their surprise attack failed, young Rindwik.' || char(13) || '
Now that you know we exist, we cannot let you go. You have two choices.'),
(2016, 'ScarabStrongbox2', 45503, 'Your people were renegades, Rindwik, but you have proven your loyalty.' || char(13) || '
You will lead the martial defence of our expeditions.'),
(2017, 'ScarabStrongbox3', 9110, 'Master Warrior Rindwik fell to one opponent alone: old age.' || char(13) || '
Only the greatest soldiers can say as much.'),
(2018, 'ScarabStrongbox4', 37074, 'In the absence of a strong martial presence, the renegades rise once more.' || char(13) || '
Their poisons threaten to cloud the land.'),
(2019, 'ScarabHarbinger1', 10338, 'Your ancestry has been much maligned by history, young Sarina Titucius,' || char(13) || '
but to the Order of the Djinn, you are born anew.'),
(2020, 'ScarabHarbinger2', 8033, 'For deciphering the language of the inscrutable ones, honoured Sarina,' || char(13) || '
we charge you with investigating their intent in our land.'),
(2021, 'ScarabHarbinger3', 48409, 'For your valour beyond the Gate, Sarina Titucius, we honour you with the first' || char(13) || '
Gilded Scarab awarded while its recipient still lives. Remain vigilant.'),
(2022, 'ScarabHarbinger4', 40021, 'The thousand year truce has faltered, for the inscrutable ones have imprisoned their own God.' || char(13) || '
Should they invade again, there will be no warning.'),
(2023, 'ScarabHarbingerNew1', 19299, 'Their troops came in numbers uncountable and from lands unknown.'),
(2024, 'ScarabHarbingerNew2', 27516, 'They seek to establish an unknown pattern.'),
(2025, 'ScarabHarbingerNew4', 47190, 'For those who can leverage it, war can be as much a machine of profit as it is death.'),
(2026, 'ScarabHarbingerNew3', 2504, 'The truly noble wage war from the front.'),
(2027, 'ScarabPerandus1', 27650, 'Your people no longer walk this continent, young Revna,' || char(13) || '
but the Order of the Djinn will give you a new home.'),
(2028, 'ScarabPerandus2', 33168, 'As you delve into the mysteries of this world, apprentice Revna,' || char(13) || '
remember to learn from the past, not be consumed by it.'),
(2029, 'ScarabPerandus3', 13422, 'We lay you to rest in the forest deep, Runesmith Revna, so that you may be' || char(13) || '
forever hidden from the stars which so terrified you in your final days.' || char(13) || '
May the secret you took to your grave be lifted from your burdens.'),
(2030, 'ScarabPerandus4', 6938, 'Darkness surges in the shadows of the past. Ancient evils stir. The stars' || char(13) || '
watch, forever aloof, forever menacing. None remain who know the' || char(13) || '
secret, so we are defenseless in the face of the unknown.'),
(2031, 'ScarabLegion1', 61093, 'Your faith and our Order are not in opposition, young Eutychus. ' || char(13) || '
Let this be the start of a new era of cooperation.'),
(2032, 'ScarabLegion2', 39598, 'As our hand in the Chamber, we grant you, Deacon Eutychus,' || char(13) || '
access to a domain we lack the resources to explore.'),
(2033, 'ScarabLegion3', 25341, 'Given the fate of Deacon Eutychus and the men under Cardinal Sanctus Vox,' || char(13) || '
let none dare the Domain, lest they too feed that vile hunger eternal.'),
(2034, 'ScarabLegion4', 48934, 'As the passage between Wraeclast and the land beyond time''s reach is torn open,' || char(13) || '
we stand on the precipice of eternal war.' || char(13) || '
And no one remains to hold us back.'),
(2035, 'ScarabMetamorph1', 8414, 'We pulled you from the piled dead, young Ixchel, while your people were going mad' || char(13) || '
with fear. The gods may have vanished, but the Order will watch over you now.'),
(2036, 'ScarabMetamorph2', 49161, 'For infiltrating the Priesthood of Yaomac and returning with their sleeping form,' || char(13) || '
Ixchel, we honour you. Your next task must be to infiltrate the Temple of Chaos.'),
(2037, 'ScarabMetamorph3', 37770, 'It was our error, Ixchel Godstealer, that led to your fate. Chaos is not asleep,' || char(13) || '
thus not a god, and for your eternal suffering, you have our eternal remorse.'),
(2038, 'ScarabMetamorph4', 47559, 'The silent war of shadows and struggle must be set aside.' || char(13) || '
Order and Chaos must ally against the coming tide. '),
(2039, 'ScarabBlight1', 31553, 'We pulled you from the raging ocean, young Dhunan,' || char(13) || '
but we cannot return you to your home. The Order of the Djinn' || char(13) || '
offers you a place on Wraeclast.'),
(2040, 'ScarabBlight2', 63977, 'For using the techniques of your homeland to contain' || char(13) || '
the fungal plague, honoured Dhunan, you shall lead the war' || char(13) || '
to eliminate it and end the century-cycle of infestation.'),
(2041, 'ScarabBlight3', 43470, 'Be at rest, Blightmaster Dhunan, on the distant shores of' || char(13) || '
your home. A dangerous expedition, but one worthy for' || char(13) || '
he who gave his life to cleanse Wraeclast.'),
(2042, 'ScarabBlight4', 8934, 'The fungal plague returns, and its roots have adapted.' || char(13) || '
The undiscovered Blightheart that Dhunan theorised' || char(13) || '
must still exist somewhere, yet none remain' || char(13) || '
with the skill to see to its destruction.'),
(2043, 'ScarabAbyss1', 34331, 'As the hordes of bone and blood and foul magic surge across the Vastiri Plains,' || char(13) || '
the scant survivors of our akhara agree to your alliance, ash-scarred Ahkeli.' || char(13) || '
Disorder means death. Order may mean life.'),
(2044, 'ScarabAbyss2', 15826, 'Your golems and your leadership have slowed the tide of death, Clayshaper.' || char(13) || '
The relics of power you bid us find have kept the Vastiri Plains from the brink' || char(13) || '
of oblivion. The defences of the Maraketh will hold.'),
(2045, 'ScarabAbyss3', 30772, 'The Winter of the World has ended at the hands of the Three Sisters. We lay this scarab' || char(13) || '
upon your ancient grave in thanks for your efforts, Honoured Founder. As you hoped,' || char(13) || '
the fate of your people will never befall another.'),
(2046, 'ScarabAbyss4', 45163, 'The Abyssals creep forth by night and by storm. Their eons underground were not' || char(13) || '
a respite, but an amassing, and now they number beyond comprehension.'),
(2047, 'MapWorldsLookout', 48831, 'A glorious vista once exclusive' || char(13) || '
to emperors. Not anymore.'),
(2048, 'MapWorldsBeach', 62685, 'A paradise, forever replenished by' || char(13) || '
endless waves teeming with life.'),
(2049, 'MapWorldsGraveyard', 53902, 'Unknown legacies.' || char(13) || '
Untold stories.'),
(2050, 'MapWorldsDungeon', 64256, 'A penitentiary for those who are not penitent' || char(13) || '
is nothing more than an inn for the evil.'),
(2051, 'MapWorldsAlleyways', 42968, 'An unwashed gutter, where wretches' || char(13) || '
cut purses and throats alike.'),
(2052, 'MapWorldsPen', 19828, 'Slaves held like cattle. A blood-soaked' || char(13) || '
revolution, just waiting to happen.'),
(2053, 'MapWorldsDesert', 34997, 'Heat. Dust. Wind. These are what' || char(13) || '
forge strong minds and bodies.'),
(2054, 'MapWorldsAridLake', 27782, 'Water vanishes; an impromptu' || char(13) || '
prison becomes a tomb.'),
(2055, 'MapWorldsFloodedMine', 63065, 'In darkness, beast and man' || char(13) || '
alike clamour to survive.'),
(2056, 'MapWorldsMarshes', 42115, 'Embraced by mud. Grasped by roots.' || char(13) || '
The careless are silently swallowed.'),
(2057, 'MapWorldsIceberg', 59084, 'Icy fangs seek tender hulls' || char(13) || '
to sink themselves into.'),
(2058, 'MapWorldsCage', 3883, 'Treat a man like a wild animal,' || char(13) || '
and he will soon learn to bite.'),
(2059, 'MapWorldsSprings', 34425, 'The water brings life,' || char(13) || '
the poison takes it away.'),
(2060, 'MapWorldsExcavation', 33025, 'Two unexplored frontiers remain:' || char(13) || '
The skies and the soil.'),
(2061, 'MapWorldsLeyline', 12937, 'Amidst the barren wastes,' || char(13) || '
a slender strand of life blooms.'),
(2062, 'MapWorldsPeninsula', 57690, 'The farmer no longer plows' || char(13) || '
or sows. Only the flattened' || char(13) || '
soil remains.'),
(2063, 'MapWorldsPort', 47088, 'The wealthy foolishly battle' || char(13) || '
the ocean for domain.'),
(2064, 'MapWorldsBurialChambers', 43016, 'Vile fiends hide beneath' || char(13) || '
the peaceful plains.'),
(2065, 'MapWorldsCells', 3775, 'Life crushed together.' || char(13) || '
Left to crumble to dust.'),
(2066, 'MapWorldsArcade', 44259, 'We create so that some part' || char(13) || '
of us may remain after death.'),
(2067, 'MapWorldsCitySquare', 44762, 'Countless generations have' || char(13) || '
walked these time-worn stones.'),
(2068, 'MapWorldsRelicChambers', 35162, 'Relics of a forbidden past.' || char(13) || '
Hidden away. Forgotten.'),
(2069, 'MapWorldsCourthouse', 49777, 'Justice born of love is a surrender.' || char(13) || '
Justice born of law is a punishment.'),
(2070, 'MapWorldsStrand', 10021, 'Nothing good washes up' || char(13) || '
on this dark shore.'),
(2071, 'MapWorldsStrandUnique', 62531, 'We all began life in darkness,' || char(13) || '
we shall all end it there.'),
(2072, 'MapWorldsChateau', 39459, 'Beauty and brutality in such close proximity.'),
(2073, 'MapWorldsChateauUnique', 11413, 'Forget kings and emperors;' || char(13) || '
He who holds the coin holds all the power.'),
(2074, 'MapWorldsGrotto', 19420, 'Trapped in absolute darkness.' || char(13) || '
Despair. Panic. Terror.'),
(2075, 'MapWorldsGorge', 4592, 'We must all walk the narrow, winding path.' || char(13) || '
The end is always the same.'),
(2076, 'MapWorldsVolcano', 30639, 'Tremble in the might of the flames.'),
(2077, 'MapWorldsLighthouse', 43308, 'Fire ignites the sky.' || char(13) || '
A signal to keep away.' || char(13) || '
An invitation to invade.'),
(2078, 'MapWorldsCanyon', 2336, 'A deep wound in the land.' || char(13) || '
One that will never heal.'),
(2079, 'MapWorldsConservatory', 6755, 'Ornate, elaborate, ostentatious...' || char(13) || '
and dripping with death.'),
(2080, 'MapWorldsSulphurVents', 6074, 'The creatures that prowl the wildest extremes,' || char(13) || '
nature anoints with cruel efficacy to defend her.'),
(2081, 'MapWorldsHauntedMansion', 1215, 'Forlorn and sorrowful, this once opulent' || char(13) || '
ruin conceals the sins of a fallen line.'),
(2082, 'MapWorldsMaze', 46524, 'They live trapped forever in darkness' || char(13) || '
and confusion. We are no different.'),
(2083, 'MapWorldsMazeUnique', 39980, 'We are ever the makers of our own undoing.'),
(2084, 'MapWorldsChannel', 22278, 'The stone cannot stop the torrent.' || char(13) || '
It can only divert it.'),
(2085, 'MapWorldsToxicSewer', 25747, 'Affluence and effluence, separated' || char(13) || '
by a few feet of soil.'),
(2086, 'MapWorldsAncientCity', 2545, 'This was not the first' || char(13) || '
civilization to believe itself' || char(13) || '
the greatest. And it will' || char(13) || '
not be the last.'),
(2087, 'MapWorldsIvoryTemple', 16982, 'Man and nature intertwined,' || char(13) || '
but only for the chosen few.'),
(2088, 'MapWorldsSpiderLair', 60607, 'Panic only hastens the venom''s' || char(13) || '
passage to the heart.'),
(2089, 'MapWorldsBarrows', 49687, 'Man burrows for only' || char(13) || '
the eternal hibernation.'),
(2090, 'MapWorldsMausoleum', 57831, 'A vault for the dead, as if' || char(13) || '
they were valuable. Pathetic.'),
(2091, 'MapWorldsFields', 36207, 'They pleaded for the gods to bless their land.' || char(13) || '
Now they lie under the soil.'),
(2092, 'MapWorldsJungleValley', 4003, 'Verdant canopies shroud the world in darkness.'),
(2093, 'MapWorldsPhantasmagoria', 47634, 'Every movement is watched,' || char(13) || '
recorded, remembered.'),
(2094, 'MapWorldsAcademy', 54575, 'They came for enlightenment,' || char(13) || '
but were imprisoned by madness.'),
(2095, 'MapWorldsThicket', 737, 'Little light enters.' || char(13) || '
No life escapes.'),
(2096, 'MapWorldsWharf', 54239, 'Reach out into the abyss,' || char(13) || '
and the abyss reaches back.'),
(2097, 'MapWorldsAshenWood', 43927, 'Desperately reaching skyward' || char(13) || '
and digging downwards.' || char(13) || '
Sustenance is an' || char(13) || '
eternal struggle.'),
(2098, 'MapWorldsAtoll', 19776, 'Time turns even the vicious' || char(13) || '
volcanoes to hollow shells.'),
(2099, 'MapWorldsAtollUnique', 11929, 'Whispers from' || char(13) || '
a world apart' || char(13) || '
Speak my name' || char(13) || '
beyond the tomb;' || char(13) || '
Bound within' || char(13) || '
the Maelström''s heart,' || char(13) || '
Will they grant me' || char(13) || '
strength or doom?'),
(2100, 'MapWorldsCemetery', 12635, 'A stone forest of forgotten names.'),
(2101, 'MapWorldsCemeteryUnique', 11313, 'Some dead have long' || char(13) || '
envied the living.' || char(13) || '
When given the chance,' || char(13) || '
they take from us what they can.' || char(13) || '
So we offer our suffrage.' || char(13) || '
In return, they give' || char(13) || '
only suffering.'),
(2102, 'MapWorldsUndergroundSea', 18545, 'Silent stillness. The waters are' || char(13) || '
as cold as they are black.'),
(2103, 'MapWorldsTribunal', 5132, 'So much power in the hands of so few.'),
(2104, 'MapWorldsCoralRuins', 41363, 'Thrust above the waves, still teeming' || char(13) || '
with horrors from the depths.'),
(2105, 'MapWorldsLavaChamber', 7088, 'Fiend and fortune-hunter alike turned to ash.' || char(13) || '
A sorry alliance of unending agony.'),
