The rest fought bravely,' || char(13) || '
and died horrifically.'),
(2274, 'UniqueWatchstone2', 24463, 'They came, full of vim and vigour, to take what was not theirs.' || char(13) || '
They crashed and clamoured like waves against rocks,' || char(13) || '
and were swept back out to sea.'),
(2275, 'UniqueWatchstone3', 33811, 'The King''s Eye returned from the west.' || char(13) || '
Fertile pastures lay just beyond sight.' || char(13) || '
Just a little farther, he said.' || char(13) || '
It was always just a little farther.'),
(2276, 'UniqueWatchstone4', 63267, 'Nothing is more alluring than mystery.'),
(2277, 'UniqueWatchstone5', 37646, 'There exists in every man and woman' || char(13) || '
a desire to push boundaries, to break new ground,' || char(13) || '
to make great discoveries,' || char(13) || '
no matter the personal cost.'),
(2278, 'UniqueWatchstone6', 38443, 'Conflict begets only suffering.' || char(13) || '
For some, that is by design.'),
(2279, 'UniqueWatchstone7_', 18076, 'Does the belly swell, or the belt shrink?' || char(13) || '
To those caught between, there is no difference,' || char(13) || '
and something must soon give.'),
(2280, 'UniqueHelmetDex10', 40352, 'A moment of calm before the battle can end the war.'),
(2281, 'UniqueGlovesDexInt16_', 32857, 'Winter''s white blanket swaddles all.'),
(2282, 'UniqueBodyStr11', 52341, 'The Trickster God turned the very Day and Night against each other.' || char(13) || '
What hope have you?'),
(2283, 'UniqueRing65', 65231, 'The machines do not hate. They merely serve one who does.'),
(2284, 'UniqueJewel137', 23905, 'Savour the bitter, cherish the sweet,' || char(13) || '
For there may never be another chance to eat.'),
(2285, 'UniqueJewel138', 37320, '"Try as I might, I could not escape it.' || char(13) || '
When I closed my eyes, I saw only death.' || char(13) || '
Each breath tainted with the scent of seared and smouldering flesh,' || char(13) || '
And each sound tangled with pleas for mercy."'),
(2286, 'UniqueJewel139', 55534, 'You can take the girl out of the woods, ' || char(13) || '
but you can''t take the woods out of the girl.'),
(2287, 'UniqueJewel140', 11047, 'Pain is a fine motivator,' || char(13) || '
But if you seek the truth,' || char(13) || '
Fear of pain unknown has no parallel.'),
(2288, 'UniqueJewel141', 52282, 'As the dead battered Highgate''s barricades,' || char(13) || '
The Black Sekhema accepted her fate,' || char(13) || '
And stood her ground.'),
(2289, 'UniqueJewel142', 29148, 'Maids used to threaten to send misbehaving children of' || char(13) || '
nobility to the pits beneath the Grand Arena.' || char(13) || '
For the children of slaves, it was more than just a threat.'),
(2290, 'UniqueJewel143', 48860, 'Once you begin to rely on your weapons, ' || char(13) || '
You ensure you can''t live without them. '),
(2291, 'UniqueJewel144', 50375, 'It was a great honour to fight at the front. ' || char(13) || '
The few that survived the initial charge were guaranteed fame and fortune.'),
(2292, 'UniqueJewel145', 64979, 'You need not go looking for a second opinion.'),
(2293, 'UniqueJewel146', 52392, 'If you''re going to act like you''re better than everyone else, make sure you are.'),
(2294, 'UniqueJewel147', 44654, 'Only a madman would ignore a god''s instructions.'),
(2295, 'UniqueBootsAtlas1', 27895, 'Nothing spreads as quickly as an idea.'),
(2296, 'AfflictionFragment', 17312, 'How do you defeat that which dwells within you?'),
(2297, 'UniqueHelmetStr8', 33434, 'Bloodlust begets suffering.'),
(2298, 'UniqueRing66', 51155, 'Lightning lives in an endless circle.'),
(2299, 'UniqueAmulet61', 53128, 'WIP'),
(2300, 'UniqueGlovesDexInt17', 24945, '"We have methods of interrogation the Inquisitors only dream of."' || char(13) || '
- Marcus, Brotherhood Liaison'),
(2301, 'UniqueBodyStrInt14', 25680, '"This was the first step in some grand design, ' || char(13) || '
lost to the ages, now ours to decipher." ' || char(13) || '
- Dominus, High Templar'),
(2302, 'UniqueHelmetStrInt18', 32331, 'The Azmeri must never touch the Tears of Maji, lest Viridi weep.'),
(2303, 'UniqueHelmetStrInt18x', 52782, '"I believed I understood Prototype #112 quite fully, until a test subject' || char(13) || '
with Azmeri ancestry donned it. I will be haunted by the results' || char(13) || '
for the rest of my life."  - Researcher Graven'),
(2304, 'UniqueGlovesDex6', 46871, 'Under its influence, shards of metal take on a life of their own, wriggling into flesh,' || char(13) || '
burrowing into organs, and exploding outwards in search of other victims.'),
(2305, 'UniqueQuiver16', 49793, 'Claws open, brace for a bite. Stinger raised, dodge or die.'),
(2306, 'UniqueBodyInt20', 54764, 'Imbue the body with stolen spirit, hold the leash tight.'),
(2307, 'UniqueShieldStrInt13', 40776, 'Chitus'' success stemmed from his cunning, taking calculated' || char(13) || '
risks so that greater dangers could be averted.'),
(2308, 'UniqueAmulet62', 58003, 'An eye for an eye.'),
(2309, 'UniqueClaw19', 24377, 'The strong survive. The strongest thrive.'),
(2310, 'UniqueStaff25', 15272, 'The pyre is never wasted on just one heretic.'),
(2311, 'UniqueOneHandSword32', 58057, '<<HBGAf>><<HBG02>><<HBGAm>><<HBG03>><<HBGAa>>' || char(13) || '
<<HBGAk>><<HBG03>><<HBGC011>><<HBGAl>><<HBG03>><<HBGAo>><<HBGAe>>' || char(13) || '
<<HBGC011>><<HBGAa>><<HBG00>><<HBGC07>>'),
(2312, 'UniqueBelt36', 53380, '<<HBGAa>><<HBG02>><<HBGAr>><<HBG01>><<HBGAl>>' || char(13) || '
<<HBGAf>><<HBG02>><<HBGC01>><<HBG01>><<HBGAr>>' || char(13) || '
<<HBGAa>><<HBG02>><<HBGC02>><<HBG01>><<HBGAn>><<HBG03>><<HBGAf>>'),
(2313, 'UniqueShieldStrInt14', 50442, '<<HBGAa>><<HBG00>><<HBGAt>>' || char(13) || '
<<HBGAa>><<HBG04>><<HBGAp>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAn>><<HBG04>><<HBGC01>>' || char(13) || '
<<HBGAf>><<HBG02>><<HBGC05>>'),
(2314, 'UniqueQuiver17', 49993, '<<HBGAf>><<HBG02>><<HBGAt>><<HBG03>><<HBGAa>>' || char(13) || '
<<HBGAf>><<HBG02>><<HBGAm>><<HBGC011>><<HBGC04>>' || char(13) || '
<<HBGAa>><<HBG00>><<HBGAt>>'),
(2315, 'UniqueHelmetDexInt14', 23291, '<<HBGAa>><<HBG01>><<HBGAf>><<HBG00>><<HBGC03>>' || char(13) || '
<<HBGAr>><<HBG03>><<HBGAy>><<HBG00>><<HBGAt>>' || char(13) || '
<<HBGAf>><<HBG02>><<HBGAr>><<HBG03>><<HBGAa>>'),
(2316, 'UniqueStaff26', 28848, '<<HBGAa>><<HBG01>><<HBGC04>><<HBG02>><<HBGC06>>' || char(13) || '
<<HBGAa>><<HBG01>><<HBGAs>><<HBG02>><<HBGC06>>' || char(13) || '
<<HBGC011>><<HBGAa>><<HBG04>><<HBGC08>><<HBGAa>>'),
(2317, 'UniqueAmulet63', 29513, 'Death creeps closer; unseen, inexorable, hungry.'),
(2318, 'UniqueHelmetInt24', 49052, 'A dance as old as time.'),
(2319, 'UniqueBelt37', 16330, 'Simple. Deadly. Unstoppable.'),
(2320, 'UniqueOneHandSword33', 54321, 'Lead by example.'),
(2321, 'UniqueBodyDexInt12', 19769, 'He may have returned from the frozen southern reaches,' || char(13) || '
but that doesn''t mean he ever truly escaped them.'),
(2322, 'UniqueAmulet64', 29276, 'For how little time they had together,' || char(13) || '
their love was all the more powerful.'),
(2323, 'UniqueBootsDexInt11', 26838, 'Every glorious conquest' || char(13) || '
stands astride innocent bones.'),
(2324, 'UniqueGlovesDex7', 45466, 'Members of the House Azadin are trained from birth to join the' || char(13) || '
family profession. The target changes, but the job''s always the same.'),
(2325, 'UniqueBelt38', 1146, 'Freedom is won only by those who are not free.'),
(2326, 'UniqueOneHandAxe10', 11181, 'Better to act without thought' || char(13) || '
than to think without action.'),
(2327, 'UniqueOneHandAxe11', 58912, 'Silence fell... we gazed upon high.' || char(13) || '
The Red Pyre flared, palms wide.' || char(13) || '
Ash-laden gales scoured our flesh.' || char(13) || '
Four screams became one roar.'),
(2328, 'OfferingGift', 30318, 'The Goddess abides a kingdom beyond compare,' || char(13) || '
should you meet her challenge.'),
(2329, 'OfferingTribute', 42897, 'You may appeal to the Goddess for another verdict,' || char(13) || '
but justice favours only the truly worthy.'),
(2330, 'OfferingDedication', 3771, 'Before the Goddess, nothing remains hidden.' || char(13) || '
Adversity reveals old flaws and new strengths.'),
(2331, 'UniqueHelmetStrInt19', 15014, 'The line that divides hope and fear,' || char(13) || '
life and death, crowd and mob,' || char(13) || '
is as thin as a whisper.'),
(2332, 'UniqueBelt39', 32925, '"This will help with the pain.' || char(13) || '
One for you... and one for me."' || char(13) || '
- Doctor ''Shaky Hands'' Opden'),
(2333, 'UniqueJewel148', 16027, 'The sky, the land, the people burned.' || char(13) || '
What little still stood soon faced wild, battering storms.' || char(13) || '
Winter arrived suddenly and stayed for a generation.' || char(13) || '
Civilisation was not simply halted, but reversed, erased.'),
(2334, 'UniqueRing67', 53029, 'Somebody does have to get hurt.'),
(2335, 'UniqueRing68', 32355, 'All roads lead to that destined doom.'),
(2336, 'UniqueDagger20', 45526, 'The shadow warrior moves like the wind;' || char(13) || '
his strikes land long after he is gone.'),
(2337, 'UniqueBodyDexInt13', 5198, 'The Oriathans built their empire on naval mobility, which allowed' || char(13) || '
them to wage war wherever their enemy was weakest.'),
(2338, 'UniqueBodyStr12', 35820, 'The giant cares not for the ants.'),
(2339, 'UniqueHelmetStrDex8', 20323, 'Expand one single ambition to crystal clarity... and beyond.'),
(2340, 'UniqueStaff27', 43682, 'To stand at the confluence of the elements,' || char(13) || '
the master must achieve perfect balance.'),
(2341, 'UniqueHelmetDexInt15', 19045, 'Obtaining information depends upon pretending one already has it.'),
(2342, 'UniqueShieldDexInt7', 33640, 'The lightning fears not the flame.'),
(2343, 'UniqueJewel152', 45458, 'Maximum power fueled by science gone mad.'),
(2344, 'UniqueJewel153', 5891, 'Indiscriminate destruction fueled by science gone mad.'),
(2345, 'UniqueShieldStrDex5', 55544, 'Fragile, explosive, and punishing.'),
(2346, 'UniqueShieldStrDex6', 5070, 'Never let the audience know your true form. Misdirect them,' || char(13) || '
beguile them. Strike when they least expect it.'),
(2347, 'UniqueHelmetStrDex9', 55858, 'The single well-placed arrow that changes the world' || char(13) || '
must be preceded by ten thousand practice shots.'),
(2348, 'UniqueBelt40', 53517, 'Teach a man to burn, and you''ll be warm for the rest of his life.'),
(2349, 'UniqueAmulet65', 50542, '"Remain poised. Remain balanced. Keep all the emotions of a lifetime caged.' || char(13) || '
Let only your enemies see the truth of your rage."'),
(2350, 'HeistUrnOfFarud', 19774, '"The Faridun cannot earn burial in the sky.' || char(13) || '
They have other ways of keeping the dead."'),
(2351, 'HeistBoxofTripyxis', 20584, '"Allegedly turns water to Lethe. That makes it my competition. ' || char(13) || '
I don''t like competition."'),
(2352, 'HeistIncenseofKeth', 5160, '"Sap of the Aturi tree, known only to grow at the meeting point of the seven waters.' || char(13) || '
Nothing since its disappearance has smelled as wondrous."'),
(2353, 'HeistCrestofEzomyr', 49287, '"A symbol of my birthright and claim to my fiefdom. ' || char(13) || '
I must have it if I am to return my family to its rightful place."'),
(2354, 'HeistEzMyraeTome', 20466, '"A true curiosity. Matches no known language, yet its illustrations hint at knowledge ' || char(13) || '
only rediscovered hundreds of years after the death of its unknown author."'),
(2355, 'HeistHandofArimor', 61396, '"Balabus Arimor was a little-known preacher during the days of Emperor Chitus,' || char(13) || '
who believed eternal life could be achieved through ritual sacrifice.' || char(13) || '
We shall see whether he was a prophet - or a charlatan."'),
(2356, 'HeistAbberathine Horns', 53710, '"As warm as living flesh, and smelling strongly of sulphite.' || char(13) || '
Morbid curiosity compels me to add it to my collection of oddities."'),
(2357, 'ThiefsTrinketSculptureFlavour', 27293, 'Rubbing the eel''s head is said to bring smugglers good fortune.'),
(2358, 'UniqueHeistContract1', 47761, '"If Jamanra has been resurrected the way so many other ancient heroes have returned,' || char(13) || '
then perhaps I can convince him to rise up and unite the Faridun once more!"'),
(2359, 'UniqueHeistContract2', 43477, '"Some of my inventions don''t live up to their names, but some work all' || char(13) || '
too well. Let''s hope that the Unbreakable is the former, not the latter."'),
(2360, 'UniqueHeistContract3', 55150, '"A part of me still believes I can convince Nashta to give up her rebellious ways and come home. That part' || char(13) || '
of me will forever be nine years of age, futilely chasing her as she runs off into the dunes yet again."'),
(2361, 'UniqueHeistContract4', 23360, '"There can be no freedom' || char(13) || '
while hate still reigns."'),
(2362, 'UniqueHeistContract5', 28300, '"If Admiral Darnaw is stupid enough to send orders to his fleet members ' || char(13) || '
and not expect us to steal them, then he deserves what''s coming to him!"'),
(2363, 'UniqueHeistContract6', 62734, '"The Vox speak in threats.' || char(13) || '
We will answer them with action."'),
(2364, 'UniqueJewel149', 6955, 'Each blow of the hammer shapes the ingot,' || char(13) || '
each strike stretching and sharpening;' || char(13) || '
The sabre''s tip reaching out, grasping for life.'),
(2365, 'UniqueJewel150', 45114, 'Quenched, the blade hardens, becomes brittle.' || char(13) || '
The edge will not last forever,' || char(13) || '
But when it breaks, its service will continue.'),
(2366, 'UniqueJewel151', 24568, 'Her apprentice spends hours working the steel,' || char(13) || '
and the end result is melted for scrap.' || char(13) || '
Each one made better than the last.' || char(13) || '
Each one made more quickly.' || char(13) || '
She knows the path well.'),
(2367, 'UniqueShieldDexInt8', 42567, 'Horrific experiments with corrupted flesh require careful management.'),
(2368, 'UniqueRing69', 51378, 'Beyond the veil of death, there burns a fire' || char(13) || '
by whose light night is borne.'),
(2369, 'UniqueGlovesStrInt12', 14979, 'A sacrifice of blood calls forth His vengeance.' || char(13) || '
Let the righteous become the Hand of God.'),
(2370, 'UniqueBelt41', 7746, 'The burden falls heaviest not on those that died,' || char(13) || '
but on those that did not.'),
(2371, 'UniqueHelmetStrInt20', 48682, '"Her sisters eternally fought for that shining apex in the skies,' || char(13) || '
but Viridi instead found strength in humility."' || char(13) || '
- Azmerian Creation Myth'),
(2372, 'UniqueDagger21', 53588, '"That bronze girl sure knows how to cut someone down to size!"' || char(13) || '
- Bertrand the Plush'),
(2373, 'UniqueDagger22', 31678, 'That which we cannot forgive' || char(13) || '
harms all those we hold dear.'),
(2374, 'UniqueBodyDexInt14', 9858, 'Within each of us exists a being of pure malice,' || char(13) || '
held back only by the lies we tell ourselves.'),
(2375, 'UniqueBelt42a', 60094, 'The tortured thinker is made heavier by the weight of his guilt.'),
(2376, 'UniqueBelt42b_', 21864, 'The cruel thinker finds glee in torture most precise.'),
(2377, 'UniqueBelt42c', 44904, 'The cowardly thinker''s greatest success is simply surviving.'),
(2378, 'UniqueRing70', 5681, 'Accept the infection, let it take hold.' || char(13) || '
Then carry it far and wide.'),
(2379, 'UniqueHelmetStrInt21', 29453, 'Primordial rage slumbers, waiting for the call' || char(13) || '
of the stars to return and swallow the world.'),
(2380, 'UniqueBootsStrDex7', 3846, 'All that was loved, all that was hated -' || char(13) || '
naught remains but ash.'),
(2381, 'UniqueOneHandSwordDemigods1', 37580, 'Stories of heroism by the victor persist,' || char(13) || '
for no one survives to contest them.'),
(2382, 'HeistGoldenIdol1', 46707, '"I found the tomb in the first place, and they had the nerve to empty it without me! ' || char(13) || '
Reckon it''ll make a fine trophy for my efforts."'),
(2383, 'HeistGoldenIdol2', 9025, '"One must, as one should, admire the lasting works of those who came before.' || char(13) || '
The Vaal were the uncontested greatest architects until we,' || char(13) || '
and Matatl soared above their best." '),
(2384, 'HeistGoldenIdol3', 19410, '"I believe she was a beautiful maiden. ' || char(13) || '
Kind, virtuous and devout through-and-through.' || char(13) || '
Such a gift will set me apart from all other suitors."'),
(2385, 'HeistGoldenIdol4', 19274, '"Victims of war, the indebted, and the irredeemably shamed' || char(13) || '
were to live their lives in servitude. Some rose above their station. ' || char(13) || '
This individual, it seems, was all but deified."'),
(2386, 'HeistGoldenIdol5', 21878, '"Heard if you put a drop of blood in its mouth,' || char(13) || '
it''ll whisper the secrets of immortality.' || char(13) || '
Doesn''t have to be your own blood, does it?"'),
(2387, 'HeistGoldenIdol6', 41287, '"I''ll give it to her and tell her' || char(13) || '
''It once held the reflection of a Queen, and now it will once more.''' || char(13) || '
Anton can cross the Vastiri on his family fruits ' || char(13) || '
if he thinks he loves her like I do."'),
(2388, 'HeistGoldenIdol7_', 39715, 'Once cast the reflections of royalty, now worth the sum of its parts.'),
(2389, 'HeistGoldenIdol8', 34195, 'Ornately adorned and heavier than is practical.'),
(2390, 'HeistGoldenIdol9', 6507, 'A common figure adorning Vaal ruins, but exquisitely crafted from gold.'),
(2391, 'HeistGoldenIdol10', 36244, 'The last shimmering face witnessed by many a sacrifice.'),
(2392, 'HeistGoldenIdol11', 19140, 'Silently keeps innumerable secrets whispered in moments of desperation. '),
(2393, 'HeistGoldenIdol12', 62481, 'At once horrid and beautiful, awkward and alluring, silly and overwhelmingly mysterious.'),
(2394, 'HeistGoldenIdol13', 22187, 'Dried blood remains trapped in its many deep grooves.'),
(2395, 'HeistIsla1', 30997, 'My inventions, my babies, deserve to be in better hands!'),
(2396, 'HeistIsla2', 49861, '...the blueprints for my Extreme Warmth Beam, my Storm Wooing Rod,' || char(13) || '
the Mind Sublimator, and the Unbreakable...!'),
(2397, 'HeistNenet1', 61743, '"If we can prove Jamanra existed, then the Faridun may have a chance to rejoin the' || char(13) || '
Maraketh. I, for one, would like to meet my parents. I have many questions..."'),
(2398, 'HeistNiles1', 49512, '"There is nothing quite so exquisite as a forced confession. The sufferer will' || char(13) || '
say anything to make the pain stop, and that''s the point. Guilt is irrelevant."'),
(2399, 'HeistNiles2', 28632, '"It supposedly causes enormous plants to grow from almost any soil. The myth claims we' || char(13) || '
need to sacrifice a baby to make it function, but that''s a bit grotesque, even for me."'),
(2400, 'HeistAdiyah1', 22460, '"When hope was but a memory, the twin sister Sekhemas Solerai and Lundara arose to unite the Maraketh.' || char(13) || '
They wielded the essence of gold and silver. The Spear is one of the two weapons that forged us."'),
(2401, 'HeistAdiyah2', 39369, '"Wraeclast is harsh, and the Plains of Vastiri are unforgiving. We Maraketh can' || char(13) || '
ill afford an internal war. We must prove that Nashta is behind these attacks."'),
(2402, 'HeistKarst1', 18751, '"They were me granddaddy''s. ' || char(13) || '
Could break into any house as quick and silent as a Cardinal''s fart."'),
(2403, 'HeistKarst2', 57262, '"Traitorous scum took the life I could''ve had. ' || char(13) || '
I ain''t usually the forgiving type, ' || char(13) || '
but I feel in this case that I owe him a little gift."'),
(2404, 'HeistKarst3_', 60447, '"Never take credit for another man''s work."'),
(2405, 'HeistTibbs1', 37438, '"Loved her like she was my own daughter.' || char(13) || '
I just want to know she''s safe."'),
(2406, 'HeistTibbs2', 55558, '"Damn near everything I''ve earned. ' || char(13) || '
Worth every little bit."'),
(2407, 'HeistHuck1', 50642, '"Lost touch with a mate of mine when' || char(13) || '
he got recruited into some secret squad.' || char(13) || '
Just want to see how he''s doing."'),
(2408, 'HeistHuck2', 13507, '"Enoch deserved better. ' || char(13) || '
This is the least I can do."'),
(2409, 'HeistVinderi1', 10720, '"Just the usual highly-illegal compounds.' || char(13) || '
Don''t drop them. It''s fine if you do, but don''t."'),
(2410, 'HeistVinderi2', 60330, '"I wish I could say this was the first time I''ve forgotten to restock on this thing. ' || char(13) || '
I forget what it was, but I''m sure I''ll remember by the time we need to get it.' || char(13) || '
Was it beetles? Bottles? I think it began with ''B''.' || char(13) || '
Or it had no ''B''."'),
(2411, 'HeistGianna1', 47355, '"I heard the script will send any who attempt to perform it mad,' || char(13) || '
but other than that, it is very good."'),
(2412, 'HeistGianna2', 2580, '"Make sure it''ll fit a small man, or a very large child.' || char(13) || '
And check for stains! Knew a few people who''d use them for-... ' || char(13) || '
...Just check for stains."'),
(2413, 'HeistTullina1', 7155, '"Let''s just hope she wasn''t wearing it when she wandered into the sea!"'),
(2414, 'HeistTullina2', 46555, '"It isn''t fair to either of us to keep chasing this dream."'),
(2415, 'Whakano1', 33417, '"When you stop viewing someone as a fellow human being,' || char(13) || '
there''s little you won''t do to forward your agenda.' || char(13) || '
That is what we''re dealing with."'),
(2416, 'Whakano2', 29849, '"Selfishness and hate fuel these kidnappings. ' || char(13) || '
It''s time we find who is leading them."'),
(2417, 'Faustus1', 48429, '"Darnaw is stupid and confident.' || char(13) || '
I am certain he will have recorded his misdeeds."'),
(2418, 'Faustus2', 4826, '"Fidium''s fealty to fairness ' || char(13) || '
makes him the perfect pawn in my plan.' || char(13) || '
Our plan. Perfect pawn in OUR plan."'),
(2419, 'Kurai1', 59741, '"A symbolic piece of history,' || char(13) || '
from a time when people of all backgrounds' || char(13) || '
united against a common enemy."'),
(2420, 'Kurai2', 51584, '"An unusual request."'),
(2421, 'Kurai3', 3278, '"I won''t be bullied.' || char(13) || '
We must get Hana back."'),
(2422, 'HeistAdmiralProclarsPipe', 61517, '"Admiral Proclar wreaked havoc on my smuggling routes for two full decades. Now that he''s dead, ' || char(13) || '
it''s a matter of thieves'' honour to check whether my product was in his pipe."'),
(2423, 'HeistAlchemicalChalice', 39510, '"The chalice holds certain properties that make scientists quite possessive and irrational.' || char(13) || '
It''s best if you don''t ask too many questions about this one."'),
(2424, 'HeistAncientSeal', 14531, '"At first glance, this seal seems no more than an ornament. But when one' || char(13) || '
looks closer, one realizes the design is from no culture we yet know of."'),
(2425, 'HeistBloodOfInnocence', 13663, '"In the early days of his religion, Innocence told his followers to drink of his blood and' || char(13) || '
enjoy eternal life. If that power holds in his ancient ichor, I hope that it can resurrect as well."'),
(2426, 'HeistCelestialStone', 45539, '"This unassuming rock reportedly fell from the sky a few centuries ago. Sounds impossible,' || char(13) || '
but the men who are guarding it obviously believe the tale, so I do, too."'),
(2427, 'HeistDekharasResolve', 48817, '"A simple ornament from the days when Keth''s trade empire was the' || char(13) || '
glory of the world. Protectors at the massive toll gates wore these."'),
(2428, 'HeistHeartCoil', 58684, '"There are very few devices in this world that can act as a heart for a' || char(13) || '
machine. This one is an ancient remnant of the work of Vaal engineers."'),
(2429, 'HeistEnigmaticAssemblyA', 3291, '"I currently possess four-hundred and forty-four pieces of this ancient' || char(13) || '
and puzzling device. A few seem to be missing. This part is crucial."'),
(2430, 'HeistEnigmaticAssemblyB', 3449, '"There is no telling what this device may do when completed, but I' || char(13) || '
have made it my life''s work. There must be a deeper meaning!"'),
(2431, 'HeistEnigmaticAssemblyC', 2140, '"I have spent my family''s entire fortune in the pursuit of this device.' || char(13) || '
Assembling it and turning it on is all I have left."'),
(2432, 'HeistEnigmaticAssemblyD', 48165, '"My schematics are clear. Once the Enigmatic Assembly is complete, it' || char(13) || '
will be a weapon to rival the gods! It must be... it has to be..."'),
(2433, 'HeistEldritchBlade', 11673, '"The Eldritch Blade is one half of a pair. Together, the two are said to drive men' || char(13) || '
insane by revealing the truth of the world to them. I wish to know this truth."'),
(2434, 'HeistEmperorCaspiro', 61367, '"Caspiro was a master of presentation. He maintained peace in Wraeclast through displays' || char(13) || '
of strength that, sadly, had no meaning to the dark presence that dismembered him..."'),
(2435, 'HeistEssenceBurner', 34462, '"Trust in scientists to create tools for better drug distillation. They don''t know the' || char(13) || '
worth of the beautiful tools they have. Let''s make sure it stays that way."'),
(2436, 'HeistFlaskOfWelakath', 29463, '"Long ago, a traitor was promised this mythical elixir. We consider her a fool for' || char(13) || '
believing it exists, but if it does... I would certainly like to take a sip and find out."'),
(2437, 'HeistForbiddenLamp', 64959, '"The lamp is said to contain Aziza, the Fourth Servant of Water. I doubt the tale' || char(13) || '
is true, but I cannot allow one of our artifacts to fall into Kondor''s hands."'),
(2438, 'HeistGoddessOfWater', 11124, '"The relief depicts some sort of forgotten Maraketh goddess. I have no idea what' || char(13) || '
the context is. The important thing is that you steal it before Bazira does."'),
(2439, 'HeistGoldenToucan', 6619, '"It is said that the Golden Ibis was forged before time itself, before writing, or even' || char(13) || '
oral history. That''s nonsense, of course, but it''s still very old, and therefore noteworthy."'),
(2440, 'HeistImpossibleCrystal', 39226, '"The world is governed by certain natural laws. Science and thaumaturgy are one' || char(13) || '
and the same. But the crystal... it shouldn''t exist. It''s not from here. We must have it."'),
(2441, 'HeistLivingIce', 46673, '"Are we the only ones who understand the danger? The fools! Living ice absorbs heat' || char(13) || '
and grows. We must control it properly, lest it spread across all of Wraeclast."'),
(2442, 'HeistSealOfLunaris', 40420, '"I have a suspicion that the Maraketh Sekhema of legend, Lundara, is the same historical' || char(13) || '
figure as the Azmeri and Eternal goddess Lunaris. The Seal may prove that."'),
(2443, 'HeistOrbalasFifthAdventure', 31284, '"The relief was the first ever depiction of some Maraketh girl named Orbala undertaking her' || char(13) || '
fifth great adventure. I don''t particularly care about the story, I just don''t want Bazira to have it."'),
(2444, 'HeistSeaPearlHeirloom', 62434, '"My accursed father owes his children this heirloom. We deserve' || char(13) || '
to know our culture, just like you full-blooded humans do."'),
(2445, 'HeistSealOfSolaris', 47560, '"It is my belief that Solerai, from the Maraketh legend, is Solaris herself in another system of' || char(13) || '
myths. If I can prove that, I can begin piecing together a true history of the Winter of the World."'),
(2446, 'HeistStaffOfTheFirstSinEater', 30793, '"The history of the order of Sin Eaters is shrouded in secrecy and shame.' || char(13) || '
Nevertheless, history demands truth, even if it takes centuries to be revealed."'),
(2447, 'HeistOghamCandelabra', 28041, '"Those Eternal bastards looted everything that wasn''t bolted to the floor when we' || char(13) || '
finally drove them from our island! That candelabra belongs with us!"'),
(2448, 'HeistSwordOfTheInverseRelic', 9219, '"By all accounts, the Sword of the Inverse Relic was found aged and rusted,' || char(13) || '
but is becoming less weathered over time. We really must study its properties."'),
(2449, 'HeistTuskedHominidSkull', 10315, '"If the skull is real, and not a forgery, then it may show that my people are not the' || char(13) || '
abominations others believe us to be. The word ''human'' may have a broader meaning."'),
(2450, 'HeistUrnOfTheOriginalAshes', 9799, '"A great fire once swept the land, and our leaders were turned to ash where they stood.' || char(13) || '
The urn contains exactly what you think it does, and serves as proof of our long lineage."'),
(2451, 'WatchstoneMaven', 65260, 'Only the souls trapped within can bear witness to the Maven''s dark proclivities, and they dare not speak up.'),
(2452, 'MavenKey', 25406, 'It would be foolish to obey the Maven''s demands.' || char(13) || '
It would also be foolish not to.'),
(2453, 'MavenTrial', 4342, 'For those who must not endure it,' || char(13) || '
there may be found a perverse joy ' || char(13) || '
in watching the struggle for survival.'),
(2454, 'MavenKeyFragment', 15548, 'Precious and perilous,' || char(13) || '
Tantalising and terrible.'),
(2455, 'UberBossKeyShaper', 61999, 'A single act of love and defiance' || char(13) || '
 may cascade destruction across the cosmos.'),
(2456, 'UberBossKeyUberElder', 62376, 'A void where only terror and emptiness exists; ' || char(13) || '
those who attempt to struggle only hasten the assimilation'),
(2457, 'UberBossKeySirus', 14249, 'Agony born of ennui. ' || char(13) || '
Hate born of love.'),
(2458, 'UberBossKeyCortex', 35662, 'When memories become twisted by a corrupted mind,' || char(13) || '
 history is rewritten, time after time.'),
(2459, 'UberBossKeyMaven_', 38098, 'You must rise from mere amusement to respected equal.'),
(2460, 'UberBossKeyEater', 49481, 'At the core of the mass, a fierce hunger seethes,' || char(13) || '
 as the Tangle''s champion devours a myriad of worlds...'),
(2461, 'UberBossKeyExarch_', 4456, 'Constellations are systematically incinerated ' || char(13) || '
in the wake of an ever-expanding archive of minds.'),
(2462, 'UberBossKeyAnger', 8056, 'A loved one''s harsh words eventually become our own.'),
(2463, 'UberBossKeyBenevolence', 52063, 'Adoration can blind us to the truth of human flaws.'),
(2464, 'UberBossKeyIgnorance', 9310, 'Grief cannot be defeated alone.'),
(2465, 'UberBossKeyFragment', 3739, '[DNT] Do not combine'),
(2466, 'UniqueWatchstone11a', 5031, '"The village was locked within its walls,' || char(13) || '
protected from those who could do them harm,' || char(13) || '
protected from those who could save them."'),
(2467, 'UniqueWatchstone11b', 53618, '"Believing them to have discovered new lands,' || char(13) || '
they planted their flag in the dirt and called it their own.' || char(13) || '
A gesture not taken with a great deal of pleasure' || char(13) || '
by those who already dwelt there."'),
(2468, 'UniqueWatchstone11c', 3340, '"The first explorers took to the hills to discover the lay of the land,' || char(13) || '
and watched with wonder as the land undulated, crashed and twisted."'),
(2469, 'UniqueWatchstone11d', 10001, '"Atop the highest peaks, the sunlight pierced but did not warm.' || char(13) || '
The air choked and did not nourish.' || char(13) || '
And those that made the trek realised the folly of their desire for greatness."'),
(2470, 'UniqueWatchstone11e', 23060, '"Where once a mountain stood there was now but fields and dust.' || char(13) || '
One by one, the stones were moved and placed with intention,' || char(13) || '
the consequences borne by the destination and the origin."'),
(2471, 'UniqueWatchstone11f', 33164, '"The Shade walked the land with no end in sight,' || char(13) || '
no purpose in mind,' || char(13) || '
but the one it invented to pass the time."'),
(2472, 'UniqueWatchstone11g', 33387, '"There were seasons in this strange new place, but not of sun and snow.' || char(13) || '
Seasons of stone that rose and fell like waves.' || char(13) || '
Seasons of structure and growth and madness and chaos.' || char(13) || '
Seasons of birth and decay that seemed untethered to cause."'),
(2473, 'UniqueWatchstone11h', 63600, '"For a time, it was thought this place could seed an empire' || char(13) || '
greater than any in history.' || char(13) || '
The lands could be tamed, and commanded, they thought.' || char(13) || '
But control, like all things in that place, was an illusion."'),
(2474, 'IncursionItemisedTempleDefault', 29047, '"Grand plans were laid for a place called Atzoatl, though fierce bickering between its Architects is said to have stifled its development." - Icius Perandus, Antiquities Collection, Research Report'),
(2475, 'UniqueShieldStrInt15', 27939, 'The Banished Architect sought to employ all the' || char(13) || '
darkest secrets of the Vaal... at the same time.'),
(2476, 'UniqueGlovesStr10', 28099, 'The first Karui born on the fringes of the Vaal empire' || char(13) || '
developed a blood fever born of corruption.'),
(2477, 'UniqueSceptre24', 26886, 'Their three serpentine heads found unity in balance.'),
(2478, 'UniqueBootsDex14', 451, 'The High Priests ensured the loyalty of their slaves by habituating' || char(13) || '
them to narcotic stimulants with lethal withdrawals.'),
(2479, 'UniqueHelmetDexInt16', 33454, 'Man retains sanity and strives toward civilisation' || char(13) || '
only under the blessed veil of ignorance.'),
(2480, 'UniqueWand20', 30410, 'Crush your enemies with your essence, so that you may drink of theirs.'),
(2481, 'UniqueStaff28', 62778, 'Bow before her... or suffer the most gruelling death imaginable.'),
(2482, 'UniqueRing71', 30334, 'The priest that carried Yaomac''s sigil was' || char(13) || '
granted one boon by each serpentine head.'),
(2483, 'UniqueStaff29', 53959, 'Stolen power is still power.'),
(2484, 'UniqueJewel154', 64356, 'The Hated Slave seeks dominion over his own kind.'),
(2485, 'UniqueJewel155', 61330, 'The Sovereign of the Well seeks dominion over the light.'),
(2486, 'UniqueJewel156', 22665, 'The Blackblooded seeks dominion over darkness itself.'),
(2487, 'UniqueJewel157', 20942, 'The Liege of the Lightless seeks dominion over the surface dwellers.'),
(2488, 'UniqueQuiver18', 17463, 'The dance of metal and flesh never ends.'),
(2489, 'UniqueShieldInt16', 58036, 'You shall be weighed and measured. You shall be judged...' || char(13) || '
and perhaps you shall be found worthy.'),
(2490, 'OrbOfVeiledChaosFlavour', 61898, '"The Order tried for centuries to shield the world from chaos.' || char(13) || '
But chaos is natural. It is a tool, like any other, with which to' || char(13) || '
shape our destinies." - The Lifegiver''s Manifesto'),
(2491, 'IncursionItemisedTempleT3Corruption', 34499, '"Atzoatl was a locus of Corruption, a temple dedicated to the worship of the unspeakable." - Icius Perandus, Antiquities Collection, Eroded Vaal Orb'),
(2492, 'IncursionItemisedTempleT3Sacrifice', 5149, '"When the Vaal discovered power could be gained from sacrificing the living, Atzoatl became a death march for the lower classes." - Icius Perandus, Antiquities Collection, Obsidian Sacrificial Knife'),
(2493, 'IncursionItemisedTempleT3Currency', 28000, '"In their paranoia, the Architects of Atzoatl hoarded wealth beyond any reasonable measure." - Icius Perandus, Antiquities Collection, Vaal Golden Idol'),
(2494, 'IncursionItemisedTempleT3Gem', 52176, '"Doryani himself conducted gem research at Atzoatl in its final days. What brilliant discoveries were lost with that temple?" - Icius Perandus, Antiquities Collection, Third Ciphered Tablet'),
(2495, 'IncursionItemisedTempleT3Museum', 38510, '"Much could be learned from the relics said to be kept in Atzoatl. We consider the Vaal ancient, so what did they consider ancient in turn?" - Icius Perandus, Antiquities Collection, Vaal Mural'),
(2496, 'IncursionItemisedTempleT3Atziri', 7035, '"Evidence suggests that Atzoatl''s influence grew great enough that Atziri herself moved her seat of power to within its walls." - Icius Perandus, Antiquities Collection, Royal Decree cast in Bronze'),
(2497, 'IncursionItemisedTempleT3Breach', 4935, '"Atzoatl played host to the Cult of the Purple Flame. I do not know what powers they worshipped, but my educated guesses leave me shaken." - Icius Perandus, Antiquities Collection, Embalmed Claw'),
(2498, 'IncursionItemisedTempleT3Legion', 42741, '"The Architects intended to research supposed ''Obelisks Beyond Time,'' but the Vaal fell before the first obtained monolith was so much as measured." - Icius Perandus, Antiquities Collection, Crystal Shard'),
(2499, 'IncursionItemisedTempleT3Jewellery', 40981, '"Trade with lesser cultures, such as the Maraketh and the early Karui, resulted in overflowing vaults full of golden trinkets and elegant jewels." - Icius Perandus, Antiquities Collection, ''Dekhara''s Resolve''');
INSERT INTO "FlavourText" ("_row", "Id", "__col1", "Text") VALUES
(2500, 'IncursionItemisedTempleT3Map', 28148, '"In its last days, the Architects of Atzoatl became increasingly obsessed with fictional lands. Wondrous lands, by their description, but fictional. Very odd." - Icius Perandus, Antiquities Collection, Unidentified Angular Device'),
(2501, 'IncursionItemisedTempleT3Strongbox', 33008, '"Zantipi is said to have spent most of his considerable talent devising ambushes that used the promise of treasure as a lure for would-be looters." - Icius Perandus, Antiquities Collection, Broken Locking Mechanism'),
(2502, 'IncursionItemisedTempleT3Tempest', 57102, '"Merchant carvings of the era consistently reported that the Architects could alter the weather in manners terrifying and incomprehensible." - Icius Perandus, Antiquities Collection, Trade Record Tablet'),
(2503, 'IncursionItemisedTempleT3Fire', 39248, '"The Vaal were said to have experimented with fire at Atzoatl, though to what end is unknown." - Icius Perandus, Antiquities Collection, Charred Parchment'),
(2504, 'IncursionItemisedTempleT3Lightning_', 63823, '"The Architects apparently sought to master lightning. They may have succeeded just before the fall." - Icius Perandus, Antiquities Collection, Copper Detritus'),
(2505, 'IncursionItemisedTempleT3Workshop', 46028, '"Their engineering knowledge may have rivaled that of the modern world. The fall of the Vaal no doubt set humanity back a thousand years." - Icius Perandus, Antiquities Collection, Ancient Gear Interlock'),
(2506, 'IncursionItemisedTempleT3PackSize', 45840, '"A great many warriors were stationed at Atzoatl, ostensibly due to repeated invasion by something referred to as ''a haunting death.''" - Icius Perandus, Antiquities Collection, Carved Interment Records'),
(2507, 'IncursionItemisedTempleT3Hatchery', 16041, '"A great many creatures were bred at Atzoatl, ostensibly due to repeated invasion by some kind of horrifying murderous entity." - Icius Perandus, Antiquities Collection, Fossilized Egg Sac'),
(2508, 'IncursionItemisedTempleT3Damage', 58611, '"At the height of their civilization, the Vaal took to ritual combat to solve all of their disputes. As a result, their surviving warriors were among the best in history." - Icius Perandus, Antiquities Collection, Rust-coated Sword'),
(2509, 'IncursionItemisedTempleT3Nexus', 28552, '"The heart of Atzoatl imbued its denizens with vigour, according to the myths." - Icius Perandus, Antiquities Collection, Glowing Stone'),
(2510, 'IncursionItemisedTempleT3Trap', 15292, '"Expedition logs suggest quite a few explorers sought Atzoatl over the centuries. The Architects planned against this potential plundering, however, with ingenious and lethal traps." - Icius Perandus, Antiquities Collection, Corroded Spring Mechanism'),
(2511, 'IncursionItemisedTempleT3Ghost', 52387, '"The Architects were certainly fond of their ghost stories. The tales almost sound as if the business was taken literally." - Icius Perandus, Antiquities Collection, Carved Fable'),
(2512, 'IncursionItemisedTempleT3Poison', 28650, '"The Vaal had little concern for the externalities of their engineering. The toxins produced by their manufacturing may have poisoned the entirety of Atzoatl." - Icius Perandus, Antiquities Collection, Desiccated Corpse of a Vaal Citizen'),
(2513, 'IncursionItemisedTempleT3Restoration', 24359, '"The Architects sought immortality... perhaps they reside within Atzoatl still..." - Icius Perandus, Antiquities Collection, Vial of Emerald Water'),
(2514, 'IncursionItemisedTempleT3Explosives', 37603, '"Atzoatl was a place of crude alchemy rather than art." - Icius Perandus, Antiquities Collection, Urn of Unstable Powder'),
(2515, 'IncursionItemisedTempleT3Armour', 56524, '"Armour crafted at Atzoatl became the envy of the known world." - Icius Perandus, Antiquities Collection, Ancient Metals'),
(2516, 'GraspingMailFlavourText', 20870, 'Of ash and avalanche,' || char(13) || '
in storm and flesh,' || char(13) || '
we dream of unity.' || char(13) || '
The time approaches...'),
(2517, 'CurrencyHarvestBossKey', 59489, 'It isn''t the twisted transformative power of corruption that makes it so dangerous.' || char(13) || '
It is its ability to hide in plain sight.'),
(2518, 'BloodCrucibleFlavourText', 30784, 'The gateway of flesh, horror unbound,' || char(13) || '
requires a key of madness and pain.'),
(2519, 'DreamFurnaceFlavourText', 19425, 'The minds of men are but motes' || char(13) || '
on a sea of infinite madness.'),
(2520, 'VisceraCauldronFlavourText', 19408, 'Flesh can be as clay to the properly motivated artist.'),
(2521, 'TangleKeyFlavourText', 55280, 'The Infinite Hunger awaits in a cosmic stomach where' || char(13) || '
whole civilisations are digested - but do not die.'),
(2522, 'TangleBossKeyFlavourText', 47264, 'From the heart of the Tangle, the Eater of Worlds' || char(13) || '
reaches out for control of the Atlas.'),
(2523, 'CleansingFireKeyFlavourText', 51109, 'Once within the grasp of the Black Star,' || char(13) || '
there can be no escape.'),
(2524, 'CleansingFireBossKeyFlavourText', 7759, 'From the corona of an ancient star,' || char(13) || '
the Searing Exarch seeks to master the Atlas.'),
(2525, 'FearKeyFlavourText', 56998, 'A single harsh word can haunt us forever.'),
(2526, 'BenevolenceKeyFlavourText', 18652, 'Simple kindness makes the most powerful of memories.'),
(2527, 'IgnoranceKeyFlavourText', 1483, 'Grief can divide, greater than any gulf.'),
(2528, 'SentinelController', 37100, 'For aeons, ancient constructs have lain dormant,' || char(13) || '
but now their designs are under your control.'),
(2529, 'ChayulaBodyPart1', 17829, 'Lay bare our flesh under the' || char(13) || '
searing light of the Torus Eternal.'),
(2530, 'ChayulaBodyPart2', 25949, 'Silent thoughts chitter in the dark,' || char(13) || '
lashing our minds into agonised ecstasy.'),
(2531, 'ChayulaBodyPart3', 37238, 'We crawl on our faces in burning ash,' || char(13) || '
choking, eating, until our throats bleed.'),
(2532, 'ChayulaBodyPart4', 8269, 'Scrape, till, toil, scream...'),
(2533, 'ChayulaBodyPart5', 54470, 'We give of our flesh so that' || char(13) || '
the Lords may thrive.'),
(2534, 'ChayulaBodyPart6', 42283, 'Let the Grey Winds' || char(13) || '
take the Foulborn.'),
(2535, 'ChayulaBodyPart7', 61193, 'Let the Mother''s love' || char(13) || '
embrace our flesh.'),
(2536, 'ChayulaBodyPart8', 52858, '"It That Was Vruun failed...' || char(13) || '
It That Will Be Vruun... will not.' || char(13) || '
Vengeance will be ours..."'),
(2537, 'ChayulaBodyPart9', 53627, 'The flesh exists for one reason, and one' || char(13) || '
reason alone... to perpetuate itself.'),
(2538, 'ChayulaBodyPart10', 40982, 'Unity... must have... the flesh...' || char(13) || '
must draw closer...'),
(2539, 'DivinationCardBrothersGift______', 46355, '<size:23>{Even though his flame has burned out,' || char(13) || '
he will never fade away.}'),
(2540, 'DivinationCardSoulQuenched', 55186, '<size:30>{Weapons such as these require a darker kind of forge...}'),
(2541, 'DivinationCardPoisonedFaith', 17168, 'Even our most devout beliefs are subtly shaped by our darkest desires.'),
(2542, 'DivinationCardAChillingWind', 19064, '<size:26>{All things slow under winter''s ' || char(13) || '
onslaught - even life itself.}'),
(2543, 'DivinationCardMatryoshka', 62491, '<size:28>{I cannot contain myself,' || char(13) || '
but I can barely squeak,' || char(13) || '
so many words I''d have for you,' || char(13) || '
if I could only speak!}'),
(2544, 'CrucibleGeode', 64992, 'Dark as obsidian with a red-hot core,' || char(13) || '
the geode hums with mysterious energy.'),
(2545, 'CrucibleGeodeUber', 62995, 'A fractured lithophysa studded with delicate crystalline formations.'),
(2546, 'CrucibleMap', 18237, 'Kalandra watched as the almighty titans fell,' || char(13) || '
relegated to the innermost depths of the world,' || char(13) || '
where horrific abominations awaited them.'),
(2547, 'SanctumKeyQuest', 46625, 'Hoc sciendo scribo ut verba mea perdant animam' || char(13) || '
meam eternam. Mihi credendum est quod novus' || char(13) || '
deus meus non sit tam divinus quam ipse petit...'),
(2548, 'SanctumKeyNonQuest', 58544, 'Mundus noster cecidit. Daemones ubique sunt. Librum' || char(13) || '
hunc in sacrarium conicio, ut forte alius viam inveniat...'),
(2549, 'ArchivesResearch', 10351, 'These Archives were among the first constructed by the Templars.' || char(13) || '
There are more books here than I could read in a lifetime...'),
(2550, 'VaultsResearch', 27253, 'The treasures within are tainted by a black spirit.'),
(2551, 'CathedralResearch', 53572, 'This was the first cathedral that Innocence ever built,' || char(13) || '
made to honour himself. It is gilded with stolen wealth.'),
(2552, 'NecropolisResearch', 6464, 'The Necropolis holds the darkest secrets of our religion,' || char(13) || '
lies that were never meant to be unearthed.'),
(2553, 'UniqueVaalSideAreaArchitects', 40529, 'They met in secret to plan aspirations beyond all others.' || char(13) || '
Their grand dreams slowly turned into endless nightmares.'),
(2554, 'UniqueVaalSideAreaEndless', 41437, 'Those citizens of the Vaal Empire that thought they survived the' || char(13) || '
Cataclysm soon realised that they had, in fact, done no such thing.'),
(2555, 'UniqueVaalSideAreaAtziri', 2977, 'In every possibility, in every world that might have been,' || char(13) || '
Queen Atziri''s mark on history was the one thing that never changed.'),
(2556, 'DivinationCardTheFortunate', 16322, '<size:26>{The fortunate find ' || char(13) || '
generosity in the divine.}'),
(2557, 'DivinationCardFireOfUnknownOrigin', 60592, '<size:26>{Faith sparks the flame,' || char(13) || '
a frenzy on the wind;' || char(13) || '
a fervour that drives us wildly onward.}'),
(2558, 'DivinationCardFathersLove', 17399, 'Everything is not enough.'),
(2559, 'DivinationCardWhoAsked', 7956, '<size:23>{In the midst ' || char(13) || '
of unrelenting requests,' || char(13) || '
the blacksmith''s forge ' || char(13) || '
conjures the unpredictable' || char(13) || '
Countless voices, countless desires – ' || char(13) || '
yielding weapons as diverse' || char(13) || '
as those who ask}'),
(2560, 'DivinationCardEldritchPerfection', 47290, 'Embrace horror.' || char(13) || '
Bathe in its beauty.'),
(2561, 'DivinationCardAssassinsGift', 11344, '<size:32>{What matters are' || char(13) || '
the Marks of your life,' || char(13) || '
not its Longevity.}'),
(2562, 'DivinationCardISeeBrothers', 4006, '<size:34>{"Where does the light go' || char(13) || '
when it is dark?"}'),
(2563, 'ValdoPuzzleBox', 26827, 'I can find no method of destroying the dangerous contents within... 
 perhaps, someday, you will find a way.'),
(2564, 'DivinationScarabOfTheCloister', 63178, 'No disease can be contained forever.'),
(2565, 'DivinationScarabOfPilfering', 51411, 'If you do not seize your fate, someone else will.'),
(2566, 'DivinationScarabOfMagicGuys', 4112, 'We create a thousand futures with every action.'),
(2567, 'ExpeditionScarab', 55852, 'They come from across the sea in search of ancient truth.'),
(2568, 'ExpeditionScarabOfRunefinding', 47100, 'That which came from the stars longs to return.'),
(2569, 'ExpeditionScarabOfVerisiumPowder', 40442, 'A properly refined pinch makes all the difference.'),
(2570, 'ExpeditionScarabOfArchaeology', 58892, 'Curiosity leads to wisdom. Wisdom leads to power.'),
(2571, 'ExpeditionScarabOfInfusion', 57141, 'Starlight empowers even the dead if bathed long enough.'),
(2572, 'IncursionScarab', 42542, 'Uncover the secrets of the Vaal one incursion at a time.'),
(2573, 'IncursionScarabOfInvasion', 47137, 'A gate, once opened, may swing in either direction.'),
(2574, 'IncursionScarabOfChampions', 63657, 'Only the best served in Atzoatl.'),
(2575, 'IncursionScarabOfTimelines', 1798, 'They say if you go far enough, you will meet yourself...'),
(2576, 'ScourgeScarab', 21997, 'The silent wall and the raging storm oppose the endless swarm.'),
(2577, 'UltimatumScarab', 54607, 'A challenge may be requested at any time.'),
(2578, 'UltimatumScarabOfBribing', 1571, 'A trial is only as incorruptible as its judge.'),
(2579, 'UltimatumScarabOfCatalysing', 63770, 'Most regret finding out how the powder is made.'),
(2580, 'UltimatumScarabOfInscription', 1369, 'There is always a wager to be made... if you can afford it.'),
(2581, 'UltimatumScarabOfDueling', 40350, 'Victory is meaningless, failure will be mocked.'),
(2582, 'DeliriumScarab', 5624, 'A perfectly innocuous Scarab that does nothing at all.'),
(2583, 'MysteriousScarab', 19276, 'They chitter, they crawl, they bite... and they swarm.'),
(2584, 'ScarabOfDivinity', 1874, 'Faith transforms.'),
(2585, 'BreachScarabHive', 38256, 'Their kingdoms always seek expansion.'),
(2586, 'BreachScarabOfTheDreamer_', 30758, 'Dreams quickly sour into Nightmare.'),
(2587, 'BreachScarabOfInstability', 31205, 'Reality warps and bends.'),
(2588, 'BreachScarabOfTheMarshal', 2382, 'Engineered and Unwavering Loyalty.'),
(2589, 'BreachScarabOfFortresses', 59721, 'Their Domain expands further still.'),
(2590, 'BreachScarabOfResonantCascade', 11523, 'Reality weakens with each new wound.'),
(2591, 'LegionScarab', 39243, 'What good is peace to a warrior?'),
(2592, 'LegionScarabOfOfficers', 55351, 'Even a battlefield has middle management.'),
(2593, 'LegionScarabOfTreasures', 44887, 'Ancient Hoards imbued with powerful Artifacts.'),
(2594, 'LegionScarabOfTheSekhema_', 13924, 'Storms of blood-stained sand will drown the enemies of the Maraketh.'),
(2595, 'LegionScarabOfEternalConflict', 57646, 'An eternity of blood. Glorious.'),
(2596, 'AbyssScarab', 1948, 'They search forever for more souls to drag to the dark.'),
(2597, 'AbyssScarabOfMultitudes', 11732, 'The Well hungers ceaselessly, even as it overflows.'),
(2598, 'AbyssScarabOfEdifice_', 51669, 'Their borrowed power swirls within ghastly crystals.'),
(2599, 'AbyssScarabOfEmptiness', 11919, 'They stare back, with hollow hypnotising eyes.'),
(2600, 'AbyssScarabOfDescending', 41843, 'They invite you to meet them; to join them.'),
(2601, 'AbyssScarabofProfoundDepth', 7064, 'They defend the depths at their Lords'' command.'),
(2602, 'DominationScarab', 32305, 'A simple exchange. Blood for power.'),
(2603, 'DominationScarabOfEvolution', 11848, 'The Atlas and Wraeclast share one terrifying secret.'),
(2604, 'DominationScarabOfTerrors', 34539, 'Whatever the prize, fight for it.'),
(2605, 'DominationScarabOfApparitions', 4858, 'Some paths to power lead only to madness.'),
(2606, 'EssenceScarab', 496, 'It is perfectly safe, the creatures trapped inside couldn''t possibly still be living.'),
(2607, 'EssenceScarabOfAscent', 50875, 'A more perfect facet cannot be achieved.'),
(2608, 'EssenceScarabOfCalcification', 8960, 'The crystals... can spread?'),
(2609, 'EssenceScarabOfStability', 17282, 'With the right tools and a precise hand, the manipulation of the crystals
can be made predictable.'),
(2610, 'EssenceScarabofAdaption', 394, 'The crystalline lattice expands in directions alien to the mortal mind.'),
(2611, 'TormentScarab', 44000, 'Their crimes in life haunt you in death.'),
(2612, 'TormentScarabOfPeculiarty', 15828, 'Now there''s a blood-curdling wail I haven''t heard before!'),
(2613, 'TormentScarabOfRelease_', 65266, 'If it could end, it wouldn''t really be damnation.'),
(2614, 'TormentScarabofRares', 5156, 'The strong are never truly alone.'),
(2615, 'TitanicScarab', 45812, 'What power lies in a name?'),
(2616, 'TitanicScarabOfTreasures', 16310, 'Greed is a trap of the mind.'),
(2617, 'TitanicScarabOfLegend', 11402, 'Power accumulates.'),
(2618, 'CartographyScarabofEscalation', 20663, 'Opportunity thrives where dreams are most perilous.'),
(2619, 'CartographyScarabOfRisk', 9682, 'What we see in the mirror can only be our own reflection.'),
(2620, 'CartographyScarabOfSingularity', 9187, 'Some regions of the Atlas never change.'),
(2621, 'CartographyScarabOfCorruption', 2435, 'Corruption bleeds between realities.'),
(2622, 'CartographyScarabOfUberPacks', 58770, 'There is no end, no horizon.'),
(2623, 'BestiaryScarab', 8172, 'The Beastmaster answers the call.'),
(2624, 'BestiaryScarabOfTheHerd', 11504, 'The First Ones ran rampant and free in the forests of old.'),
(2625, 'BestiaryScarabOfDuplicating', 48388, '"What''s better than one captured beast, exile?"'),
(2626, 'BestiaryScarabOfTheBlackMorrigan', 2135, 'The Nameless begin to slip their bonds of nonexistence...'),
(2627, 'InfluencingScarabOfTheShaper', 35756, 'A sea of stars awaits those who dare imagine.'),
(2628, 'InfluencingScarabOfTheElder', 51160, 'Beyond the light lies only the void.'),
(2629, 'InfluencingScarabOfHordes', 40138, 'Ideas cannot be contained.'),
(2630, 'InfluencingScarabOfConversion', 42431, 'Memories resound in the Atlas, echoing forever.'),
(2631, 'SulphiteScarab', 33910, 'Delve into darkness in search of the truth...'),
(2632, 'SulphiteScarabOfGreed', 55585, 'There is no such thing as ''enough''.'),
(2633, 'SulphiteScarabOfFumes', 36414, 'When the land itself is sick, even the very ground rots and spills forth.'),
(2634, 'HornedScarabOfChampions', 15524, 'Only the hardiest survive. Only survivors perpetuate.'),
(2635, 'HornedScarabOfAntagonism', 62308, 'Glory draws ever tighter its own doom.'),
(2636, 'HornedScarabOfPreservation', 15984, 'We must not forget those who came before.'),
(2637, 'HornedScarabOfCharts', 55421, 'The Atlas can be anything you want... and everything you want.'),
(2638, 'HornedScarabOfPlenty', 22360, 'To the strongest, prosperity be thine.'),
(2639, 'HornedScarabOfGlittering', 59248, 'Wealth flows to those that shine brightest.'),
(2640, 'HornedScarabOfTitans', 15363, 'Punctured dreams bleed into the mind.'),
(2641, 'HornedScarabOfOpulence', 31375, 'May Prospero favour you in all your endeavours.'),
(2642, 'ScarabofStability', 35671, 'Astonishing! A means to sustain the connection...'),
(2643, 'AmbushScarab', 46885, 'Is it still an ambush if you''re expecting it?'),
(2644, 'AmbushScarabOfHiddenCompartments', 57986, 'Beneath the obvious lies the real treasure...'),
(2645, 'AmbushScarabOfPotency', 49339, 'The locksmith dreams of building a better box.'),
(2646, 'AmbushScarabOfContainment', 32899, 'The silence belies lurking doom.'),
(2647, 'AmbushScarabOfDiscernment', 43323, 'A keen eye sorts the worthy from the chaff.'),
(2648, 'AnarchyScarab', 31196, 'On Wraeclast, it''s kill or be killed.'),
(2649, 'AnarchyScarabOfGigantification', 3002, 'The consumption of sulphite can cause strange growth.'),
(2650, 'AnarchyScarabOfPartnership', 11964, 'Among exiles, alliances shift and change constantly.'),
(2651, 'AnarchyScarabOfTheExceptional', 48477, 'Among many, one stands above the rest.'),
(2652, 'RitualScarabOfSelectiveness', 50289, 'Pick and choose which sacred tenets you prefer...'),
(2653, 'RitualScarabOfAFriendlyWisp', 29702, 'Trust in the Draíocht, and you shall never be alone.'),
(2654, 'RitualScarabOfAbundance', 27127, 'He draws ever closer...'),
(2655, 'RitualScarabOfCorpses', 56739, 'Reduced to mere Puppets; they yearn for life once more.'),
(2656, 'HarvestScarab', 62494, 'Hidden routes lead to vales of shadow and light...'),
(2657, 'HarvestScarabOfDoubling', 15328, 'A good season brings bounty.'),
(2658, 'HarvestScarabOfCornucopia', 49313, 'The taller the tree, the better the fruit.'),
(2659, 'BetrayalScarab', 39429, 'The Syndicate must pay for what they have done.'),
(2660, 'BetrayalScarabOfIntelligence', 62804, 'Those that can never die fear only pain.'),
(2661, 'BetrayalScarabOfReinforcements', 43125, 'Move and countermove.'),
(2662, 'BetrayalScarabOfUnbreaking', 50890, 'Dying over and over builds a tolerance to pain.'),
(2663, 'ScourgeScarabOfCorruption', 42606, 'Their very flesh exudes Corruption.'),
(2664, 'ScourgeScarabOfHaemophilia', 23, 'Reality itself begins to bleed.'),
(2665, 'ScourgeScarabOfResurgence', 63522, 'They hunger.'),
(2666, 'ScourgeScarabOfTheInvasion', 10955, 'The fated hour is almost nigh.'),
(2667, 'DeliriumScarabOfMania', 62770, 'They''re so loud! Why are they so loud?!' || char(13) || '
All you can do is scream!'),
(2668, 'DeliriumScarabOfParanoia', 56228, 'If it seems too good to be true...'),
(2669, 'DeliriumScarabOfNeuroses', 15646, 'Toothy grins shine in the dark.'),
(2670, 'DeliriumScarabOfDelusions', 47891, 'What are you talking about?' || char(13) || '
The Atlas was always like this.'),
(2671, 'BlightScarab', 60984, 'The tendrils creep and grow...'),
(2672, 'BlightScarabOfBounty', 50204, 'A ghastly fruit, but twice as sweet.'),
(2673, 'BlightScarabOfVeryBigChest', 51709, 'The core grows larger with each cycle, doomed to spill forth...'),
(2674, 'BlightScarabOfBlooming', 64011, 'Once a century, the Blight spills forth...'),
(2675, 'BlightScarabofInvigoration', 36766, 'Reversing the polarity of the compression modulator seems to have intriguing effects...'),
(2676, 'ScarabSettlers1', 57643, 'Rich veins run deeper still.'),
(2677, 'ScarabSettlers2', 17119, 'Digging''s the easy part. '),
(2678, 'ScarabSettlers3', 61927, 'Ore''s true worth lies not in stone, but in what it becomes.'),
(2679, 'ScarabSettlers4', 19375, 'The ore lives and breathes; and is not happy with your efforts.'),
(2680, 'ScarabMercenaries1', 23324, 'To the victor go the spoils.'),
(2681, 'ScarabMercenaries2', 11658, 'Some men must make their own way.'),
(2682, 'ScarabMercenaries3', 33499, 'Who goes there, bedecked in legend?'),
(2683, 'ScarabMercenaries4', 12748, '"Technically, historically... they''re all exiles, really."'),
(2684, 'ScarabOfMonstrousLineage', 57538, 'The bloodlines evolve faster than they can be culled.'),
(2685, 'ScarabOfAdversaries', 11845, 'They stand against you with equal enmity.'),
(2686, 'ScarabOfHuntedTraitors', 1308, 'Nothing is as unforgiveable.'),
(2687, 'ScarabCommander', 58817, '"The job never ends."'),
(2688, 'ScarabEvolution_', 22327, 'The cycle of death shapes life to its environment.'),
(2689, 'ScarabWisps', 52771, 'The Draíocht connects everything that lives.'),
(2690, 'ScarabSinistral', 40990, 'Flip a coin, do you wish for Heads?'),
(2691, 'ScarabDextral', 9894, 'Flip a coin, do you wish for Tails?'),
(2692, 'ScarabUnity', 59417, 'The great cacophony of life roars to a crescendo.'),
(2693, 'KalguuranRune1', 9257, 'The Sun, magnanimous on its throne, gifts' || char(13) || '
heat and light to all those it surveys.'),
(2694, 'KalguuranRune2', 44188, 'Sometimes, it is the connections between, rather' || char(13) || '
than the things themselves, that matters most.'),
(2695, 'KalguuranRune3', 16892, 'All living things move and change in patterns' || char(13) || '
that cannot be seen until they are gone.'),
(2696, 'KalguuranRune4__', 28727, 'No energy in this world stands alone.' || char(13) || '
There is always an opposite.'),
(2697, 'KalguuranRune5', 18787, 'All things flow. Stillness is an illusion.'),
(2698, 'KalguuranRune6_', 49063, 'Plenty is a matter of perspective.'),
(2699, 'KalguuranRune7', 55980, 'Though you may not know' || char(13) || '
your destination, it exists.'),
(2700, 'KalguuranRune8', 31877, 'The difference between here and' || char(13) || '
there is merely a single climb.'),
(2701, 'KalguuranRune9', 30202, 'We march ever forward.'),
(2702, 'KalguuranRune10', 423, 'Naught else matters.'),
(2703, 'CurrencyRitualBossFragment', 20226, 'On the edge of existence,' || char(13) || '
he watches with ire.'),
(2704, 'CurrencyMastermindBossFragment', 10398, 'Follow the strands of a web to its center,' || char(13) || '
and you''ll find Death lying in wait...'),
(2705, 'RandomContentNamelessSeer', 36668, 'The wanderer waits where' || char(13) || '
the water flows.'),
(2706, 'RandomContentPerandus', 50439, 'The ghostly visage of Cadiro' || char(13) || '
glitters in gold.'),
(2707, 'RandomContentReflectingMist', 50408, 'One small sliver of that' || char(13) || '
primordial lake.'),
(2708, 'RandomContentUniqueVaalSacrifice', 2259, 'An empty hall, but for a' || char(13) || '
choice left by its patron.'),
(2709, 'RandomContentVentorsStrongbox', 45641, 'In the alleys of Sarn, one' || char(13) || '
can place their bets.'),
(2710, 'RandomContentVaalTrader', 49689, 'Outside of time, she offers' || char(13) || '
wares to challenge Order.'),
(2711, 'RandomContentBetrayal', 55176, 'A location revealed with' || char(13) || '
no informant to blame.'),
(2712, 'RandomContentBlueprintWing', 62402, 'An invitation to join a scheme' || char(13) || '
already plotted.'),
(2713, 'RandomContentLogbook', 52767, 'They cannot truly settle, when' || char(13) || '
adventure keeps calling.'),
(2714, 'RandomContentUntaintedParadise', 13214, '[DNT]'),
(2715, 'RandomContentHarvestGrove', 1805, 'The harvest appears unkempt,' || char(13) || '
its crops unruly.'),
(2716, 'QuestLeftReliquaryVaultKey', 53329, 'The true disciple gives all that they are unto God.'),
(2717, 'QuestRightReliquaryVaultKey', 46118, 'The true disciple brings enlightenment to heretics.'),
(2718, 'QuestOssuaryBoneKey', 24557, '[DNT]'),
(2719, 'DivinationCardAvianPursuit', 39039, 'Blazing through the night' || char(13) || '
Longing for infinite flight' || char(13) || '
Awaiting dawn''s first light'),
(2720, 'DivinationCardTemperance', 55982, 'Good things come' || char(13) || '
to those who wait;' || char(13) || '
but, greatness seeks' || char(13) || '
those who do not come.'),
(2721, 'DivinationCardLonelyWarrior', 37595, 'A true warrior fights' || char(13) || '
for those who cannot' || char(13) || '
fight for themselves.'),
(2722, 'DivinationCardToxicTidings', 51292, 'A beast even Einhar' || char(13) || '
will not hunt.'),
(2723, 'UniqueRing86', 123, 'I never knew fear until she was ripped away.' || char(13) || '
My promises were hollow ever after.'),
(2724, 'UniqueAmulet79', 21560, '"You grew up an orphan, and for that, you blame me.' || char(13) || '
Fair enough. So... why not let me erase that pain from your mind?' || char(13) || '
Then we can all stand united against the demons at the door..."'),
(2725, 'UniqueTwoHandAxe17', 34643, 'What began in the stars was settled in blood, beneath an uncaring sky.'),
(2726, 'UniqueAmulet80', 57840, 'In the Atlas, you do not go mad. You are rewritten.'),
(2727, 'UniqueHelmetInt28_', 36574, '"Hate? You speak to me of hate? You have no idea what your persecution inflicts.' || char(13) || '
How it chokes the heart. Withers the soul. Judge me, and you judge yourself."' || char(13) || '
- Saresh, last words, to Sekhema Orbala'),
(2728, 'UniqueBodyDexInt16', 42504, 'Those devoted to the Dreamer pursue' || char(13) || '
perfection of the body and the will.'),
(2729, 'UniqueStaff35', 16992, 'We shared a memory of your mother,' || char(13) || '
a memory of roses, of autumn.' || char(13) || '
One day, I will be but a memory as well,' || char(13) || '
but I will never leave your side.'),
(2730, 'UniqueBodyDexInt17', 24121, 'Eaten away by anxiety and fear,' || char(13) || '
nothing remained but the void.'),
(2731, 'UniqueSceptre26', 21548, 'Over the course of a lifetime, Cadigan the First' || char(13) || '
conquered every city-state on Middengard one by one,' || char(13) || '
continually leveraging the power of each against the next.'),
(2732, 'UniqueHelmetStrInt23', 59830, '[DNT] It is not difficult to accept their lack of introspection as faith when you know their sacrifice is more meaningful than their belief'),
(2733, 'UniqueHelmetStrInt24', 50247, 'The pain of solitude can be endured, but' || char(13) || '
the pain of heartbreak might just destroy us.'),
(2734, 'UniqueAmulet81', 45666, '"In a time of great need, the tale-man sacrificed his very' || char(13) || '
body to bring forth the waters of victory and salvation."'),
(2735, 'UniqueTwoHandMace14', 23877, '[DNT] Few can stand before calamity with faith unbroken'),
(2736, 'UniqueTwoHandMace15', 15999, '"Sacred water has no power of its own, and yet' || char(13) || '
holds the greatest strength of all... it can carry' || char(13) || '
what we give it. What we sacrifice for each other."' || char(13) || '
- Rashi, Grand Daiyata of the Sel Khari'),
(2737, 'UniqueTwoHandMace16', 60544, '"All men must drink. Deny us water,' || char(13) || '
and we shall have blood instead."' || char(13) || '
- Rukh, of the Afarud'),
(2738, 'UniqueWand23', 63148, 'Beyond the edge of existence, there' || char(13) || '
shines violet, naught but pain...' || char(13) || '
one lantern carries a single flame.'),
(2739, 'UniqueHelmetInt29', 53107, '[DNT] Some things are better left unaware of themselves'),
(2740, 'UniqueWand22', 32744, '"Waging war is a simple matter of geometry and death."' || char(13) || '
- Trinian, Intellectus Prime'),
(2741, 'UniqueGlovesDexInt21', 14331, 'Napuatzi was meant as a sacrifice to the snakes.' || char(13) || '
Instead, they offered themselves... as weapons.'),
(2742, 'UniqueGlovesDexInt22', 47796, 'We moved to be close, yet grew no closer, since the' || char(13) || '
Breaking of the Sun. We clung to the feet of the Lords,' || char(13) || '
wailing, weeping, begging for unity. Now, they heed. '),
(2743, 'UniqueGlovesDex8', 47038, '"Our flesh is mere machinery;' || char(13) || '
chemicals and mechanisms.' || char(13) || '
Drink deeply. Fuel the fire."'),
(2744, 'UniqueGlovesInt12', 21256, '"You''ll feel no pain. All you have to do is run toward' || char(13) || '
High Templar Andronicus, and we''ll let your family go."' || char(13) || '
- Morengen, of the Brotherhood of Silence'),
(2745, 'UniqueGlovesStrDex16', 8711, '[DNT] As life escapes you, everything feels cold'),
(2746, 'UniqueShieldDex10', 49410, '[DNT] Her love was trapped somewhere distant, but the pain reminds me'),
(2747, 'UniqueShieldInt17', 38758, 'He raised the greatest army Trarthus had ever seen... against' || char(13) || '
Bardiya''s orders, they ravaged and pillaged without mercy.'),
(2748, 'UniqueShieldStr15', 50394, '"A tale-woman passed through here not long ago.' || char(13) || '
Taught us a thing or two. We''re not going to execute' || char(13) || '
you for what you''ve done... no. You''ve a debt to repay."'),
(2749, 'UniqueShieldStrDex16', 45830, 'We isolate ourselves to hide our long-held pain.' || char(13) || '
We lash out, when all we want is an end to loneliness.'),
(2750, 'UniqueMercenaryShieldDex1', 41012, '"Keita expects an assassination attempt by stealth or subterfuge.' || char(13) || '
I say we attack head-on, like madmen. Let the fates decide."' || char(13) || '
- Azadi, first ancestor of the House Azadin'),
(2751, 'UniqueMercenaryBootsInt1', 6332, 'The grave insult had to be answered; in a mystic flash,' || char(13) || '
Bardiya crossed the room and struck Cyaxan.' || char(13) || '
Thus began the War of the Great Families.'),
(2752, 'UniqueMercenaryHelmetStr1', 46609, '"Our new capital will be called Korathin.' || char(13) || '
My slaves will build it. My price is dominion...' || char(13) || '
or blood." - Keita''s Proclamation, 872 IC'),
(2753, 'UniqueMercenaryBelt1', 2214, 'What once marked his submission became the tool of his defiance - torn from the lash of House Keita.'),
(2754, 'UniqueMercenaryGlovesStrInt1', 48799, '"The followers of Light recognize Tyndarus Phrecius as' || char(13) || '
the Emperor. For siding with the rebels, you and your' || char(13) || '
brothers shall be cast out from the true faith, forevermore!"' || char(13) || '
- High Templar Andronicus, 892 IC'),
(2755, 'UniqueQuiver21', 29969, 'Ensconced in the pulsing core of the Beast,' || char(13) || '
Malachai reached out for control of all living things.'),
(2756, 'UniqueBelt52', 18641, '"I weep not for myself, but for the truth of what we are.' || char(13) || '
It rots away inside all of us, the darkness within. They blame' || char(13) || '
me, but I am merely the prophet, the one who sees the black."'),
(2757, 'UniqueRing87', 31637, 'In truth, your terror is cold' || char(13) || '
You mask it with heat and ire' || char(13) || '
But they know.' || char(13) || '
They know.'),
(2758, 'UniqueRing88', 23921, 'It is not a wound caused by an enemy that bites us twice.' || char(13) || '
It is the smile, the nod... the handshake... of a former friend.'),
(2759, 'UniqueRing89', 63179, '[DNT] Sometimes we hold on when we should let go'),
(2760, 'UniqueAmulet82_', 50302, '[DNT] We are many, we are all, we are one'),
(2761, 'UniqueAmulet83', 34605, 'We cannot hide from the wounds of youth.' || char(13) || '
They fuel the fires within, driving us on.'),
(2762, 'UniqueAmulet84', 38852, 'Hills of stark and jagged white it walks,' || char(13) || '
scratching your ribs without, within.' || char(13) || '
The Fiend has naught but Empty Eyes,' || char(13) || '
though sees you, it does, indeed.'),
(2763, 'UniqueFlask36', 5680, '"Let us share our thirsts. Yours, for power,' || char(13) || '
and mine, for death. A stable alliance,' || char(13) || '
so long as you never speak my name..."'),
(2764, 'UniqueRing90', 19191, '"Worry not, my friend, that I tour in fineries.' || char(13) || '
The ostentation is all part of being a Perandus.' || char(13) || '
As long as I maintain my Vigilance,' || char(13) || '
nothing can harm the Empire... or me."' || char(13) || '
- Emperor Chitus, to Ondar'),
(2765, 'UniqueStaff36', 16333, '"I have risked everything. My position, my ambition, my' || char(13) || '
very life. There has to be a way to save our people. If we' || char(13) || '
must, let us tear apart the very foundations of reality!"'),
(2766, 'UniqueBodyStr15', 35967, '[DNT] Coming Soon'),
(2767, 'UniqueBelt53', 34386, '[DNT] Coming Soon'),
(2768, 'UniqueBelt54', 23938, 'Motion, purpose... craft. The fruits of my mind laboured' || char(13) || '
to build my wildest imaginings, never tiring, never faltering.' || char(13) || '
Life... or something like it, engineered in its image.'),
(2769, 'UniqueBootsStr15', 55630, '[DNT] Coming Soon'),
(2770, 'UniqueBootsStr16', 40613, '[DNT] Coming Soon'),
(2771, 'UniqueRing91', 60512, 'Madness crawls under the skin,' || char(13) || '
bursting forth from the flesh.'),
(2772, 'UniqueRing92', 46812, 'They seek that which lies before them, shining' || char(13) || '
Yours is a special curse, nipping at your heels' || char(13) || '
Driving you on long past agony and despair'),
(2773, 'UniqueRing93', 3663, 'The old wound lurks deep within,' || char(13) || '
never healing, never relenting,' || char(13) || '
making every smile half-hearted.'),
(2774, 'UniqueRing94a', 44856, 'They hide in deep places, and hidden places,' || char(13) || '
but stillness will find them... and bury them.'),
(2775, 'UniqueRing94b', 39544, 'They dance and scream under the Broken Sun' || char(13) || '
as spiraling oblivion deepens into flame.'),
(2776, 'UniqueRing94c', 13961, 'They whisper in the dark, building towers of' || char(13) || '
mindless thought that seek a hollow truth.'),
(2777, 'UniqueRing94d', 9939, 'They move and coil, gripped by painful ecstasy,' || char(13) || '
all meaning long since lost to dead-eyed lust.'),
(2778, 'UniqueRing94e', 34712, 'They dream no longer, strive no longer,' || char(13) || '
feel no longer. They dream only of' || char(13) || '
continuing to dream, and know not why.'),
(2779, 'UniqueRing95', 8561, 'All gates are closed.' || char(13) || '
All dreams are silenced.' || char(13) || '
What could have been...'),
(2780, 'UniqueQuiver22', 26857, 'Enacting a grand vision requires cold-hearted sacrifice.' || char(13) || '
The loyal must be no more than fodder against the unwilling.'),
(2781, 'UniqueBodyStrDex9', 41815, '"The Greatwolf is with us! Gaius Sentari' || char(13) || '
flees! Let us give chase, for today, my' || char(13) || '
brothers and sisters, we are finally free!"'),
(2782, 'UniqueOneHandMace13', 35342, '"We must be ready. We are the voice of Wraeclast''s vengeance,' || char(13) || '
tolling righteous fury for those who would dare invade our world!"' || char(13) || '
- Ailith, First of the Keepers'),
(2783, 'UniqueJewel184', 58256, 'The future weaves ever forward, twisting into itself forever,' || char(13) || '
driven by the passions and tragedies of those who seek.'),
(2784, 'DivinationCardRunicLuck', 5268, 'If you believe hard enough,' || char(13) || '
you''ll win.'),
(2785, 'DivinationCardLastStand__', 45580, 'Return with your shield...' || char(13) || '
or on it.'),
(2786, 'DivinationCardDamnation', 48985, 'Blood and death lead' || char(13) || '
the way to hell.'),
(2787, 'DivinationCardWhenCurrentsBlaze', 30806, 'In their fiery union,' || char(13) || '
the storm left the rivers' || char(13) || '
forever changed.'),
(2788, 'DivinationCardHistory', 48407, 'The future is oft-foretold' || char(13) || '
in records of the past.'),
(2789, 'TulNormalRing', 64752, 'We lie eternal, eyes open, yet still.'),
(2790, 'XophNormalRing', 39764, 'The embers of the Red Pyre yet glow.'),
(2791, 'EshNormalRing', 56116, 'Metallic thoughts whisper in the dark.'),
(2792, 'UulNetolNormalRing', 6863, 'Our flesh longs to move as one.'),
(2793, 'ChayulaNormalRing', 25396, 'We will seize back our wayward Dream.'),
(2794, 'HiveBrainNodeFlavourText', 31778, 'Countless voices murmur,' || char(13) || '
singing of the Hive...'),
(2795, 'DivinationCardTheLastLaugh', 46052, '<size:24>{Holding fast when shadows fall,' || char(13) || '
Over ruins, jesters call.' || char(13) || '
Nothing breaks their twisted cheer,' || char(13) || '
Kings of chaos, friends sincere.}'),
(2796, 'DivinationCardTheLake____', 863, 'Gaze upon the Lake' || char(13) || '
Gaze upon your Reflection' || char(13) || '
Your full Potential'),
(2797, 'DivinationCardOneLastScore', 36772, '<size:30>{You want to know how' || char(13) || '
I haven''t been caught? ' || char(13) || '
It''s not just speed.' || char(13) || '
You need some luck.}'),
(2798, 'DivinationCardBoundByFlame', 37349, '<size:30>{In battle we burn together' || char(13) || '
or not at all.}'),
(2799, 'DivinationCardOutfoxed', 18984, 'The prize vanished. ' || char(13) || '
No trail, no struggle.' || char(13) || '
Just a single, rust-red hair.'),
(2800, 'UniqueBelt55', 23607, '"When we first saw the Sun, our eyes were not above,' || char(13) || '
but on her. She was the burning heart of fury, and the' || char(13) || '
dead turned to flee. We drove them beneath for all time."'),
(2801, 'UniqueBelt56', 48522, '"I staggered on, dying of thirst... I thought I found respite,' || char(13) || '
but no... it was a pit of newborns... dry and hollow...' || char(13) || '
and they screamed still, begging me for vengeance..."' || char(13) || '
'),
(2802, 'UniqueStaff37', 34476, 'Before they ''saved'' their beloved leader, the Afarud' || char(13) || '
tested their ritual on a dying man... but they made' || char(13) || '
a fatal mistake. They did not bind him to an object.'),
(2803, 'UniqueAmulet85', 2134, '"We fought the Abyssals, too. That''s the part they leave out.' || char(13) || '
Khatal was Faridun... and for saving all their lives, the Maraketh' || char(13) || '
made him drink the enemy''s blood. He melted from the inside out."' || char(13) || '
- Toryal, of the Afarud'),
(2804, 'UniqueRing96_', 29543, '"Sasan tells a tale of robbery, and accosting a' || char(13) || '
Bardiyan princeling on the road. If that were' || char(13) || '
true, why hasn''t he sold the damn thing already?' || char(13) || '
Why does he still wear it like a shameful secret?"'),
(2805, 'UniqueRing97', 16736, '"I designed this to protect you,' || char(13) || '
whatever you may face. And when' || char(13) || '
this is all over... let''s talk."'),
(2806, 'UniqueSceptre27', 38287, 'A future of untold power and doom opened' || char(13) || '
before Zarokh in that moment. He realised' || char(13) || '
there was not one Time, but many...'),
(2807, 'SupportGemGreaterSpellCascade', 45492, 'The echoes of lost loved ones surrounded her,' || char(13) || '
maddeningly close, but forever out of reach.'),
(2808, 'SupportGemEclipse', 30471, '"Although we are two bodies, we are of one mind, one heart, drifting' || char(13) || '
through the cosmos, in search of purpose. The moment we cross paths,' || char(13) || '
both fleeting and eternal, our eyes are opened to our potential."'),
(2809, 'SupportGemInvertTheRules', 8280, '"She fled from the prison of her birth, drawn by the breaking' || char(13) || '
of that great Silence. At that moment, the universe was changed,' || char(13) || '
and walls that were once impenetrable became brittle.' || char(13) || '
A fortress became a shell, and she alone escaped."'),
(2810, 'SupportGemCastOnWardBreak', 41129, '"Prove yourself! Are you a knave, or a knight?' || char(13) || '
I shall know by the strength of your blows!"'),
(2811, 'SupportGemWard', 4980, 'Uhtred was remembered as a traitor, but it was he that unearthed' || char(13) || '
the only way out. The survivors found themselves in an unfamiliar' || char(13) || '
forest.  Strangely, a third were not present, including Uhtred himself.'),
(2812, 'SupportGemVaalSacrifice', 1758, 'Under Atziri, sacrifice was a ruthless and efficient science.' || char(13) || '
Her people were willing to give everything... and they did.'),
(2813, 'SupportGemGreaterSpellEcho', 791, 'She gazed into the mirror...' || char(13) || '
and the mirror gazed back.'),
(2814, 'SupportGemVaalTemptation', 10034, '"If Chaos offers you a deal, challenger,' || char(13) || '
think deeply before you accept."'),
(2815, 'SupportGemMachinations_', 57401, '"My master enjoys the strange, and the unexpected.' || char(13) || '
I''m sure you can think of a few ways to entertain them."'),
(2816, 'SupportGemPyre_', 2115, 'A vast pillar of hands embraces a charred sky.' || char(13) || '
Within burns a beam of purest heat.'),
(2817, 'SupportGemBonespire', 43970, 'In its madness, Xesht desperately seeks communion.'),
(2818, 'SupportGemFoulgrasp', 8480, '"Words without thought drive us' || char(13) || '
to claw and scrabble in the dirt,' || char(13) || '
seeking respite found only in pain."'),
(2819, 'SupportGemHiveborn', 41944, '"We spill forth, cleaving our flesh' || char(13) || '
to theirs, until we become one."'),
(2820, 'SupportGemScornfulHerald_', 24912, 'Her bitterness blinded her to the true price of immortality.' || char(13) || '
Let Wraeclast burn and be devoured, she told herself...' || char(13) || '
and only herself, for centuries without end.'),
(2821, 'SupportGemCullTheWeak', 45218, '"Beidat is the lesser of three evils. The other two desire only' || char(13) || '
to consume us, but under him, there is a chance to survive...' || char(13) || '
a chance to serve... if you can prove yourself useful."'),
(2822, 'SupportGemGreaterAncestralCall', 56496, '"I believe the Halls of the Dead are secretly a' || char(13) || '
training ground. One day, we will be called' || char(13) || '
forth to stand and fight against a great tide."'),
(2823, 'SupportGemFissure', 19736, '"Oh yes, K''Tash understands you. It has a keen swarm-mind' || char(13) || '
somewhere within its multitudes. It hears your pleas, but' || char(13) || '
ignores them... because it hates you with a burning fury."'),
(2824, 'SupportGemHextoad', 11350, '"A warlock like myself knows that even the most abominable' || char(13) || '
plagues are part of the cycle of life and death. From that ruination,' || char(13) || '
new life will emerge, and that life will kill, and so on..."'),
(2825, 'SupportGemHexpass', 28056, '"Your wards and your charms are meaningless' || char(13) || '
to one who knows your true name."'),
(2826, 'SupportGemGreaterFork', 25737, 'Lioneye earned his moniker by killing' || char(13) || '
three men with a single arrow.'),
(2827, 'SupportGemGreaterChain_', 4613, '"We are all connected. Each of us burns with the same fire.' || char(13) || '
Queen Hyrri knew that... she chooses to battle still, somewhere' || char(13) || '
beyond Hinekora''s sight. There must be a very good reason."'),
(2828, 'SupportGemLethalDose', 37132, '"They cast me into a pit of vipers, and' || char(13) || '
that is where I found my true self."'),
(2829, 'SupportGemCompanionship', 56569, 'The Black Sekhema was a formidable fighter' || char(13) || '
alongside her dekhara, but she was unstoppable' || char(13) || '
when she fought atop her trusted mount, Shiyo.'),
(2830, 'SupportGemDivineSentinel', 58580, '"The world will never know our sacrifice, but' || char(13) || '
we will stand and fight for as long as it takes!"'),
(2831, 'SupportGemAnnihilation', 13695, 'Those citizens of Oriath touched by the' || char(13) || '
roving storms died most horrible deaths.'),
(2832, 'SupportGemEdify', 1434, '"You were the best of us, Sirus. Fighting alongside' || char(13) || '
you made me better. I will always miss you."'),
(2833, 'SupportGemInvention', 59220, '"The direct approach failed. So be it. In my crusade' || char(13) || '
to protect Wraeclast, I must take... a longer view."'),
(2834, 'SupportGemGreaterKineticInstability', 51610, '"Accusations fly. Sinner! Heretic! I am but an initiate, and my patron urges' || char(13) || '
silence. We will keep our heads down while one High Templar supplants' || char(13) || '
another. It''s all about power, my patron whispers, and we have none..."'),
(2835, 'SupportGemCooldownRecovery', 14222, '"The science is... incomprehensible at best. Nearest I can tell, the Arcana exhibits' || char(13) || '
a blast of wrath once it has been fully charged, and when directed at the Elder' || char(13) || '
will force it to take on the form it held before it entered our dimension."'),
(2836, 'SupportGemVoidstorm', 27311, '"Not even stopping to look behind, I dove through the shimmering window...' || char(13) || '
With not a minute to waste, I took a nearby tool and jammed it into the infernal' || char(13) || '
device, where it hummed, ominously entrenched in my laboratory floor."'),
(2837, 'SupportGemVoidShockwave', 42780, 'The Elder''s influence yet lingers' || char(13) || '
in the darkest corners of Wraeclast.'),
(2838, 'SupportGemEldritchBlasphemy', 15365, 'Even trapped in stone, the Elder''s shadow lingered' || char(13) || '
in their hearts and coiled around their dreams.'),
(2839, 'SupportGemGluttony', 44619, 'Champions of the Tangle are driven to seek' || char(13) || '
sustenance for their master; should they fall' || char(13) || '
behind, they would soon be consumed as well.'),
(2840, 'SupportGemOverheat', 43796, 'No walls can stand against its gaze. No fortress,' || char(13) || '
no cave, no mountain. Better to die fighting.'),
(2841, 'SupportGemGreaterMultistrike', 56717, 'Zana watched in awe as her father spoke. With each word,' || char(13) || '
he seemed to grow larger and more frightening, drawing' || char(13) || '
increasingly fervorous responses from his rapt audience.'),
(2842, 'SupportGemCongregation', 59083, '"I have a recurring nightmare... I run...' || char(13) || '
I scream... but only the dead hear me..."'),
(2843, 'SupportGemFrostmage', 31766, 'Her understanding of the Atlas was not innate. The' || char(13) || '
more committed she became to understanding it,' || char(13) || '
the more the knowledge weighed on her.'),
(2844, 'SupportGemGreaterDevour_', 43614, 'A High Templar''s fear consumed her entire life,' || char(13) || '
so she cast aside her own, to do what must be done.'),
(2845, 'SupportGemMagnetism', 19138, 'The dominance of the Templars left an indelible mark.' || char(13) || '
Zana would ever after stand guarded in their presence.'),
(2846, 'SupportGemGreaterUnleash', 5178, '"True power grows with patience. You must nurture it.' || char(13) || '
You learn what it needs. You provide. You wait. Only' || char(13) || '
then, when it is ripe, does it yield its fruits."'),
(2847, 'SupportGemPacifism', 25564, '"My people refused to take part in the ills of Wraeclast.' || char(13) || '
They were called primitives by some, and cowards by' || char(13) || '
others... but they are gone, and we still remain."'),
(2848, 'SupportGemBloodsoakedBanner', 36839, '"The history of Wraeclast is marked by bloody conflicts. The rise' || char(13) || '
and fall of empires. Man slaughtered man, never suspecting the' || char(13) || '
madness lurking under the surface might not have been innate."'),
(2849, 'SupportGemMinionPact', 16588, 'Catarina envisioned a Wraeclast of disparate societies united.' || char(13) || '
That diversity would empower the Syndicate - and the increased' || char(13) || '
number of dispensible bodies was a convenient coincidence.'),
(2850, 'SupportGemHarrowingThrong', 9195, 'Catarina envisioned a Wraeclast of disparate societies united.' || char(13) || '
That diversity would empower the Syndicate - and the increased' || char(13) || '
number of dispensible bodies was a convenient coincidence.'),
(2851, 'SupportGemUnholyTrinity', 29716, 'It was a delicate balancing act for Malachai to ensure the loyalty' || char(13) || '
of his three students - each as ambitious as they were depraved.'),
(2852, 'SupportGemOverloadedIntensity', 1332, '"I didn''t design it to overload... let''s call it a happy little accident!"'),
(2853, 'SupportGemTransfusion', 54147, 'Let the eternal scream within' || char(13) || '
flow from your weeping blood.'),
(2854, 'SkillGemPactOfBeidat', 12787, 'Wield the gifts of Beidat, luminary of the pale unseeing,' || char(13) || '
whose honeyed words bore tunnels through pliant minds.'),
(2855, 'SkillGemPactOfGhorr', 1344, 'Offer yourself to Ghorr, the gluttonous, the cage of' || char(13) || '
flesh trapping souls in the cycle of consumption.'),
(2856, 'SkillGemPactOfKtash', 35775, 'Unleash the fury of K''Tash, incarnation of hate.' || char(13) || '
Endless bodies burn beneath the flames of his pursuit.'),
(2857, 'SkillGemPactOfLycia', 49031, 'Call upon Lycia, conduit of the Scourge. She forfeit' || char(13) || '
her soul for the power to condemn lies told by bones.'),
(2858, 'FaridunBossKey', 58371, '"Darkness lurks within us all. The void from beyond' || char(13) || '
Time ever seeks to reclaim what we have stolen. Do' || char(13) || '
you think your fate will be any different from mine?"'),
(2859, 'CoinRestoration', 26266, '"Drain away the sands of Time,' || char(13) || '
restore that which is now mine!"'),
(2860, 'CoinDesecration', 30019, '"The supposed heroes of history now rot.' || char(13) || '
I am alive, and I choose my own destiny."'),
(2861, 'CoinKnowledge', 37802, '"Power and skill can be outsmarted...' || char(13) || '
I wish for intellect beyond compare."'),
(2862, 'CoinPower', 3684, '"Knowledge and speed are useless without the' || char(13) || '
strength to wield them. I wish for power!"'),
(2863, 'CoinSkill', 42788, '"Strong and slow, clever and weak. I fear neither.' || char(13) || '
I wish for the skill to overcome them both."'),
(2864, 'UniqueJewel185', 23960, 'They believed themselves courageous and selfless,' || char(13) || '
but that bravery became the doom at their door.'),
(2865, 'BlightedLands', 33970, 'The ancient will of the Blightheart' || char(13) || '
festers and spreads...'),
(2866, 'UtzaalArena', 59887, 'In the outskirts of a lost city,' || char(13) || '
face the ultimate challenge...'),
(2867, 'DomainTimelessFlavour', 32799, 'In the heart of a true warrior,' || char(13) || '
the war never ends.'),
(2868, 'SanctuaryMapFlavour', 30435, 'Belief and despair battle eternal.' || char(13) || '
Truth and heresy are one.'),
(2869, 'CitadelMapFlavour', 48453, 'Their courage and heroism' || char(13) || '
became their downfall.'),
(2870, 'FortressMapFlavour', 25227, 'Machinery is merely the shaping' || char(13) || '
of reality by the mind.'),
(2871, 'AbominationMapFlavour', 19662, 'Each of us are destined' || char(13) || '
to do what we do... forever.'),
(2872, 'ZigguratMapFlavour', 22041, 'She who gazes into the' || char(13) || '
Abyss must take care...'),
(2873, 'ReliquaryVaultFlavour', 31041, 'All we hold dear awaits us.' || char(13) || '
We must merely reach out.'),
(2874, 'AtziriAtlasNodeFlavour', 32932, 'In a realm of crimson madness,' || char(13) || '
the Queen lives on.'),
(2875, 'ShaperAtlasNodeFlavour', 25137, 'You must let me go, my daughter...' || char(13) || '
I am but a ghost, now. A memory...'),
(2876, 'ElderAtlasNodeFlavour', 36749, 'The cosmos birthed from nothing,' || char(13) || '
and to nothing it shall Decay.'),
(2877, 'SirusAtlasNodeFlavour', 7686, 'What remains when all' || char(13) || '
else is stripped away?'),
(2878, 'ValdoMapFlavour', 18665, 'Some dreams are too broken to fix.' || char(13) || '
Let broken realities lie dormant.'),
(2879, 'SacredGroveFlavour', 39702, 'The four bloods of Wraeclast' || char(13) || '
run deep and vibrant.'),
(2880, 'AtzoatlNodeFlavour', 50959, 'A monument to hubris,' || char(13) || '
in more ways than one.'),
(2881, 'LegionFragmentKarui', 26305, 'The unmatched discipline of the Karui...'),
(2882, 'LegionFragmentMaraketh', 44775, 'The strategic heights of the Maraketh...'),
(2883, 'LegionFragmentEternal', 20718, 'The relentless brutality of the Eternals...'),
(2884, 'LegionFragmentTemplar', 9426, 'The bludgeoning faith of the Templars...'),
(2885, 'LegionFragmentVaal', 32367, 'The boundless thaumaturgy of the Vaal...'),
(2886, 'DivinationCardTheEverlasting', 14062, 'The Atlas invites us all' || char(13) || '
to a lifelong journey.' || char(13) || '
It would be unwise' || char(13) || '
to overstay our welcome.'),
(2887, 'DivinationCardLuckyBastion', 61785, 'Discipline forged our unbreakable Rampart.' || char(13) || '
Bastion against Despair.'),
(2888, 'DivinationCardTheMiracle', 35760, 'Despite arriving early,' || char(13) || '
her silly seraphim' || char(13) || '
couldn''t be happier.' || char(13) || '
Octavia, 2023'),
(2889, 'DivinationCardApocalypse', 60499, '<size:24>{The Ezomytes,' || char(13) || '
buried beneath flaming mountains' || char(13) || '
by the First Ones.' || char(13) || '
The Vaal,' || char(13) || '
undone by a cataclysm' || char(13) || '
of their own making.' || char(13) || '
Are all empires fated to fall to hubris?}'),
(2890, 'DivinationCardTheSlumberingBeast', 14523, 'He slumbers...' || char(13) || '
But soon he will awaken.'),
(2891, 'DivinationCardTheForbiddenFruit', 35167, 'It''s about working smarter,' || char(13) || '
not harder.'),
(2892, 'DivinationCardTheSillyBoy', 8902, 'From silly pondering' || char(13) || '
comes legend,' || char(13) || '
and from legend,' || char(13) || '
horned fortune'),
(2893, 'DivinationCardTheReflectionoftheHeart', 36978, 'He thought she was all' || char(13) || '
he ever wanted,' || char(13) || '
yet his heart yearned' || char(13) || '
for something more.'),
(2894, 'UniqueShieldStrDex10', 12013, 'On the Kraken''s Rot, there was no whipping.' || char(13) || '
No lashes. Only barnacle-scraping duty.'),
(2895, 'UniqueStaff38', 17677, 'The experienced sailor knows the true mystery of the sea:' || char(13) || '
why, on every continent, in every lagoon, does there skitter' || char(13) || '
a crab of new size and colour? Not related, not lost spawn,' || char(13) || '
but a clawed snapper all of its own make and temperament...'),
(2896, 'UniqueFlask37a', 43623, 'There was no grand contest or battle with Tasalio that day.' || char(13) || '
Captain Brinehook Vex drank and sang merry with Karui warriors' || char(13) || '
on the high seas. Only later did he realise who he had met.'),
(2897, 'UniqueFlask37b', 58237, 'On that fateful day, beset by tempest, Captain Brinehook Vex' || char(13) || '
came face to face with the blustering Karui god of thunder,' || char(13) || '
Valako himself. A wager was had, and a wager was won.'),
(2898, 'UniqueBodyStrInt16', 28810, '"We huddle in the fading light of our candles,' || char(13) || '
begging the darkness to leave us in peace...' || char(13) || '
but what if we joined Him, and left fear behind?"'),
(2899, 'UniqueShieldInt18', 5236, '"This infernal imp wasn''t willing to part with its piece of the Allflame.' || char(13) || '
It''s taught me ways to stoke the flame. To burn unnaturally fierce.' || char(13) || '
The imp may have the Allflame, but I have the imp."' || char(13) || '
- Velka, the Tide Witch'),
(2900, 'UniqueAmulet86', 34525, '[DNT] Flavourful Text'),
(2901, 'UniqueJewel186a', 6623, 'He lusts for retribution, but his' || char(13) || '
captors are long since dust.'),
(2902, 'UniqueJewel186b', 32527, 'He lusts for the Fall of Night,' || char(13) || '
but it will cost him everything.'),
(2903, 'UniqueJewel186c', 64303, 'He lusts for power over his former' || char(13) || '
slavers, but he will never be free.'),
(2904, 'UniqueJewel186d', 64078, 'He lusts for a crown and a scepter,' || char(13) || '
but he destroys all he touches.'),
(2905, 'UniqueJewel186e_', 9555, 'He who was made has but one desire: inflict his' || char(13) || '
malady upon the Boundless Cavern above.'),
(2906, 'UniqueHelmetStrInt26', 33073, 'A lich may lust for vengeance, power,' || char(13) || '
darkness, or dominion, but it is their' || char(13) || '
nature. They can never be satisfied.'),
(2907, 'UniqueTwoHandAxe18', 26010, '"Not all the Abyssals serve the Lich Lords.' || char(13) || '
Some serve themselves, living off stolen' || char(13) || '
flesh and bone from those they... eat."'),
(2908, 'DeepwaterUpgradePiece1', 60022, 'Breathe life into dying embers. Turn not from their emerald hue.'),
(2909, 'DeepwaterUpgradePiece2', 1335, 'Life springs eternal in the darkest depths of the ocean.'),
(2910, 'DeepwaterUpgradePiece3', 23593, 'Restore that which was lost. Watch it burn anew.'),
(2911, 'DeepwaterUpgradePiece4', 12271, 'Essence of undeath, refined and distilled.'),
(2912, 'DeepwaterUpgradePiece5', 48520, 'Secrets from below... now yours to do with as you will.'),
(2913, 'UniqueOneHandSword36', 3959, '"Dread Captain''s a title, boy. Taken, not earned.' || char(13) || '
From Brinehook Vex on down to the Piratebane' || char(13) || '
himself. Beware. That cutlass has no allegiance."'),
(2914, 'SupportGemAbyssalWell', 4100, 'Velka reached out her hand. One touch and she' || char(13) || '
folded, screaming, clawing desperately at her back' || char(13) || '
as the crustaceous gift burst itself from her spine.'),
(2915, 'UniqueHelmetDexInt18', 27514, 'The High Templar sought sight beyond the mortal plane.' || char(13) || '
He feared no pain but that of touching greatness,' || char(13) || '
only to let it slip through his grasp.' || char(13) || '
'),
(2916, 'Talisman5_1', 30322, '"With the Winter Curse held at bay, Lysanda' || char(13) || '
and her Knights pursued the fell power that' || char(13) || '
had sent it... a Hag who made her lair in a' || char(13) || '
Tower that was ancient beyond ancient."'),
(2917, 'Talisman5_2', 56200, '"They bound the Hag of the Winter Curse' || char(13) || '
and set her alight, to no avail. Her cackle' || char(13) || '
was gleeful and wicked. Even if they slew' || char(13) || '
her, she boasted, she had many daughters..."' || char(13) || '
'),
(2918, 'Talisman5_3', 23513, '"Lysanda roared, and hacked the Hag apart' || char(13) || '
limb by limb, not stopping until the deed' || char(13) || '
was done. Her daughters, however, were' || char(13) || '
spared... and tasked with service and duty."'),
(2919, 'Talisman5_4', 22237, '"With the Hag''s daughters easing the climate,' || char(13) || '
an age of plenty and bounty began. Lysanda' || char(13) || '
revived the Phaaryl tradition of the hunt,' || char(13) || '
so the people never forgot their roots."'),
(2920, 'Talisman5_5', 50184, '"The first city was completed, and others sprouted.' || char(13) || '
The clans came together to declare Lysanda of Myr' || char(13) || '
the Queen. Henceforth, they became known as the' || char(13) || '
Ezomytes of Myr, and their numbers swelled."'),
(2921, 'AbyssPinnacleNodeFlavour', 48135, 'The dormant carrier lies' || char(13) || '
still as death.'),
(2922, 'Talisman5_6', 39042, '"There began an eternal summer, as the' || char(13) || '
daughters of the Hag perfected their mastery' || char(13) || '
of the Tower. The forests became as gardens.' || char(13) || '
The hungry had only to pick a fruit and eat."'),
(2923, 'Talisman5_7', 16036, '"Twenty-two years into Lysanda''s reign, the' || char(13) || '
Spiders swarmed from out of the dark. Her' || char(13) || '
Knights were ill-equipped for this foe, and' || char(13) || '
the people fled in droves, seeking safety."'),
(2924, 'Talisman5_8', 9836, '"As deadly and dangerous creatures were' || char(13) || '
culled, the Queen chose to leave those' || char(13) || '
that were docile or beauteous. Tide pools' || char(13) || '
became known as places of wonder."'),
(2925, 'Talisman5_9', 53657, '"Decades into Lysanda''s reign, the' || char(13) || '
lands of the Ezomytes of Myr slowly' || char(13) || '
became known as Ezo De Myr, and' || char(13) || '
then simply Ezomyr. And so it was."'),
(2926, 'Talisman5_10', 46130, '"Ezomyr grew on a foundation of' || char(13) || '
choice. Its climate was chosen. Its' || char(13) || '
animals were chosen. For once,' || char(13) || '
Wraeclast was not harsh, but kind."'),
(2927, 'Talisman5_11', 16494, '"The sea calmed, and contact was' || char(13) || '
renewed with the Isles of Skothe.' || char(13) || '
It was said that Craiceann had' || char(13) || '
given a blessing to the people."'),
(2928, 'Talisman5_12', 15768, '"The Spiders that had been driven' || char(13) || '
back by the Blue Knight now sought' || char(13) || '
peace and cooperation. It was said' || char(13) || '
that Fenumus had commanded it."'),
(2929, 'Talisman5_13', 35663, '"The skies were clear and blue, yet' || char(13) || '
brought rains when needed. It was' || char(13) || '
said that the people had proven' || char(13) || '
themselves to Saqawal and his flocks."'),
(2930, 'Talisman5_14', 61981, '"Forty-six years into her reign, Lysanda' || char(13) || '
slew the last deadly creature. She smiled,' || char(13) || '
took a wineskin, and rode off into the forest.' || char(13) || '
One last hunt, it was said. Farrul would stalk' || char(13) || '
by her side, in this life... and the next."'),
(2931, 'Talisman5_15', 19220, '"There are some stories that may never' || char(13) || '
be known, never be heard. But to history,' || char(13) || '
I say, let it be known the the Ezomytes' || char(13) || '
of Myr persevered... and built a home."'),
(2932, 'UniqueRing98', 42065, '"Velka was a mere pirate when she ventured to Tsoatha,' || char(13) || '
a reverence for the Brine King burning in her heart.' || char(13) || '
She returned as something different. Something more.' || char(13) || '
So the legend of the Tide Witch is told."'),
(2933, 'UniqueAmulet87', 33159, 'Betrayal bites cold as a southerly wind,' || char(13) || '
Thunder heralds the coming storm,' || char(13) || '
On her day of mutiny, the Rotmother sinned,' || char(13) || '
A brother burned, a bond forsworn'),
(2934, 'UniqueBelt57', 26954, 'A pact is a debt which both sides repay. For a human to' || char(13) || '
barter an alliance in their favour... extraordinary.'),
(2935, 'AbyssPinnacleKeyMurderous_', 25189, 'A sliver of his wrath, a bodiless roar...'),
(2936, 'AbyssPinnacleKeySearching__', 48034, 'His grasp, severed from his spark...'),
(2937, 'AbyssPinnacleKeyHypnotic', 36796, 'A mote of his desire, contained without...'),
(2938, 'AbyssPinnacleKeyGhastly_', 47832, 'Peer into his dominion, the lightless void...'),
(2939, 'DeepwaterBlankCurrency_', 14849, 'To appease Tsoatha, they tossed it to sea, but the storm grew ever madder.' || char(13) || '
None returned to shore. Yet the vessel sails on, and its captain is merry.'),
(2940, 'DeepwaterAttributeSwap', 22359, 'A noble Eternal who gave up his name to join the Brinerots. He climbed' || char(13) || '
the ranks with calculated savagery like Pondium had never seen.'),
(2941, 'DeepwaterItemSplit', 23722, 'Vaal Kishara sailed the seas, seeking her equal. None were worthy. From' || char(13) || '
each contender she took a carnal gift, and thus, the Brinerot clan was born.'),
(2942, 'DeepwaterChartReroll', 53286, 'Telesia carved the earth with her oars, and filled the seas with her tears. ' || char(13) || '
The waters, still as stone, began to dance and flow to cheer her.'),
(2943, 'DeepwaterSaboteur', 39119, 'Under Weylam, the Brinerots had become soft and aimless. Lussi' || char(13) || '
"Rotmother" Roth saw her opportunity, and took it. Blood be damned.'),
(2944, 'DeepwaterPantheon', 60187, 'Brinehook Vex inspired the Brinerot name. He fought the sea. Sailed with' || char(13) || '
gods. Drank with heroes. Wed a dozen wives, and the Leviathan, too.'),
(2945, 'DeepwaterEldritch', 53361, 'Mirthful Ukatoa travelled the world to teach it the Way. He ventured south, ' || char(13) || '
and came back changed, a sombre husk filled with unearthly arcana.'),
(2946, 'DeepwaterTatttoo', 84, 'A thousand ships litter the eastern seabed. All Katakohi''s doing. His fleet would ' || char(13) || '
board, fast as lightning. Every captive saved, every slaver butchered.'),
(2947, 'DeepwaterVelkaAllflame', 49693, 'Bright as her ambition, cold as the bitter deep.'),
(2948, 'DeepwaterGhostbuster', 57966, 'Before his work in Atzoatl, Tzamoto travelled the world in search of' || char(13) || '
forbidden arcana. He believed spirits held many untapped secrets.'),
(2949, 'DeepwaterMercenaryCurrency', 32157, 'Kylian Cyaxan sold every vice known to man, and more. Wares tailored to' || char(13) || '
break man''s will. Every customer returned, or died from deprivation.'),
(2950, 'SupportGemCrystalfall', 37845, 'The ancient golem of bone climbs ever upward. ' || char(13) || '
Its body is an engine. Its eyes are fuel.'),
(2951, 'DeepwaterAbyssCurrency', 31079, 'Merrick the Wanting''s dark desires forced the Brinerot to maroon him. So' || char(13) || '
he walked to the bottom of the sea, and made himself a new crew.'),
(2952, 'UniqueFishingRod3', 4642, 'Not every well has a bottom, but every line has another end.'),
(2953, 'DivinationCardPearlsBeforeSwine', 4774, '<size:26>{The unknowledgable know not' || char(13) || '
what treasures lie so closely' || char(13) || '
within their feeble reach.}'),
(2954, 'DivinationCardEnergySword', 35659, 'To my number one fan.' || char(13) || '
- Griffin, with love'),
(2955, 'DivinationCardDivineShard', 43293, '<size:26>{Sin sought to contain Divinity' || char(13) || '
so that no mortal would gain' || char(13) || '
such monstrous power ever again.}'),
(2956, 'QuestDucat1GraspingDeep', 27598, 'Beneath the Leviathan''s shadow,' || char(13) || '
in the boundless dark,' || char(13) || '
its many limbs stretch upward...'),
(2957, 'QuestDucat2FoulKin', 36906, 'Each accursed union begot stranger forms.' || char(13) || '
Elongated necks, membranes, even tails...'),
(2958, 'QuestDucat3TsoathasGift', 15941, 'The Brine King had found, within all humanity,' || char(13) || '
a dark truth waiting to claw itself free...'),
(2959, 'QuestDucat4UndeadSea_', 37929, 'Creatures perished in droves,' || char(13) || '
drawn to that verdant glow.' || char(13) || '
Yet their bones swam away...'),
(2960, 'QuestDucat5EucaridIsle', 30064, 'Not a soul stepped foot on the isle,' || char(13) || '
for shelled monstrosities skittered about its shores...'),
(2961, 'QuestDucat6FallenStars', 46855, 'Still they follow her siren''s song.' || char(13) || '
Deemed unworthy, left to die, unwilling to accept fate...');
